using System.Numerics;
using WoWAddonLab.Emulator.Addons;
using WoWAddonLab.Emulator.Diagnostics;
using WoWAddonLab.Emulator.Lua;
using WoWAddonLab.Emulator.UI;

namespace WoWAddonLab.Tests;

public sealed class LuaRuntimeTests
{
    [Fact]
    public void TimerAfterRunsExactlyOnce()
    {
        using var session = new EmulatorSession();
        session.Lua.Evaluate("timerCount = 0; C_Timer.After(0, function() timerCount = timerCount + 1 end)");

        for (var index = 0; index < 10; index++)
            session.Tick(1.0 / 60.0);

        Assert.Equal("1", session.Lua.Evaluate("timerCount"));
    }

    [Fact]
    public void ApiBindingsResolveTheRuntimeFromCoroutineStates()
    {
        using var session = new EmulatorSession();

        var result = session.Lua.Evaluate(
            "(function() local co=coroutine.create(function() " +
            "C_Timer.After(0,function() COROUTINE_TIMER_RAN=true end) end); " +
            "local ok,err=coroutine.resume(co); return tostring(ok)..':'..tostring(err) end)()");
        for (var index = 0; index < 10; index++)
            session.Tick(1.0 / 60.0);

        Assert.Equal("true:nil", result);
        Assert.Equal("true", session.Lua.Evaluate("tostring(COROUTINE_TIMER_RAN)"));
    }

    [Fact]
    public void TimerHandlesCanCancelTickers()
    {
        using var session = new EmulatorSession();
        session.Lua.Evaluate(
            "tickerCount = 0; local ticker; " +
            "ticker = C_Timer.NewTicker(0.01, function() tickerCount = tickerCount + 1; ticker:Cancel() end)");

        for (var index = 0; index < 10; index++)
            session.Tick(1.0 / 60.0);

        Assert.Equal("1", session.Lua.Evaluate("tickerCount"));
    }

    [Fact]
    public void RuntimeUsesLua51AndPreservesCustomFrameFields()
    {
        var log = new EmulatorLog();
        var ui = new UiSystem();
        using var runtime = new LuaRuntime(log, ui);

        Assert.StartsWith("Lua 5.1", runtime.GetVersion());
        Assert.Equal(
            "answer",
            runtime.Evaluate("(function() local f=CreateFrame('Frame','TestFrame',UIParent); f.custom='answer'; return f.custom end)()"));
    }

    [Fact]
    public void XpcallForwardsWowStyleArgumentsAndPreservesResults()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "true:alpha:nil:omega:false:handled:failure",
            session.Lua.Evaluate(
                "local ok,a,b,c=xpcall(function(...) return ... end,tostring,'alpha',nil,'omega'); " +
                "local failed,message=xpcall(function(value) error(value) end," +
                "function(value) return 'handled:'..tostring(value):match('failure') end,'failure'); " +
                "return table.concat({tostring(ok),a,tostring(b),c,tostring(failed),message},':')"));
    }

    [Fact]
    public void FrameSurrogatesUseRawIdentityInsteadOfPrototypeIdentity()
    {
        using var session = new EmulatorSession();

        session.Lua.Evaluate("CreateFrame('Frame','SecureIdentityFrame')");
        var secure = session.Ui.Find("SecureIdentityFrame")!;
        secure.Protected = true;
        secure.ProtectedExplicitly = true;

        Assert.Equal(
            "true:true",
            session.Lua.Evaluate(
                "local prototype=CreateFrame('Frame'); " +
                "local surrogate={[0]=SecureIdentityFrame[0],[1]=SecureIdentityFrame}; " +
                "setmetatable(surrogate,{__index=prototype}); " +
                "local effective,explicit=surrogate:IsProtected(); " +
                "return tostring(effective)..':'..tostring(explicit)"));
    }

    [Fact]
    public void UntaintedLoaderAndScrubPreserveValuesWithoutATaintEngine()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "answer:nil:tail",
            session.Lua.Evaluate(
                "local loader=assert(loadstring_untainted('return ...')); " +
                "local value=loader('answer'); local a,b,c=scrub(value,nil,'tail'); " +
                "return table.concat({a,tostring(b),c},':')"));
    }

    [Fact]
    public void ScrollFrameExposesHorizontalAndVerticalScrollStateAndRanges()
    {
        using var session = new EmulatorSession();

        var result = session.Lua.Evaluate(
            "(function() " +
            "local scroll=CreateFrame('ScrollFrame','TestScroll',UIParent); scroll:SetSize(100,80); " +
            "scroll:SetPoint('TOPLEFT',UIParent,'TOPLEFT',200,-100); " +
            "local rangeChanged=0; local verticalChanged=0; " +
            "scroll:SetScript('OnScrollRangeChanged',function(_,x,y) rangeChanged=x+y end); " +
            "scroll:SetScript('OnVerticalScroll',function(_,y) verticalChanged=y end); " +
            "local child=CreateFrame('Frame','TestScrollChild',scroll); child:SetSize(250,200); " +
            "local button=CreateFrame('Button','TestScrolledButton',child); button:SetSize(80,20); " +
            "button:SetPoint('TOPLEFT',child,'TOPLEFT',10,-50); " +
            "local overlay=CreateFrame('Button','TestScrollOverlay',scroll); overlay:SetSize(20,20); " +
            "overlay:SetPoint('TOPLEFT',scroll,'TOPLEFT',-40,-5); " +
            "scroll:SetScrollChild(child); scroll:UpdateScrollChildRect(); " +
            "scroll:SetHorizontalScroll(45); scroll:SetVerticalScroll(30); " +
            "return table.concat({scroll:GetHorizontalScroll(),scroll:GetHorizontalScrollRange()," +
            "scroll:GetVerticalScroll(),scroll:GetVerticalScrollRange()," +
            "scroll:GetScrollChild()==child and rangeChanged or -1,verticalChanged},':') end)()");

        Assert.Equal("45:150:30:120:270:30", result);
        var scroll = session.Ui.Find("TestScroll")!;
        var child = session.Ui.ResolveBounds(session.Ui.Find("TestScrollChild")!.Id);
        Assert.False(scroll.ClipsChildren);
        Assert.Equal(155, child.Left);
        Assert.Equal(630, child.Bottom);
        Assert.Equal(830, child.Top);
        Assert.Null(session.Ui.HitTest(new(170, 770)));
        Assert.Equal("TestScrollOverlay", session.Ui.HitTest(new(170, 785))?.Name);
        Assert.Equal("TestScrolledButton", session.Ui.HitTest(new(210, 770))?.Name);
    }

    [Fact]
    public void ScrollFrameUsesCachedRangesAndDoesNotClampNativeScrollOffsets()
    {
        using var session = new EmulatorSession();

        var result = session.Lua.Evaluate(
            "(function() " +
            "local scroll=CreateFrame('ScrollFrame','NativeScroll',UIParent); scroll:SetSize(100,80); " +
            "local events=0; local horizontalEvents=0; " +
            "scroll:SetScript('OnScrollRangeChanged',function() events=events+1 end); " +
            "scroll:SetScript('OnHorizontalScroll',function() horizontalEvents=horizontalEvents+1 end); " +
            "local first=CreateFrame('Frame','FirstNativeScrollChild',scroll); first:SetSize(250,200); " +
            "scroll:SetScrollChild(first); local before=scroll:GetHorizontalScrollRange(); " +
            "scroll:UpdateScrollChildRect(); scroll:UpdateScrollChildRect(); " +
            "scroll:SetHorizontalScroll(-25); scroll:SetHorizontalScroll(-25+0.0000001); " +
            "scroll:SetVerticalScroll(500); " +
            "local second=CreateFrame('Frame','SecondNativeScrollChild',UIParent); second:SetSize(110,90); " +
            "scroll:SetScrollChild(second); scroll:UpdateScrollChildRect(); " +
            "local missing=pcall(scroll.SetHorizontalScroll,scroll); " +
            "local nilChild=pcall(scroll.SetScrollChild,scroll,nil); " +
            "return table.concat({before,scroll:GetHorizontalScrollRange()," +
            "scroll:GetVerticalScrollRange(),scroll:GetHorizontalScroll(),scroll:GetVerticalScroll()," +
            "events,horizontalEvents,tostring(first:GetParent()==nil),tostring(missing)," +
            "tostring(nilChild),tostring(scroll.SetChild==nil)},':') end)()");

        Assert.Equal("0:10:10:-25:500:2:1:true:false:false:true", result);
    }

