    [Fact]
    public void ScrollFrameSetToDefaultsResetsOffsetsButRetainsChildAndRecalculatesRanges()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "0:150:0:120:true:true",
            session.Lua.Evaluate(
                "(function() local scroll=CreateFrame('ScrollFrame','ResetScroll',UIParent); " +
                "scroll:SetSize(100,80); local child=CreateFrame('Frame','ResetScrollChild'); " +
                "child:SetSize(250,200); scroll:SetScrollChild(child); " +
                "scroll:UpdateScrollChildRect(); scroll:SetHorizontalScroll(45); " +
                "scroll:SetVerticalScroll(30); scroll:SetToDefaults(); " +
                "return table.concat({scroll:GetHorizontalScroll()," +
                "scroll:GetHorizontalScrollRange(),scroll:GetVerticalScroll()," +
                "scroll:GetVerticalScrollRange(),tostring(scroll:GetScrollChild()==child)," +
                "tostring(child:GetParent()==scroll)},':') end)()"));

        Assert.False(session.Ui.Find("ResetScroll")!.ClipsChildren);
    }

    [Fact]
    public void WidgetFormattingCallbacksAndSpecializedControlsUseNativeContracts()
    {
        using var session = new EmulatorSession();

        session.Lua.Evaluate(
            "widgetCallbackValue=0; widgetCallbackOwner=false; " +
            "WidgetCallbackFrame=CreateFrame('Frame','WidgetCallbackFrame',UIParent); " +
            "WidgetCallbackFrame:SetSize(50,50); WidgetCallbackFrame:EnableMouse(true); " +
            "WidgetCallbackFrame:RegisterEventCallback('TOOLTIP_SHOW_ITEM_COMPARISON'," +
            "function(self,value) widgetCallbackOwner=self==WidgetCallbackFrame; " +
            "widgetCallbackValue=value end); " +
            "WidgetFormatText=WidgetCallbackFrame:CreateFontString('WidgetFormatText'); " +
            "WidgetFormatText:SetFont('Fonts\\\\FRIZQT__.TTF',12); " +
            "WidgetFormatText:SetFormattedText('Value %.1f',2.25); " +
            "WidgetFormatButton=CreateFrame('Button','WidgetFormatButton',UIParent); " +
            "WidgetFormatButton:SetFormattedText('Page %d',3); " +
            "WidgetFormatButton:SetMotionScriptsWhileDisabled(true); " +
            "WidgetFormatButton:LockHighlight(); WidgetFormatButton:UnlockHighlight(); " +
            "WidgetSlider=CreateFrame('Slider','WidgetSlider',UIParent); " +
            "WidgetSlider:SetObeyStepOnDrag(true); WidgetSlider:Disable(); " +
            "widgetSliderDisabled=not WidgetSlider:IsEnabled(); WidgetSlider:SetEnabled(true); " +
            "WidgetScroll=CreateFrame('ScrollFrame','WidgetScroll',UIParent); " +
            "WidgetScroll:UpdateScrollChildRect(); " +
            "WidgetModel=CreateFrame('PlayerModel','WidgetModel',UIParent); " +
            "WidgetModel:SetRotation(1.25); WidgetModel:SetPortraitZoom(0.4)");
        var frame = session.Ui.Find("WidgetCallbackFrame")!;
        session.Ui.HoveredObjectId = frame.Id;
        session.Lua.TriggerEvent("TOOLTIP_SHOW_ITEM_COMPARISON", 17);

        Assert.Equal(
            "Value 2.2:Page 3:true:true:true:true:17",
            session.Lua.Evaluate(
                "return table.concat({WidgetFormatText:GetText(),WidgetFormatButton:GetText()," +
                "tostring(WidgetSlider:GetObeyStepOnDrag())," +
                "tostring(widgetSliderDisabled),tostring(WidgetCallbackFrame:IsMouseMotionFocus())," +
                "tostring(widgetCallbackOwner),widgetCallbackValue},':')"));
        Assert.True(session.Ui.Find("WidgetFormatButton")!.MotionScriptsWhileDisabled);
        Assert.False(session.Ui.Find("WidgetFormatButton")!.HighlightLocked);
        Assert.Equal(1.25f, session.Ui.Find("WidgetModel")!.ModelYaw);
        Assert.Equal(0.4f, session.Ui.Find("WidgetModel")!.ModelPortraitZoom);
    }

    [Fact]
    public void FrameEventCallbacksUnitFiltersDragButtonsAndTextureRotationUseNativeSeparation()
    {
        using var session = new EmulatorSession();
        Assert.Equal(
            "true:true:true:false",
            session.Lua.Evaluate(
                "FrameCallbackAudit=CreateFrame('Frame','FrameCallbackAudit',UIParent);" +
                "frameCallbackOwner=false; frameCallbackValue=0; frameOnEventCount=0;" +
                "frameDuplicateCallbackCount=0; unitCallbackTrace='';" +
                "FrameCallbackAudit:SetScript('OnEvent',function() frameOnEventCount=frameOnEventCount+1 end);" +
                "local registered=FrameCallbackAudit:RegisterEventCallback(" +
                "'TOOLTIP_SHOW_ITEM_COMPARISON',function(self,value) " +
                "frameCallbackOwner=self==FrameCallbackAudit; frameCallbackValue=value end);" +
                "local duplicate=FrameCallbackAudit:RegisterEventCallback(" +
                "'TOOLTIP_SHOW_ITEM_COMPARISON',function() " +
                "frameDuplicateCallbackCount=frameDuplicateCallbackCount+1 end);" +
                "local unitRegistered=FrameCallbackAudit:RegisterUnitEventCallback(" +
                "'MINIMAP_PING',function(self,unit,value) " +
                "unitCallbackTrace=(self==FrameCallbackAudit and 'owner' or 'wrong')..':'..unit..':'..value end," +
                "'target');" +
                "FrameCallbackAudit:RegisterForDrag('leftbutton','Button4');" +
                "FrameCallbackTexture=FrameCallbackAudit:CreateTexture('FrameCallbackTexture');" +
                "FrameCallbackLine=FrameCallbackAudit:CreateLine('FrameCallbackLine');" +
                "FrameCallbackNested=CreateFrame('Frame','FrameCallbackNested',FrameCallbackAudit);" +
                "FrameCallbackNestedTexture=FrameCallbackNested:CreateTexture('FrameCallbackNestedTexture');" +
                "FrameCallbackAudit:RotateTextures(0.75,0.2,0.8);" +
                "local badRotate=pcall(FrameCallbackAudit.RotateTextures,FrameCallbackAudit);" +
                "return table.concat({tostring(registered),tostring(duplicate)," +
                "tostring(unitRegistered),tostring(badRotate)},':')"));

        session.Lua.TriggerEvent("TOOLTIP_SHOW_ITEM_COMPARISON", 23);
        session.Lua.TriggerEvent("MINIMAP_PING", "target", 9);

        Assert.Equal(
            "true:23:1:0:owner:target:9",
            session.Lua.Evaluate(
                "return table.concat({tostring(frameCallbackOwner),frameCallbackValue," +
                "frameDuplicateCallbackCount,frameOnEventCount,unitCallbackTrace},':')"));
        var frame = session.Ui.Find("FrameCallbackAudit")!;
        Assert.Contains("LeftButton", frame.DragRegistrations);
        Assert.Contains("Button4", frame.DragRegistrations);
        Assert.Equal(0.75f, session.Ui.Find("FrameCallbackTexture")!.Texture!.Rotation);
        Assert.Equal(new Vector2(0.2f, 0.8f), session.Ui.Find("FrameCallbackTexture")!.Texture!.RotationPoint);
        Assert.Equal(0.75f, session.Ui.Find("FrameCallbackLine")!.Line!.Texture.Rotation);
        Assert.Equal(0, session.Ui.Find("FrameCallbackNestedTexture")!.Texture!.Rotation);
    }

    [Fact]
    public void FrameAlphaGradientAndWidgetSpecificMethodsUseNativeContracts()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "true:true:true:true:true:true:true:true:false:false:false:false:false:" +
            "0:true:false:false:false:false:1",
            session.Lua.Evaluate(
                "FrameGradientAudit=CreateFrame('Frame','FrameGradientAudit',UIParent);" +
                "local edit=CreateFrame('EditBox','GradientEditBox',UIParent);" +
                "local button=CreateFrame('Button'); local slider=CreateFrame('Slider');" +
                "local browser=CreateFrame('Browser');" +
                "local surface={FrameGradientAudit.ClearFocus==nil," +
                "FrameGradientAudit.SetEnabled==nil,FrameGradientAudit.StopMoving==nil," +
                "type(FrameGradientAudit.StopMovingOrSizing)=='function'," +
                "type(edit.ClearFocus)=='function',type(edit.SetEnabled)=='function'," +
                "type(button.SetEnabled)=='function',type(browser.ClearFocus)=='function'};" +
                "local missingIndex=pcall(FrameGradientAudit.SetAlphaGradient,FrameGradientAudit);" +
                "local missingVector=pcall(FrameGradientAudit.SetAlphaGradient,FrameGradientAudit,0);" +
                "local wrongVector=pcall(FrameGradientAudit.SetAlphaGradient,FrameGradientAudit,0,{});" +
                "local missingY=pcall(FrameGradientAudit.SetAlphaGradient,FrameGradientAudit,0,{x=1});" +
                "local infinite=pcall(FrameGradientAudit.SetAlphaGradient,FrameGradientAudit,0,{x=1/0,y=1});" +
                "local returns=select('#',FrameGradientAudit:SetAlphaGradient(0,{x='2.5',y=-4}));" +
                "FrameGradientAudit:SetAlphaGradient(1,{x=7,y=8});" +
                "FrameGradientAudit:SetAlphaGradient(2,{x=90,y=91});" +
                "edit:SetFocus(); edit:SetEnabled(false); local focusCleared=not edit:HasFocus();" +
                "edit:SetEnabled(); local editDefault=edit:IsEnabled();" +
                "button:Disable(); button:SetEnabled(); local buttonDefault=button:IsEnabled();" +
                "local sliderMissing=pcall(slider.SetEnabled,slider);" +
                "slider:SetEnabled(nil); local sliderNil=slider:IsEnabled();" +
                "local enableEvents=0; edit:SetScript('OnEnable',function() enableEvents=enableEvents+1 end);" +
                "edit:SetEnabled(true); edit:SetEnabled();" +
                "local result={surface[1],surface[2],surface[3],surface[4]," +
                "surface[5],surface[6],surface[7],surface[8]," +
                "missingIndex,missingVector,wrongVector,missingY,infinite,returns," +
                "focusCleared,editDefault,buttonDefault,sliderMissing," +
                "sliderNil,enableEvents}; for i=1,#result do result[i]=tostring(result[i]) end;" +
                "return table.concat(result,':')"));

        var frame = session.Ui.Find("FrameGradientAudit")!;
        Assert.True(frame.HasFrameAlphaGradient);
        Assert.Equal(new Vector2(2.5f, -4), frame.FrameAlphaGradientEdges[0]);
        Assert.Equal(new Vector2(7, 8), frame.FrameAlphaGradientEdges[1]);

        session.Lua.Evaluate("FrameGradientAudit:SetToDefaults()");
        Assert.False(frame.HasFrameAlphaGradient);
        Assert.Equal(Vector2.Zero, frame.FrameAlphaGradientEdges[0]);
        Assert.Equal(Vector2.Zero, frame.FrameAlphaGradientEdges[1]);
    }

    [Fact]
    public void FrameRegionFactoriesParseAtomicallyAndUseNativeLayerAndSublevelContracts()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "false:false:false:false:false:true:true:true:0:5",
            session.Lua.Evaluate(
                "RegionFactoryOwner=CreateFrame('Frame','RegionFactoryOwner',UIParent);" +
                "local before=RegionFactoryOwner:GetNumRegions();" +
                "local badName=pcall(RegionFactoryOwner.CreateTexture,RegionFactoryOwner,{});" +
                "local badLayer=pcall(RegionFactoryOwner.CreateTexture,RegionFactoryOwner," +
                "'BadLayer','NOT_A_LAYER');" +
                "local badTemplate=pcall(RegionFactoryOwner.CreateTexture,RegionFactoryOwner," +
                "'BadTemplateArgument',nil,{});" +
                "local badSublevel=pcall(RegionFactoryOwner.CreateTexture,RegionFactoryOwner," +
                "'BadSublevel',nil,nil,{});" +
                "local badInt8=pcall(RegionFactoryOwner.CreateTexture,RegionFactoryOwner," +
                "'BadInt8',nil,nil,128);" +
                "local missing=RegionFactoryOwner:CreateTexture(" +
                "'MissingTemplate','ARTWORK','EmulatorMissingTemplate');" +
                "local tooLow=RegionFactoryOwner:CreateTexture(" +
                "'TooLow','ARTWORK',nil,-9);" +
                "local tooHigh=RegionFactoryOwner:CreateTexture(" +
                "'TooHigh','ARTWORK',nil,8);" +
                "RegionFactoryTexture=RegionFactoryOwner:CreateTexture(" +
                "'RegionFactoryTexture','overlay',nil,-8);" +
                "RegionFactoryMask=RegionFactoryOwner:CreateMaskTexture(" +
                "'RegionFactoryMask','BACKGROUND',nil,7);" +
                "RegionFactoryLine=RegionFactoryOwner:CreateLine(" +
                "'RegionFactoryLine','BORDER',nil,-3.9);" +
                "RegionFactoryFont=RegionFactoryOwner:CreateFontString(" +
                "'RegionFactoryFont','HIGHLIGHT',nil,7);" +
                "RegionFactoryDefault=RegionFactoryOwner:CreateTexture('RegionFactoryDefault');" +
                "return table.concat({tostring(badName),tostring(badLayer)," +
                "tostring(badTemplate),tostring(badSublevel),tostring(badInt8)," +
                "tostring(missing==nil),tostring(tooLow==nil),tostring(tooHigh==nil)," +
                "before,RegionFactoryOwner:GetNumRegions()},':')"));

        Assert.Equal("OVERLAY", session.Ui.Find("RegionFactoryTexture")!.DrawLayer);
        Assert.Equal(-8, session.Ui.Find("RegionFactoryTexture")!.SubLevel);
        Assert.Equal("BACKGROUND", session.Ui.Find("RegionFactoryMask")!.DrawLayer);
        Assert.Equal(7, session.Ui.Find("RegionFactoryMask")!.SubLevel);
        Assert.Equal("BORDER", session.Ui.Find("RegionFactoryLine")!.DrawLayer);
        Assert.Equal(-3, session.Ui.Find("RegionFactoryLine")!.SubLevel);
        Assert.Equal("HIGHLIGHT", session.Ui.Find("RegionFactoryFont")!.DrawLayer);
        Assert.Equal(0, session.Ui.Find("RegionFactoryFont")!.SubLevel);
        Assert.Equal("ARTWORK", session.Ui.Find("RegionFactoryDefault")!.DrawLayer);
        Assert.Equal(0, session.Ui.Find("RegionFactoryDefault")!.SubLevel);
        Assert.Null(session.Ui.Find("MissingTemplate"));
        Assert.Null(session.Ui.Find("TooLow"));
        Assert.Null(session.Ui.Find("TooHigh"));
    }

    [Fact]
    public void GlobalMouseEventsPrecedeFocusedWidgetScripts()
    {
        using var session = new EmulatorSession();

        session.Lua.Evaluate(
            "mouseOrder={}; " +
            "local events=CreateFrame('Frame',nil,UIParent); " +
            "events:RegisterEvent('GLOBAL_MOUSE_DOWN'); events:RegisterEvent('GLOBAL_MOUSE_UP'); " +
            "events:SetScript('OnEvent',function(_,event,button) " +
            "table.insert(mouseOrder,event..':'..button) end); " +
            "MouseOrderButton=CreateFrame('Button','MouseOrderButton',UIParent); " +
            "MouseOrderButton:SetSize(100,40); " +
            "MouseOrderButton:SetPoint('BOTTOMLEFT',UIParent,'BOTTOMLEFT',20,20); " +
            "MouseOrderButton:SetScript('OnMouseDown',function(_,button) " +
            "table.insert(mouseOrder,'OnMouseDown:'..button) end); " +
            "MouseOrderButton:SetScript('OnMouseUp',function(_,button) " +
            "table.insert(mouseOrder,'OnMouseUp:'..button) end); " +
            "MouseOrderButton:SetScript('OnClick',function(_,button) " +
            "table.insert(mouseOrder,'OnClick:'..button) end)");

        session.MouseMove(50, 40);
        session.MouseButton("LeftButton", true);
        session.MouseButton("LeftButton", false);

        Assert.Equal(
            "GLOBAL_MOUSE_DOWN:LeftButton,OnMouseDown:LeftButton," +
            "GLOBAL_MOUSE_UP:LeftButton,OnMouseUp:LeftButton,OnClick:LeftButton",
            session.Lua.Evaluate("return table.concat(mouseOrder,',')"));
    }

