    [Fact]
    public void SetParentKeyCanClearEveryOtherParentReference()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "nil:nil:true:Current:false:false:nil:nil",
            session.Lua.Evaluate(
                "local parent=CreateFrame('Frame','ParentKeyOwner',UIParent); " +
                "local child=CreateFrame('Frame','ParentKeyChild',parent); " +
                "child:SetParentKey('Previous'); parent.Other=child; " +
                "child:SetParentKey('Current',true); " +
                "parent.lowercase=child; local bound=parent.Current==child; " +
                "local selected=child:GetParentKey(); " +
                "local missing=pcall(function() child:SetParentKey() end); " +
                "local invalid=pcall(function() child:SetParentKey({}) end); " +
                "child:SetParentKey('',true); " +
                "return table.concat({tostring(parent.Previous),tostring(parent.Other)," +
                "tostring(bound),selected,tostring(missing),tostring(invalid)," +
                "tostring(parent.Current),tostring(child:GetParentKey())},':')"));
    }

    [Fact]
    public void ScriptHandlersUseNativeClassSupportAndReturnConventions()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "true:false:true:true:false:true:false:true:false:1:true:0:0:" +
            "false:true:old,hook:true:1:0:true",
            session.Lua.Evaluate(
                "local frame=CreateFrame('Frame'); local button=CreateFrame('Button'); " +
                "local texture=frame:CreateTexture(); local edit=CreateFrame('EditBox'); " +
                "local group=frame:CreateAnimationGroup(); " +
                "local animation=group:CreateAnimation('Alpha'); " +
                "local absentCount=select('#',frame:GetScript('OnEvent')); " +
                "local absentNil=frame:GetScript('OnEvent')==nil; " +
                "local unsupportedCount=select('#',frame:GetScript('OnClick')); " +
                "local numericCount=select('#',frame:GetScript(1)); " +
                "frame:SetScript('OnEvent',function() end); " +
                "local before=frame:GetScript('onevent'); " +
                "frame:SetScript('OnEvent','bad'); " +
                "local preserved=frame:GetScript('OnEvent')==before; " +
                "local order={}; frame:SetScript('OnShow',function() table.insert(order,'old') end); " +
                "local hookResult=frame:HookScript('onshow',function() table.insert(order,'hook') end); " +
                "frame:GetScript('ONSHOW')(frame); " +
                "frame:SetScript('OnShow',nil); " +
