    [Fact]
    public void FrameMovingAndSizingUseNativeSharedInteractionState()
    {
        using var session = new EmulatorSession();
        _ = session.Lua.Evaluate(
            "(function() frame=CreateFrame('Frame','InteractiveFrame',UIParent); " +
            "frame:SetPoint('BOTTOMLEFT',UIParent,'BOTTOMLEFT',100,100); " +
            "frame:SetSize(100,80); frame:SetMovable(true); frame:SetResizable(true); " +
            "frame:SetResizeBounds(90,70,130,100); " +
            "other=CreateFrame('Frame','OtherInteractiveFrame',UIParent); " +
            "other:SetMovable(true); other:SetResizable(true); return true end)()");

        session.MouseMove(200, 180);
        Assert.Equal(
            "false:false",
            session.Lua.Evaluate(
                "local invalidPoint=pcall(function() frame:StartSizing('DIAGONAL') end); " +
                "local numericPoint=pcall(function() frame:StartSizing(8) end); " +
                "return tostring(invalidPoint)..':'..tostring(numericPoint)"));

        _ = session.Lua.Evaluate("(function() frame:StartSizing(); return true end)()");
        var frame = session.Ui.Find("InteractiveFrame")!;
        Assert.Equal(frame.Id, session.Ui.MovingObjectId);
        Assert.Equal("BOTTOMRIGHT", session.Ui.MovingPoint);

        _ = session.Lua.Evaluate(
            "(function() other:StartMoving(); other:StopMovingOrSizing(); return true end)()");
        Assert.Equal(frame.Id, session.Ui.MovingObjectId);
        session.MouseMove(260, 120);

        var sized = session.Ui.ResolveBounds(frame.Id);
        Assert.Equal(100, sized.Left, 3);
        Assert.Equal(80, sized.Bottom, 3);
        Assert.Equal(130, sized.Width, 3);
        Assert.Equal(100, sized.Height, 3);

        _ = session.Lua.Evaluate(
            "(function() frame:StopMovingOrSizing(); return true end)()");
        Assert.Null(session.Ui.MovingObjectId);
        Assert.Null(session.Ui.MovingPoint);

        _ = session.Lua.Evaluate("(function() frame:StartMoving(); return true end)()");
        session.MouseMove(270, 140);
        var moved = session.Ui.ResolveBounds(frame.Id);
        Assert.Equal(110, moved.Left, 3);
        Assert.Equal(100, moved.Bottom, 3);
        Assert.True(frame.UserPlaced);
    }

