            "NamePlateB=CreateFrame('Frame','NamePlateB',UIParent)");
        var firstId = session.Ui.Find("NamePlateA")!.Id;
        var secondId = session.Ui.Find("NamePlateB")!.Id;
        session.Lua.NamePlates.ObjectIdsByUnit["nameplate1"] = firstId;
        session.Lua.NamePlates.ObjectIdsByUnit["nameplate2"] = secondId;
        session.Lua.NamePlates.ForbiddenObjectIds.Add(secondId);

        Assert.Equal(
            "110:45:true:true:true:true:1:2",
            session.Lua.Evaluate(
                "(function() local w,h=C_NamePlate.GetNamePlateSize(); " +
                "local visible=C_NamePlate.GetNamePlateForUnit('nameplate1'); " +
                "local hidden=C_NamePlate.GetNamePlateForUnit('nameplate2'); " +
                "local allowed=C_NamePlate.GetNamePlateForUnit('nameplate2',1); " +
                "local absent=C_NamePlate.GetNamePlateForUnit('target'); " +
                "return table.concat({w,h,tostring(visible==NamePlateA)," +
                "tostring(hidden==nil),tostring(allowed==NamePlateB)," +
                "tostring(absent==nil),#C_NamePlate.GetNamePlates()," +
                "#C_NamePlate.GetNamePlates(true)},':') end)()"));

        Assert.Equal(
