                "(function() local returns=select('#',C_NamePlate.SetNamePlateSize('123.25',67.5)); " +
                "local w,h=C_NamePlate.GetNamePlateSize(); " +
                "return table.concat({returns,w,h," +
                "tostring(pcall(C_NamePlate.GetNamePlateForUnit))," +
                "tostring(pcall(C_NamePlate.GetNamePlateForUnit,{}))," +
                "tostring(pcall(C_NamePlate.GetNamePlateForUnit,'invalid'))," +
                "tostring(pcall(C_NamePlate.SetNamePlateSize,80))},':') end)()"));

        Assert.Equal(
            "123.25:67.5",
            session.Lua.Evaluate(
                "(function() local w,h=C_NamePlate.GetNamePlateSize(); return w..':'..h end)()"));
    }

    [Fact]
    public void UiWidgetManagerCoreQueriesAndUnitMutationsMatchNativeContracts()
    {
        using var session = new EmulatorSession();
        var widgets = session.Lua.UiWidgets;
        widgets.WidgetSets[8] = new WowUiWidgetSetInfoState(8, 1, 6);
        widgets.WidgetsBySetId[8] =
        [
            new WowUiWidgetInfoState(91, 3, 9, "target"),
            new WowUiWidgetInfoState(92, 4)
        ];

        Assert.Equal(
            "2:240:283:1:2:nil:1:6:91:9:3:target:92:8:4:nil:1:true",
            session.Lua.Evaluate(
                "(function() local info=C_UIWidgetManager.GetWidgetSetInfo('8'); " +
                "local all=C_UIWidgetManager.GetAllWidgetsBySetID('8'); " +
                "local missing=C_UIWidgetManager.GetStatusBarWidgetVisualizationInfo(12345); " +
                "return table.concat({C_UIWidgetManager.GetBelowMinimapWidgetSetID()," +
                "C_UIWidgetManager.GetObjectiveTrackerWidgetSetID()," +
                "C_UIWidgetManager.GetPowerBarWidgetSetID()," +
                "C_UIWidgetManager.GetTopCenterWidgetSetID()," +
                "(function() local n=0 for _ in pairs(info) do n=n+1 end return n end)()," +
                "tostring(info.widgetSetID),info.layoutDirection,info.verticalPadding," +
                "all[1].widgetID,all[1].widgetSetID,all[1].widgetType,all[1].unitToken," +
                "all[2].widgetID,all[2].widgetSetID,all[2].widgetType," +
                "tostring(all[2].unitToken),select('#',missing),tostring(missing==nil)},':') end)()"));

        Assert.Equal(
            "false:false:false:false",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(pcall(C_UIWidgetManager.GetWidgetSetInfo))," +
                "tostring(pcall(C_UIWidgetManager.GetAllWidgetsBySetID,{}))," +
                "tostring(pcall(C_UIWidgetManager.GetStatusBarWidgetVisualizationInfo,'bad'))," +
                "tostring(pcall(C_UIWidgetManager.SetProcessingUnit,'invalid'))},':')"));

        session.Lua.Evaluate(
            "C_UIWidgetManager.RegisterUnitForWidgetUpdates('target'); " +
            "C_UIWidgetManager.RegisterUnitForWidgetUpdates('Creature-0-1',true); " +
            "C_UIWidgetManager.RegisterUnitForWidgetUpdates(123); " +
            "C_UIWidgetManager.UnregisterUnitForWidgetUpdates('target'); " +
            "C_UIWidgetManager.SetProcessingUnit('focus')");
        Assert.DoesNotContain("target", widgets.RegisteredUnitTokens);
        Assert.Contains("123", widgets.RegisteredUnitTokens);
        Assert.Contains("Creature-0-1", widgets.RegisteredUnitGuids);
        Assert.Equal("focus", widgets.ProcessingUnit);
        Assert.False(widgets.ProcessingUnitIsGuid);

        session.Lua.Evaluate("C_UIWidgetManager.SetProcessingUnitGuid('Player-0-1')");
        Assert.Equal("Player-0-1", widgets.ProcessingUnit);
        Assert.True(widgets.ProcessingUnitIsGuid);

        session.Lua.Evaluate("C_UIWidgetManager.SetProcessingUnitGuid(nil)");
        Assert.Null(widgets.ProcessingUnit);
        Assert.True(widgets.ProcessingUnitIsGuid);
    }

