    [Fact]
    public void ContainerSubsetMatchesNativeGeneratedAndLegacyContracts()
    {
        using var session = new EmulatorSession();
        var containers = session.Lua.Containers;
        containers.ContainerSlotCounts[0] = 16;
        containers.ContainerSlotCounts[2] = 24;
        containers.TotalNumberOfFreeBagSlots = 7;
        containers.FilteredContainerIds.Add(2);
        containers.ProfessionBagSlotsByUnit["player"] =
            new Dictionary<int, bool>
            {
                [21] = true,
                [22] = false
            };

        Assert.Equal(
            "31:35:64:69:101:105:0:0:16:24:7:false:true:true:false:false:0",
            session.Lua.Evaluate(
                "(function() C_Container.SetBagSlotFlag(2,4,true); " +
                "C_Container.SetBagSlotFlag(6,8,true); " +
                "local before=C_Container.IsContainerFiltered(2); " +
                "C_Container.SetItemSearch('ore'); " +
                "return table.concat({" +
                "C_Container.ContainerIDToInventoryID(1)," +
                "C_Container.ContainerIDToInventoryID(5)," +
                "C_Container.ContainerIDToInventoryID(6)," +
                "C_Container.ContainerIDToInventoryID(11)," +
                "C_Container.ContainerIDToInventoryID(12)," +
                "C_Container.ContainerIDToInventoryID(16)," +
                "select('#',C_Container.ContainerIDToInventoryID(0))," +
                "select('#',C_Container.ContainerIDToInventoryID(17))," +
                "C_Container.GetContainerNumSlots(0)," +
                "C_Container.GetContainerNumSlots(2)," +
                "C_Container.CalculateTotalNumberOfFreeBagSlots()," +
                "tostring(before),tostring(C_Container.IsContainerFiltered(2))," +
                "tostring(C_Container.GetBagSlotFlag(2,4))," +
                "tostring(C_Container.GetBagSlotFlag(6,8))," +
                "tostring(IsInventoryItemProfessionBag('player',22))," +
                "select('#',IsInventoryItemProfessionBag('player',23))" +
                "},':') end)()"));

        Assert.Equal(
            "true:true:0:false:true:true:true:true:true:123",
            session.Lua.Evaluate(
                "(function() " +
                "local named=IsInventoryItemProfessionBag('player','BAG1SLOT'); " +
                "local numeric=IsInventoryItemProfessionBag('player',21); " +
                "local missing=select('#',IsInventoryItemProfessionBag('target',21)); " +
                "local okUnit=pcall(IsInventoryItemProfessionBag,21,21); " +
                "local okContainer=pcall(C_Container.GetContainerNumSlots); " +
                "local okFlag=pcall(C_Container.GetBagSlotFlag,2,1024); " +
                "local okSet=pcall(C_Container.SetBagSlotFlag,2,4); " +
                "local okSearch=pcall(C_Container.SetItemSearch,nil); " +
                "C_Container.SetItemSearch(123); " +
                "return table.concat({tostring(named),tostring(numeric),missing," +
                "tostring(okUnit),tostring(not okContainer),tostring(not okFlag)," +
                "tostring(not okSet),tostring(not okSearch)," +
                "tostring(C_Container.IsContainerFiltered(2))," +
                "sessionSearch or '123'},':') end)()"));
        Assert.Equal("123", containers.ItemSearch);
    }

    [Fact]
    public void HousingNamespaceAndEnumsMatchNativeRegistration()
    {
        using var session = new EmulatorSession();
        string[] functions =
        [
            "AcceptNeighborhoodOwnership", "CanEditCharter",
