        housing.ReportScreenshotReasonByPlotIndex[2] = 7;
        housing.FactionMatchesNeighborhoodByGuid["Neighborhood-1"] = true;
        housing.NeighborhoodTextureSuffixByGuid["Neighborhood-1"] = "-Alliance";
