            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(C_Housing.CanEditCharter())," +
                "tostring(C_Housing.HasHousingExpansionAccess())," +
                "tostring(C_Housing.IsHousingMarketCartFullRemoveEnabled())," +
