                "C_Housing.GetCurrentHouseRefundAmount()," +
                "C_Housing.GetHousingAccessFlags(),C_Housing.GetMaxHouseLevel()," +
                "C_Housing.GetCurrentNeighborhoodGUID()," +
                "C_Housing.GetTrackedHouseGuid()," +
                "C_Housing.GetHouseLevelFavorForLevel(3)," +
                "C_Housing.CanTakeReportScreenshot(2)," +
                "tostring(C_Housing.DoesFactionMatchNeighborhood('Neighborhood-1'))," +
                "C_Housing.GetNeighborhoodTextureSuffix('Neighborhood-1')," +
