            session.Lua.Evaluate(
                "(function() local v=C_Housing.GetCurrentHouseInfo() return " +
                "table.concat({v.plotID,v.houseName,v.ownerName,v.plotCost," +
                "v.neighborhoodName,v.moveOutTime,tostring(v.plotReserved)," +
                "v.neighborhoodGUID,v.houseGUID},':') end)()"));
        Assert.Equal(
