            session.Lua.Evaluate(
                "(function() local v=C_Housing.GetVisitCooldownInfo() return " +
                "table.concat({v.startTime,v.duration,tostring(v.isEnabled)," +
                "tostring(v.isActive),v.modRate,v.activeCategory," +
                "v.timeUntilEndOfStartRecovery,tostring(v.isOnGCD)},':') end)()"));

        housing.CurrentHouseInfo = null;
        housing.VisitCooldownInfo = null;
        housing.CurrentNeighborhoodGuid = null;
        Assert.Equal(
            "1:nil:0:1:nil",
            session.Lua.Evaluate(
                "return table.concat({" +
                "select('#',C_Housing.GetCurrentHouseInfo())," +
                "tostring(C_Housing.GetCurrentHouseInfo())," +
                "select('#',C_Housing.GetVisitCooldownInfo())," +
                "select('#',C_Housing.GetCurrentNeighborhoodGUID())," +
