                "Enum.PingSubjectTypeMeta.MaxValue," +
                "Enum.PingSubjectType.Attack," +
                "Enum.PingSubjectType.AlertNotThreat," +
                "Enum.PingResultMeta.NumValues," +
                "Enum.PingResultMeta.MinValue," +
                "Enum.PingResultMeta.MaxValue," +
                "Enum.PingResult.FailedUnspecified," +
                "Enum.PingModeMeta.NumValues," +
                "Enum.PingModeMeta.MinValue," +
                "Enum.PingModeMeta.MaxValue," +
                "Enum.PingMode.ClickDrag," +
                "Enum.PingTypeFlagsMeta.NumValues," +
                "Enum.PingTypeFlagsMeta.MinValue," +
                "Enum.PingTypeFlagsMeta.MaxValue},':')"));
        Assert.Equal(
            "125:500:3:2:Ping-Assist:4:5:Ping-Assist:1:nil:true",
            session.Lua.Evaluate(
                "local cooldown=C_Ping.GetCooldownInfo();" +
                "local options=C_Ping.GetDefaultPingOptions();" +
                "return table.concat({cooldown.startTimeMs,cooldown.endTimeMs," +
                "options[1].orderIndex,options[1].type," +
                "options[1].uiTextureKitID," +
                "C_Ping.GetContextualPingTypeForUnit('target')," +
                "C_Ping.GetContextualPingTypeForUnit()," +
                "C_Ping.GetTextureKitForType(2)," +
                "select('#',C_Ping.GetTextureKitForType(3))," +
                "tostring(C_Ping.GetTextureKitForType(3))," +
                "tostring(C_Ping.IsPingSystemEnabled())},':')"));
        Assert.Equal(
            "Ping-Assist:false:false:true:true:0:0",
            session.Lua.Evaluate(
                "local wrapped=C_Ping.GetTextureKitForType(258);" +
                "local invalid=pcall(C_Ping.GetTextureKitForType,6);" +
                "local missingToggle=pcall(C_Ping.TogglePingListener);" +
                "local nilToggle=pcall(C_Ping.TogglePingListener,nil);" +
                "local send=pcall(C_Ping.SendMacroPing,nil,123);" +
                "return table.concat({wrapped,tostring(invalid)," +
                "tostring(missingToggle),tostring(nilToggle),tostring(send)," +
                "select('#',C_Ping.SendMacroPing(2,'focus'))," +
                "select('#',C_Ping.TogglePingListener(true))},':')"));
        Assert.True(ping.IsListenerDown);
        Assert.Contains(
            ping.Requests,
            request => request.Operation == "SendMacroPing" &&
                request.Arguments.SequenceEqual([null, "123"]));
        Assert.Contains(
            ping.Requests,
            request => request.Operation == "SendMacroPing" &&
                request.Arguments.SequenceEqual([(byte?)2, "focus"]));
    }

