    [Fact]
    public void QuestSessionCompleteNamespaceMatchesNativeCommandContracts()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "1:nil",
            session.Lua.Evaluate(
                "(function() local details=C_QuestSession.GetSessionBeginDetails(); " +
                "return select('#',C_QuestSession.GetSessionBeginDetails())..':'.." +
                "tostring(details) end)()"));

        session.Lua.QuestSession.CanStart = true;
        session.Lua.QuestSession.CanStop = true;
        session.Lua.QuestSession.HasJoined = true;
        session.Lua.QuestSession.BeginDetails =
            new WowQuestSessionPlayerDetailsState(
                "Party member",
                "Player-1-0001");

        Assert.Equal(
            "1:1:true:false:true:false:Party member:1:nil",
            session.Lua.Evaluate(
                "(function() " +
                "local badTrack=pcall(C_QuestSession.SetQuestIsSuperTracked,42); " +
                "local goodTrack=pcall(C_QuestSession.SetQuestIsSuperTracked,42,true); " +
                "local badResponse=pcall(C_QuestSession.SendSessionBeginResponse); " +
                "C_QuestSession.RequestSessionStart(); " +
                "C_QuestSession.RequestSessionStop(); " +
                "local details=C_QuestSession.GetSessionBeginDetails(); " +
                "C_QuestSession.SendSessionBeginResponse(true); " +
                "local cleared=C_QuestSession.GetSessionBeginDetails(); " +
                "return table.concat({" +
                "C_QuestSession.GetAvailableSessionCommand()," +
                "C_QuestSession.GetPendingCommand()," +
                "tostring(C_QuestSession.HasPendingCommand())," +
                "tostring(badTrack),tostring(goodTrack),tostring(badResponse)," +
                "details.name,select('#',C_QuestSession.GetSessionBeginDetails())," +
                "tostring(cleared)},':') end)()"));

        Assert.Equal(1U, session.Lua.QuestSession.PendingCommand);
        Assert.Equal(1, session.Lua.QuestSession.StartRequestCount);
        Assert.Equal(0, session.Lua.QuestSession.StopRequestCount);
        Assert.Equal(42, session.Lua.QuestSession.SuperTrackedQuestId);
        Assert.True(session.Lua.QuestSession.LastBeginResponse);

        session.Lua.Evaluate(
            "C_QuestSession.SetQuestIsSuperTracked(42,false)");
        Assert.Null(session.Lua.QuestSession.SuperTrackedQuestId);
    }

