                CreationTime = 40,
                ExpirationTime = 50,
                DefaultStreamId = memberId,
                Creator = member
            }
        ];

        Assert.Equal(
            "false:1:true:false:true:true:false:7,8:1:true:" +
            "12:0xFEDCBA9876543210:Club:Tag:1:true:" +
            "31:0xFEDCBA9876543211:Member:true:1:12:" +
            "1:4:12:31:1:31:1:4:0xFEDCBA9876543211:Candidate:2:3:" +
            "1:7:ticket:0xFEDCBA9876543211:31:false:false",
            session.Lua.Evaluate(
                "local function fields(t) local n=0; for _ in pairs(t) do n=n+1 end; return n end; " +
                "local id='0xFEDCBA9876543210'; " +
                "local club=C_Club.GetClubInfo(id); " +
                "local missingCount=select('#',C_Club.GetClubInfo(99)); " +
                "local member=C_Club.GetMemberInfoForSelf(id); " +
                "local subscribed=C_Club.GetSubscribedClubs(); " +
                "local invitations=C_Club.GetInvitationsForSelf(); " +
                "local candidates=C_Club.GetInvitationCandidates('find',5,-2,true,id); " +
                "local tickets=C_Club.GetTickets(id); " +
                "local avatarMissingCount=select('#',C_Club.GetAvatarIdList(3)); " +
                "return table.concat({" +
                "tostring(C_Club.IsEnabled()),C_Club.IsRestricted()," +
                "tostring(C_Club.DoesAnyCommunityHaveUnreadMessages())," +
                "tostring(C_Club.ShouldAllowClubType(0))," +
                "tostring(C_Club.ShouldAllowClubType(1))," +
                "tostring(C_Club.ShouldAllowClubType(2))," +
                "tostring(C_Club.ShouldAllowClubType(3))," +
                "table.concat(C_Club.GetAvatarIdList(2),',')," +
                "avatarMissingCount,tostring(C_Club.GetAvatarIdList(3)==nil)," +
                "fields(club),club.clubId,club.name,club.shortName," +
                "missingCount,tostring(C_Club.GetClubInfo(99)==nil)," +
                "fields(member),member.memberId,member.name,tostring(member.isSelf)," +
                "#subscribed,fields(subscribed[1]),#invitations,fields(invitations[1])," +
                "fields(invitations[1].club),fields(invitations[1].inviter)," +
                "#invitations[1].leaders,fields(invitations[1].leaders[1])," +
                "#candidates,fields(candidates[1]),candidates[1].memberId," +
                "candidates[1].name,candidates[1].priority,candidates[1].status," +
                "#tickets,fields(tickets[1]),tickets[1].ticketId," +
                "tickets[1].defaultStreamId,fields(tickets[1].creator)," +
                "tostring(pcall(C_Club.GetClubInfo,'0x0000000000000001'))," +
                "tostring(pcall(C_Club.GetInvitationCandidates,nil,nil,nil,1,id))},':')"));

        Assert.Equal(
            "0:0:0:0",
            session.Lua.Evaluate(
                "return table.concat({" +
                "select('#',C_Club.RequestTickets('0xFEDCBA9876543210'))," +
                "select('#',C_Club.ClearAutoAdvanceStreamViewMarker())," +
                "select('#',C_Club.ClearClubPresenceSubscription('ignored'))," +
                "select('#',C_Club.Flush())},':')"));
        Assert.Equal([clubId], clubs.TicketRequests);
        Assert.Equal(
            new WowClubInvitationCandidateQuery(
                "find",
                5,
                -2,
                true,
                clubId),
            Assert.Single(clubs.InvitationCandidateQueries));
        Assert.Equal(1, clubs.ClearAutoAdvanceStreamViewMarkerRequests);
        Assert.Equal(1, clubs.ClearClubPresenceSubscriptionRequests);
        Assert.Equal(1, clubs.FlushRequests);
    }

