    [Fact]
    public void LegacyGarrisonStateCommandsAndInteractionClosuresMatchNative()
    {
        using var session = new EmulatorSession();
        var garrison = session.Lua.Garrison;
        var interactions = session.Lua.PlayerInteractions;
        garrison.CanGenerateRecruits = true;
        garrison.CanSetRecruitmentPreference = true;
        garrison.FollowerCountsByType[4] = 12;
        garrison.FollowerCountsByType[22] = 3;
        garrison.GarrisonInfoByType[2] =
            new WowGarrisonInfoState(3, "Fort", .25f, .75f);
        garrison.GarrisonInfoByType[3] =
            new WowGarrisonInfoState(1);
        garrison.GarrisonIdsByFollowerType[4] = 100;

        Assert.Equal(
            "true:true:12:3:12:4:3:Fort:0.25:0.75:1:0:0:false",
            session.Lua.Evaluate(
                "local level,name,x,y=C_Garrison.GetGarrisonInfo(2); " +
                "return table.concat({" +
                "tostring(C_Garrison.CanGenerateRecruits())," +
                "tostring(C_Garrison.CanSetRecruitmentPreference())," +
                "C_Garrison.GetNumFollowers(),C_Garrison.GetNumFollowers(22)," +
                "C_Garrison.GetNumFollowers('not-a-number')," +
                "select('#',C_Garrison.GetGarrisonInfo(2)),level,name,x,y," +
                "select('#',C_Garrison.GetGarrisonInfo(3))," +
                "select('#',C_Garrison.GetGarrisonInfo(999))," +
                "select('#',C_Garrison.RequestGarrisonUpgradeable(4))," +
                "tostring(pcall(C_Garrison.RequestGarrisonUpgradeable,999))},':')"));
        Assert.Equal([4], garrison.GarrisonUpgradeableRequests);

        session.Lua.Evaluate(
            "C_Garrison.RequestLandingPageShipmentInfo(); " +
            "C_Garrison.RequestLandingPageShipmentInfo()");
        Assert.Equal(2, garrison.LandingPageShipmentInfoRequestCount);

        interactions.HasActiveInteraction = true;
        interactions.CurrentInteractionType = 30;
        Assert.Equal(
            "0",
            session.Lua.Evaluate("select('#',C_Garrison.CloseArchitect())"));
        Assert.False(interactions.HasActiveInteraction);
        Assert.Equal(30, interactions.LastClearInteractionType);

        interactions.HasActiveInteraction = true;
        interactions.CurrentInteractionType = 99;
        var requestsBeforeMissionClose = interactions.ClearInteractionRequests;
        session.Lua.Evaluate("C_Garrison.CloseMissionNPC()");
        Assert.Equal(
            requestsBeforeMissionClose,
            interactions.ClearInteractionRequests);
        Assert.True(interactions.HasActiveInteraction);

        interactions.CurrentInteractionType = 32;
        session.Lua.Evaluate("C_Garrison.CloseMissionNPC()");
        Assert.False(interactions.HasActiveInteraction);
        Assert.Equal(32, interactions.LastClearInteractionType);

        interactions.HasActiveInteraction = true;
        interactions.CurrentInteractionType = 31;
        session.Lua.Evaluate("C_Garrison.CloseGarrisonTradeskillNPC()");
        Assert.False(interactions.HasActiveInteraction);
        Assert.Equal(31, interactions.LastClearInteractionType);

        interactions.HasActiveInteraction = true;
        interactions.CurrentInteractionType = 99;
        session.Lua.Evaluate(
            "C_Garrison.CloseTalentNPC(); " +
            "C_Garrison.CloseTradeskillCrafter(); " +
            "C_Garrison.CloseRecruitmentNPC()");
        Assert.True(interactions.HasActiveInteraction);
        Assert.Equal(34, interactions.LastClearInteractionType);
    }

