    [Fact]
    public void BlizzardPanelConnectionPlayerModelSceneRecentAlliesAndPvpApisRetainTypedState()
    {
        using var session = new EmulatorSession();
        session.Lua.Client.RealmId = 57;
        session.Lua.Client.NativeRealmId = 58;
        session.Lua.Client.RealmName = "Emulator Realm";
        session.Lua.PlayerScript.SheathState = 1;
        session.Lua.Pvp.BattlemasterOpen = true;
        session.Lua.RecentAllies.IsSupported = true;
        session.Lua.RecentAllies.IsEnabled = true;
        session.Lua.RecentAllies.IsDataReady = true;
        session.Lua.RecentAllies.Allies.Add(
            new WowRecentAllyState
            {
                Guid = "Player-1-2",
                Name = "Ally",
                FullName = "Ally-Emulator",
                RealmName = "Emulator",
                Level = 80,
                ClassId = 8,
                RaceId = 1,
                Sex = 2
            });

        Assert.Equal(
            "57:58:Emulator Realm:1:true:true:1:Ally:false:0",
            session.Lua.Evaluate(
                "(function() local scene=CreateFrame('ModelScene',nil,UIParent); " +
                "scene:SetLightDirection(1,2,3); scene:SetLightPosition(4,5,6); " +
                "scene:SetLightType(1); C_RecentAllies.TryRequestRecentAlliesData(); " +
                "local allies=C_RecentAllies.GetRecentAllies(); ClearBattlemaster(); " +
                "return table.concat({GetRealmID(),GetNativeRealmID(),GetRealmName()," +
                "GetSheathState(),tostring(C_RecentAllies.IsSystemSupported())," +
                "tostring(C_RecentAllies.IsRecentAllyDataReady()),#allies," +
                "allies[1].characterData.name,tostring(C_RecentAllies.IsRecentAllyPinned('Player-1-2'))," +
                "select('#',ClearBattlemaster())},':') end)()"));

        var scene = session.Ui.Objects.Values.Last(value => value.ObjectType == "ModelScene");
        Assert.Equal(
            System.Numerics.Vector3.Normalize(new System.Numerics.Vector3(1, 2, 3)),
            scene.ModelScene!.LightDirection);
        Assert.Equal(new System.Numerics.Vector3(4, 5, 6), scene.ModelScene.LightPosition);
        Assert.Equal(1, scene.ModelScene.LightType);
        Assert.False(session.Lua.Pvp.BattlemasterOpen);
        Assert.Equal(1, session.Lua.RecentAllies.DataRequests);
    }

    [Fact]
    public void RecentAlliesPreserveNativeRecordShapesGatesAndRequests()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "false:false:0:0",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(C_RecentAllies.IsSystemSupported())," +
                "tostring(C_RecentAllies.IsSystemEnabled())," +
                "select('#',C_RecentAllies.GetRecentAllies())," +
                "select('#',C_RecentAllies.IsRecentAllyDataReady())},':')"));

        var recent = session.Lua.RecentAllies;
        recent.IsSupported = true;
        recent.IsEnabled = true;
        var ally = new WowRecentAllyState
        {
            Guid = "Player-1-2",
            Name = "Ally",
            FullName = "Ally-Realm",
            RealmName = "Realm",
            Level = 80,
            ClassId = 8,
            RaceId = 1,
            Sex = 2,
            IsOnline = true,
            IsDnd = true,
            PinExpirationDate = 123456,
            FriendRequestSentThisSession = true,
            CurrentLocation = "Dornogal",
            Note = "cached note"
        };
        ally.Interactions.Add(
            new WowRecentAllyInteractionState(
                3,
                "Mythic+",
                777,
                new WowRecentAllyInteractionContextState(
                    19019,
                    "The Stonevault",
                    23,
                    12)));
        recent.Allies.Add(ally);

        Assert.Equal(
            "1:true:true:false:false:123456:true:Dornogal:" +
            "Player-1-2:Ally:Ally-Realm:Realm:80:8:1:2:" +
            "1:3:Mythic+:777:19019:The Stonevault:23:12:cached note:" +
            "false:false:true:true:nil:1:1:false:false",
            session.Lua.Evaluate(
                "local allies=C_RecentAllies.GetRecentAllies();" +
                "local a=allies[1]; local i=a.interactionData.interactions[1];" +
                "local byGuid=C_RecentAllies.GetRecentAllyByGUID('Player-1-2');" +
                "local byName=C_RecentAllies.GetRecentAllyByFullName('Ally-Realm');" +
                "C_RecentAllies.SetRecentAllyNote('Player-1-2','new note');" +
                "C_RecentAllies.SetRecentAllyPinned('Player-1-2',false);" +
                "C_RecentAllies.TryRequestRecentAlliesData();" +
                "local badGuid=pcall(C_RecentAllies.IsRecentAllyByGUID,{});" +
                "local badPin=pcall(C_RecentAllies.SetRecentAllyPinned,'Player-1-2',1);" +
                "return table.concat({" +
                "#allies,tostring(a.stateData.isOnline),tostring(a.stateData.isDND)," +
                "tostring(a.stateData.isAFK),tostring(a.stateData.pinExpirationDate==nil)," +
                "a.stateData.pinExpirationDate," +
                "tostring(a.stateData.friendRequestSentThisSession)," +
                "a.stateData.currentLocation,a.characterData.guid,a.characterData.name," +
                "a.characterData.fullName,a.characterData.realmName,a.characterData.level," +
                "a.characterData.classID,a.characterData.raceID,a.characterData.sex," +
                "#a.interactionData.interactions,i.type,i.description,i.timestamp," +
                "i.contextData.itemID,i.contextData.locationName," +
                "i.contextData.activityDifficultyID,i.contextData.activityDifficultyLevel," +
                "a.interactionData.note,tostring(byGuid==a),tostring(byName==a)," +
                "tostring(C_RecentAllies.IsRecentAllyByGUID('Player-1-2'))," +
                "tostring(C_RecentAllies.IsRecentAllyByFullName('Ally-Realm'))," +
                "tostring(C_RecentAllies.GetRecentAllyByGUID('Player-9-9'))," +
                "select('#',C_RecentAllies.GetRecentAllyByGUID('Player-9-9'))," +
                "select('#',C_RecentAllies.GetRecentAllyByFullName('Missing'))," +
                "tostring(badGuid),tostring(badPin)},':')"));

        Assert.Equal(
            [new WowRecentAllyNoteRequest("Player-1-2", "new note")],
            recent.NoteRequests);
        Assert.Equal(
            [new WowRecentAllyPinnedRequest("Player-1-2", false)],
            recent.PinnedRequests);
        Assert.Equal("cached note", ally.Note);
        Assert.Equal(123456, ally.PinExpirationDate);
        Assert.Equal(1, recent.DataRequests);
    }

