    [Fact]
    public void ClickBindingsMatchNativeValidationCanonicalizationAndInteractionSemantics()
    {
        using var session = new EmulatorSession();
        session.Lua.ClickBindings.AssumePositiveSpellIdsAreClickBindable = false;
        session.Lua.ClickBindings.ClickBindableSpellIds.Add(80);

        Assert.Equal(
            "4:LeftButton:MiddleButton:RightButton:Button4:80:12:1:3:LeftButton:RightButton:nil:1:" +
            "true:false:false:false:4",
            session.Lua.Evaluate(
                "(function() " +
                "C_ClickBindings.SetProfileByInfo({" +
                "{type=3,actionID=1,button='RightButton',modifiers=4}," +
                "{type=3,actionID=1,button='LeftButton',modifiers=0}," +
                "{type=3,actionID=2,button='Button4',modifiers=1}," +
                "{type=1,actionID=80,button='leftbutton',modifiers=2}," +
                "{type=1,actionID=81,button='Button5',modifiers=0}," +
                "{type=2,actionID=11,button='MiddleButton',modifiers=3}," +
                "{type=2,actionID=12,button='middlebutton',modifiers=3}," +
                "{type=0,actionID=1,button='Button6',modifiers=0}," +
                "{type=2,actionID=10,button='NotAButton',modifiers=0}}); " +
                "local profile=C_ClickBindings.GetProfileInfo(); " +
                "local target=C_ClickBindings.GetEffectiveInteractionButton('rightbutton',4); " +
                "local context=C_ClickBindings.GetEffectiveInteractionButton('Button4',1); " +
                "local ordinary=C_ClickBindings.GetEffectiveInteractionButton('LeftButton',2); " +
                "local ordinaryCount=select('#',C_ClickBindings.GetEffectiveInteractionButton('LeftButton',2)); " +
                "local profileOk=pcall(C_ClickBindings.SetProfileByInfo,{{type=1}}); " +
                "local keyOk=pcall(C_ClickBindings.GetBindingType,'LeftButton',-1); " +
                "local executeOk=pcall(C_ClickBindings.ExecuteBinding,'player','LeftButton'); " +
                "C_ClickBindings.ExecuteBinding('player','leftbutton',2); " +
                "return table.concat({" +
                "#profile,profile[1].button,profile[2].button,profile[3].button,profile[4].button," +
                "profile[1].actionID,profile[2].actionID," +
                "C_ClickBindings.GetBindingType('LEFTBUTTON',2)," +
                "C_ClickBindings.GetBindingType('RightButton',4)," +
                "target,context,tostring(ordinary),ordinaryCount," +
                "tostring(C_ClickBindings.CanSpellBeClickBound('|Hspell:80|h'))," +
                "tostring(C_ClickBindings.CanSpellBeClickBound(81))," +
                "tostring(profileOk),tostring(keyOk),#C_ClickBindings.GetProfileInfo()},':') end)()"));

        Assert.Equal(
            new WowExecutedClickBindingState("player", "LeftButton", 2, 1, 80),
            session.Lua.ClickBindings.LastExecutedBinding);

        session.Lua.Client.InCombatLockdown = true;
        session.Lua.Evaluate("C_ClickBindings.ExecuteBinding('mouseover','LeftButton',2)");
        Assert.Equal(
            new WowExecutedClickBindingState("player", "LeftButton", 2, 1, 80),
            session.Lua.ClickBindings.LastExecutedBinding);
    }

