    [Fact]
    public void FriendListActionsValidateAndRecordNativeRequests()
    {
        using var session = new EmulatorSession();
        session.Lua.Friends.Friends.Add(
            new WowFriendInfoState(
                "Friend",
                true,
                null,
                null,
                null,
                "Player-1",
                80,
                false,
                false,
                0));
        session.Lua.Friends.Ignores.Add("Ignored");

        Assert.Equal(
            "false:true:true:false:false:false:true",
            session.Lua.Evaluate(
                "C_FriendList.AddFriend('New Friend','note');" +
                "C_FriendList.AddFriend('No Note');" +
                "local duplicate=C_FriendList.AddIgnore('Ignored');" +
                "local added=C_FriendList.AddIgnore('New Ignore');" +
                "local removed=C_FriendList.DelIgnore('Ignored');" +
                "local missing=C_FriendList.DelIgnore('missing');" +
                "C_FriendList.DelIgnoreByIndex(1);" +
                "C_FriendList.RemoveFriendByIndex(1);" +
                "C_FriendList.SendWho('mage',3);" +
                "C_FriendList.SendWho('warrior');" +
                "C_FriendList.ShowFriends();" +
                "C_FriendList.SortWho('level');" +
                "local missingWhoToUi=pcall(C_FriendList.SetWhoToUi);" +
                "local badFriend=pcall(C_FriendList.AddFriend,{});" +
                "C_FriendList.SetWhoToUi(1);" +
                "return table.concat({" +
                "tostring(duplicate),tostring(added),tostring(removed)," +
                "tostring(missing),tostring(missingWhoToUi),tostring(badFriend)," +
                "tostring(C_FriendList.GetNumFriends()==1 and " +
                "C_FriendList.GetNumIgnores()==1)},':')"));

        Assert.Equal(
            [
                new WowAddFriendRequest("New Friend", "note"),
                new WowAddFriendRequest("No Note", null)
            ],
            session.Lua.Friends.AddFriendRequests);
        Assert.Equal(["New Ignore"], session.Lua.Friends.AddIgnoreRequests);
        Assert.Equal(
            ["Ignored", "Ignored"],
            session.Lua.Friends.RemoveIgnoreRequests);
        Assert.Equal(["Player-1"], session.Lua.Friends.RemoveFriendRequests);
        Assert.Equal(
            [new WowWhoRequest("mage", 3), new WowWhoRequest("warrior", null)],
            session.Lua.Friends.WhoRequests);
        Assert.Equal(["level"], session.Lua.Friends.WhoSortRequests);
        Assert.Equal(1, session.Lua.Friends.ShowFriendsRequests);
        Assert.True(session.Lua.Friends.WhoResultsToUi);
    }

