    [Fact]
    public void LegacyBattleNetCommandsValidateAndRecordNativeRequests()
    {
        using var session = new EmulatorSession();
        var friends = session.Lua.Friends;
        friends.BattleNetAccountId = 11;
        friends.BattleNetFriends.Add(
            new WowBattleNetFriendState(100, "Friend", true, false));
        friends.BattleNetBlockedAccounts.Add(
            new WowBattleNetBlockedState(200, "Blocked"));
        friends.BattleNetFriendInvites.Add(
            new WowBattleNetFriendInviteState(300, "Invite", false, 7));

        Assert.Equal(
            "0:0:0:true:1:1:false:false:false",
            session.Lua.Evaluate(
                "local guildResults=select('#',BNCheckBattleTagInviteToGuildMember('Guildie'));" +
                "local unitResults=select('#',BNCheckBattleTagInviteToUnit('party1'));" +
                "local recentResults=select('#'," +
                "C_BattleNet.BNCheckBattleTagInviteToRecentAlly('Player-1-2'));" +
                "BNSendFriendInvite('Target#1234');" +
                "BNSendFriendInvite('not-an-address');" +
                "BNSendFriendInviteByID(100);" +
                "BNDeclineFriendInvite(300);" +
                "BNSetBlocked(100,true);" +
                "BNSetFriendNote(100,'note');" +
                "BNSetFriendFavoriteFlag(100,true);" +
                "BNSetSelectedFriend(1);" +
                "BNSetSelectedBlock(1);" +
                "BNSummonFriendByIndex(1);" +
                "local fof=BNRequestFOFInfo(100);" +
                "BNRequestInviteFriend(100,true,false,true);" +
                "local badBlock=pcall(BNSetBlocked,100);" +
                "local badFriend=pcall(BNSetSelectedFriend,2);" +
                "local badBlocked=pcall(BNGetBlockedInfo,2);" +
                "return table.concat({" +
                "guildResults,unitResults,recentResults,tostring(fof)," +
                "BNGetSelectedBlock(),BNGetFriendIndex(100)," +
                "tostring(badBlock),tostring(badFriend),tostring(badBlocked)},':')"));

        Assert.Equal(["Guildie"], friends.BattleNetGuildMemberInviteChecks);
        Assert.Equal(["party1"], friends.BattleNetUnitInviteChecks);
        Assert.Equal(["Player-1-2"], friends.BattleNetRecentAllyInviteChecks);
        Assert.Equal(["Target#1234"], friends.BattleNetFriendInviteRequests);
        Assert.Equal([100u], friends.BattleNetFriendInviteByIdRequests);
        Assert.Equal([300u], friends.BattleNetDeclineFriendInviteRequests);
        Assert.Equal(
            [new WowBattleNetBlockedRequest(100, true)],
            friends.BattleNetBlockedRequests);
        Assert.Equal(
            [new WowBattleNetFriendNoteRequest(100, "note")],
            friends.BattleNetFriendNoteRequests);
        Assert.Equal(
            [new WowBattleNetFavoriteRequest(100, true)],
            friends.BattleNetFavoriteRequests);
        Assert.Equal([100u], friends.BattleNetSummonFriendRequests);
        Assert.Equal([100u], friends.BattleNetFofRequests);
        Assert.Equal(
            [new WowBattleNetInviteRoleRequest(100, true, false, true)],
            friends.BattleNetInviteRoleRequests);
        Assert.Equal(1, friends.SelectedBattleNetFriend);
        Assert.Equal(200u, friends.SelectedBattleNetBlockedAccountId);
    }

