    [Fact]
    public void PassThroughButtonsRouteOnlyRegisteredClicksToUnderlyingFrames()
    {
        using var session = new EmulatorSession();
        session.Lua.Evaluate(
            "passThroughBottomClicks=0; passThroughTopClicks=0; " +
            "local bottom=CreateFrame('Button','PassThroughBottom',UIParent); " +
            "bottom:SetSize(100,100); bottom:SetPoint('CENTER'); bottom:EnableMouse(true); " +
            "bottom:SetScript('OnClick',function() passThroughBottomClicks=passThroughBottomClicks+1 end); " +
            "local top=CreateFrame('Button','PassThroughTop',UIParent); " +
            "top:SetAllPoints(bottom); top:EnableMouse(true); " +
            "top:SetPassThroughButtons('Button1'); " +
            "top:SetScript('OnClick',function() passThroughTopClicks=passThroughTopClicks+1 end)");

        var center = session.Ui.ResolveBounds(session.Ui.Find("PassThroughTop")!.Id).Center;
        session.MouseMove(center.X, center.Y);
        session.MouseButton("LeftButton", true);
        session.MouseButton("LeftButton", false);

        Assert.Equal(
            "1:0:true:false",
            session.Lua.Evaluate(
                "return table.concat({passThroughBottomClicks,passThroughTopClicks," +
                "tostring(PassThroughTop:ShouldButtonPassThrough('LeftButton'))," +
                "tostring(PassThroughTop:ShouldButtonPassThrough('RightButton'))},':')"));
    }

