    [Fact]
    public void FontStringNativeVisualStateMethodsRoundTripAndValidate()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "-1:0:-2:3:-1:0:0.25:true:1:false:false:0:0:0:true",
            session.Lua.Evaluate(
                "(function() local text=UIParent:CreateFontString('NativeVisualFontString'); " +
                "text:SetFont('Fonts\\\\FRIZQT__.TTF',12,''); text:SetText('clear me'); " +
                "local initialStart,initialLength=text:GetAlphaGradient(); " +
                "text:SetAlphaGradient(-2,3); local start,length=text:GetAlphaGradient(); " +
                "text:ClearAlphaGradient(); local clearStart,clearLength=text:GetAlphaGradient(); " +
                "text:SetRotation(.25); text:SetSmoothScaling(true); " +
                "text:SetScaleAnimationMode(1); text:SetFixedColor(true); " +
                "local missingSmooth=pcall(text.SetSmoothScaling,text); " +
                "local invalidMode=pcall(text.SetScaleAnimationMode,text,2); " +
                "local colorsReturns=select('#',text:OnColorsUpdated()); " +
                "local fixedReturns=select('#',text:SetFixedColor(true)); " +
                "local clearTextReturns=select('#',text:ClearText()); " +
                "return table.concat({initialStart,initialLength,start,length,clearStart,clearLength," +
                "text:GetRotation(),tostring(text:GetSmoothScaling()),text:GetScaleAnimationMode()," +
                "tostring(missingSmooth),tostring(invalidMode),colorsReturns,fixedReturns," +
                "clearTextReturns,tostring(text:GetText()==nil)},':') end)()"));

        var text = session.Ui.Find("NativeVisualFontString")!;
        Assert.Equal(0.25f, text.FontRotation);
        Assert.True(text.FontSmoothScaling);
        Assert.Equal((byte)1, text.FontScaleAnimationMode);
        Assert.True(text.FontFixedColor);
        Assert.Equal(ushort.MaxValue, text.FontAlphaGradientStart);
        Assert.Equal((ushort)0, text.FontAlphaGradientLength);
    }

