            session.Lua.Evaluate(
                "(function() " +
                "local badGuid=select(1,pcall(C_SocialQueue.GetGroupInfo,7)); " +
                "local missingGuid=select(1,pcall(C_SocialQueue.GetGroupInfo)); " +
                "local badPriority=select(1,pcall(C_SocialQueue.SignalToastDisplayed,'Group-1',0/0)); " +
                "local join=C_SocialQueue.RequestToJoin('Group-1'); " +
                "local toastCount=select('#',C_SocialQueue.SignalToastDisplayed('Group-1','3.5')); " +
                "return table.concat({#C_SocialQueue.GetAllGroups()," +
                "select('#',C_SocialQueue.GetConfig())," +
