                "local pg,solo=C_SocialQueue.GetGroupForPlayer('Player-1'); " +
                "local canJoin,numQueues,needTank,needHealer,needDamage,isSolo,quest,leader=" +
                "C_SocialQueue.GetGroupInfo('Group-1'); " +
                "local m=C_SocialQueue.GetGroupMembers('Group-1'); " +
                "local q=C_SocialQueue.GetGroupQueues('Group-1'); local d=q[1].queueData; " +
                "return table.concat({n,tostring(c.TOASTS_DISABLED),c.TOAST_DURATION," +
                "#defaults,defaults[1],#all,all[1],all[2],pg,tostring(solo)," +
                "select('#',C_SocialQueue.GetGroupInfo('Group-1')),tostring(canJoin),numQueues," +
                "tostring(needTank),tostring(needHealer),tostring(needDamage),tostring(isSolo)," +
                "tostring(quest),leader,#m,m[1].guid,m[1].clubId,m[2].guid,m[2].clubId," +
                "#q,q[1].clientID,tostring(q[1].eligible),tostring(q[1].needTank)," +
                "tostring(q[1].needHealer),tostring(q[1].needDamage),tostring(q[1].isAutoAccept)," +
                "d.queueType,#d.lfgIDs,d.lfgIDs[1],d.lfgIDs[2],d.lfgListID,d.activityID," +
                "d.battlefieldType,d.listID,d.mapName,tostring(d.rated),tostring(d.isBrawl)," +
                "d.teamSize,tostring(C_SocialQueue.RequestToJoin('Group-1',true,nil,1))},':') end)()"));

        Assert.Equal(
            new object?[] { "Group-1", true, false, true },
            Assert.Single(session.Lua.SocialQueue.Requests).Arguments);
    }

