                "tostring(validName),tostring(validGuid)},':')"));

        Assert.Equal(2, guild.RankOrderByGuid["Player-1-1"]);
        Assert.False(guild.RankOrderByGuid.ContainsKey("Player-1-2"));
        Assert.Equal(
            new WowGuildNote("Public note", true),
            guild.NotesByGuid["Player-1-1"]);
        Assert.Contains(
            guild.Requests,
            request =>
                request.Operation == "QueryGuildMemberRecipes" &&
                request.Arguments.SequenceEqual(
                    ["Player-1-1", 164]));
        Assert.Contains(
            guild.Requests,
            request =>
                request.Operation == "QueryGuildMembersForRecipe" &&
                request.Arguments.SequenceEqual([164, 1001, 3]));
    }

    [Fact]
    public void LegacyGuildGlobalsFollowNativeCountsTypesAndLocalState()
    {
        using var session = new EmulatorSession();
        var guild = session.Lua.Guild;
        guild.IsInGuild = true;
        guild.IsGuildLeader = true;
        guild.CanGuildInvite = true;
        guild.GuildRenameRequired = true;
        guild.GuildRankCount = 5;
        guild.GuildBankTabCount = 3;
        guild.CurrentGuildBankTab = 2;
        guild.GuildFactionGroup = 1;
        guild.GuildPerkCount = 4;
        guild.GuildNewsFilterMask = (1 << 0) | (1 << 8);
        guild.LegacyTabardFileIds = [10, null, 30, 40, 50, 60];

        Assert.Equal(
            "true:true:true:true:5:3:2:1:4:6:10:nil:60:" +
            "9:true:true:3:false:false",
            session.Lua.Evaluate(
                "local a,b,c,d,e,f=GetGuildTabardFiles(); " +
                "local filters={GetGuildNewsFilters()}; " +
                "GuildControlSetRank(3); " +
                "SetGuildNewsFilter(2,1); SetGuildNewsFilter(1,0); " +
                "QueryGuildEventLog(); RequestGuildRewards(); " +
                "RequestGuildChallengeInfo(); DeclineGuild(); " +
                "local numericFilter=pcall(SetGuildNewsFilter,1,true); " +
                "local requiredRank=pcall(GuildControlSetRank); " +
                "return table.concat({" +
                "tostring(IsInGuild()),tostring(IsGuildLeader())," +
                "tostring(CanGuildInvite())," +
                "tostring(GetGuildRenameRequired())," +
                "GuildControlGetNumRanks(),GetNumGuildBankTabs()," +
                "GetCurrentGuildBankTab(),GetGuildFactionGroup()," +
                "GetNumGuildPerks(),select('#',GetGuildTabardFiles())," +
                "a,tostring(b),f,#filters,tostring(filters[1])," +
                "tostring(filters[9])," +
                "tostring(" +
                "GuildControlGetNumRanks() >= 3 and 3 or 0)," +
                "tostring(numericFilter),tostring(requiredRank)},':')"));

        Assert.Equal(3, guild.SelectedGuildRankOrder);
        Assert.Equal((1 << 1) | (1 << 8), guild.GuildNewsFilterMask);
        Assert.Contains(
            guild.Requests,
            request => request.Operation == "QueryGuildEventLog");
        Assert.Contains(
            guild.Requests,
            request => request.Operation == "RequestGuildRewards");
        Assert.Contains(
            guild.Requests,
            request => request.Operation == "RequestGuildChallengeInfo");
        Assert.Contains(
            guild.Requests,
            request => request.Operation == "DeclineGuild");
    }

