                "local badOrder=pcall(GetLFDChoiceOrder,7);" +
                "local looseQueued=pcall(GetLFGQueuedList,2,7);" +
                "local looseEnabled=pcall(GetLFDChoiceEnabledState,7);" +
                "return table.concat({" +
                "select('#',GetLFGDeserterExpiration())," +
                "GetLFGDeserterExpiration(),tostring(leader)," +
