    [Fact]
    public void PlayerChoiceMatchesNativeRecordsEnumsAndCommands()
    {
        using var session = new EmulatorSession();
        var playerChoice = session.Lua.PlayerChoice;
        playerChoice.NumRerolls = 2;
        playerChoice.RemainingTime = 20;
        playerChoice.WaitingForResponse = true;

        var info = new WowPlayerChoiceInfo
        {
            ObjectGuid = "Creature-0-1",
            ChoiceId = 9,
            QuestionText = "Question",
            PendingChoiceText = "Pending",
            UiTextureKit = "top-kit",
            HideWarboardHeader = true,
            KeepOpenAfterChoice = false,
            ShowChoicesAsList = true,
            RequiresSelection = true,
            ShowChoicesAsGrid = false,
            SoundKitId = 101,
            CloseUiSoundKitId = 102
        };
        var option = new WowPlayerChoiceOptionInfo
        {
            Id = 7,
            Description = "Description",
            Header = "Header",
            ChoiceArtId = 88,
            DesaturatedArt = true,
            DisabledOption = false,
            HasRewards = true,
            UiTextureKit = "option-kit",
            MaxStacks = 4,
            WidgetSetId = 11,
            SpellId = 12,
            Rarity = 3,
            TypeArtId = 13,
            HeaderIconAtlasElement = "atlas-element",
            SubHeader = "Sub",
            ConsolidateWidgets = true
        };
        option.Buttons.Add(
            new WowPlayerChoiceButtonInfo
            {
                Id = 55,
                Text = "Choose",
                Disabled = false,
                ShowCheckmark = true,
                HideButtonShowText = false,
                Selected = true,
                Confirmation = "Confirm",
                Tooltip = "Tip",
                RewardQuestId = 90,
                SoundKitId = 91,
                ListText = "List"
            });
        option.RewardInfo.CurrencyRewards.Add(
            new WowPlayerChoiceCurrencyReward(1, "Currency", 2, 3, true));
        option.RewardInfo.ItemRewards.Add(
            new WowPlayerChoiceItemReward(4, "Item", 5));
        option.RewardInfo.ReputationRewards.Add(
            new WowPlayerChoiceReputationReward(6, 7));
        info.Options.Add(option);
        playerChoice.CurrentChoice = info;

        Assert.Equal(
            "Creature-0-1:9:Question:Pending:top-kit:true:false:true:true:" +
            "false:1:7:Description:Header:88:true:false:true:option-kit:4:" +
            "11:12:3:13:atlas-element:Sub:true:1:55:Choose:false:true:" +
            "false:true:Confirm:Tip:90:91:List:1:1:Currency:2:3:true:1:" +
            "4:Item:5:1:6:7:2:20:false:0:0:0:false:false:0:0:1:2:3:0:3",
            session.Lua.Evaluate(
                "local i=C_PlayerChoice.GetCurrentPlayerChoiceInfo();" +
                "local o=i.options[1]; local b=o.buttons[1];" +
                "local c=o.rewardInfo.currencyRewards[1];" +
                "local item=o.rewardInfo.itemRewards[1];" +
                "local rep=o.rewardInfo.repRewards[1];" +
                "local missing=pcall(C_PlayerChoice.SendPlayerChoiceResponse);" +
                "local wrong=pcall(C_PlayerChoice.SendPlayerChoiceResponse,false);" +
                "local ignored=select('#'," +
                "C_PlayerChoice.SendPlayerChoiceResponse(-1));" +
                "local reroll=select('#'," +
                "C_PlayerChoice.RequestRerollPlayerChoice());" +
                "local sent=select('#'," +
                "C_PlayerChoice.SendPlayerChoiceResponse('55.9'));" +
                "local closed=select('#',C_PlayerChoice.OnUIClosed());" +
                "return table.concat({" +
                "i.objectGUID,i.choiceID,i.questionText,i.pendingChoiceText," +
                "i.uiTextureKit,tostring(i.hideWarboardHeader)," +
                "tostring(i.keepOpenAfterChoice)," +
                "tostring(i.showChoicesAsList)," +
                "tostring(i.requiresSelection)," +
                "tostring(i.showChoicesAsGrid),#i.options,o.id,o.description," +
                "o.header,o.choiceArtID,tostring(o.desaturatedArt)," +
                "tostring(o.disabledOption),tostring(o.hasRewards)," +
                "o.uiTextureKit,o.maxStacks,o.widgetSetID,o.spellID,o.rarity," +
                "o.typeArtID,o.headerIconAtlasElement,o.subHeader," +
                "tostring(o.consolidateWidgets),#o.buttons,b.id,b.text," +
                "tostring(b.disabled),tostring(b.showCheckmark)," +
                "tostring(b.hideButtonShowText),tostring(b.selected)," +
                "b.confirmation,b.tooltip,b.rewardQuestID,b.soundKitID," +
                "b.listText,#o.rewardInfo.currencyRewards,c.currencyId,c.name," +
                "c.currencyTexture,c.quantity,tostring(c.isCurrencyContainer)," +
                "#o.rewardInfo.itemRewards,item.itemId,item.name,item.quantity," +
                "#o.rewardInfo.repRewards,rep.factionId,rep.quantity," +
                "C_PlayerChoice.GetNumRerolls()," +
                "C_PlayerChoice.GetRemainingTime()," +
                "tostring(C_PlayerChoice.IsWaitingForPlayerChoiceResponse())," +
                "ignored,reroll,sent,tostring(missing),tostring(wrong),closed," +
                "Enum.PlayerChoiceRarity.Common," +
                "Enum.PlayerChoiceRarity.Uncommon," +
                "Enum.PlayerChoiceRarity.Rare," +
                "Enum.PlayerChoiceRarity.Epic," +
                "Enum.PlayerChoiceRarityMeta.MinValue," +
                "Enum.PlayerChoiceRarityMeta.MaxValue},':')"));

        Assert.Equal(1, playerChoice.RerollRequestCount);
        Assert.Equal(1, playerChoice.ResponseRequestCount);
        Assert.Equal(55, playerChoice.LastResponseId);
        Assert.False(playerChoice.WaitingForResponse);
        Assert.Equal(1, playerChoice.UiClosedRequestCount);
        Assert.False(playerChoice.WasWaitingOnLastUiClose);
    }

    [Fact]
    public void SummonInfoMatchesNativeOptionalValuesEnumsAndResponses()
    {
        using var session = new EmulatorSession();
        var summon = session.Lua.SummonInfo;
        summon.AreaName = "Dornogal";
        summon.Summoner = "Mage-Realm";
        summon.ConfirmTimeLeft = 17;
        summon.Reason = 1;
        summon.SkippingStartExperience = true;

        Assert.Equal(
            "Dornogal:Mage-Realm:1:17:1:true:0::1:true:0:0:false:" +
            "0:1:2:0:1",
            session.Lua.Evaluate(
                "local area=C_SummonInfo.GetSummonConfirmAreaName();" +
                "local summoner=C_SummonInfo.GetSummonConfirmSummoner();" +
                "local summonerCount=select('#'," +
                "C_SummonInfo.GetSummonConfirmSummoner());" +
                "local time=C_SummonInfo.GetSummonConfirmTimeLeft();" +
                "local reason=C_SummonInfo.GetSummonReason();" +
                "local skipping=C_SummonInfo." +
                "IsSummonSkippingStartExperience();" +
                "local confirm=select('#',C_SummonInfo.ConfirmSummon());" +
                "return table.concat({area,summoner,summonerCount,time,reason," +
                "tostring(skipping),confirm," +
                "C_SummonInfo.GetSummonConfirmAreaName()," +
                "select('#',C_SummonInfo.GetSummonConfirmSummoner())," +
                "tostring(C_SummonInfo.GetSummonConfirmSummoner()==nil)," +
                "C_SummonInfo.GetSummonConfirmTimeLeft()," +
                "C_SummonInfo.GetSummonReason()," +
                "tostring(C_SummonInfo.IsSummonSkippingStartExperience())," +
                "Enum.SummonReason.Spell,Enum.SummonReason.Scenario," +
                "Enum.SummonReasonMeta.NumValues," +
                "Enum.SummonReasonMeta.MinValue," +
                "Enum.SummonReasonMeta.MaxValue},':')"));

        Assert.Equal(1, summon.AcceptRequestCount);
        Assert.True(summon.LastResponseAccepted);

        summon.AreaName = "Other";
        summon.Summoner = "Warlock";
        summon.ConfirmTimeLeft = -4;
        summon.Reason = 1;
        summon.SkippingStartExperience = true;

        Assert.Equal(
            "0:0::true",
            session.Lua.Evaluate(
                "local before=C_SummonInfo.GetSummonConfirmTimeLeft();" +
                "local count=select('#',C_SummonInfo.CancelSummon('ignored'));" +
                "return table.concat({before,count," +
                "C_SummonInfo.GetSummonConfirmAreaName()," +
                "tostring(C_SummonInfo.GetSummonConfirmSummoner()==nil)},':')"));

        Assert.Equal(1, summon.RejectRequestCount);
        Assert.False(summon.LastResponseAccepted);
    }

