    [Fact]
    public void AdventureJournalMatchesNativeSlotsTablesRewardsAndMutations()
    {
        using var session = new EmulatorSession();
        var journal = session.Lua.AdventureJournal;
        journal.CanBeShown = false;
        journal.AvailableSuggestionCount = 4;
        journal.PrimaryOffset = 1;
        journal.Suggestions.Add(
            new WowAdventureJournalSuggestion
            {
                Title = "First",
                Description = "Desc",
                ButtonText = "Go",
                EncounterJournalInstanceId = 77,
                HideDifficulty = true,
                DifficultyId = 23,
                ExpansionLevel = 10,
                IsRandomDungeon = false,
                IconPath = 123
            });
        journal.Suggestions.Add(null);
        journal.Suggestions.Add(
            new WowAdventureJournalSuggestion
            {
                Title = "Third",
                Description = "Other",
                ButtonText = "Open"
            });
        journal.Rewards[2] = new WowAdventureJournalReward
        {
            ItemLevel = 650,
            MinimumItemLevel = 645,
            MaximumItemLevel = 655,
            IsRewardTable = true,
            ItemId = 19019,
            ItemQuantity = 2,
            ItemIcon = 987,
            ItemLink = "|Hitem:19019|h",
            CurrencyType = 2003,
            CurrencyQuantity = 50,
            CurrencyIcon = 456,
            RewardDescription = "Reward"
        };

        Assert.Equal(
            "false:4:2:true:true:First:Desc:Go:77:true:23:10:" +
            "false:123:true:Third:true:650:645:655:true:19019:2:" +
            "987:|Hitem:19019|h:2003:50:456:Reward:0:false:false:" +
            "false:false:false:true:0",
            session.Lua.Evaluate(
                "local seed={stale=true};" +
                "local suggestions=C_AdventureJournal.GetSuggestions(seed);" +
                "C_AdventureJournal.SetPrimaryOffset(2);" +
                "C_AdventureJournal.SetPrimaryOffset(2);" +
                "C_AdventureJournal.ActivateEntry(3);" +
                "C_AdventureJournal.UpdateSuggestions(true);" +
                "local reward=C_AdventureJournal.GetReward(2);" +
                "local badActivate=pcall(C_AdventureJournal.ActivateEntry,0);" +
                "local missingActivate=pcall(C_AdventureJournal.ActivateEntry);" +
                "local badReward=pcall(C_AdventureJournal.GetReward,4);" +
                "local badOffset=pcall(C_AdventureJournal.SetPrimaryOffset,4);" +
                "local missingOffset=pcall(C_AdventureJournal.SetPrimaryOffset);" +
                "local looseSuggestions,looseTable=pcall(" +
                "C_AdventureJournal.GetSuggestions,7);" +
                "return table.concat({" +
                "tostring(C_AdventureJournal.CanBeShown())," +
                "C_AdventureJournal.GetNumAvailableSuggestions()," +
                "C_AdventureJournal.GetPrimaryOffset()," +
                "tostring(suggestions==seed),tostring(seed.stale==nil)," +
                "suggestions[1].title,suggestions[1].description," +
                "suggestions[1].buttonText,suggestions[1].ej_instanceID," +
                "tostring(suggestions[1].hideDifficulty)," +
                "suggestions[1].difficultyID," +
                "suggestions[1].expansionLevel," +
                "tostring(suggestions[1].isRandomDungeon)," +
                "suggestions[1].iconPath,tostring(suggestions[2]==nil)," +
                "suggestions[3].title," +
                "tostring(suggestions[3].difficultyID==nil)," +
                "reward.itemLevel,reward.minItemLevel,reward.maxItemLevel," +
                "tostring(reward.isRewardTable),reward.itemID," +
                "reward.itemQuantity,reward.itemIcon,reward.itemLink," +
                "reward.currencyType,reward.currencyQuantity," +
                "reward.currencyIcon,reward.rewardDesc," +
                "select('#',C_AdventureJournal.GetReward(1))," +
                "tostring(badActivate),tostring(missingActivate)," +
                "tostring(badReward),tostring(badOffset)," +
                "tostring(missingOffset),tostring(looseSuggestions)," +
                "select('#',C_AdventureJournal.UpdateSuggestions())},':')"));

        Assert.Equal(3, journal.ActivatedEntryIndex);
        Assert.Equal(1, journal.ActivationCount);
        Assert.Equal(1, journal.PrimaryOffsetChangeCount);
        Assert.Equal(2, journal.UpdateSuggestionsRequestCount);
        Assert.False(journal.LastUpdateSuggestionsForce);
    }

