            session.Lua.Evaluate(
                "local missingNameCount=select('#',GetMonitorName({})); " +
                "local name,primary=GetMonitorName('2'); " +
                "local invalidName,invalidPrimary=GetMonitorName(3); " +
                "local createCount=select('#',CreateWindow()); " +
