    [Fact]
    public void SpellTargetingMatchesNativeResultsParsersAndOwnership()
    {
        using var session = new EmulatorSession();
        var targeting = session.Lua.SpellTargeting;
        const ulong followerId = 0xAB;
        targeting.IsTargeting = true;
        targeting.CanTargetGarrisonMission = true;
        targeting.CanTargetItem = true;
        targeting.CanTargetQuest = true;
        targeting.GarrisonFollowerResultById[followerId] = 0;
        targeting.GarrisonFollowerAbilityResult[(followerId, 7)] = 3;
        targeting.CanTargetUnitByToken["target"] = true;

        Assert.Equal(
            "true:0:false:2:false:4:true:true:false:true:true:false:" +
            "true:nil:function",
            session.Lua.Evaluate(
                "local follower,reason=" +
                "SpellCanTargetGarrisonFollower(" +
                "'0x00000000000000AB'); " +
                "local invalid,invalidReason=" +
                "SpellCanTargetGarrisonFollower(123); " +
                "local ability,abilityReason=" +
                "SpellCanTargetGarrisonFollowerAbility(" +
                "'0x00000000000000AB','7.9'); " +
                "return table.concat({" +
                "tostring(follower),reason,tostring(invalid)," +
                "invalidReason,tostring(ability),abilityReason," +
                "tostring(SpellCanTargetGarrisonMission())," +
                "tostring(SpellCanTargetItem())," +
                "tostring(SpellCanTargetItemID())," +
                "tostring(SpellCanTargetQuest())," +
                "tostring(SpellCanTargetUnit('target'))," +
                "tostring(SpellCanTargetUnit('focus'))," +
                "tostring(SpellIsTargeting())," +
                "tostring(SpellTargetBattlePet)," +
                "type(C_PetJournal.SpellTargetBattlePet)" +
                "},':')"));

        Assert.Equal(
            "false:false:false:true",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(pcall(" +
                "SpellCanTargetGarrisonFollowerAbility," +
                "'0x00000000000000AB'))," +
                "tostring(pcall(SpellCanTargetUnit))," +
                "tostring(pcall(SpellTargetUnit,{}))," +
                "tostring(pcall(" +
                "SpellCanTargetGarrisonFollowerAbility," +
                "'bad',7))" +
                "},':')"));

        session.Lua.Evaluate(
            "SpellTargetItem('42'); " +
            "SpellTargetUnit('target'); " +
            "C_PetJournal.SpellTargetBattlePet(" +
            "'BattlePet-0-000000000001')");

        Assert.Equal(
            [
                new WowSpellTargetRequest("SpellTargetItem", 42),
                new WowSpellTargetRequest("SpellTargetUnit", "target"),
                new WowSpellTargetRequest(
                    "SpellTargetBattlePet",
                    "BattlePet-0-000000000001")
            ],
            targeting.TargetRequests);

        targeting.HasPendingTargetingCursor = true;
        Assert.Equal(
            "true:false",
            session.Lua.Evaluate(
                "return tostring(SpellStopTargeting())..':'.." +
                "tostring(SpellStopTargeting())"));
    }

