    [Fact]
    public void MovementControlGlobalsToggleTypedDirectionalState()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "function:function:function",
            session.Lua.Evaluate(
                "return type(MoveForwardStart)..':'..type(StrafeRightStop)..':'.." +
                "type(JumpOrAscendStart)"));

        session.Lua.Evaluate(
            "MoveForwardStart(); TurnLeftStart(); StrafeRightStart(); JumpOrAscendStart()");
        Assert.True(session.Lua.Movement.MovingForward);
        Assert.True(session.Lua.Movement.TurningLeft);
        Assert.True(session.Lua.Movement.StrafingRight);
        Assert.True(session.Lua.Movement.Ascending);

        session.Lua.Evaluate(
            "MoveForwardStop(); TurnLeftStop(); StrafeRightStop(); AscendStop()");
        Assert.False(session.Lua.Movement.MovingForward);
        Assert.False(session.Lua.Movement.TurningLeft);
        Assert.False(session.Lua.Movement.StrafingRight);
        Assert.False(session.Lua.Movement.Ascending);

        session.Lua.Movement.StrafeAlsoTurns = true;
        Assert.Equal(
            "0:0",
            session.Lua.Evaluate(
                "local startCount=select('#',StrafeLeftStart('ignored')); " +
                "local stopCount=select('#',StrafeLeftStop()); " +
                "return startCount..':'..stopCount"));
        Assert.False(session.Lua.Movement.StrafingLeft);
        Assert.False(session.Lua.Movement.TurningLeft);

        session.Lua.Evaluate("StrafeRightStart()");
        Assert.True(session.Lua.Movement.StrafingRight);
        Assert.True(session.Lua.Movement.TurningRight);
        session.Lua.Evaluate("StrafeRightStop()");
        Assert.False(session.Lua.Movement.StrafingRight);
        Assert.False(session.Lua.Movement.TurningRight);
    }

