    [Fact]
    public void ScenarioQueriesPreserveNativeLegacyTuplesAndReusableTables()
    {
        using var session = new EmulatorSession();
        var scenario = session.Lua.Scenario;
        scenario.CurrentScenarioId = 77;
        scenario.CurrentStepId = 88;
        scenario.Info = new WowScenarioInfoState(
            "The Scenario",
            2,
            4,
            9,
            true,
            150,
            275,
            3,
            "Silvermoon",
            "scenario-kit");
        scenario.ProvingGrounds = new WowScenarioProvingGroundsInfoState(5, 6, 7, 90);
        scenario.ShouldShowCriteria = true;
        scenario.BonusStepIds.Add(88);
        scenario.BonusStepIds.Add(89);
        scenario.ChoiceOrder.Add(77);
        scenario.ChoiceOrder.Add(78);
        scenario.SupersededObjectives.Add(
            new WowScenarioSupersededObjectiveState(88, 89));
        scenario.StepsById[88] = new WowScenarioStepInfoState(
            "First Step",
            "Do the thing",
            3,
            false,
            true,
            true,
            false,
            new[] { new WowScenarioStepSpellInfoState(123, "Scenario Spell", 456) },
            65,
            9001,
            42);

        Assert.Equal(
            "13:The Scenario:2:4:9:false:false:true:150:275:3:" +
            "Silvermoon:scenario-kit:77:true:true:true",
            session.Lua.Evaluate(
                "local values={C_Scenario.GetInfo('ignored')}; " +
                "return table.concat({select('#',C_Scenario.GetInfo())," +
                "values[1],values[2],values[3],values[4],tostring(values[5])," +
                "tostring(values[6]),tostring(values[7]),values[8],values[9]," +
                "values[10],values[11],values[12],values[13]," +
                "tostring(C_Scenario.IsInScenario())," +
                "tostring(C_Scenario.ShouldShowCriteria())," +
                "tostring(C_Scenario.TreatScenarioAsDungeon())},':')"));

        Assert.Equal(
            "12:First Step:Do the thing:3:false:true:true:false:1:" +
            "123:Scenario Spell:456:65:9001:42:9001:4:5:6:7:90",
            session.Lua.Evaluate(
                "local values={C_Scenario.GetStepInfo({ignored=true})}; " +
                "local spell=values[9][1]; " +
                "return table.concat({select('#',C_Scenario.GetStepInfo())," +
                "values[1],values[2],values[3],tostring(values[4])," +
                "tostring(values[5]),tostring(values[6]),tostring(values[7])," +
                "values[8],spell.spellID,spell.spellName,spell.spellIcon," +
                "values[10],values[11],values[12]," +
                "C_Scenario.GetBonusStepRewardQuestID('88')," +
                "select('#',C_Scenario.GetProvingGroundsInfo())," +
                "C_Scenario.GetProvingGroundsInfo()},':')"));

        Assert.Equal(
            "true:2:88:89:true:nil:2:77:78:true:1:88:89:false",
            session.Lua.Evaluate(
                "local bonus={old=true,[7]=7}; local returned=C_Scenario.GetBonusSteps(bonus);" +
                "local choice={old=true}; local ordered=GetScenariosChoiceOrder(choice);" +
                "local superseded={old=true}; local supers=C_Scenario.GetSupersededObjectives(superseded);" +
                "return table.concat({tostring(returned==bonus),#bonus,bonus[1],bonus[2]," +
                "tostring(bonus.old==nil),tostring(choice.old)," +
                "#ordered,ordered[1],ordered[2],tostring(ordered==choice)," +
                "#supers,supers[1][1],supers[1][2]," +
                "tostring(pcall(GetScenariosChoiceOrder,7))},':')"));

        Assert.Equal(
            "12:true:true:false",
            session.Lua.Evaluate(
                "local missing={C_Scenario.GetStepInfo(999)};" +
                "return table.concat({select('#',C_Scenario.GetStepInfo(999))," +
                "tostring(missing[1]==nil),tostring(missing[9]==nil)," +
                "tostring(pcall(C_Scenario.GetBonusStepRewardQuestID,{}))},':')"));
    }

