    [Fact]
    public void NativeFunctionContainersDriveGlobalEventCallbacks()
    {
        using var session = new EmulatorSession();
        session.Lua.Evaluate(
            "globalEventValue = ''; " +
            "globalEventCallback = C_FunctionContainers.CreateCallback(function(owner, value) " +
            "globalEventValue = tostring(owner)..':'..value end); " +
            "globalEventRegistered = RegisterEventCallback(" +
            "'TOOLTIP_SHOW_ITEM_COMPARISON', globalEventCallback)");

        Assert.Equal(
            "userdata:false:true:true:false:property:property:false",
            session.Lua.Evaluate(
                "local another=C_FunctionContainers.CreateCallback(function() end);" +
                "globalEventCallback.marker='property';" +
                "local dump=globalEventCallback:Dump();" +
                "local writable=pcall(function() globalEventCallback.Dump=1 end);" +
                "return table.concat({type(globalEventCallback)," +
                "tostring(getmetatable(globalEventCallback))," +
                "tostring(globalEventRegistered)," +
                "tostring(globalEventCallback==globalEventCallback)," +
                "tostring(globalEventCallback==another)," +
                "globalEventCallback.marker,dump.marker," +
                "tostring(writable)},':')"));

        session.Lua.TriggerEvent(
            "TOOLTIP_SHOW_ITEM_COMPARISON",
            "payload");
        Assert.Equal("nil:payload", session.Lua.Evaluate("globalEventValue"));

        Assert.Equal(
            "true:false",
            session.Lua.Evaluate(
                "local removed=UnregisterEventCallback(" +
                "'TOOLTIP_SHOW_ITEM_COMPARISON', globalEventCallback);" +
                "local removedAgain=UnregisterEventCallback(" +
                "'TOOLTIP_SHOW_ITEM_COMPARISON', globalEventCallback);" +
                "globalEventValue = 'unchanged';" +
                "return tostring(removed)..':'..tostring(removedAgain)"));
        session.Lua.TriggerEvent(
            "TOOLTIP_SHOW_ITEM_COMPARISON",
            "ignored");
        Assert.Equal("unchanged", session.Lua.Evaluate("globalEventValue"));

        session.Lua.Evaluate(
            "globalUnitValue='';" +
            "globalUnitCallback=C_FunctionContainers.CreateCallback(" +
            "function(owner,unit,value) globalUnitValue=unit..':'..value end);" +
            "globalUnitRegistered=RegisterUnitEventCallback(" +
            "'MINIMAP_PING',globalUnitCallback,'target')");
        session.Lua.TriggerEvent(
            "MINIMAP_PING",
            "player",
            3);
        Assert.Equal("", session.Lua.Evaluate("globalUnitValue"));
        session.Lua.TriggerEvent(
            "MINIMAP_PING",
            "target",
            7);
        Assert.Equal(
            "true:target:7:true",
            session.Lua.Evaluate(
                "local removed=UnregisterUnitEventCallback(" +
                "'MINIMAP_PING',globalUnitCallback,'target');" +
                "return table.concat({tostring(globalUnitRegistered)," +
                "globalUnitValue,tostring(removed)},':')"));

        Assert.Equal(
            "0:0",
            session.Lua.Evaluate(
                "return select('#',RegisterEventCallback(" +
                "'NOT_A_CALLBACK_EVENT',function() end))..':'.." +
                "select('#',RegisterUnitEventCallback(" +
                "'TOOLTIP_SHOW_ITEM_COMPARISON',function() end,'player'))"));
    }

