    [Fact]
    public void CombatLogNavigationAndFilteringShareNativeNamespaceState()
    {
        using var session = new EmulatorSession();
        session.Lua.CombatLog.Entries.Add(new WowCombatLogEntry(
            ["old", 1],
            ShouldShow: true,
            MatchesEventFilters: true));
        session.Lua.CombatLog.Entries.Add(new WowCombatLogEntry(
            ["filtered", 2],
            ShouldShow: true,
            MatchesEventFilters: false));
        session.Lua.CombatLog.Entries.Add(new WowCombatLogEntry(
            ["new", 3],
            ShouldShow: false,
            MatchesEventFilters: true));
        session.Lua.CombatLog.CurrentEvent = new WowCombatLogEntry(
            ["ACTIVE_EVENT", 44]);

        Assert.Equal(
            "2:3:true:new:ACTIVE_EVENT:false:true:old:true:false:0",
            session.Lua.Evaluate(
                "C_CombatLog.AddEventFilter('SPELL_DAMAGE'); " +
                "local filtered=C_CombatLog.GetEntryCount(); " +
                "local all=C_CombatLogSecure.GetEntryCount(true); " +
                "local newest=C_CombatLog.SeekToNewestEntry(); " +
                "local newestEntry=C_CombatLog.GetCurrentEntryInfo(); " +
                "local newestEvent=C_CombatLogInternal.GetCurrentEventInfo(); " +
                "local shouldShow=C_CombatLog.ShouldShowCurrentEntry(); " +
                "local previous=C_CombatLogSecure.SeekToPreviousEntry(); " +
                "local previousEntry=C_CombatLogSecure.GetCurrentEntryInfo(); " +
                "local previousShouldShow=C_CombatLogSecure.ShouldShowCurrentEntry(); " +
                "local exhausted=C_CombatLog.SeekToPreviousEntry(); " +
                "return table.concat({filtered,all,tostring(newest),newestEntry,newestEvent," +
                "tostring(shouldShow),tostring(previous),previousEntry," +
                "tostring(previousShouldShow),tostring(exhausted)," +
                "select('#',C_CombatLog.GetCurrentEntryInfo())},':')"));
        Assert.Null(session.Lua.CombatLog.CurrentEntryIndex);

        Assert.Equal(
            "0:0",
            session.Lua.Evaluate(
                "C_CombatLog.ClearEntries(); C_CombatLog.ClearEventFilters(); " +
                "return table.concat({C_CombatLog.GetEntryCount()," +
                "C_CombatLogSecure.GetEntryCount()},':')"));
        Assert.Empty(session.Lua.CombatLog.Entries);
        Assert.Empty(session.Lua.CombatLog.EventFilters);
        Assert.Null(session.Lua.CombatLog.CurrentEvent);
    }

