    [Fact]
    public void IsSecureVariableReportsUntaintedKeysInsideUserAddons()
    {
        var root = Path.Combine(Path.GetTempPath(), $"secure-variable-{Guid.NewGuid():N}");
        var addon = CreateAddon(
            root,
            "SecureVariableProbe",
            ["main.lua"],
            [
                "local value={}; value.key=nil; " +
                "local secure,taint=issecurevariable(value,'key'); " +
                "secureVariableResult=tostring(secure)..':'..tostring(taint==nil)"
            ]);
        try
        {
            using var session = new EmulatorSession();
            var progress = new List<AddonLoadProgress>();
            session.LoadProgress += progress.Add;
            session.Load(addon);

            Assert.Equal("true:true", session.Lua.Evaluate("secureVariableResult"));
            Assert.Collection(
                progress,
                value =>
                {
                    Assert.Equal("SecureVariableProbe", value.AddonName);
                    Assert.Equal(0, value.Completed);
                    Assert.Equal(1, value.Total);
                },
                value =>
                {
                    Assert.Equal("SecureVariableProbe", value.AddonName);
                    Assert.Equal(1, value.Completed);
                    Assert.Equal(1, value.Total);
                });
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

