    [Fact]
    public void TitleGlobalsMatchNativeDbFlagsValidationAndRequestSemantics()
    {
        using var session = new EmulatorSession();
        session.Lua.Titles.Titles.Add(
            new WowTitleState(2, "%s the Explorer", IsKnown: true, IsPlayerTitle: true));
        session.Lua.Titles.Titles.Add(
            new WowTitleState(7, "Arena Master %s", IsKnown: false, IsPlayerTitle: false));
        session.Lua.Titles.CurrentTitleId = 2;

        Assert.Equal(
            "7:the Explorer:true:Arena Master :false:2:false:false:true:true:2:false",
            session.Lua.Evaluate(
                "local first,firstPlayer=GetTitleName(2); " +
                "local second,secondPlayer=GetTitleName(7); " +
                "local missing,missingPlayer=GetTitleName(6); " +
                "local validName=pcall(GetTitleName); " +
                "local validKnown=pcall(IsTitleKnown,-1); " +
                "SetCurrentTitle(7); " +
                "return table.concat({GetNumTitles(),first,tostring(firstPlayer)," +
                "second,tostring(secondPlayer),GetCurrentTitle()," +
                "tostring(IsTitleKnown(7)),tostring(missingPlayer)," +
                "tostring(missing==nil),tostring(not validName),GetCurrentTitle()," +
                "tostring(validKnown)},':')"));
        Assert.Equal(7, session.Lua.Titles.RequestedTitleId);

        session.Lua.Client.InCombatLockdown = true;
        session.Lua.Evaluate("SetCurrentTitle(-1)");

        Assert.Equal(7, session.Lua.Titles.RequestedTitleId);
        Assert.Equal(2, session.Lua.Titles.CurrentTitleId);
    }

