    [Fact]
    public void EquipmentSetNamespaceUsesNativeRecordsIndicesAndMutations()
    {
        using var session = new EmulatorSession();
        var first = new WowEquipmentSetState
        {
            Id = 7,
            Name = "Raid",
            IconFileId = 123,
            AssignedSpecIndex = 2,
            IsEquipped = true,
            ContainsLockedItems = true,
            NumItems = 16,
            NumEquipped = 14,
            NumInInventory = 1,
            NumLost = 1,
            NumIgnored = 2
        };
        first.IgnoredSlots[0] = true;
        first.IgnoredSlots[18] = false;
        first.ItemIds[0] = 190001;
        first.ItemIds[18] = 190019;
        first.ItemLocations[0] = 65537;
        first.ItemLocations[18] = 65555;
        var second = new WowEquipmentSetState
        {
            Id = 9,
            Name = "World",
            IconFileId = 456
        };
        session.Lua.Equipment.EquipmentSets.Add(first);
        session.Lua.Equipment.EquipmentSets.Add(second);
        session.Lua.Equipment.NextEquipmentSetId = 10;

        Assert.Equal(
            "nil:2:7:9:7:2:7:2",
            session.Lua.Evaluate(
                "local ids=C_EquipmentSet.GetEquipmentSetIDs(); " +
                "return table.concat({" +
                "tostring(C_EquipmentSet.OffhandHasWeapon)," +
                "#ids,ids[1],ids[2],C_EquipmentSet.GetEquipmentSetID('Raid')," +
                "C_EquipmentSet.GetEquipmentSetAssignedSpec(7)," +
                "C_EquipmentSet.GetEquipmentSetForSpec(2)," +
                "C_EquipmentSet.GetNumEquipmentSets()},':')"));
        Assert.Equal(
            "Raid:123:7:true:16:14:1:1:2",
            session.Lua.Evaluate(
                "local n,i,id,e,a,b,c,d,f=C_EquipmentSet.GetEquipmentSetInfo(7); " +
                "return table.concat({n,i,id,tostring(e),a,b,c,d,f},':')"));
        Assert.Equal(
            "true:nil:false:190001:190019:65537:65555:true:0",
            session.Lua.Evaluate(
                "local ignored=C_EquipmentSet.GetIgnoredSlots(7); " +
                "local items=C_EquipmentSet.GetItemIDs(7); " +
                "local locations=C_EquipmentSet.GetItemLocations(7); " +
                "return table.concat({" +
                "tostring(ignored[1]),tostring(ignored[2]),tostring(ignored[19])," +
                "items[1],items[19],locations[1],locations[19]," +
                "tostring(C_EquipmentSet.EquipmentSetContainsLockedItems(7))," +
                "select('#',C_EquipmentSet.GetItemIDs(404))},':')"));

        Assert.Equal(
            "true:false:false:true",
            session.Lua.Evaluate(
                "C_EquipmentSet.IgnoreSlotForSave(1); " +
                "local a=C_EquipmentSet.IsSlotIgnoredForSave(1); " +
                "local outOfRange=C_EquipmentSet.IsSlotIgnoredForSave(20); " +
                "C_EquipmentSet.UnignoreSlotForSave(1); " +
                "local b=C_EquipmentSet.IsSlotIgnoredForSave(1); " +
                "C_EquipmentSet.IgnoreSlotForSave(19); " +
                "local c=C_EquipmentSet.IsSlotIgnoredForSave(19); " +
                "C_EquipmentSet.ClearIgnoredSlotsForSave(); " +
                "return table.concat({tostring(a),tostring(outOfRange)," +
                "tostring(b),tostring(c)},':')"));
        Assert.Equal(
            "0:2:9:true:true:false:World Two",
            session.Lua.Evaluate(
                "C_EquipmentSet.AssignSpecToEquipmentSet(9,2); " +
                "C_EquipmentSet.ModifyEquipmentSet(9,'World Two','icon-path'); " +
                "C_EquipmentSet.PickupEquipmentSet(9); " +
                "C_EquipmentSet.SaveEquipmentSet(9,'saved-icon'); " +
                "local used=C_EquipmentSet.UseEquipmentSet(9); " +
                "return table.concat({" +
                "select('#',C_EquipmentSet.GetEquipmentSetAssignedSpec(7))," +
                "C_EquipmentSet.GetEquipmentSetAssignedSpec(9)," +
                "C_EquipmentSet.GetEquipmentSetForSpec(2),tostring(used)," +
                "tostring(select(4,C_EquipmentSet.GetEquipmentSetInfo(9)))," +
                "tostring(select(4,C_EquipmentSet.GetEquipmentSetInfo(7)))," +
                "(C_EquipmentSet.GetEquipmentSetInfo(9))},':')"));
        Assert.Equal(1, second.PickupCount);
        Assert.Equal(1, second.SaveCount);
        Assert.Equal("saved-icon", second.IconAsset);

        Assert.Equal(
            "true:true:0",
            session.Lua.Evaluate(
                "local badId=pcall(C_EquipmentSet.GetEquipmentSetInfo); " +
                "local badSlot=pcall(C_EquipmentSet.IgnoreSlotForSave,0); " +
                "C_EquipmentSet.DeleteEquipmentSet(7); " +
                "return table.concat({tostring(not badId),tostring(not badSlot)," +
                "select('#',C_EquipmentSet.GetEquipmentSetInfo(7))},':')"));
    }

    [Fact]
    public void LegacyEquipmentGlobalsUseNativeSlotRecordsAndResultArity()
    {
        using var session = new EmulatorSession();
        session.Lua.Equipment.InventoryItems[("player", 1)] =
            new WowInventoryItemState
            {
                ItemId = 190001,
                TextureFileId = 136516,
                Quality = 4,
                Link = "|cffa335ee|Hitem:190001|h[Test Helm]|h|r",
                IsLocked = true,
                CurrentDurability = 31,
                MaxDurability = 44
            };
        session.Lua.Equipment.InventorySlotTextureFileIds[1] = 136516;
        session.Lua.Equipment.InventoryAlertStatuses[1] = 7;
        session.Lua.Equipment.MainHandEnchant =
            new WowWeaponEnchantState(true, 12000, 3, 99);

        Assert.Equal(
            "1:136516:false:136516:4:190001:" +
            "|cffa335ee|Hitem:190001|h[Test Helm]|h|r:true:7:1:0:0",
            session.Lua.Evaluate(
                "local slot,slotTexture,hidden=GetInventorySlotInfo('HEADSLOT'); " +
                "local missingTexture=GetInventoryItemTexture('player',2); " +
                "PickupInventoryItem('HEADSLOT'); " +
                "return table.concat({" +
                "slot,slotTexture,tostring(hidden)," +
                "GetInventoryItemTexture('player','HEADSLOT')," +
                "GetInventoryItemQuality('player',1)," +
                "GetInventoryItemID('player',1)," +
                "GetInventoryItemLink('player',1)," +
                "tostring(IsInventoryItemLocked('HEADSLOT'))," +
                "GetInventoryAlertStatus('2')," +
                "select('#',GetInventoryItemTexture('player',2))," +
                "select('#',GetInventoryItemID('player',2))," +
                "select('#',IsInventoryItemLocked('not-a-slot'))},':')"));
        Assert.Equal(1, session.Lua.Equipment.LastPickedInventorySlot);
        Assert.Equal(
            "31:44:0:true",
            session.Lua.Evaluate(
                "local current,maximum=GetInventoryItemDurability(1); " +
                "return table.concat({current,maximum," +
                "select('#',GetInventoryItemDurability(2))," +
                "tostring(not pcall(GetInventoryItemDurability,{}))},':')"));
        Assert.Equal(
            "true:12000:3:99:false:nil:nil:nil:8:false",
            session.Lua.Evaluate(
                "local a,b,c,d,e,f,g,h=GetWeaponEnchantInfo(); " +
                "local ok=pcall(GetInventorySlotInfo,'not-a-slot'); " +
                "return table.concat({tostring(a),b,c,d,tostring(e)," +
                "tostring(f),tostring(g),tostring(h)," +
                "select('#',GetWeaponEnchantInfo()),tostring(ok)},':')"));

        Assert.Equal(
            "1:0:nil:false:false",
            session.Lua.Evaluate(
                "local cost,canRepair=GetRepairAllCost(); " +
                "return table.concat({select('#',GetRepairAllCost()),cost," +
                "tostring(canRepair),tostring(CanMerchantRepair())," +
                "tostring(InRepairMode())},':')"));
        session.Lua.Merchant.CanRepair = true;
        session.Lua.Merchant.IsInRepairMode = true;
        session.Lua.Merchant.RepairAllCost = 543;
        Assert.Equal(
            "2:543:true:true:true",
            session.Lua.Evaluate(
                "local cost,canRepair=GetRepairAllCost(); " +
                "return table.concat({select('#',GetRepairAllCost()),cost," +
                "tostring(canRepair),tostring(CanMerchantRepair())," +
                "tostring(InRepairMode())},':')"));
    }

