                "C_EncounterJournal.OnOpen();" +
                "C_EncounterJournal.OnClose();" +
                "C_EncounterJournal.SetPreviewMythicPlusLevel(1);" +
                "C_EncounterJournal.SetPreviewPvpTier(-5);" +
                "C_EncounterJournal.SetSlotFilter(3);" +
                "C_EncounterJournal.SetTab(4);" +
                "C_EncounterJournal.StartArathiRPE();" +
                "C_EncounterJournal.ResetSlotFilter();" +
                "return table.concat({" +
                "#C_EncounterJournal.GetDungeonEntrancesForMap(84)," +
