                "tostring(l.displayAsExtremelyRare),l.displaySeasonID,li.itemID," +
                "#f,f[1],f[2],s.spellID,s.title,s.description,s.headerType," +
                "s.abilityIcon,s.creatureDisplayID,s.uiModelSceneID," +
                "s.siblingSectionID,s.firstChildSectionID," +
                "tostring(s.filteredByDifficulty),s.link,tostring(s.startsOpen)," +
                "tostring(C_EncounterJournal.InstanceHasLoot())," +
                "tostring(C_EncounterJournal.IsEncounterComplete(55))," +
                "select('#',C_EncounterJournal.OnOpen())," +
                "select('#',C_EncounterJournal.OnClose())," +
                "select('#',C_EncounterJournal.SetPreviewMythicPlusLevel(2))," +
                "select('#',C_EncounterJournal.SetPreviewPvpTier(-1))," +
                "select('#',C_EncounterJournal.SetSlotFilter(15))," +
                "select('#',C_EncounterJournal.SetTab(3))," +
                "C_EncounterJournal.GetSlotFilter()," +
                "Enum.JournalLinkTypes.Section," +
                "Enum.JournalLinkTypesMeta.MinValue," +
                "Enum.JournalLinkTypesMeta.MaxValue," +
                "Enum.ItemSlotFilterType.NoFilter," +
                "Enum.ItemSlotFilterTypeMeta.NumValues," +
                "Enum.JournalEncounterSecTypes.Generic," +
                "Enum.JournalEncounterIconFlags.Bleed," +
                "tostring(C_EncounterJournal.RequestPendingChestRewards==nil)," +
                "tostring(badMap),tostring(badInfo),tostring(badLink)," +
                "tostring(badIndex),tostring(badComplete),tostring(badSlot)},':')"));

        Assert.Equal(2, journal.OpenRequestCount);
        Assert.Equal(2, journal.CloseRequestCount);
        Assert.Equal(2, journal.PreviewMythicPlusLevel);
        Assert.Equal(-1, journal.PreviewPvpTier);
        Assert.Equal(15, journal.SlotFilter);
        Assert.Equal(3, journal.SelectedTab);
        Assert.Equal(1, journal.StartArathiRpeRequestCount);
    }

