    [Fact]
    public void PlayerInteractionManagerUsesNativeEnumAndStateContracts()
    {
        using var session = new EmulatorSession();
        var interactions = session.Lua.PlayerInteractions;

        Assert.Equal(
            "true:false:false:false",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(C_PlayerInteractionManager.IsInteractingWithNpcOfType(0))," +
                "tostring(C_PlayerInteractionManager.IsInteractingWithNpcOfType(1))," +
                "tostring(C_PlayerInteractionManager.IsReplacingUnit())," +
                "tostring(C_PlayerInteractionManager.IsValidNPCInteraction(0))},':')"));

        interactions.CurrentInteractionType = 79;
        interactions.PendingInteractionType = 12;
        interactions.HasActiveInteraction = true;
        interactions.HasPendingInteraction = true;
        interactions.IsReplacingUnit = true;
        interactions.ValidNpcInteractionTypes.Add(79);
        interactions.ValidNpcInteractionTypes.Add(12);
        interactions.InteractUnitResults["npc"] = true;
        interactions.InteractUnitResults["42"] = true;

        Assert.Equal(
            "true:true:true:true:true",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(C_PlayerInteractionManager.IsInteractingWithNpcOfType(79))," +
                "tostring(C_PlayerInteractionManager.IsReplacingUnit())," +
                "tostring(C_PlayerInteractionManager.IsValidNPCInteraction(79))," +
                "tostring(C_PlayerInteractionManager.InteractUnit('npc'))," +
                "tostring(C_PlayerInteractionManager.InteractUnit(42,nil,false))},':')"));

        Assert.Equal(
            new WowPlayerInteractionRequest("npc", true, true),
            interactions.InteractionRequests[0]);
        Assert.Equal(
            new WowPlayerInteractionRequest("42", true, false),
            interactions.InteractionRequests[1]);

        Assert.Equal(
            "false:false:false:false:false",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(pcall(C_PlayerInteractionManager.IsInteractingWithNpcOfType))," +
                "tostring(pcall(C_PlayerInteractionManager.IsInteractingWithNpcOfType,-1))," +
                "tostring(pcall(C_PlayerInteractionManager.IsValidNPCInteraction,80))," +
                "tostring(pcall(C_PlayerInteractionManager.ClearInteraction,'bad'))," +
                "tostring(pcall(C_PlayerInteractionManager.InteractUnit,{}))},':')"));

        session.Lua.Evaluate(
            "C_PlayerInteractionManager.ConfirmationInteraction(12); " +
            "C_PlayerInteractionManager.ConfirmationInteraction(); " +
            "C_PlayerInteractionManager.ClearInteraction(12)");
        Assert.Equal(1, interactions.ConfirmationInteractionRequests);
        Assert.True(interactions.HasActiveInteraction);
        Assert.Equal(1, interactions.ClearInteractionRequests);

        session.Lua.Evaluate(
            "C_PlayerInteractionManager.ClearInteraction(79); " +
            "C_PlayerInteractionManager.ReopenInteraction()");
        Assert.False(interactions.HasActiveInteraction);
        Assert.False(interactions.HasPendingInteraction);
        Assert.Equal(0, interactions.CurrentInteractionType);
        Assert.Equal(0, interactions.PendingInteractionType);
        Assert.Empty(interactions.ValidNpcInteractionTypes);
        Assert.Equal(2, interactions.ClearInteractionRequests);
        Assert.Equal(1, interactions.ReopenInteractionRequests);
    }

    [Fact]
    public void LootJournalUsesNativeRecordsFiltersAndNoResultMisses()
    {
        using var session = new EmulatorSession();
        var lootJournal = session.Lua.LootJournal;

        Assert.Equal(
            "0:0",
            session.Lua.Evaluate(
                "return #C_LootJournal.GetItemSets()..':'.." +
                "select('#',C_LootJournal.GetItemSetItems(100))"));

        lootJournal.ItemSets.Add(new WowLootJournalItemSetState(
            100,
            489,
            "Arcane Regalia",
            new HashSet<int> { 8 },
            new HashSet<int> { 62, 63, 64 }));
        lootJournal.ItemSets.Add(new WowLootJournalItemSetState(
            101,
            500,
            null,
            new HashSet<int> { 5 },
            new HashSet<int> { 257 }));
        lootJournal.ItemsBySetId[100] =
        [
            new WowLootJournalItemState(190001, 123456, 15),
            new WowLootJournalItemState(190002, null, 4)
        ];

        Assert.Equal(
            "2:100:489:Arcane Regalia:1:100:1:100:0",
            session.Lua.Evaluate(
                "local all=C_LootJournal.GetItemSets(); " +
                "local mage=C_LootJournal.GetItemSets(8); " +
                "local frost=C_LootJournal.GetItemSets(8,64); " +
                "return table.concat({#all,all[1].setID,all[1].itemLevel,all[1].name," +
                "#mage,mage[1].setID,#frost,frost[1].setID," +
                "#C_LootJournal.GetItemSets(8,257)},':')"));

        Assert.Equal(
            "2:190001:123456:16:190002:nil:5",
            session.Lua.Evaluate(
                "local items=C_LootJournal.GetItemSetItems(100); " +
                "return table.concat({#items,items[1].itemID,items[1].icon," +
                "items[1].invType,items[2].itemID,tostring(items[2].icon)," +
                "items[2].invType},':')"));

        Assert.Equal(
            "false:false:false:false",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(pcall(C_LootJournal.GetItemSetItems))," +
                "tostring(pcall(C_LootJournal.GetItemSetItems,{}))," +
                "tostring(pcall(C_LootJournal.GetItemSets,{}))," +
                "tostring(pcall(C_LootJournal.GetItemSets,8,{}))},':')"));

        lootJournal.DataAvailable = false;
        Assert.Equal(
            "0:0",
            session.Lua.Evaluate(
                "return select('#',C_LootJournal.GetItemSets())..':'.." +
                "select('#',C_LootJournal.GetItemSetItems(100))"));
    }

    [Fact]
    public void LootHistoryUsesNativeEncounterDropAndRollRecords()
    {
        using var session = new EmulatorSession();
        var history = session.Lua.LootHistory;
        history.Time = 45;
        history.Encounters.Add(new WowLootEncounterState
        {
            EncounterId = 42,
            EncounterName = "The Test",
            StartTime = 10,
            Duration = 30
        });
        var leader = new WowLootPlayerInfoState(
            "Alice",
            "Player-1-1",
            "MAGE",
            true,
            1,
            false,
            88);
        var winner = new WowLootPlayerInfoState(
            "Bob",
            "Player-1-2",
            "PRIEST",
            false,
            3,
            true,
            null);
        history.SortedDropsByEncounterId[42] =
        [
            new WowLootDropState(
                7,
                "|cff0070dd|Hitem:190001::::::::|h[Test Item]|h|r",
                4,
                leader,
                true,
                winner,
                false,
                [leader, winner],
                12,
                18)
        ];

        Assert.Equal(
            "1:The Test:42:10:30:The Test:45",
            session.Lua.Evaluate(
                "local all=C_LootHistory.GetAllEncounterInfos(); " +
                "local one=C_LootHistory.GetInfoForEncounter(42); " +
                "return table.concat({#all,all[1].encounterName,all[1].encounterID," +
                "all[1].startTime,all[1].duration,one.encounterName," +
                "C_LootHistory.GetLootHistoryTime()},':')"));

        Assert.Equal(
            "1:7:|cff0070dd|Hitem:190001::::::::|h[Test Item]|h|r:4:" +
            "Alice:Player-1-1:MAGE:true:1:false:88:true:Bob:Player-1-2:" +
            "PRIEST:false:3:true:nil:false:2:12:18",
            session.Lua.Evaluate(
                "local drops=C_LootHistory.GetSortedDropsForEncounter(42); " +
                "local d=C_LootHistory.GetSortedInfoForDrop(42,7); " +
                "local l=d.currentLeader; local w=d.winner; " +
                "return table.concat({#drops,d.lootListID,d.itemHyperlink,d.playerRollState," +
                "l.playerName,l.playerGUID,l.playerClass,tostring(l.isSelf),l.state," +
                "tostring(l.isWinner),l.roll,tostring(d.isTied),w.playerName,w.playerGUID," +
                "w.playerClass,tostring(w.isSelf),w.state,tostring(w.isWinner)," +
                "tostring(w.roll),tostring(d.allPassed),#d.rollInfos,d.startTime,d.duration},':')"));

        Assert.Equal(
            "1:nil:1:nil:1:nil",
            session.Lua.Evaluate(
                "return table.concat({" +
                "select('#',C_LootHistory.GetInfoForEncounter(999))," +
                "tostring(C_LootHistory.GetInfoForEncounter(999))," +
                "select('#',C_LootHistory.GetSortedDropsForEncounter(999))," +
                "tostring(C_LootHistory.GetSortedDropsForEncounter(999))," +
                "select('#',C_LootHistory.GetSortedInfoForDrop(42,8))," +
                "tostring(C_LootHistory.GetSortedInfoForDrop(42,8))},':')"));

        Assert.Equal(
            "false:false:false:false:false",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(pcall(C_LootHistory.GetInfoForEncounter))," +
                "tostring(pcall(C_LootHistory.GetSortedDropsForEncounter,{}))," +
                "tostring(pcall(C_LootHistory.GetSortedInfoForDrop,42))," +
                "tostring(pcall(C_LootHistory.GetSortedInfoForDrop,42,-1))," +
                "tostring(pcall(C_LootHistory.GetSortedInfoForDrop,42,256))},':')"));
    }

