    [Fact]
    public void FrameWindowAndHyperlinkStateUseNativeValidationAndHierarchy()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "true:false:true:false:true:true:true:true:false",
            session.Lua.Evaluate(
                "(function() local parent=CreateFrame('Frame',nil,UIParent); " +
                "local child=CreateFrame('Frame',nil,parent); " +
                "local first={__type='SimpleWindow',id=1}; " +
                "local second={__type='SimpleWindow',id=2}; " +
                "parent:SetWindow(first); child:SetWindow(second); parent:SetWindow(first); " +
                "local propagated=child:GetWindow()==first; " +
                "local invalid=pcall(function() parent:SetWindow({}) end); " +
                "local preserved=child:GetWindow()==first; " +
                "local initial=parent:GetHyperlinksEnabled(); " +
                "parent:SetHyperlinksEnabled(true); local enabled=parent:GetHyperlinksEnabled(); " +
                "parent:SetHyperlinksEnabled(); local omitted=parent:GetHyperlinksEnabled(); " +
                "parent:SetHyperlinksEnabled(true); parent:SetToDefaults(); " +
                "local reset=parent:GetHyperlinksEnabled(); " +
                "local resetWindow=parent:GetWindow(); " +
                "local resetHierarchy=resetWindow~=first and child:GetWindow()==resetWindow; " +
                "parent:SetWindow(first); parent:SetWindow(); " +
                "local cleared=parent:GetWindow()~=first and child:GetWindow()==parent:GetWindow(); " +
                "return table.concat({tostring(propagated),tostring(invalid),tostring(preserved)," +
                "tostring(initial),tostring(enabled),tostring(not omitted),tostring(resetHierarchy)," +
                "tostring(cleared)," +
                "tostring(reset)},':') end)()"));
    }

