    [Fact]
    public void SocialRestrictionsMatchNativeChatStateAndResponseEvents()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "false:false:false:false:0:true:0:true",
            session.Lua.Evaluate(
                "socialEvents={}; local listener=CreateFrame('Frame'); " +
                "listener:RegisterEvent('CHAT_DISABLED_CHANGED'); " +
                "listener:RegisterEvent('CHAT_DISABLED_CHANGE_FAILED'); " +
                "listener:SetScript('OnEvent',function(_,event,value) " +
                "socialEvents[#socialEvents+1]=event..':'..tostring(value) end); " +
                "local missing=pcall(C_SocialRestrictions.SetChatDisabled); " +
                "local wrong=pcall(C_SocialRestrictions.SetChatDisabled,1); " +
                "C_SocialRestrictions.SetChatDisabled(true); " +
                "C_SocialRestrictions.SetChatDisabled(true); " +
                "C_SocialRestrictions.AcknowledgeRegionalChatDisabled(); " +
                "return table.concat({tostring(missing),tostring(wrong)," +
                "tostring(C_SocialRestrictions.CanReceiveChat())," +
                "tostring(C_SocialRestrictions.CanSendChat())," +
                "#socialEvents,tostring(C_SocialRestrictions.IsChatDisabled())," +
                "#socialEvents,tostring(C_SocialRestrictions.IsChatDisabled())},':')"));

        Assert.Equal([true, true], session.Lua.SocialRestrictions.ChatDisabledRequests);
        Assert.True(session.Lua.SocialRestrictions.RegionalChatDisabledAcknowledged);
        Assert.Equal(true, session.Lua.SocialRestrictions.PendingChatDisabledRequest);

        session.Lua.ApplyChatDisabledServerResponse(true);
        Assert.Equal(
            "CHAT_DISABLED_CHANGED:true",
            session.Lua.Evaluate("return table.concat(socialEvents,',')"));

        session.Lua.Evaluate("C_SocialRestrictions.SetChatDisabled(false)");
        session.Lua.ApplyChatDisabledServerResponse(true);
        Assert.Equal(
            "true:CHAT_DISABLED_CHANGED:true,CHAT_DISABLED_CHANGE_FAILED:true",
            session.Lua.Evaluate(
                "return tostring(C_SocialRestrictions.IsChatDisabled())..':'.." +
                "table.concat(socialEvents,',')"));

        session.Lua.SocialRestrictions.IsMuted = true;
        session.Lua.SocialRestrictions.ChatDisabled = false;
        Assert.Equal(
            "false:false:true",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(C_SocialRestrictions.CanReceiveChat())," +
                "tostring(C_SocialRestrictions.CanSendChat())," +
                "tostring(C_SocialRestrictions.IsMuted())},':')"));
    }

