            "false:nil:1:false:false:false",
            session.Lua.Evaluate(
                "local badType=pcall(CinematicStarted,4,1); " +
                "local badID=pcall(CinematicStarted,0,'bad'); " +
                "local badMouse=pcall(MouseOverrideCinematicDisable,1); " +
                "return table.concat({tostring(InCinematic())," +
                "tostring(GetCurrentCinematicSummary())," +
                "select('#',GetCurrentCinematicSummary()),tostring(badType)," +
                "tostring(badID),tostring(badMouse)},':')"));

        Assert.Equal(
            "0:0",
            session.Lua.Evaluate(
                "return table.concat({select('#',CinematicStarted(0,123,false))," +
                "select('#',CinematicStarted(1,456))},':')"));
        Assert.True(session.Lua.Cinematics.InCinematic);
        Assert.Equal(2, session.Lua.Cinematics.ActiveByType.Count);
        Assert.False(session.Lua.Cinematics.ActiveByType[0].CanCancel);
        Assert.True(session.Lua.Cinematics.ActiveByType[1].CanCancel);
        Assert.Equal(456, session.Lua.Cinematics.CurrentMovieId);

        session.Lua.Cinematics.CurrentSummary = "Current cinematic";
        Assert.Equal("Current cinematic", session.Lua.Evaluate(
            "return GetCurrentCinematicSummary()"));

        Assert.Equal(
            "true:true:false",
            session.Lua.Evaluate(
                "CinematicFinished(0,true,false); local afterFirst=InCinematic(); " +
                "StopCinematic(); local afterStop=InCinematic(); " +
                "CinematicFinished(1,false,true); return table.concat({" +
                "tostring(afterFirst),tostring(afterStop)," +
                "tostring(InCinematic())},':')"));
        Assert.Equal(1, session.Lua.Cinematics.LastFinishedType);
        Assert.False(session.Lua.Cinematics.LastFinishWasUserCanceled);
        Assert.True(session.Lua.Cinematics.LastFinishHadError);
        Assert.Null(session.Lua.Cinematics.CurrentSummary);

        session.Lua.Evaluate(
            "CinematicStarted(2,0,true); MouseOverrideCinematicDisable(true); " +
            "MouseOverrideCinematicDisable(); OpeningCinematic()");
        Assert.False(session.Lua.Cinematics.InCinematic);
        Assert.False(session.Lua.Cinematics.MouseOverrideDisabled);
        Assert.True(session.Lua.Cinematics.OpeningCinematicRequested);
    }

