    [Fact]
    public void VideoOptionsGlobalsMatchNativeShapesAndValidation()
    {
        using var session = new EmulatorSession();
        session.Lua.VideoOptions.DefaultGameWindowSize = (1920, 1080);
        session.Lua.VideoOptions.GameWindowSizes.Add((1280, 720));
        session.Lua.VideoOptions.GameWindowSizes.Add((1920, 1080));
        session.Lua.VideoOptions.Adapters.Add(
            new WowGraphicsAdapterState("Virtual GPU", false, true));
        session.Lua.VideoOptions.AdvancedAntiAliasingAvailable = true;
        session.Lua.VideoOptions.UpscalingAntiAliasingAvailable = true;

        Assert.Equal(
            "3:D3D11:D3D12:Auto:90:50:90:true:true:true:true:" +
            "1920x1080:2:Virtual GPU:false:true:0:0",
            session.Lua.Evaluate(
                "local apiCount=select('#',GetGraphicsAPIs()); " +
                "local api1,api2,api3=GetGraphicsAPIs(); " +
                "local defaultFov,minFov,maxFov=GetCameraFOVDefaults(); " +
                "local aa1,aa2,aa3=AntiAliasingSupported(); " +
                "local defaultSize=C_VideoOptions.GetDefaultGameWindowSize(0); " +
                "local sizes=C_VideoOptions.GetGameWindowSizes(0,false); " +
                "local adapters=C_VideoOptions.GetGxAdapterInfo(); " +
                "return table.concat({apiCount,api1,api2,api3,defaultFov,minFov," +
                "maxFov,tostring(aa1),tostring(aa2),tostring(aa3)," +
                "tostring(C_VideoOptions.IsSpellVisualDensitySystemSupported())," +
                "defaultSize.x..'x'..defaultSize.y,#sizes,adapters[1].name," +
                "tostring(adapters[1].isLowPower)," +
                "tostring(adapters[1].isExternal)," +
                "IsGraphicsCVarValueSupported('RenderScale','-1.5')," +
                "IsGraphicsSettingValueSupported('graphicsQuality',-1.5,true)},':')"));

        Assert.Equal(
            "false:false:false:false:auto:auto:1920x1080",
            session.Lua.Evaluate(
                "local badDefault=pcall(C_VideoOptions.GetDefaultGameWindowSize); " +
                "local badSizes=pcall(C_VideoOptions.GetGameWindowSizes,0); " +
                "local badSet=pcall(C_VideoOptions.SetGameWindowSize,1920); " +
                "local badValidation=pcall(IsGraphicsCVarValueSupported); " +
                "C_VideoOptions.SetGameWindowSize(0,0); " +
                "local auto=C_CVar.GetCVar('xNewResolution'); " +
                "C_VideoOptions.SetGameWindowSize(100,100); " +
                "local preserved=C_CVar.GetCVar('xNewResolution'); " +
                "C_VideoOptions.SetGameWindowSize(1920,1080); " +
                "return table.concat({tostring(badDefault),tostring(badSizes)," +
                "tostring(badSet),tostring(badValidation),auto,preserved," +
                "C_CVar.GetCVar('xNewResolution')},':')"));
    }

    [Fact]
    public void MapValuesMapsEachArgumentToOneResult()
    {
