    [Fact]
    public void MinimapSettersFollowNativeRequiredTypesAndStateLayout()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "false:false:false:false:false:false:0:0",
            session.Lua.Evaluate(
                "local m=Minimap; " +
                "local zoomOk=pcall(function() m:SetZoom() end); " +
                "local alphaOk=pcall(function() m:SetArchBlobInsideAlpha(256) end); " +
                "local scalarOk=pcall(function() m:SetQuestBlobRingScalar(0/0) end); " +
                "local textureOk=pcall(function() m:SetTaskBlobRingTexture({}) end); " +
                "local oneCoordinateOk=pcall(function() m:PingLocation(2) end); " +
                "local maskOk=pcall(function() m:SetMaskTexture() end); " +
                "m:PingLocation(); local x,y=m:GetPingPosition(); " +
                "return table.concat({tostring(zoomOk),tostring(alphaOk)," +
                "tostring(scalarOk),tostring(textureOk),tostring(oneCoordinateOk)," +
                "tostring(maskOk),x,y},':')"));

        Assert.Equal(
            "12:-5.5:34:67:255:3.25",
            session.Lua.Evaluate(
                "local m=Minimap; " +
                "m:SetArchBlobInsideAlpha(12.9); " +
                "m:SetArchBlobRingScalar(-5.5); " +
                "m:SetQuestBlobOutsideAlpha(34); " +
                "m:SetTaskBlobRingAlpha(67); " +
                "m:SetTaskBlobOutsideAlpha(255); " +
                "m:SetTaskBlobRingScalar(3.25); " +
                "m:SetArchBlobInsideTexture('Interface\\\\Minimap\\\\Arch'); " +
                "m:SetQuestBlobOutsideTexture(12345); " +
                "m:SetMaskTexture(67890); " +
                "return table.concat({12,-5.5,34,67,255,3.25},':')"));

        var minimap = session.Ui.Find("Minimap")!.Minimap!;
        Assert.Equal((byte)12, minimap.Arch.InsideAlpha);
        Assert.Equal(-5.5f, minimap.Arch.RingScalar);
        Assert.Equal("Interface\\Minimap\\Arch", minimap.Arch.InsideTexture);
        Assert.Equal((byte)34, minimap.Quest.OutsideAlpha);
        Assert.Equal((uint)12345, minimap.Quest.OutsideTextureFileDataId);
        Assert.Equal((byte)67, minimap.Task.RingAlpha);
        Assert.Equal(byte.MaxValue, minimap.Task.OutsideAlpha);
        Assert.Equal(3.25f, minimap.Task.RingScalar);
        Assert.Equal((uint)67890, minimap.MaskTextureFileDataId);

        minimap.BlipRefreshAccumulator = 12.5f;
        session.Lua.Evaluate("Minimap:UpdateBlips()");
        Assert.Equal(0, minimap.BlipRefreshAccumulator);
    }

    [Fact]
    public void MinimapXmlLoadsNativeBlobTextureAttributes()
    {
        var root = Path.Combine(
            Path.GetTempPath(),
            $"wow-addon-lab-{Guid.NewGuid():N}");
        var addon = CreateAddon(
            root,
            "MinimapXml",
            ["layout.xml"],
            [
                "<Ui><Minimap name=\"BinaryMinimap\" " +
                "minimapQuestBlobInsideTexture=\"QuestInside\" " +
                "minimapQuestBlobOutsideSelectedTexture=\"12345\" " +
                "minimapTaskBlobRingTexture=\"TaskRing\" " +
                "minimapArchBlobOutsideTexture=\"ArchOutside\"/></Ui>"
            ]);
        try
        {
            using var session = new EmulatorSession();
            session.Load(addon);

            var minimap = session.Ui.Find("BinaryMinimap")!.Minimap!;
            Assert.Equal("QuestInside", minimap.Quest.InsideTexture);
            Assert.Equal(
                (uint)12345,
                minimap.Quest.OutsideSelectedTextureFileDataId);
            Assert.Equal("TaskRing", minimap.Task.RingTexture);
            Assert.Equal("ArchOutside", minimap.Arch.OutsideTexture);
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

