        };
        session.Lua.Units.Player.PortraitFileDataId = 12345;

        Assert.Equal(
            "15:42:Known:10:true:7:30:2026:Description:16385:77:Reward:true:true:" +
            "Tester:true:42:3:-1:0:2:1:1:true:10:1:13:Criterion:8:true:2:3:" +
            "Tester:4:99:2 / 3:4201:false:60:10:13:900:1:43:true:true:" +
            "false:true:41:1:43",
            session.Lua.Evaluate(
                "local id,name,points,completed,month,day,year,description,flags," +
                "icon,reward,isGuild,earnedByMe,earnedBy,isStatistic=" +
                "GetAchievementInfo(42); " +
                "local categoryID=GetAchievementInfo(1,1); " +
                "local categoryName,parent,categoryFlags=GetCategoryInfo(1); " +
                "local total,done,incomplete=GetCategoryNumAchievements(1); " +
                "local criteria={GetAchievementCriteriaInfo(42,1)}; " +
                "local criteriaByID={GetAchievementCriteriaInfoByID(42,4201)}; " +
                "local supers=C_AchievementInfo.GetSupercedingAchievements(42); " +
                "local nextID,nextCompleted=GetNextAchievement(42); " +
                "return table.concat({" +
                "select('#',GetAchievementInfo(42)),id,name,points,tostring(completed)," +
                "month,day,year,description,flags,icon,reward,tostring(isGuild)," +
                "tostring(earnedByMe),earnedBy,tostring(isStatistic),categoryID," +
                "select('#',GetCategoryInfo(1)),parent,categoryFlags,total,done," +
                "incomplete,tostring(GetAchievementNumRewards(42))," +
                "GetAchievementReward(42,1),GetAchievementNumCriteria(42)," +
                "#criteria,criteria[1],criteria[2],tostring(criteria[3]),criteria[4]," +
                "criteria[5],criteria[6],criteria[7],criteria[8],criteria[9]," +
                "criteria[10],tostring(criteria[11]),criteria[12],criteria[13]," +
                "#criteriaByID,C_AchievementInfo.GetRewardItemID(42),#supers,supers[1]," +
                "tostring(C_AchievementInfo.IsGuildAchievement(42))," +
                "tostring(C_AchievementInfo.IsValidAchievement(42))," +
                "tostring(IsAchievementEligible(42))," +
                "tostring(IsAchievementEligible(999)),GetPreviousAchievement(42)," +
                "select('#',GetNextAchievement(42)),nextID},':')"));

        Assert.Equal(
            "1:true:1:42:2:2:0:0:false:nil:nil:nil:0:0:0",
            session.Lua.Evaluate(
                "local searchReturns=select('#',SetAchievementSearchString('Known')); " +
                "local searchComplete=SetAchievementSearchString('Known'); " +
                "local filtered=GetNumFilteredAchievements(); " +
                "local filteredID=GetFilteredAchievementID(1); " +
                "local progress=GetAchievementSearchProgress(); " +
                "local searchSize=GetAchievementSearchSize(); " +
                "local badTab=pcall(SwitchAchievementSearchTab,4); " +
                "local switchReturns=select('#',SwitchAchievementSearchTab(3)); " +
                "local texture=UIParent:CreateTexture('AchievementPortrait'); " +
                "C_AchievementInfo.SetPortraitTexture(texture); " +
                "SetFocusedAchievement(43); SetFocusedAchievement(42); " +
                "ClearAchievementSearchString(); " +
                "return table.concat({searchReturns,tostring(searchComplete),filtered," +
                "filteredID,progress,searchSize,GetNumFilteredAchievements(),switchReturns," +
                "tostring(badTab),type(AddTrackedAchievement)," +
                "type(IsTrackedAchievement),type(RemoveTrackedAchievement)," +
                "select('#',C_AchievementTelemetry.ShowAchievements())," +
                "select('#',C_AchievementTelemetry.LinkAchievementInClub(42))," +
                "select('#',C_AchievementTelemetry.LinkAchievementInWhisper(42))},':')"));

        Assert.Equal(3, session.Lua.Achievements.SearchTabIndex);
        Assert.Equal(42, session.Lua.Achievements.FocusedAchievementId);
        Assert.Equal(
            12345u,
            session.Ui.Find("AchievementPortrait")!.Texture!.FileDataId);
        Assert.Equal(
            "player",
            session.Ui.Find("AchievementPortrait")!.Texture!.PortraitUnitToken);
    }

