    [Fact]
    public void AzeriteEssenceUsesNativeShapesArityEventsAndRequestSemantics()
    {
        using var emptySession = new EmulatorSession();
        Assert.Equal(
            "21:0:0:0:0:0:false:false:false:false",
            emptySession.Lua.Evaluate(
                "local count=0; for _ in pairs(C_AzeriteEssence) " +
                "do count=count+1 end;" +
                "return table.concat({" +
                "count,select('#',C_AzeriteEssence.GetEssences())," +
                "select('#',C_AzeriteEssence.GetMilestones())," +
                "select('#',C_AzeriteEssence.GetEssenceInfo(1))," +
                "select('#',C_AzeriteEssence.GetMilestoneInfo(1))," +
                "select('#',C_AzeriteEssence.GetMilestoneEssence(1))," +
                "tostring(pcall(C_AzeriteEssence.GetEssenceInfo))," +
                "tostring(pcall(C_AzeriteEssence.GetEssenceInfo,-1))," +
                "tostring(pcall(C_AzeriteEssence.GetEssenceHyperlink,1))," +
                "tostring(pcall(C_AzeriteEssence.CanActivateEssence,1))" +
                "},':')"));

        using var session = new EmulatorSession
        {
            AzeriteEssenceProvider = new TestAzeriteEssenceProvider()
        };
        var essence = session.Lua.AzeriteEssence;
        essence.CanOpenUi = true;
        essence.Essences.Add(
            new WowAzeriteEssenceInfoState(
                55,
                "Test Essence",
                3,
                true,
                true,
                1234,
                4));
        essence.Essences.Add(
            new WowAzeriteEssenceInfoState(
                66,
                null,
                1,
                false,
                true,
                5678,
                2));
        essence.UnlockedEssenceIds.Add(55);
        essence.UnlockedMilestoneIds.Add(10);
        essence.UnlockableMilestoneIds.Add(40);
        essence.ActivatablePairs.Add((55, 10));
        essence.DeactivatableMilestoneIds.Add(10);
        essence.ActiveEssenceByMilestoneId[10] = 77;

        session.Lua.PlayerInteractions.HasActiveInteraction = true;
        session.Lua.PlayerInteractions.CurrentInteractionType = 56;

        Assert.Equal(
            "2:55:Test Essence:3:true:true:1234:66:nil:1:false:true:" +
            "5678:55:Test Essence:true:true:1:1:77:true:false:true:" +
            "true:55:true:false:PENDING_AZERITE_ESSENCE_CHANGED:55:" +
            "AZERITE_ESSENCE_FORGE_CLOSE",
            session.Lua.Evaluate(
                "local pendingEvent,pendingID,closeEvent;" +
                "local listener=CreateFrame('Frame');" +
                "listener:RegisterEvent('PENDING_AZERITE_ESSENCE_CHANGED');" +
                "listener:RegisterEvent('AZERITE_ESSENCE_FORGE_CLOSE');" +
                "listener:SetScript('OnEvent',function(_,event,id) " +
                "if event=='PENDING_AZERITE_ESSENCE_CHANGED' then " +
                "pendingEvent=event; pendingID=id else closeEvent=event end end);" +
                "local all=C_AzeriteEssence.GetEssences();" +
                "local one=C_AzeriteEssence.GetEssenceInfo(55);" +
                "local validLink=C_AzeriteEssence." +
                "GetEssenceHyperlink(55,0);" +
                "local invalidLink=C_AzeriteEssence." +
                "GetEssenceHyperlink(55,9);" +
                "C_AzeriteEssence.SetPendingActivationEssence(55);" +
                "C_AzeriteEssence.SetPendingActivationEssence(66);" +
                "C_AzeriteEssence.ActivateEssence(55,10);" +
                "C_AzeriteEssence.UnlockMilestone(40);" +
                "C_AzeriteEssence.CloseForge();" +
                "return table.concat({" +
                "#all,all[1].ID,all[1].name,all[1].rank," +
                "tostring(all[1].unlocked),tostring(all[1].valid)," +
                "all[1].icon,all[2].ID,tostring(all[2].name)," +
                "all[2].rank,tostring(all[2].unlocked)," +
                "tostring(all[2].valid),all[2].icon,one.ID,one.name," +
                "tostring(validLink==" +
                "'|cnIQ2:|Hazessence:55:1|h[Test Essence]|h|r')," +
                "tostring(invalidLink=='')," +
                "C_AzeriteEssence.GetNumUnlockedEssences()," +
                "C_AzeriteEssence.GetNumUsableEssences()," +
                "C_AzeriteEssence.GetMilestoneEssence(10)," +
                "tostring(C_AzeriteEssence.CanActivateEssence(55,10))," +
                "tostring(C_AzeriteEssence.CanActivateEssence(66,10))," +
                "tostring(C_AzeriteEssence.CanDeactivateEssence(10))," +
                "tostring(C_AzeriteEssence.CanOpenUI())," +
                "C_AzeriteEssence.GetPendingActivationEssence()," +
                "tostring(C_AzeriteEssence.HasPendingActivationEssence())," +
                "tostring(C_AzeriteEssence." +
                "HasNeverActivatedAnyEssences()),pendingEvent,pendingID," +
                "closeEvent},':')"));

        Assert.Equal(
            [new WowAzeriteEssenceActivationRequest(55, 10)],
            essence.ActivationRequests);
        Assert.Equal([40], essence.UnlockMilestoneRequests);
        Assert.Equal(77, essence.ActiveEssenceByMilestoneId[10]);
        Assert.DoesNotContain(40, essence.UnlockedMilestoneIds);
        Assert.Equal(55, essence.PendingActivationEssenceId);
        Assert.False(session.Lua.PlayerInteractions.HasActiveInteraction);
        Assert.Equal(
            56,
            session.Lua.PlayerInteractions.LastClearInteractionType);

        Assert.Equal(
            "0:false:true",
            session.Lua.Evaluate(
                "local cleared=false; local f=CreateFrame('Frame');" +
                "f:RegisterEvent('PENDING_AZERITE_ESSENCE_CHANGED');" +
                "f:SetScript('OnEvent',function(_,_,id) cleared=id==nil end);" +
                "C_AzeriteEssence.ClearPendingActivationEssence();" +
                "return table.concat({" +
                "C_AzeriteEssence.GetPendingActivationEssence()," +
                "tostring(C_AzeriteEssence.HasPendingActivationEssence())," +
                "tostring(cleared)},':')"));
        Assert.Null(essence.PendingActivationEssenceId);
    }

