    [Fact]
    public void ContentTrackingUsesNativeEnumsOrderingAndResultShapes()
    {
        using var session = new EmulatorSession();
        var tracking = session.Lua.ContentTracking;
        tracking.TrackableEntries.Add((0, 20));
        tracking.TrackableEntries.Add((0, 10));
        tracking.BestMaps[(0, 20, false)] =
            new WowContentTrackingBestMapResult(0, 777);
        tracking.CurrentTargets[(0, 20)] = new WowContentTrackingTarget(4, 91);
        tracking.EncounterInfo[77] = new WowContentTrackingEncounterInfo(
            EncounterName: "Boss",
            JournalEncounterId: 77,
            GroupFinderActivityId: 88);
        var mapInfo = new WowContentTrackingMapInfo(
            0.25f,
            0.75f,
            0,
            20,
            4,
            91,
            "Map point");
        tracking.NextWaypoints[(0, 20, 777)] =
            new WowContentTrackingWaypointResult(0, mapInfo);
        tracking.ObjectiveTexts[(4, 91, true)] = "Do it";
        tracking.Titles[(0, 20)] = "Tracked";
        tracking.TrackablesOnMaps[(0, 777)] =
            new WowContentTrackingMapResult(0, [mapInfo]);
        tracking.VendorInfo[8] = new WowContentTrackingVendorInfo(
            CreatureName: "Vendor",
            Cost: 12345);
        tracking.WaypointTexts[(0, 20)] = "Follow";
        tracking.Navigability[(0, 20)] =
            new WowContentTrackingNavigableResult(0, true);

        Assert.Equal(
            "0:3:20:10:0:777:4:91:Boss:88:0:0.25:4:Do it:Tracked:" +
            "0:1:Map point:Vendor:12345:Follow:0:true:" +
            "false:false:false:false:false:false:false",
            session.Lua.Evaluate(
                "C_ContentTracking.StartTracking(0,20); " +
                "C_ContentTracking.StartTracking(0,10); " +
                "local types=C_ContentTracking.GetCollectableSourceTypes(); " +
                "local ids=C_ContentTracking.GetTrackedIDs(0); " +
                "local bestResult,bestMap=C_ContentTracking.GetBestMapForTrackable(0,20); " +
                "local targetType,targetID=C_ContentTracking.GetCurrentTrackingTarget(0,20); " +
                "local encounter=C_ContentTracking.GetEncounterTrackingInfo(77); " +
                "local waypointResult,waypoint=C_ContentTracking.GetNextWaypointForTrackable(0,20,777); " +
                "local objective=C_ContentTracking.GetObjectiveText(4,91,true); " +
                "local title=C_ContentTracking.GetTitle(0,20); " +
                "local mapResult,mapEntries=C_ContentTracking.GetTrackablesOnMap(0,777); " +
                "local vendor=C_ContentTracking.GetVendorTrackingInfo(8); " +
                "local waypointText=C_ContentTracking.GetWaypointText(0,20); " +
                "local navigableResult,navigable=C_ContentTracking.IsNavigable(0,20); " +
                "local badType=pcall(C_ContentTracking.IsTrackable,4,1); " +
                "local missingID=pcall(C_ContentTracking.IsTracking,0); " +
                "local missingStop=pcall(C_ContentTracking.StopTracking,0,20); " +
                "local badStop=pcall(C_ContentTracking.ToggleTracking,0,20,3); " +
                "local badOptional=pcall(C_ContentTracking.GetBestMapForTrackable,0,20,1); " +
                "local badTarget=pcall(C_ContentTracking.GetObjectiveText,5,91); " +
                "C_ContentTracking.StopTracking(0,20,2); " +
                "return table.concat({types[1],types[2],ids[1],ids[2]," +
                "bestResult,bestMap,targetType,targetID,encounter.encounterName," +
                "encounter.groupFinderActivityID,waypointResult,waypoint.x," +
                "waypoint.targetType,objective,title,mapResult,#mapEntries," +
                "mapEntries[1].waypointText,vendor.creatureName,vendor.cost," +
                "waypointText,navigableResult,tostring(navigable)," +
                "tostring(badType),tostring(missingID),tostring(missingStop)," +
                "tostring(badStop),tostring(badOptional),tostring(badTarget)," +
                "tostring(C_ContentTracking.IsTracking(0,20))},':')"));
        Assert.Equal(2, tracking.LastStopType);
        Assert.Equal([(0, 10)], tracking.TrackedEntries);
    }

    [Fact]
    public void ContentTrackingStartUsesNativeDuplicateCapacityAndTrackabilityOrder()
    {
        using var session = new EmulatorSession();
        var tracking = session.Lua.ContentTracking;
        tracking.TrackedEntries.Add((0, 7));
        for (var id = 100; id < 114; id++)
            tracking.TrackedEntries.Add((0, id));
        tracking.TrackableEntries.Add((0, 999));

        Assert.Equal(
            "2:1:0",
            session.Lua.Evaluate(
                "return table.concat({" +
                "C_ContentTracking.StartTracking(0,7)," +
                "C_ContentTracking.StartTracking(0,999)," +
                "C_ContentTracking.StartTracking(1,999)" +
                "},':')"));

        tracking.TrackedEntries.Clear();
        for (var id = 0; id < 10; id++)
            tracking.TrackedEntries.Add((2, id));
        tracking.TrackableEntries.Add((2, 999));

        Assert.Equal(
            "1",
            session.Lua.Evaluate(
                "return tostring(C_ContentTracking.StartTracking(2,999))"));
    }

