                "local add1=C_CombatAudioAlert.AddToKnownTargetingList('player'); " +
                "local add2=C_CombatAudioAlert.AddToKnownTargetingList('PLAYER'); " +
                "local addBad=C_CombatAudioAlert.AddToKnownTargetingList('not-a-unit'); " +
                "local remove1=C_CombatAudioAlert.RemoveFromKnownTargetingList('Player'); " +
                "local remove2=C_CombatAudioAlert.RemoveFromKnownTargetingList('player'); " +
                "local voice1=C_CombatAudioAlert.SetCategoryVoice(2,2); " +
                "local voice2=C_CombatAudioAlert.SetCategoryVoice(2,3); " +
                "local volume1=C_CombatAudioAlert.SetCategoryVolume(3,75); " +
                "local volume2=C_CombatAudioAlert.SetCategoryVolume(3,101); " +
                "local f00a=C_CombatAudioAlert.SetFormatSetting(0,0,5); " +
                "local f00b=C_CombatAudioAlert.SetFormatSetting(0,0,6); " +
                "local f01a=C_CombatAudioAlert.SetFormatSetting(0,1,4); " +
                "local f01b=C_CombatAudioAlert.SetFormatSetting(0,1,5); " +
                "local f10a=C_CombatAudioAlert.SetFormatSetting(1,0,8); " +
                "local f10b=C_CombatAudioAlert.SetFormatSetting(1,0,9); " +
                "local f11a=C_CombatAudioAlert.SetFormatSetting(1,1,6); " +
                "local f11b=C_CombatAudioAlert.SetFormatSetting(1,1,7); " +
                "local speed1=C_CombatAudioAlert.SetSpeakerSpeed(-10); " +
                "local speed2=C_CombatAudioAlert.SetSpeakerSpeed(10); " +
                "local speed3=C_CombatAudioAlert.SetSpeakerSpeed(11); " +
                "local spec0a=C_CombatAudioAlert.SetSpecSetting(0,5); " +
                "local spec0b=C_CombatAudioAlert.SetSpecSetting(0,6); " +
                "local spec2a=C_CombatAudioAlert.SetSpecSetting(2,2); " +
                "local spec2b=C_CombatAudioAlert.SetSpecSetting(2,3); " +
                "local spec3a=C_CombatAudioAlert.SetSpecSetting(3,100); " +
                "local spec3b=C_CombatAudioAlert.SetSpecSetting(3,101); " +
                "local spec8a=C_CombatAudioAlert.SetSpecSetting(8,3); " +
                "local spec8b=C_CombatAudioAlert.SetSpecSetting(8,4); " +
                "local throttle1=C_CombatAudioAlert.SetThrottle(1,2.5); " +
                "local throttle0=C_CombatAudioAlert.SetThrottle(0,2); " +
                "local throttle7=C_CombatAudioAlert.SetThrottle(7,2); " +
                "local throttleBad=C_CombatAudioAlert.SetThrottle(1,5.1); " +
                "local speakCount=select('#',C_CombatAudioAlert.SpeakText('hello',1,true)); " +
                "local badCategory=pcall(C_CombatAudioAlert.GetCategoryVoice,9); " +
                "local badThrottle=pcall(C_CombatAudioAlert.GetThrottle,11); " +
                "local badUnit=pcall(C_CombatAudioAlert.GetFormatSetting,2,0); " +
                "local missing=pcall(C_CombatAudioAlert.SetCategoryVolume,1); " +
                "local badOverlap=pcall(C_CombatAudioAlert.SpeakText,'x',1,1); " +
                "local badToken=pcall(C_CombatAudioAlert.AddToKnownTargetingList,{}); " +
                "return table.concat({" +
                "tostring(add1),tostring(add2),tostring(addBad),tostring(remove1),tostring(remove2)," +
                "tostring(voice1),C_CombatAudioAlert.GetCategoryVoice(2),tostring(voice2)," +
                "C_CombatAudioAlert.GetCategoryVoice(2),tostring(volume1)," +
                "C_CombatAudioAlert.GetCategoryVolume(3),tostring(volume2)," +
                "C_CombatAudioAlert.GetCategoryVolume(3)," +
                "tostring(f00a),tostring(f00b),tostring(f01a),tostring(f01b)," +
                "tostring(f10a),tostring(f10b),tostring(f11a),tostring(f11b)," +
                "C_CombatAudioAlert.GetFormatSetting(1,1)," +
                "tostring(speed1),tostring(speed2),tostring(speed3)," +
                "C_CombatAudioAlert.GetSpeakerSpeed()," +
                "tostring(spec0a),tostring(spec0b),tostring(spec2a),tostring(spec2b)," +
                "tostring(spec3a),tostring(spec3b),tostring(spec8a),tostring(spec8b)," +
                "tostring(throttle1),tostring(throttle0),tostring(throttle7)," +
                "tostring(throttleBad),C_CombatAudioAlert.GetThrottle(0)," +
                "C_CombatAudioAlert.GetThrottle(1),C_CombatAudioAlert.GetThrottle(7),speakCount," +
                "tostring(badCategory),tostring(badThrottle),tostring(badUnit)," +
                "tostring(missing),tostring(badOverlap),tostring(badToken)" +
                "},':')"));

        Assert.Equal(
            new WowCombatAudioAlertSpeech("hello", 1, true),
            audio.LastSpeechRequest);
        Assert.Equal(
            new WowCombatAudioAlertSpeech("hello", 1, true),
            Assert.Single(audio.SpokenRequests));

        Assert.Equal(
            "true:1:true:2:true:80:true:90",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(C_CombatAudioAlert.SetCategoryVoice(5,1))," +
                "C_CombatAudioAlert.GetSpecSetting(2)," +
                "tostring(C_CombatAudioAlert.SetSpecSetting(6,2))," +
                "C_CombatAudioAlert.GetCategoryVoice(6)," +
                "tostring(C_CombatAudioAlert.SetCategoryVolume(5,80))," +
                "C_CombatAudioAlert.GetSpecSetting(3)," +
                "tostring(C_CombatAudioAlert.SetSpecSetting(7,90))," +
                "C_CombatAudioAlert.GetCategoryVolume(6)" +
                "},':')"));

        audio.ActiveSpecializationIndex = 1;
        Assert.Equal(
            "true:4",
            session.Lua.Evaluate(
                "return tostring(C_CombatAudioAlert.SetSpecSetting(0,4)) .. ':' .. " +
                "C_CombatAudioAlert.GetSpecSetting(0)"));
        audio.ActiveSpecializationIndex = 2;
        Assert.Equal(
            "0:true:5",
            session.Lua.Evaluate(
                "return C_CombatAudioAlert.GetSpecSetting(0) .. ':' .. " +
                "tostring(C_CombatAudioAlert.SetSpecSetting(0,5)) .. ':' .. " +
                "C_CombatAudioAlert.GetSpecSetting(0)"));
        audio.ActiveSpecializationIndex = 1;
        Assert.Equal("4", session.Lua.Evaluate(
            "return tostring(C_CombatAudioAlert.GetSpecSetting(0))"));

        audio.Available = false;
        Assert.Equal(
            "false:0:0:false",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(C_CombatAudioAlert.IsEnabled())," +
                "C_CombatAudioAlert.GetSpeakerSpeed()," +
                "C_CombatAudioAlert.GetThrottle(7)," +
                "tostring(C_CombatAudioAlert.SetSpeakerSpeed(0))" +
                "},':')"));
    }

