        session.Lua.PlayerInteractions.CurrentInteractionType = 41;

        Assert.Equal(
            "8:0:7:1:101:2:201:202:Contribution-A:nil:Contribution-C:Contribution-D:" +
            "Building:nil:Two minutes remain:true:Status-Atlas:Border-Atlas:Banner-Atlas:" +
            "301:nil:Collector:Collector-Atlas:401:0.4:0.6:0:War Effort:Supply the front.:" +
            "2:101:102:7:601:25:701:3:501:3:0.625:1700000000:1234:false:true:true",
            session.Lua.Evaluate(
                "local appearance=C_ContributionCollector.GetContributionAppearance(101,3); " +
