                "local activeCount=select('#',C_ContributionCollector.GetActive()); " +
                "local active=C_ContributionCollector.GetActive(); " +
                "local buffCount=select('#',C_ContributionCollector.GetBuffs(101)); " +
                "local buff1,buff2=C_ContributionCollector.GetBuffs(101); " +
                "local managedCount=select('#',C_ContributionCollector.GetManagedContributionsForCreatureID(401)); " +
                "local managed1,managed2=C_ContributionCollector.GetManagedContributionsForCreatureID(401); " +
                "C_ContributionCollector.Contribute(101); " +
                "local pending=C_ContributionCollector.HasPendingContribution(101); " +
                "local awaiting=C_ContributionCollector.IsAwaitingRewardQuestData(101); " +
                "C_ContributionCollector.Close(); " +
                "return table.concat({" +
                "Enum.ContributionResultMeta.NumValues,Enum.ContributionResult.Success,Enum.ContributionResult.InternalError," +
                "activeCount,active,buffCount,buff1,buff2," +
                "C_ContributionCollector.GetAtlases(101)[1],tostring(C_ContributionCollector.GetAtlases(101)[2])," +
                "C_ContributionCollector.GetAtlases(101)[3],C_ContributionCollector.GetAtlases(101)[4]," +
                "appearance.stateName,type(appearance.stateColor.GetRGBA),appearance.tooltipLine," +
                "tostring(appearance.tooltipUseTimeRemaining),appearance.statusBarAtlas,appearance.borderAtlas,appearance.bannerAtlas," +
                "collector.areaPoiID,type(collector.position.GetXY),collector.name,collector.atlasName,collector.collectorCreatureID,x,y," +
                "C_ContributionCollector.GetContributionResult(101),C_ContributionCollector.GetName(101)," +
                "C_ContributionCollector.GetDescription(101),managedCount,managed1,managed2," +
                "C_ContributionCollector.GetOrderIndex(101),currencyID,currencyAmount,itemID,itemCount," +
                "C_ContributionCollector.GetRewardQuestID(101),contributionState,percentage,nextTime,startTime," +
                "tostring(C_ContributionCollector.HasPendingContribution(999)),tostring(pending),tostring(awaiting)},':')"));

        Assert.Equal(1, contributions.ContributionRequestCount);
        Assert.Equal((uint)101, contributions.LastContributionId);
        Assert.Equal(1, session.Lua.PlayerInteractions.ClearInteractionRequests);
        Assert.Equal(41, session.Lua.PlayerInteractions.LastClearInteractionType);
        Assert.False(session.Lua.PlayerInteractions.HasActiveInteraction);
