    [Fact]
    public void TradeInfoMatchesNativeMoneyMutationAritiesAndValidationContracts()
    {
        using var session = new EmulatorSession();
        session.Lua.Client.Money = 200_000_000_000;
        session.Lua.Client.PlayerTradeMoney = 100;
        session.Lua.Client.TargetTradeMoney = 55;
        session.Lua.Cursor.SetMoney(25);
        session.Lua.TradeInfo.IsTradeOpen = true;
        session.Lua.TradeInfo.ShouldShowTradeOfferWarning = true;

        Assert.Equal(
            "100:55:true:0:125:nil:0:105:20:0:99999999999:0:true",
            session.Lua.Evaluate(
                "local playerBefore=GetPlayerTradeMoney(); " +
                "local targetMoney=GetTargetTradeMoney(); " +
                "local warning=C_TradeInfo.ShouldShowTradeOfferWarning(); " +
                "local addCount=select('#',C_TradeInfo.AddTradeMoney()); " +
                "local playerAfterAdd=GetPlayerTradeMoney(); " +
                "local cursorAfterAdd=GetCursorInfo(); " +
                "local pickupCount=select('#',C_TradeInfo.PickupTradeMoney(20)); " +
                "local playerAfterPickup=GetPlayerTradeMoney(); " +
                "local cursorMoney=GetCursorMoney(); " +
                "local setCount=select('#',C_TradeInfo.SetTradeMoney(100000000005)); " +
                "local playerAfterSet=GetPlayerTradeMoney(); " +
                "local closeCount=select('#',CloseTrade()); " +
                "return table.concat({" +
                "playerBefore,targetMoney,tostring(warning),addCount,playerAfterAdd," +
                "tostring(cursorAfterAdd),pickupCount,playerAfterPickup,cursorMoney," +
                "setCount,playerAfterSet,closeCount," +
                "tostring(C_TradeInfo.ShouldShowTradeOfferWarning())},':')"));

        var trade = session.Lua.TradeInfo;
        Assert.Equal(1, trade.AddTradeMoneyRequests);
        Assert.Equal(1, trade.SuccessfulAddTradeMoneyRequests);
        Assert.Equal(1, trade.PickupTradeMoneyRequests);
        Assert.Equal(1, trade.SuccessfulPickupTradeMoneyRequests);
        Assert.Equal((ulong)20, trade.LastPickupTradeMoneyAmount);
        Assert.Equal(1, trade.SetTradeMoneyRequests);
        Assert.Equal(1, trade.SuccessfulSetTradeMoneyRequests);
        Assert.Equal((ulong)100_000_000_005, trade.LastRequestedTradeMoneyAmount);
        Assert.Equal((ulong)99_999_999_999, trade.LastClampedTradeMoneyAmount);
        Assert.Equal(1, trade.CloseTradeRequests);
        Assert.False(trade.IsTradeOpen);

        session.Lua.Client.Money = 50;
        session.Lua.Cursor.SetMoney(10);
        Assert.Equal(
            "0:99999999999:10:0:99999999999:false:true:false:false",
            session.Lua.Evaluate(
                "local addCount=select('#',C_TradeInfo.AddTradeMoney()); " +
                "local afterAdd=GetPlayerTradeMoney(); " +
                "local cursorMoney=GetCursorMoney(); " +
                "local setCount=select('#',C_TradeInfo.SetTradeMoney(60)); " +
                "return table.concat({" +
                "addCount,afterAdd,cursorMoney,setCount,GetPlayerTradeMoney()," +
                "tostring(pcall(C_TradeInfo.PickupTradeMoney,-1))," +
                "tostring(pcall(C_TradeInfo.SetTradeMoney,0/0))," +
                "tostring(pcall(C_TradeInfo.SetTradeMoney,9007199254740992))," +
                "tostring(pcall(C_TradeInfo.PickupTradeMoney,'money'))},':')"));

        Assert.Equal(2, trade.AddTradeMoneyRequests);
        Assert.Equal(1, trade.SuccessfulAddTradeMoneyRequests);
        Assert.Equal(3, trade.SetTradeMoneyRequests);
        Assert.Equal(2, trade.SuccessfulSetTradeMoneyRequests);
        Assert.Equal(1UL << 63, trade.LastRequestedTradeMoneyAmount);
        Assert.Equal((ulong)0, trade.LastClampedTradeMoneyAmount);
        Assert.Equal((ulong)0, session.Lua.Client.PlayerTradeMoney);
    }

    [Fact]
    public void ItemSocketInfoMatchesNativeRecordsAritiesEnumsAndIndexContracts()
    {
        using var session = new EmulatorSession();
        var socketInfo = session.Lua.ItemSocketInfo;
        socketInfo.IsOpen = true;
        socketInfo.SocketItemName = "Socketed Blade";
        socketInfo.SocketItemIconFileDataId = 9876;
        socketInfo.SocketItemQuality = 4;
        socketInfo.SocketItemBoundTradeable = true;
        socketInfo.SocketItemRefundable = true;
        socketInfo.HasBoundGemProposed = true;
        socketInfo.Sockets.Add(new WowItemSocketState(
            "Ruby",
            111,
            true,
            "|Hitem:101|h[Ruby]|h",
            "Sapphire",
            222,
            false,
            "|Hitem:102|h[Sapphire]|h",
            "Red"));
        socketInfo.Sockets.Add(new WowItemSocketState(
            SocketType: "Prismatic"));
        socketInfo.ArtifactRelicItemIds.Add(900);
        session.Lua.Items.Items[900] = new WowItemData
        {
            ItemId = 900,
            Name = "Ancient Relic",
            Link = "|Hitem:900|h[Ancient Relic]|h"
        };

        Assert.Equal(
            "0:1:0:0:2:3:Ruby:111:true:" +
            "|Hitem:101|h[Ruby]|h:3:Sapphire:222:false:" +
            "|Hitem:102|h[Sapphire]|h:Red:Prismatic:" +
            "Socketed Blade:9876:4:true:true:true:true:true:false:" +
            "0:0:0:false:false:false",
            session.Lua.Evaluate(
                "local en=Enum.ItemSocketInfoUIType; " +
                "local meta=Enum.ItemSocketInfoUITypeMeta; " +
                "local existingName,existingIcon,existingMatches=" +
                "C_ItemSocketInfo.GetExistingSocketInfo(1); " +
                "local newName,newIcon,newMatches=" +
                "C_ItemSocketInfo.GetNewSocketInfo(1); " +
                "local itemName,itemIcon,itemQuality=" +
                "C_ItemSocketInfo.GetSocketItemInfo(); " +
                "local acceptCount=select('#'," +
                "C_ItemSocketInfo.AcceptSockets()); " +
                "local clickCount=select('#'," +
                "C_ItemSocketInfo.ClickSocketButton(2)); " +
                "local completeCount=select('#'," +
                "C_ItemSocketInfo.CompleteSocketing()); " +
                "return table.concat({" +
                "en.Default,meta.NumValues,meta.MinValue,meta.MaxValue," +
                "C_ItemSocketInfo.GetNumSockets()," +
                "select('#',C_ItemSocketInfo.GetExistingSocketInfo(1))," +
                "existingName,existingIcon,tostring(existingMatches)," +
                "C_ItemSocketInfo.GetExistingSocketLink(1)," +
                "select('#',C_ItemSocketInfo.GetNewSocketInfo(1))," +
                "newName,newIcon,tostring(newMatches)," +
                "C_ItemSocketInfo.GetNewSocketLink(1)," +
                "C_ItemSocketInfo.GetSocketTypes(1)," +
                "C_ItemSocketInfo.GetSocketTypes(2)," +
                "itemName,itemIcon,itemQuality," +
                "tostring(C_ItemSocketInfo.GetSocketItemBoundTradeable())," +
                "tostring(C_ItemSocketInfo.GetSocketItemRefundable())," +
                "tostring(C_ItemSocketInfo.HasBoundGemProposed())," +
                "tostring(C_ItemSocketInfo.IsArtifactRelicItem(900))," +
                "tostring(C_ItemSocketInfo.IsArtifactRelicItem(" +
                "'Ancient Relic'))," +
                "tostring(C_ItemSocketInfo.IsArtifactRelicItem(901))," +
                "acceptCount,clickCount,completeCount," +
                "tostring(pcall(C_ItemSocketInfo.GetSocketTypes,-1))," +
                "tostring(pcall(C_ItemSocketInfo.GetNewSocketLink," +
                "4294967296))," +
                "tostring(pcall(C_ItemSocketInfo.IsArtifactRelicItem,{}))" +
                "},':')"));

        Assert.Equal(1, socketInfo.AcceptSocketsRequests);
        Assert.Equal(1, socketInfo.ClickSocketButtonRequests);
        Assert.Equal((uint)1, socketInfo.LastClickedSocketIndex);
        Assert.Equal(1, socketInfo.CompleteSocketingRequests);
        Assert.Equal(
            "nil:nil:false:nil",
            session.Lua.Evaluate(
                "local name,icon,matches=" +
                "C_ItemSocketInfo.GetExistingSocketInfo(3); " +
                "return table.concat({tostring(name),tostring(icon)," +
                "tostring(matches),tostring(" +
                "C_ItemSocketInfo.GetExistingSocketLink(3))},':')"));
        Assert.Equal(
            "0\ttrue",
            session.Lua.Evaluate(
                "return select('#',C_ItemSocketInfo.CloseSocketInfo())," +
                "tostring(C_ItemSocketInfo.IsArtifactRelicItem(" +
                "'|Hitem:900|h[Ancient Relic]|h'))"));
        Assert.False(socketInfo.IsOpen);
        Assert.Equal(1, socketInfo.CloseSocketInfoRequests);
    }

    [Fact]
    public void IslandsQueueMatchesNativeRecordsInteractionAndArgumentContracts()
    {
        using var session = new EmulatorSession();
        var islandsQueue = session.Lua.IslandsQueue;
        islandsQueue.Difficulties.Add(
            new WowIslandDifficultyInfoState(1, 51001));
        islandsQueue.Difficulties.Add(
            new WowIslandDifficultyInfoState(2, 51002));
        islandsQueue.WeeklyQuestEligibilityFlags = 2;

        var interactions = session.Lua.PlayerInteractions;
        interactions.HasActiveInteraction = true;
        interactions.HasPendingInteraction = true;
        interactions.CurrentInteractionType = 43;
        interactions.PendingInteractionType = 43;
        interactions.ValidNpcInteractionTypes.Add(43);

        Assert.Equal(
            "2:1:51001:2:51002:3:53436:0:0:false:" +
            "0:0:false:false:false:false:false:false",
            session.Lua.Evaluate(
                "local difficulties=" +
                "C_IslandsQueue.GetIslandDifficultyInfo(); " +
                "local queueCount=select('#'," +
                "C_IslandsQueue.QueueForIsland(2.9)); " +
                "local preloadCount=select('#'," +
                "C_IslandsQueue.RequestPreloadRewardData(51002)); " +
                "return table.concat({" +
                "#difficulties," +
                "difficulties[1].difficultyId," +
                "difficulties[1].previewRewardQuestId," +
                "difficulties[2].difficultyId," +
                "difficulties[2].previewRewardQuestId," +
                "C_IslandsQueue.GetIslandsMaxGroupSize()," +
                "C_IslandsQueue.GetIslandsWeeklyQuestID()," +
                "queueCount,preloadCount," +
                "tostring(C_PlayerInteractionManager." +
                "IsInteractingWithNpcOfType(43))," +
                "select('#',C_IslandsQueue.CloseIslandsQueueScreen())," +
                "select('#',C_IslandsQueue.QueueForIsland(-1))," +
                "tostring(pcall(C_IslandsQueue.QueueForIsland))," +
                "tostring(pcall(C_IslandsQueue.QueueForIsland,{}))," +
                "tostring(pcall(C_IslandsQueue.QueueForIsland,0/0))," +
                "tostring(pcall(C_IslandsQueue.QueueForIsland,1/0))," +
                "tostring(pcall(C_IslandsQueue.QueueForIsland," +
                "2147483648))," +
                "tostring(pcall(C_IslandsQueue." +
                "RequestPreloadRewardData,-2147483649))" +
                "},':')"));

        Assert.Equal(1, islandsQueue.CloseScreenRequests);
        Assert.Equal(2, islandsQueue.QueueRequests);
        Assert.Equal(1, islandsQueue.SuccessfulQueueRequests);
        Assert.Equal(-1, islandsQueue.LastRequestedDifficultyId);
        Assert.Equal(2, islandsQueue.LastQueuedDifficultyId);
        Assert.Equal(1, islandsQueue.PreloadRewardDataRequests);
        Assert.Equal(51002, islandsQueue.LastPreloadRewardQuestId);
        Assert.Equal(2, interactions.ClearInteractionRequests);
        Assert.Equal(43, interactions.LastClearInteractionType);

        islandsQueue.WeeklyQuestEligibilityFlags = 5;
        Assert.Equal(
            "53435",
            session.Lua.Evaluate(
                "return C_IslandsQueue.GetIslandsWeeklyQuestID()"));
        islandsQueue.WeeklyQuestEligibilityFlags = 0;
        Assert.Equal(
            "nil",
            session.Lua.Evaluate(
                "return tostring(" +
                "C_IslandsQueue.GetIslandsWeeklyQuestID())"));
    }

