                "C_GossipInfo.GetNumActiveQuests()," +
                "C_GossipInfo.GetNumAvailableQuests()," +
                "active[1].title,active[1].questLevel," +
                "tostring(active[1].isTrivial),active[1].frequency," +
                "tostring(active[1].repeatable)," +
                "tostring(active[1].isComplete)," +
                "tostring(active[1].isLegendary)," +
                "tostring(active[1].isIgnored),active[1].questID," +
                "tostring(active[1].isImportant)," +
                "tostring(active[1].isMeta),active[1].questInfoID," +
                "available[1].title,available[1].questLevel," +
                "tostring(available[1].isTrivial)," +
                "tostring(available[1].frequency)," +
                "tostring(available[1].repeatable)," +
                "tostring(available[1].isComplete)," +
                "tostring(available[1].isLegendary)," +
                "tostring(available[1].isIgnored)," +
                "available[1].questID," +
                "tostring(available[1].isImportant)," +
                "tostring(available[1].isMeta)," +
                "available[1].questInfoID," +
                "C_GossipInfo.GetCompletedOptionDescriptionString()," +
                "tostring(C_GossipInfo." +
                "GetCustomGossipDescriptionString())," +
                "#widgets,widgets[1].widgetType," +
                "widgets[1].uiWidgetSetID,#options," +
                "options[1].gossipOptionID,options[1].name," +
                "options[1].icon,#options[1].rewards," +
