                "options[1].rewards[1].rewardType," +
                "options[1].rewards[1].context,options[1].status," +
                "tostring(options[1].spellID),options[1].flags," +
                "options[1].overrideIconID," +
                "tostring(options[1].selectOptionWhenOnlyOption)," +
                "options[1].orderIndex,options[1].failureDescription," +
                "friendship.friendshipFactionID,friendship.standing," +
                "friendship.maxRep,friendship.name,friendship.text," +
                "friendship.texture,friendship.reaction," +
                "friendship.reactionThreshold," +
                "friendship.nextThreshold," +
                "tostring(friendship.reversedColor)," +
                "tostring(friendship.overrideColor)," +
                "ranks.currentLevel,ranks.maxLevel," +
                "C_GossipInfo.GetPoiForUiMapID(84),poi.name," +
                "poi.textureIndex,poi.position.x,poi.position.y," +
                "tostring(poi.inBattleMap),C_GossipInfo.GetText()" +
                "},':')"));

        Assert.Equal(
            "1:1:nil:1:nil:1:nil:0:1:2:0:1:4:2:true",
            session.Lua.Evaluate(
                "return table.concat({" +
                "select('#',C_GossipInfo.GetFriendshipReputation(999))," +
                "select('#',C_GossipInfo.GetPoiInfo(84,999))," +
                "tostring(C_GossipInfo.GetPoiInfo(84,999))," +
                "select('#',C_GossipInfo.GetPoiForUiMapID(999))," +
                "tostring(C_GossipInfo.GetPoiForUiMapID(999))," +
                "select('#',C_GossipInfo." +
                "GetCustomGossipDescriptionString())," +
                "tostring(C_GossipInfo." +
                "GetCustomGossipDescriptionString())," +
                "#C_GossipInfo." +
                "GetOptionUIWidgetSetsAndTypesByOptionID(999)," +
                "#C_GossipInfo.GetOptions()," +
                "Enum.GossipOptionRewardTypeMeta.NumValues," +
                "Enum.GossipOptionRewardTypeMeta.MinValue," +
                "Enum.GossipOptionRewardTypeMeta.MaxValue," +
                "Enum.GossipOptionStatusMeta.NumValues," +
                "Enum.GossipOptionUIWidgetSetTypesMeta.NumValues," +
                "tostring(Enum.GossipOptionStatus.AlreadyComplete==3)" +
                "},':')"));

        Assert.Equal(
            "false:false:false:false:false:false",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(pcall(C_GossipInfo.GetPoiInfo,84))," +
                "tostring(pcall(C_GossipInfo.GetPoiInfo,{},77))," +
                "tostring(pcall(C_GossipInfo.GetPoiInfo,1/0,77))," +
                "tostring(pcall(C_GossipInfo.SelectOption))," +
                "tostring(pcall(C_GossipInfo.SelectOption,1,{}))," +
                "tostring(pcall(C_GossipInfo.SelectOption,1,nil,1))" +
                "},':')"));

        session.Lua.Evaluate(
            "C_GossipInfo.RefreshOptions(); " +
            "C_GossipInfo.SelectActiveQuest(501); " +
            "C_GossipInfo.SelectActiveQuest(999); " +
            "C_GossipInfo.SelectAvailableQuest(502); " +
            "C_GossipInfo.SelectAvailableQuest(999); " +
            "C_GossipInfo.SelectOption(600,'hello',true); " +
            "C_GossipInfo.SelectOptionByIndex(2,42); " +
            "C_GossipInfo.CloseGossip()");

        Assert.False(gossip.IsOpen);
        Assert.Equal(1, gossip.CloseRequests);
        Assert.Equal(1, gossip.RefreshRequests);
        Assert.Equal(
            [
                new WowGossipSelectionRequest(
                    "SelectActiveQuest",
                    501,
                    null,
                    null),
                new WowGossipSelectionRequest(
                    "SelectAvailableQuest",
                    502,
                    null,
                    null),
                new WowGossipSelectionRequest(
                    "SelectOption",
                    600,
                    "hello",
                    true),
                new WowGossipSelectionRequest(
                    "SelectOptionByIndex",
                    2,
                    "42",
                    null)
            ],
            gossip.SelectionRequests);
    }

