    [Fact]
    public void EncodingUtilPreservesBinaryDataAndDecodesCompressedCbor()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "11:0:world:11:0:world:11:0:world:2:12.0.7:3:1:2",
            session.Lua.Evaluate(
                "local function decode(value, method) " +
                "local bytes=C_EncodingUtil.DecodeBase64(value); " +
                "local result=C_EncodingUtil.DecompressString(bytes,method); " +
                "return #result,string.byte(result,6),string.sub(result,7) end; " +
                "local r1,n1,s1=decode('y0jNyclnKM8vykkBAA==',Enum.CompressionMethod.Deflate); " +
                "local r2,n2,s2=decode('eJzLSM3JyWcozy/KSQEAGUsEPQ==',Enum.CompressionMethod.Zlib); " +
                "local r3,n3,s3=decode('H4sIAAAAAAACCstIzcnJZyjPL8pJAQCzFOYKCwAAAA==',Enum.CompressionMethod.Gzip); " +
                "local data=C_EncodingUtil.DecodeBase64('o2d2ZXJzaW9uAmVidWlsZGYxMi4wLjdmdmFsdWVzgwECAw=='); " +
                "local value=C_EncodingUtil.DeserializeCBOR(data); " +
                "return table.concat({r1,n1,s1,r2,n2,s2,r3,n3,s3,value.version,value.build," +
                "#value.values,value.values[1],value.values[2]},':')"));
