    [Fact]
    public void MessageFrameApisFollowNativeMethodArgumentsDefaultsAndState()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "3:1:true:BOTTOM:10:nil:nil:nil:false:false:false:true:TOP:7:4:false:true:false",
            session.Lua.Evaluate(
                "MessageFrameAudit=CreateFrame('MessageFrame','MessageFrameAudit',UIParent); " +
                "local f=MessageFrameAudit; f:SetSize(400,200); " +
                "local initialDuration,initialPower,initialFading,initialMode,initialTime=" +
                "f:GetFadeDuration(),f:GetFadePower(),f:GetFading(),f:GetInsertMode(),f:GetTimeVisible(); " +
                "local missing=pcall(f.AddMessage,f); " +
                "local partialColor=pcall(f.AddMessage,f,'bad',1,0); " +
                "f:AddMessage('first',1,0,0,0.5,17); " +
                "f:AddMessage('second',nil,nil,nil,nil,18); " +
                "local fontString=f:GetFontStringByID(17); " +
                "f:SetFadeDuration(7); f:SetFadePower(4); f:SetFadePower(0); " +
                "f:SetFading(false); f:SetInsertMode('top'); " +
                "f:SetIndentedWordWrap(true); f:SetTimeVisible(9); " +
                "return table.concat({" +
                "initialDuration,initialPower,tostring(initialFading),initialMode,initialTime," +
                "tostring(fontString)," +
                "tostring(f.GetNumMessages),tostring(f.SetMaxLines)," +
                "tostring(missing),tostring(partialColor)," +
                "tostring(f:HasMessageByID(17)),tostring(f:GetIndentedWordWrap())," +
                "f:GetInsertMode(),f:GetFadeDuration(),f:GetFadePower()," +
                "tostring(f:GetFading()),tostring(type(f.GetFont) == 'function')," +
                "tostring(type(f.AddLine) == 'function')},':')"));

        var frame = session.Ui.Find("MessageFrameAudit")!;
        Assert.Collection(
            frame.Messages,
            first =>
            {
                Assert.Equal("first", first.Text);
                Assert.Equal((uint)17, first.MessageId);
                Assert.Equal((byte)128, first.Alpha);
            },
            second =>
            {
                Assert.Equal("second", second.Text);
                Assert.Equal((uint)18, second.MessageId);
                Assert.Null(second.Alpha);
            });
        Assert.Equal(string.Empty, frame.Font!.Text);

        session.Tick(0);
        Assert.Empty(frame.Messages);
        Assert.Equal(
            "table\ttrue",
            session.Lua.Evaluate(
                "return type(MessageFrameAudit:GetFontStringByID(17))," +
                "tostring(MessageFrameAudit:HasMessageByID(17))"));
        Assert.Equal(2, frame.MessageLines.Count(line => line.Active));
        Assert.All(
            frame.MessageLines.Where(line => line.Active),
            line =>
            {
                Assert.Equal(7, line.FadeDuration);
                Assert.Equal(9, line.TimeVisible);
            });

        session.Lua.Evaluate(
            "MessageFrameAudit:ResetMessageFadeByID(17); MessageFrameAudit:Clear()");
        Assert.Empty(frame.Messages);
        Assert.DoesNotContain(frame.MessageLines, line => line.Active);
        Assert.Equal(string.Empty, frame.Font.Text);

        session.Lua.Evaluate(
            "for i=1,105 do " +
            "MessageFrameAudit:AddMessage(tostring(i),nil,nil,nil,nil,i) end");
        Assert.Equal(101, frame.Messages.Count);
        session.Lua.Evaluate("MessageFrameAudit:Clear()");
    }

