    [Fact]
    public void AccountStoreApisFollowNativeShapesDefaultsStateAndTransactions()
    {
        using var session = new EmulatorSession
        {
            AccountStoreProvider = new TestAccountStoreProvider()
        };
        session.Lua.AccountStore.Currencies[42] =
            new WowAccountStoreCurrencyState(1234, 0, "Plunder", 222);
        session.Lua.AccountStore.CurrencyIdsByStoreFront[0] = 42;
        session.Lua.AccountStore.StoreFrontStates[0] =
            WowAccountStoreFrontState.Available;

        Assert.Equal(
            "404::2:0:1:nil:1:1:1:2:8:false:1234:0:Plunder:222:42:0:true",
            session.Lua.Evaluate(
                "local missingCategory=C_AccountStore.GetCategoryInfo(404);" +
                "local missingItem=C_AccountStore.GetItemInfo(404);" +
                "local item=C_AccountStore.GetItemInfo(77);" +
                "local currency=C_AccountStore.GetCurrencyInfo(42);" +
                "return table.concat({" +
                "missingCategory.id,missingCategory.name,missingCategory.type,missingCategory.icon," +
                "select('#',C_AccountStore.GetCurrencyIDForStore(404))," +
                "tostring(C_AccountStore.GetCurrencyIDForStore(404))," +
                "select('#',missingItem),C_AccountStore.GetStoreFrontState(404)," +
                "item.status,item.mode,item.flags,tostring(item.nonrefundable)," +
                "currency.amount,currency.maxQuantity,currency.name,currency.icon," +
                "C_AccountStore.GetCurrencyIDForStore(0)," +
                "C_AccountStore.GetStoreFrontState(0)," +
                "tostring(C_AccountStore.BeginPurchase(77))},':')"));
        Assert.Equal(77, session.Lua.AccountStore.PendingPurchaseItemId);

        session.Lua.AccountStore.Items[77] = new WowAccountStoreItemState(
            WowAccountStoreItemStatus.Refundable,
            WowAccountStoreItemMode.Locked,
            45.5);

        Assert.Equal(
            "2:3:45.5:1:true:0",
            session.Lua.Evaluate(
                "local item=C_AccountStore.GetItemInfo(77);" +
                "local items=C_AccountStore.GetCategoryItems(12);" +
                "return table.concat({item.status,item.mode,item.refundSecondsRemaining," +
                "#items,tostring(C_AccountStore.RefundItem(77))," +
                "select('#',C_AccountStore.RequestStoreFrontInfoUpdate(3))},':')"));
        Assert.Equal(77, session.Lua.AccountStore.PendingRefundItemId);
        Assert.Equal(3, session.Lua.AccountStore.RequestedStoreFrontId);

        session.Lua.AccountStore.Items[77] = new WowAccountStoreItemState(
            WowAccountStoreItemStatus.Owned,
            WowAccountStoreItemMode.Hidden);
        Assert.Equal(
            "0",
            session.Lua.Evaluate(
                "return #C_AccountStore.GetCategoryItems(12)"));

        Assert.Equal(
            "1:2:3:1:2:3:0:1:2:3139:2814",
            session.Lua.Evaluate(
                "return table.concat({" +
                "Enum.AccountStoreItemStatus.Unowned," +
                "Enum.AccountStoreItemStatus.Refundable," +
                "Enum.AccountStoreItemStatus.Owned," +
                "Enum.AccountStoreItemMode.Normal," +
                "Enum.AccountStoreItemMode.Hidden," +
                "Enum.AccountStoreItemMode.Locked," +
                "Enum.AccountStoreState.Available," +
                "Enum.AccountStoreState.Unknown," +
                "Enum.AccountStoreState.Unavailable," +
                "Constants.AccountStoreConsts.PlunderstormPlunderCurrencyID," +
                "Constants.AccountStoreConsts.KegLegRenownCurrencyID},':')"));
    }

