    [Fact]
    public void KioskCommandsOnlyMutateStateWhenEnabled()
    {
        using var session = new EmulatorSession();

        session.Lua.Evaluate(
            "Kiosk.EnableGodMode(); Kiosk.RequestHousingReset(); Kiosk.StartSession(); return 0");
        Assert.False(session.Lua.Kiosk.IsGodModeRequested);
        Assert.False(session.Lua.Kiosk.IsHousingResetPending);
        Assert.Equal(WowKioskSessionState.Lobby, session.Lua.Kiosk.SessionState);

        session.Lua.Kiosk.IsEnabled = true;
        session.Lua.Evaluate(
            "Kiosk.EnableGodMode(); Kiosk.RequestHousingReset(); Kiosk.StartSession(); return 0");
        Assert.True(session.Lua.Kiosk.IsGodModeRequested);
        Assert.True(session.Lua.Kiosk.IsHousingResetPending);
        Assert.Equal(WowKioskSessionState.Active, session.Lua.Kiosk.SessionState);
        Assert.Equal(
            "false:false",
            session.Lua.Evaluate(
                "return tostring(Kiosk.IsExpired())..':'..tostring(Kiosk.IsInLobby())"));
    }

