    [Fact]
    public void MountJournalArgumentsFiltersAndCommandsMatchNativeContracts()
    {
        using var session = new EmulatorSession();
        var equipmentLocation = WowItemLocation.Equipment(4);
        session.Lua.MountJournal.MountEquipmentItemLocations.Add(equipmentLocation);

        Assert.Equal(
            "1:nil:true:true:false:false:true:false:true:false",
            session.Lua.Evaluate(
                "return table.concat({" +
                "select('#',C_MountJournal.GetAppliedMountEquipmentID())," +
                "tostring(C_MountJournal.GetAppliedMountEquipmentID())," +
                "tostring(C_MountJournal.GetCollectedFilterSetting(1))," +
                "tostring(C_MountJournal.IsValidSourceFilter(12))," +
                "tostring(C_MountJournal.IsValidSourceFilter(13))," +
                "tostring(C_MountJournal.IsValidTypeFilter(4))," +
                "tostring(C_MountJournal.IsValidTypeFilter(5))," +
                "tostring(C_MountJournal.IsValidTypeFilter(33))," +
                "tostring(C_MountJournal.IsItemMountEquipment({equipmentSlotIndex=4}))," +
                "tostring(type(C_MountJournal.CanPlayerUseMountEquipment)=='function')" +
                "},':')"));

        Assert.Equal(
            "false:false:false",
            session.Lua.Evaluate(
                "local a=pcall(C_MountJournal.GetCollectedFilterSetting);" +
                "local b=pcall(C_MountJournal.IsValidSourceFilter,-1);" +
                "local c=pcall(C_MountJournal.SummonByID,{});" +
                "return table.concat({tostring(a),tostring(b),tostring(c)},':')"));

        session.Lua.Evaluate(
            "C_MountJournal.SummonByID(0); C_MountJournal.ClearRecentFanfares(); return 0");
        Assert.Null(session.Lua.MountJournal.SummonedMountId);
        Assert.Equal(0, session.Lua.MountJournal.MountsNeedingFanfare);

        Assert.Equal(
            "1:2:3:false:false:false:false:griffon:true:true:true",
            session.Lua.Evaluate(
                "C_MountJournal.SetCollectedFilterSetting(1,false); " +
                "C_MountJournal.SetSourceFilter(2,false); " +
                "C_MountJournal.SetTypeFilter(5,false); " +
                "C_MountJournal.SetSearch('griffon'); " +
                "local changed=table.concat({LE_MOUNT_JOURNAL_FILTER_COLLECTED," +
                "LE_MOUNT_JOURNAL_FILTER_NOT_COLLECTED,LE_MOUNT_JOURNAL_FILTER_UNUSABLE," +
                "tostring(C_MountJournal.GetCollectedFilterSetting(1))," +
                "tostring(C_MountJournal.IsSourceChecked(2))," +
                "tostring(C_MountJournal.IsTypeChecked(5))," +
                "tostring(C_MountJournal.IsUsingDefaultFilters()),'griffon'},':'); " +
                "C_MountJournal.SetDefaultFilters(); return changed..':'.." +
                "table.concat({tostring(C_MountJournal.GetCollectedFilterSetting(1))," +
                "tostring(C_MountJournal.IsSourceChecked(2))," +
                "tostring(C_MountJournal.IsUsingDefaultFilters())},':')"));
        Assert.Equal("griffon", session.Lua.MountJournal.SearchText);
    }

