    [Fact]
    public void TraitMutationCallbacksValidateArgumentsAndReturnBackendResults()
    {
        using var session = new EmulatorSession();
        var traits = session.Lua.Traits;
        traits.CascadeRepurchaseResults[(9, 41, 31)] = true;
        traits.CommitConfigResults[9] = true;
        traits.PurchaseRankResults[(9, 41)] = true;
        traits.RefundAllRanksResults[(9, 41)] = true;
        traits.RefundRankResults[(9, 41, true)] = true;
        traits.RollbackConfigResults[9] = true;
        traits.SetSelectionResults[(9, 41, 31, true)] = true;

        Assert.Equal(
            "true:true:true:true:true:true:true:0",
            session.Lua.Evaluate(
                "local a=C_Traits.CascadeRepurchaseRanks(9,41,31);" +
                "local b=C_Traits.CommitConfig(9);" +
                "local c=C_Traits.PurchaseRank(9,41);" +
                "local d=C_Traits.RefundAllRanks(9,41);" +
                "local e=C_Traits.RefundRank(9,41,true);" +
                "local f=C_Traits.RollbackConfig(9);" +
                "local g=C_Traits.SetSelection(9,41,31,true);" +
                "local h=select('#',C_Traits.ClearCascadeRepurchaseHistory(9));" +
                "return table.concat({tostring(a),tostring(b),tostring(c)," +
                "tostring(d),tostring(e),tostring(f),tostring(g),h},':')"));

        Assert.Single(traits.CascadeRepurchaseRequests);
        Assert.Single(traits.ClearedCascadeRepurchaseHistoryConfigIds);
        Assert.Single(traits.CommitConfigRequests);
        Assert.Single(traits.PurchaseRankRequests);
        Assert.Single(traits.RefundAllRanksRequests);
        Assert.Single(traits.RefundRankRequests);
        Assert.Single(traits.RollbackConfigRequests);
        Assert.Single(traits.SelectionRequests);
        Assert.True(traits.IsReadyForCommit);

        Assert.Equal(
            "false:false:false:false:false:false:false:false",
            session.Lua.Evaluate(
                "local a=pcall(C_Traits.CascadeRepurchaseRanks,9);" +
                "local b=pcall(C_Traits.ClearCascadeRepurchaseHistory);" +
                "local c=pcall(C_Traits.CommitConfig);" +
                "local d=pcall(C_Traits.PurchaseRank,9);" +
                "local e=pcall(C_Traits.RefundAllRanks,9);" +
                "local f=pcall(C_Traits.RefundRank,9,41,1);" +
                "local g=pcall(C_Traits.RollbackConfig);" +
                "local h=pcall(C_Traits.SetSelection,9,41,nil,1);" +
                "return table.concat({tostring(a),tostring(b),tostring(c)," +
                "tostring(d),tostring(e),tostring(f),tostring(g),tostring(h)},':')"));
    }

    [Fact]
    public void ItemUpgradeQueriesAndLifecycleMatchNativeContracts()
    {
        using var session = new EmulatorSession();
        var location = WowItemLocation.Bag(0, 1);
        session.Lua.Items.LocationItemIds[location] = 12345;
        session.Lua.Items.LocationItemIds[WowItemLocation.Bag(0, 2)] = 12346;
        session.Lua.ItemUpgrade.UpgradableItemLocations.Add(location);
        session.Lua.ItemUpgrade.IsOpen = true;
        var discount = new WowItemUpgradeDiscountInfoState(
            true,
            515,
            false,
            true,
            true);
        session.Lua.ItemUpgrade.CurrentItemInfo =
            new WowItemUpgradeItemInfoState(
                100,
                "Upgradeable Blade",
                true,
                4,
                16,
                2,
                6,
                500,
                528,
                [
                    new WowItemUpgradeLevelInfoState(
                        3,
                        4,
                        4,
                        [new WowItemUpgradeStatState("+10 Strength", 10, true)],
                        [new WowItemUpgradeCurrencyCostState(15, 3008, discount)],
                        [new WowItemUpgradeItemCostState(2, 20001, discount)],
                        123,
                        null)
                ],
                "Veteran 2/6",
                [
                    new WowItemUpgradeCostTypeForSeasonState(
                        null,
                        3008,
                        1,
                        "Crests")
                ]);

        Assert.Equal(
            "true:false:true:100:Upgradeable Blade:true:4:16:2:6:500:528:" +
            "1:3:4:+10 Strength:10:true:15:3008:true:515:2:20001:123:" +
            "Veteran 2/6:1:nil:3008:1:Crests",
            session.Lua.Evaluate(
                "local location={bagID=0,slotIndex=1};" +
                "local info=C_ItemUpgrade.GetItemUpgradeItemInfo();" +
                "local level=info.upgradeLevelInfos[1];" +
                "local stat=level.levelStats[1];" +
                "local currency=level.currencyCostsToUpgrade[1];" +
                "local item=level.itemCostsToUpgrade[1];" +
                "local costType=info.upgradeCostTypesForSeason[1];" +
                "return table.concat({" +
                "tostring(C_ItemUpgrade.CanUpgradeItem(location))," +
                "tostring(C_ItemUpgrade.CanUpgradeItem({bagID=0,slotIndex=2}))," +
                "tostring(info~=nil),info.iconID,info.name,tostring(info.itemUpgradeable)," +
                "info.displayQuality,info.highWatermarkSlot,info.currUpgrade,info.maxUpgrade," +
                "info.minItemLevel,info.maxItemLevel,#info.upgradeLevelInfos," +
                "level.upgradeLevel,level.itemLevelIncrement,stat.displayString,stat.statValue," +
                "tostring(stat.active),currency.cost,currency.currencyID," +
                "tostring(currency.discountInfo.isDiscounted)," +
                "currency.discountInfo.discountHighWatermark,item.cost,item.itemID," +
                "level.moneyCost,info.customUpgradeString,#info.upgradeCostTypesForSeason," +
                "tostring(costType.itemID),costType.currencyID,costType.orderIndex," +
                "costType.sourceString},':')"));

        Assert.Equal(
            "false:false:false",
            session.Lua.Evaluate(
                "local a=pcall(C_ItemUpgrade.CanUpgradeItem);" +
                "local b=pcall(C_ItemUpgrade.CanUpgradeItem,{bagID=0,slotIndex=99});" +
                "local c=pcall(C_ItemUpgrade.CanUpgradeItem,{});" +
                "return table.concat({tostring(a),tostring(b),tostring(c)},':')"));

        Assert.Equal(
            "0:0",
            session.Lua.Evaluate(
                "local a=select('#',C_ItemUpgrade.CloseItemUpgrade());" +
                "local b=select('#',C_ItemUpgrade.ClearItemUpgrade());" +
                "return table.concat({a,b},':')"));
        Assert.False(session.Lua.ItemUpgrade.IsOpen);
        Assert.Null(session.Lua.ItemUpgrade.CurrentItemInfo);
        Assert.Equal(1, session.Lua.ItemUpgrade.CloseRequestCount);
        Assert.Equal(1, session.Lua.ItemUpgrade.ClearRequestCount);
        Assert.Equal(
            "0",
            session.Lua.Evaluate(
                "return select('#',C_ItemUpgrade.GetItemUpgradeItemInfo())"));
    }

    [Fact]
    public void TtsSettingsValidateNativeRangesAndChannelRecords()
    {
        using var session = new EmulatorSession();
        session.Lua.TtsSettings.OverrideMessages.Add((7, "Override me"));

        Assert.Equal(
            "0:100:true:false:true:false:12:Voice:true:true:false",
            session.Lua.Evaluate(
                "local channel={" +
                "name='General',shortcut='1',localID=7,instanceID=0," +
                "zoneChannelID=0,channelType=1};" +
                "C_TTSSettings.SetSpeechRate(5);" +
                "C_TTSSettings.SetSpeechRate(11);" +
                "C_TTSSettings.SetSpeechVolume(80);" +
                "C_TTSSettings.SetSpeechVolume(101);" +
                "C_TTSSettings.SetSetting(2,true);" +
                "C_TTSSettings.SetSetting(4);" +
                "C_TTSSettings.SetVoiceOption(1,12);" +
                "C_TTSSettings.SetVoiceOptionName(1,'Voice');" +
                "C_TTSSettings.SetChatTypeEnabled('SAY',false);" +
                "C_TTSSettings.SetChannelEnabled(channel,true);" +
                "C_TTSSettings.SetChannelKeyEnabled('custom',true);" +
                "C_TTSSettings.MarkCharacterSettingsSaved();" +
                "return table.concat({" +
                "C_TTSSettings.GetSpeechRate()-5," +
                "C_TTSSettings.GetSpeechVolume()+20," +
                "tostring(C_TTSSettings.GetSetting(2))," +
                "tostring(C_TTSSettings.GetSetting(4))," +
                "tostring(C_TTSSettings.GetChannelEnabled(channel))," +
                "tostring(C_TTSSettings.GetChatTypeEnabled('SAY'))," +
                "C_TTSSettings.GetVoiceOptionID(1)," +
                "C_TTSSettings.GetVoiceOptionName(1)," +
                "tostring(C_TTSSettings.GetCharacterSettingsSaved())," +
                "tostring(C_TTSSettings.ShouldOverrideMessage(7,'Override me'))," +
                "tostring(C_TTSSettings.ShouldOverrideMessage(7,'Other'))},':')"));

        Assert.Equal(
            "false:false:false:false:false:false:false:false:false:false",
            session.Lua.Evaluate(
                "local a=pcall(C_TTSSettings.GetSetting,5);" +
                "local b=pcall(C_TTSSettings.SetSetting,0,1);" +
                "local c=pcall(C_TTSSettings.GetVoiceOptionID,2);" +
                "local d=pcall(C_TTSSettings.SetSpeechRate);" +
                "local e=pcall(C_TTSSettings.SetSpeechVolume,-1);" +
                "local f=pcall(C_TTSSettings.GetChatTypeEnabled,{});" +
                "local g=pcall(C_TTSSettings.GetChannelEnabled,{name='x'});" +
                "local h=pcall(C_TTSSettings.SetChannelKeyEnabled,1,true);" +
                "local i=pcall(C_TTSSettings.SetVoiceOptionName,0,1);" +
                "local j=pcall(C_TTSSettings.ShouldOverrideMessage,7);" +
                "return table.concat({tostring(a),tostring(b),tostring(c)," +
                "tostring(d),tostring(e),tostring(f),tostring(g),tostring(h)," +
                "tostring(i),tostring(j)},':')"));

        Assert.Equal(
            "0:100:true:false:false",
            session.Lua.Evaluate(
                "C_TTSSettings.SetDefaultSettings();" +
                "local channel={name='General',shortcut='1',localID=7," +
                "instanceID=0,zoneChannelID=0,channelType=1};" +
                "return table.concat({C_TTSSettings.GetSpeechRate()," +
                "C_TTSSettings.GetSpeechVolume()," +
                "tostring(C_TTSSettings.GetSetting(0))," +
                "tostring(C_TTSSettings.GetSetting(4))," +
                "tostring(C_TTSSettings.GetChannelEnabled(channel))},':')"));
    }

