        session.Lua.LfgList.Applications.AddRange(
        [
            new WowLfgApplicationInfo(101, 1, 0, 12, "tank"),
            new WowLfgApplicationInfo(102, 0, 2, -5, "healer"),
            new WowLfgApplicationInfo(103, 0, 0, 8, "not-a-role")
        ]);

        Assert.Equal(
            "101,102:1,3:3:1:true:false:true:true:true:true:77:2:101:applied:nil:12:TANK:" +
            "102:none:invited:0:HEALER:0:2",
