                "local categories=C_LFGList.GetAvailableCategories({});" +
                "local total,active=C_LFGList.GetNumApplications();" +
                "local tank,healer,damage=C_LFGList.GetAvailableRoles();" +
                "local checking,activityID=C_LFGList.GetRoleCheckInfo();" +
                "local a1,a2,a3,a4,a5=C_LFGList.GetApplicationInfo(101);" +
                "local b1,b2,b3,b4,b5=C_LFGList.GetApplicationInfo(102);" +
                "local missing=select('#',C_LFGList.GetApplicationInfo(999));" +
                "C_LFGList.RequestAvailableActivities();" +
                "return table.concat({" +
                "table.concat(applications,','),table.concat(categories,','),total,active," +
                "tostring(tank),tostring(healer),tostring(damage)," +
                "tostring(C_LFGList.HasActiveEntryInfo())," +
                "tostring(C_LFGList.HasActivityList()),tostring(checking),activityID," +
                "C_LFGList.GetPremadeGroupFinderStyle(),a1,a2,tostring(a3),a4,a5," +
