            "SET graphicsQuality \"5\"",
            "SET uiScale \"0.75\"",
            "SET sampleText \"quoted \\\"value\\\"\"",
            "not a cvar"
        ]);

        Assert.Equal(3, imported);
        Assert.Equal(
            "5:5:0.75:1:quoted \"value\"",
            session.Lua.Evaluate(
                "return table.concat({" +
                "C_CVar.GetCVar('graphicsQuality'),C_CVar.GetCVarDefault('graphicsQuality')," +
                "C_CVar.GetCVar('uiScale'),C_CVar.GetCVarDefault('uiScale'),C_CVar.GetCVar('sampleText')" +
                "},':')"));
    }

    [Fact]
    public void ClientConfigCVarsSurviveSessionRuntimeRecreation()
    {
        var root = Path.Combine(Path.GetTempPath(), $"WoWAddonLab-{Guid.NewGuid():N}");
        try
        {
            Directory.CreateDirectory(root);
            var configPath = Path.Combine(root, "Config.wtf");
            File.WriteAllText(configPath, "SET graphicsQuality \"5\"");
            using var session = new EmulatorSession
            {
                ClientCVarConfigPath = configPath
            };

