                "select('#',C_StoreSecure.ClearPreGeneratedExternalTransactionID())," +
                "select('#',C_StoreSecure.PurchaseVASProduct(" +
                "1,'Player-1-1',nil,nil,nil,nil,nil,nil,false,false))," +
                "tostring(C_StoreSecure.PurchaseVASProduct(" +
                "1,'Player-1-1',nil,nil,nil,nil,nil,nil,false,false))," +
                "select('#',C_StoreSecure.RequestCharacterGuildFollowInfo('Player-1-1',1))," +
                "select('#',C_StoreSecure.RequestRealmGuildMasterInfo(1))," +
                "select('#',C_StoreSecure.ValidateBnetTransfer('WoW1'))," +
