                "local m=C_StoreSecure.GetVASGuildMasterInfoForCharacterByGUID('Player-1-2'); " +
                "return table.concat({tostring(C_StoreSecure.AckFailure()),bg,bi[1]," +
                "c.name,c.classFileName,c.createScreenIconAtlas," +
                "currency.currencyID,currency.sharedData.regionID," +
                "currency.sharedData.formatShort,tostring(currency.sharedData.requireLicenseAccept)," +
                "races[1].raceName,tostring(races[1].isHeritageArmorUnlocked)," +
                "e.productID,e.groupID,e.sharedData.name,e.sharedData.normalDollars," +
                "e.sharedData.normalCents,e.sharedData.cards[1].title," +
                "#e.sharedData.cards[1].itemModifiedAppearanceIDs," +
                "e.sharedData.deliverables[1].name,g.groupName,p[1]," +
                "r.realmName,tostring(r.pvp),f.transferredRealm,tostring(f.factionChanged)," +
                "m.guildName,m.guildMemberInfos[1].memberName," +
                "C_StoreSecure.GetVasServiceType(5)," +
                "C_StoreSecure.GetWoWAccountGUIDFromName('WoW1',true)," +
                "tostring(C_StoreSecure.HasDynamicPriceData(5))," +
                "tostring(C_StoreSecure.HasProductType(2))," +
                "tostring(C_StoreSecure.IsDynamicBundle(5))," +
                "tostring(C_StoreSecure.IsVASEligibleCharacterGUID('Player-1-2'))," +
                "tostring(C_StoreSecure.PurchaseProduct(5))," +
                "tostring(C_StoreSecure.PurchaseProductConfirm(true,8,49))},':')"));

        Assert.Equal(3, store.Requests.Count);
        Assert.Equal(
            ["GetProducts", "PurchaseProduct", "PurchaseProductConfirm"],
            store.Requests.Select(request => request.Operation));
    }

