    [Fact]
    public void TooltipSetOwnerStartsAFreshOwnerRelativeTooltip()
    {
        using var session = new EmulatorSession();

        var result = session.Lua.Evaluate(
            "(function() " +
            "local first=CreateFrame('Frame','FirstTooltipOwner',UIParent); " +
            "first:SetSize(30,30); first:SetPoint('CENTER',UIParent,'CENTER',0,0); " +
            "GameTooltip:SetOwner(first,'ANCHOR_LEFT'); GameTooltip:AddLine('old one'); " +
            "GameTooltip:AddLine('old two'); GameTooltip:Show(); GameTooltip:Hide(); " +
            "GameTooltip:SetOwner(first,'ANCHOR_LEFT'); GameTooltip:AddLine('fresh'); " +
            "return GameTooltip:GetLeftLine(1):GetText()..':'..GameTooltip:NumLines() end)()");

        Assert.Equal("fresh:1", result);
        var owner = session.Ui.ResolveBounds(session.Ui.Find("FirstTooltipOwner")!.Id);
        var tooltip = session.Ui.ResolveBounds(session.Ui.Find("GameTooltip")!.Id);
        Assert.Equal(owner.Left, tooltip.Right);
        Assert.Equal(owner.Top, tooltip.Bottom);
    }

    [Fact]
    public void TooltipRightAnchorUsesTheNativeCornerPairAndOwnerOffsets()
    {
        using var session = new EmulatorSession();

        session.Lua.Evaluate(
            "local owner=CreateFrame('Frame','RightTooltipOwner',UIParent); " +
            "owner:SetSize(30,30); owner:SetPoint('CENTER',UIParent,'CENTER',0,0); " +
            "GameTooltip:SetOwner(owner,'ANCHOR_RIGHT',3,-4); " +
            "GameTooltip:SetText('Native corner placement')");

        var owner = session.Ui.ResolveBounds(session.Ui.Find("RightTooltipOwner")!.Id);
        var tooltip = session.Ui.ResolveBounds(session.Ui.Find("GameTooltip")!.Id);
        Assert.Equal(owner.Right + 3, tooltip.Left);
        Assert.Equal(owner.Top - 4, tooltip.Bottom);
    }

    [Fact]
    public void TooltipLinesUseChildFontStringsAndDriveTooltipLayout()
    {
        using var session = new EmulatorSession();

        var result = session.Lua.Evaluate(
            "(function() " +
            "GameTooltip:SetOwner(UIParent,'ANCHOR_NONE'); " +
            "GameTooltip:SetPadding(3,4,5,6); GameTooltip:SetMinimumWidth(90); " +
            "GameTooltip:SetText('Heading',1,.8,0); " +
            "GameTooltip:AddDoubleLine('Left value','Right value',1,1,1,.5,.6,.7); " +
            "local left=GameTooltip:GetLeftLine(2); local right=GameTooltip:GetRightLine(2); " +
            "local r,b,l,t=GameTooltip:GetPadding(); " +
            "return table.concat({GameTooltip:NumLines(),left:GetText(),right:GetText()," +
            "left:GetJustifyH(),right:GetJustifyH(),r,b,l,t},':') end)()");

        Assert.Equal("2:Left value:Right value:LEFT:RIGHT:3:4:5:6", result);
        var tooltip = session.Ui.Find("GameTooltip")!;
        Assert.Null(tooltip.Font);
        Assert.True(tooltip.Width >= 90);
        Assert.True(tooltip.Height > 20);
        Assert.Equal(2, tooltip.Tooltip!.Lines.Count);
        Assert.All(
            tooltip.Tooltip.Lines,
            line =>
            {
                Assert.True(session.Ui.Find(line.LeftId)!.Shown);
                Assert.NotEmpty(session.Ui.Find(line.LeftId)!.Anchors);
            });
    }

