    [Fact]
    public void WrappedTooltipLinesShrinkFromTheNativeWidthPresetAndGrowVertically()
    {
        using var session = new EmulatorSession();
        const string longText =
            "This tooltip contains enough separate words to require several rows " +
            "instead of making the tooltip continue growing horizontally forever.";

        session.Lua.Evaluate(
            $"GameTooltip:SetOwner(UIParent,'ANCHOR_NONE'); " +
            $"GameTooltip:SetText('{longText}',1,1,1,1,true)");

        var tooltip = session.Ui.Find("GameTooltip")!;
        var left = session.Ui.Find(tooltip.Tooltip!.Lines[0].LeftId)!;

        Assert.True(tooltip.Width < 250.4f);
        Assert.Equal(tooltip.Width!.Value - 20, left.Width!.Value, 3);
        Assert.True(left.Height > left.Font!.FontSize);
        Assert.True(
            int.Parse(
                session.Lua.Evaluate("return GameTooltip:GetLeftLine(1):GetNumLines()"),
                System.Globalization.CultureInfo.InvariantCulture) > 1);
    }

    [Fact]
    public void UnwrappedTooltipLinesCanGrowPastTheNativeWrappedWidthPreset()
    {
        using var session = new EmulatorSession();
        const string longText =
            "This tooltip contains enough separate words to be substantially wider " +
            "than the native wrapped tooltip preset when wrapping is disabled.";

        session.Lua.Evaluate(
            $"GameTooltip:SetOwner(UIParent,'ANCHOR_NONE'); " +
            $"GameTooltip:SetText('{longText}',1,1,1,1,false)");

        var tooltip = session.Ui.Find("GameTooltip")!;
        var left = session.Ui.Find(tooltip.Tooltip!.Lines[0].LeftId)!;

        Assert.True(tooltip.Width > 250.4f);
        Assert.Null(left.Width);
        Assert.Equal(left.Font!.FontSize, left.Height);
        Assert.Equal("1", session.Lua.Evaluate("return GameTooltip:GetLeftLine(1):GetNumLines()"));
        Assert.Equal("false", session.Lua.Evaluate("return tostring(GameTooltip:GetLeftLine(1):IsTruncated())"));
    }

