    {
        using var session = new EmulatorSession();
        const string longText =
            "This left tooltip column wraps while retaining room for its right value.";

        session.Lua.Evaluate(
            "GameTooltip:SetOwner(UIParent,'ANCHOR_NONE'); " +
            $"GameTooltip:AddDoubleLine('{longText}','Value',1,1,1,1,1,1,true)");

        var tooltip = session.Ui.Find("GameTooltip")!;
        var line = tooltip.Tooltip!.Lines[0];
        var left = session.Ui.Find(line.LeftId)!;
        var right = session.Ui.Find(line.RightId)!;

        Assert.True(tooltip.Width > 250.4f);
        Assert.False(line.Wrap);
        Assert.Null(right.Width);
        Assert.True(session.Ui.ResolveBounds(right.Id).Width > 0);
        Assert.Equal(left.Font!.FontSize, left.Height);
    }

