    [Fact]
    public void TexturePixelSnappingAndTilingMethodsPreserveClientState()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "0.3:true:false:false:1.0:0.0:false:false:true:true",
            session.Lua.Evaluate(
                "(function() " +
                "local texture=UIParent:CreateTexture('SnappingTexture'); " +
                "local initialBias=texture:GetTexelSnappingBias(); " +
                "local initialSnap=texture:IsSnappingToPixelGrid(); " +
                "local initialHoriz=texture:GetHorizTile(); local initialVert=texture:GetVertTile(); " +
                "texture:SetTexelSnappingBias(2); local high=texture:GetTexelSnappingBias(); " +
                "texture:SetTexelSnappingBias(-2); local low=texture:GetTexelSnappingBias(); " +
                "texture:SetSnapToPixelGrid(false); texture:SetHorizTile(); texture:SetVertTile(true); " +
                "return table.concat({string.format('%.1f',initialBias),tostring(initialSnap)," +
                "tostring(initialHoriz),tostring(initialVert),string.format('%.1f',high)," +
                "string.format('%.1f',low),tostring(texture:IsSnappingToPixelGrid())," +
                "tostring(texture:GetHorizTile()),tostring(texture:GetVertTile())," +
                "tostring(type(texture.SetTexelSnappingBias)=='function')},':') end)()"));

        var texture = session.Ui.Find("SnappingTexture")!.Texture!;
        Assert.False(texture.SnapToPixelGrid);
        Assert.Equal(0, texture.TexelSnappingBias);
        Assert.False(texture.HorizontallyTiled);
        Assert.True(texture.VerticallyTiled);
    }

    [Fact]
    public void TextureMutatorsFollowClientReturnDefaultsAndCoordinateValidation()
    {
        using var session = new EmulatorSession();
        session.AtlasProvider = new TestAtlasProvider();

        var result = session.Lua.Evaluate(
            "(function() " +
            "local texture=UIParent:CreateTexture('NativeTextureValidation'); " +
            "texture:SetAtlas('TestAtlas'); local atlasBefore=texture:GetAtlas(); " +
            "local atlasClearReturns=select('#',texture:SetAtlas(nil)); " +
            "local clearedAtlas=tostring(texture:GetAtlas()); " +
            "local textureResult=texture:SetTexture(nil); " +
            "texture:SetTexture(134400,true,false,'NEAREST'); " +
            "texture:SetTexCoord(.1,.9,.2,.8); " +
            "texture:SetTexCoord(10001,.9,.2,.8); " +
            "local ulx,uly,_,_,_,_,lrx,lry=texture:GetTexCoord(); " +
            "texture:SetHorizTile(true); texture:SetHorizTile(); " +
            "texture:SetVertTile(true); texture:SetVertTile(); " +
            "texture:SetSnapToPixelGrid(true); texture:SetSnapToPixelGrid(); " +
            "local invalidBlendOk=pcall(function() texture:SetBlendMode('BOGUS') end); " +
            "return table.concat({atlasBefore,atlasClearReturns,clearedAtlas," +
            "tostring(textureResult),string.format('%.1f',ulx),string.format('%.1f',uly)," +
            "string.format('%.1f',lrx),string.format('%.1f',lry)," +
            "tostring(texture:GetHorizTile()),tostring(texture:GetVertTile())," +
            "tostring(texture:IsSnappingToPixelGrid()),tostring(invalidBlendOk)," +
            "texture:GetBlendMode()},':') end)()");

        Assert.Equal(
            "TestAtlas:0:nil:true:0.1:0.2:0.9:0.8:false:false:false:false:BLEND",
            result);
        var texture = session.Ui.Find("NativeTextureValidation")!.Texture!;
        Assert.Equal((uint)134400, texture.FileDataId);
        Assert.Equal("REPEAT", texture.WrapHorizontal);
        Assert.Equal("CLAMP", texture.WrapVertical);
        Assert.Equal("NEAREST", texture.FilterMode);
        Assert.Contains(
            session.Log.Snapshot(),
            entry => entry.Message.Contains(
                "SetTextCoord: TexCoord out of range",
                StringComparison.Ordinal));
    }

