    [Fact]
    public void TextureDesaturationRotationAndVertexOffsetsFollowClientStorage()
    {
        using var session = new EmulatorSession();

        var result = session.Lua.Evaluate(
            "(function() " +
            "local texture=UIParent:CreateTexture('NativeTextureGeometryState'); " +
            "texture:SetDesaturated(true); texture:SetDesaturated(); " +
            "texture:SetRotation(1.25,{x=.25,y=.75}); " +
            "local radians,pivot=texture:GetRotation(); " +
            "texture:SetVertexOffset(1,3,4); texture:SetVertexOffset(5,99,99); " +
            "texture:SetColorTexture(.5,-1,2,.5); " +
            "return table.concat({texture:GetDesaturation(),radians,pivot.x,pivot.y," +
            "select('#',texture:GetRotation())},':') end)()");

        Assert.Equal("0:1.25:0.25:0.75:2", result);
        var texture = session.Ui.Find("NativeTextureGeometryState")!.Texture!;
        Assert.Equal(new System.Numerics.Vector2(3, 4), texture.VertexOffsets[0]);
        Assert.Equal(System.Numerics.Vector2.Zero, texture.VertexOffsets[3]);
        Assert.Equal(new System.Numerics.Vector2(.25f, .75f), texture.RotationPoint);
        Assert.Equal(
            new System.Numerics.Vector4(128 / 255f, 0, 1, 128 / 255f),
            texture.Color);
    }

    [Fact]
    public void TextureGeometrySettersValidateAtomicallyWithNativeIndexing()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "false:false:false:false:true:false:false:777:2:0.25:0.75:0.4",
            session.Lua.Evaluate(
                "(function() local texture=UIParent:CreateTexture('TextureValidationAudit'); " +
                "texture:SetTexture(777); " +
                "texture:SetRotation(2,{x=.25,y=.75}); " +
                "texture:SetDesaturation(.4); texture:SetTexelSnappingBias(.6); " +
                "local badColor=pcall(texture.SetColorTexture,texture,1,2); " +
                "local missingRotation=pcall(texture.SetRotation,texture); " +
                "local badPoint=pcall(texture.SetRotation,texture,3,{x=1}); " +
                "local missingDesaturation=pcall(texture.SetDesaturation,texture); " +
                "local missingBias=pcall(texture.SetTexelSnappingBias,texture); " +
                "local zeroIndex=pcall(texture.SetVertexOffset,texture,0,7,8); " +
                "local missingOffset=pcall(texture.SetVertexOffset,texture,1,7); " +
                "local radians,pivot=texture:GetRotation(); " +
                "return table.concat({tostring(missingRotation),tostring(badPoint)," +
                "tostring(missingDesaturation),tostring(missingBias),tostring(zeroIndex)," +
                "tostring(missingOffset),tostring(badColor),texture:GetTexture()," +
                "radians,pivot.x,pivot.y," +
                "string.format('%.1f',texture:GetDesaturation())},':') end)()"));

        var texture = session.Ui.Find("TextureValidationAudit")!.Texture!;
        Assert.Equal(0.6f, texture.TexelSnappingBias);
        Assert.All(
            texture.VertexOffsets,
            offset => Assert.Equal(System.Numerics.Vector2.Zero, offset));
    }

