    [Fact]
    public void UnpositionedRegionsDoNotRenderUntilTheirAnchorChainResolves()
    {
        var ui = new UiSystem();
        var root = ui.Create("Frame", "UIParent", null);
        var fragment = ui.Create("Frame", "DetachedFragment", null);
        fragment.Width = 100;
        fragment.Height = 50;
        var texture = ui.Create("Texture", null, fragment.Id);
        texture.AllPointsTargetId = fragment.Id;

        Assert.True(ui.IsVisible(fragment));
        Assert.False(ui.HasResolvedRect(fragment));
        Assert.False(ui.HasResolvedRect(texture));
        Assert.DoesNotContain(fragment, ui.RenderOrder());
        Assert.DoesNotContain(texture, ui.RenderOrder());

        fragment.Anchors.Add(new UiAnchor("BOTTOMLEFT", root.Id, "BOTTOMLEFT", 20, 30));
        ui.InvalidateLayout();

        Assert.True(ui.HasResolvedRect(fragment));
        Assert.True(ui.HasResolvedRect(texture));
        Assert.Contains(fragment, ui.RenderOrder());
        Assert.Contains(texture, ui.RenderOrder());
    }

    [Fact]
    public void OpposingAnchorsOverrideIntrinsicAtlasSizeLikeBlizzardNineSliceRegions()
    {
        var ui = new UiSystem();
        ui.Resize(400, 300);
