        var panel = ui.Create("Frame", "Panel", root.Id);
        panel.Width = 260;
        panel.Height = 80;
        panel.Anchors.Add(new UiAnchor("BOTTOMLEFT", root.Id, "BOTTOMLEFT", 20, 30));

        var topLeft = ui.Create("Texture", null, panel.Id);
        topLeft.Width = 7;
        topLeft.Height = 7;
        topLeft.Anchors.Add(new UiAnchor("TOPLEFT", panel.Id, "TOPLEFT", 0, 0));
        var topRight = ui.Create("Texture", null, panel.Id);
        topRight.Width = 7;
        topRight.Height = 7;
        topRight.Anchors.Add(new UiAnchor("TOPRIGHT", panel.Id, "TOPRIGHT", 0, 0));

        var topEdge = ui.Create("Texture", null, panel.Id);
        topEdge.Width = 16;
        topEdge.Height = 7;
        topEdge.Anchors.Add(new UiAnchor("TOPLEFT", topLeft.Id, "TOPRIGHT", 0, 0));
        topEdge.Anchors.Add(new UiAnchor("TOPRIGHT", topRight.Id, "TOPLEFT", 0, 0));

        var center = ui.Create("Texture", null, panel.Id);
        center.Width = 64;
        center.Height = 64;
        center.Anchors.Add(new UiAnchor("TOPLEFT", panel.Id, "TOPLEFT", 3, -3));
        center.Anchors.Add(new UiAnchor("BOTTOMRIGHT", panel.Id, "BOTTOMRIGHT", -3, 3));

        Assert.Equal(new UiRect(27, 103, 246, 7), ui.ResolveBounds(topEdge.Id));
        Assert.Equal(new UiRect(23, 33, 254, 74), ui.ResolveBounds(center.Id));
    }

