    [Fact]
    public void HighlightDrawLayerMaskTracksMouseMotionFocusAndLockState()
    {
        var ui = new UiSystem();
        var root = ui.Create("Frame", "UIParent", null);
        var tab = ui.Create("Button", "Tab", root.Id);
        tab.Width = 72;
        tab.Height = 32;
        tab.Anchors.Add(new UiAnchor("CENTER", root.Id, "CENTER", 0, 0));
        var highlight = ui.Create("Texture", "TabHighlight", tab.Id, "HIGHLIGHT");
        highlight.AllPointsTargetId = tab.Id;

        Assert.DoesNotContain(highlight, ui.RenderOrder());

        ui.SetMouseFoci([tab]);
        Assert.Contains(highlight, ui.RenderOrder());
        Assert.Contains("HIGHLIGHT", tab.EnabledDrawLayers);

        tab.Enabled = false;
        ui.UpdateHighlightDrawLayer(tab);
        Assert.DoesNotContain(highlight, ui.RenderOrder());
        Assert.DoesNotContain("HIGHLIGHT", tab.EnabledDrawLayers);

        ui.SetHighlightLocked(tab, true);
        Assert.DoesNotContain(highlight, ui.RenderOrder());

        tab.Enabled = true;
        ui.UpdateHighlightDrawLayer(tab);
        ui.SetMouseFoci([]);
        ui.SetHighlightLocked(tab, true);
        Assert.Contains(highlight, ui.RenderOrder());
        Assert.True(highlight.Shown);

        highlight.Shown = false;
        Assert.DoesNotContain(highlight, ui.RenderOrder());
        Assert.Contains("HIGHLIGHT", tab.EnabledDrawLayers);

        highlight.Shown = true;
        ui.SetMouseFoci([tab]);
        ui.SetHighlightLocked(tab, false);
        Assert.Contains(highlight, ui.RenderOrder());
        Assert.Contains("HIGHLIGHT", tab.EnabledDrawLayers);

        ui.SetMouseFoci([]);
        Assert.DoesNotContain(highlight, ui.RenderOrder());
        Assert.DoesNotContain("HIGHLIGHT", tab.EnabledDrawLayers);
    }

