    [Fact]
    public void XmlFontFamiliesAndStylesApplyTheSelectedAlphabetMetrics()
    {
        var root = Path.Combine(Path.GetTempPath(), $"xml-font-family-{Guid.NewGuid():N}");
        var addon = CreateAddon(
            root,
            "XmlFontFamily",
            ["ui.xml"],
            [
                """
                <Ui xmlns="http://www.blizzard.com/wow/ui/">
                  <FontFamily name="XmlSystemFontLarge" virtual="true">
                    <Member alphabet="roman">
                      <Font font="Fonts\FRIZQT__.TTF" height="16" outline="NORMAL" spacing="1.5"
                            canBeUserScaled="true">
                        <Shadow>
                          <Offset><AbsDimension x="1" y="-1"/></Offset>
                          <Color r="0.1" g="0.2" b="0.3" a="0.4"/>
                        </Shadow>
                      </Font>
                    </Member>
                    <Member alphabet="russian">
                      <Font font="Fonts\FRIZQT___CYR.TTF" height="17"/>
                    </Member>
                  </FontFamily>
                  <Font name="XmlHighlightLarge" inherits="XmlSystemFontLarge"
                        justifyH="LEFT" virtual="true">
                    <Color r="0.8" g="0.7" b="0.6"/>
                  </Font>
                  <Font name="XmlReplacementFont" font="Fonts\ARIALN.TTF"
                        height="22" virtual="true"/>
                  <FontString name="XmlStyledLabel" inherits="XmlHighlightLarge" text="Styled"/>
                  <Button name="XmlStyledButton" text="Button">
                    <NormalFont style="XmlHighlightLarge"/>
                  </Button>
                </Ui>
                """
            ]);

        try
        {
            using var session = new EmulatorSession();
            session.Load(addon);

            Assert.Equal(
                "Font:Fonts\\FRIZQT__.TTF:16:NORMAL:1.5:LEFT:1:-1:0.8:0.4:" +
                "XmlHighlightLarge:16:XmlHighlightLarge:true:true:true:true:true",
                session.Lua.Evaluate(
                    "local _,baseSize,baseFlags=XmlSystemFontLarge:GetFont(); " +
                    "local file,size,flags=XmlStyledLabel:GetFont(); " +
                    "local sx,sy=XmlStyledLabel:GetShadowOffset(); local r=XmlStyledLabel:GetTextColor(); " +
                    "local _,_,_,a=XmlStyledLabel:GetShadowColor(); " +
                    "local buttonText=XmlStyledButton:GetFontString(); local _,buttonSize=buttonText:GetFont(); " +
                    "return table.concat({XmlSystemFontLarge:GetObjectType(),file,size,flags," +
                    "XmlStyledLabel:GetSpacing(),XmlStyledLabel:GetJustifyH(),sx,sy," +
                    "string.format('%.1f',r),string.format('%.1f',a)," +
                    "XmlStyledLabel:GetFontObject():GetName()," +
                    "buttonSize,XmlStyledButton:GetNormalFontObject():GetName()," +
                    "tostring(XmlSystemFontLarge:GetFontObject()==" +
                    "XmlSystemFontLarge:GetFontObjectForAlphabet('Roman'))," +
                    "tostring(XmlSystemFontLarge:GetFontObjectForAlphabet('Russian')~=" +
                    "XmlSystemFontLarge:GetFontObjectForAlphabet('Roman'))," +
                    "tostring(XmlSystemFontLarge:GetFontObjectForAlphabet('Korean')==nil)," +
                    "tostring(XmlHighlightLarge:GetFontObjectForAlphabet('Roman')==" +
                    "XmlSystemFontLarge:GetFontObjectForAlphabet('Roman'))," +
                    "tostring(GetFontInfo(XmlSystemFontLarge).canBeUserScaled)},':')"));

            Assert.Equal(
                "16:22:XmlReplacementFont",
                session.Lua.Evaluate(
                    "local _,before=XmlStyledLabel:GetFont(); " +
                    "XmlStyledLabel:SetFontObject(XmlReplacementFont); " +
                    "local _,after=XmlStyledLabel:GetFont(); " +
                    "return before..':'..after..':'..XmlStyledLabel:GetFontObject():GetName()"));
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

