            "local frame=CreateFrame('Frame','ScaledRectFrame',UIParent); " +
            "frame:SetSize(100,50); frame:SetScale(2); frame:SetPoint('CENTER',UIParent,'CENTER'); " +
            "local left,bottom,width,height=frame:GetScaledRect(); " +
            "local rectLeft,rectBottom,rectWidth,rectHeight=frame:GetRect(); " +
            "local unresolved=CreateFrame('Frame',nil,UIParent); " +
            "return string.format('%.3f:%.3f:%.3f:%.3f:%.3f:%.3f:%.3f:%.3f:%.3f:%.3f:%.3f:%.3f:%d:%d:%d:%d:%d'," +
            "left,bottom,width,height,frame:GetLeft(),frame:GetBottom()," +
            "frame:GetWidth(),frame:GetHeight(),rectLeft,rectBottom,rectWidth,rectHeight," +
            "select('#',unresolved:GetRect()),select('#',unresolved:GetScaledRect())," +
            "select('#',unresolved:GetLeft()),select('#',unresolved:GetTop())," +
            "select('#',unresolved:GetCenter())) end)()");

        Assert.Equal(
            "597.333:341.333:170.667:85.333:350.000:200.000:100.000:50.000:" +
            "350.000:200.000:100.000:50.000:0:0:0:0:0",
