    [Fact]
    public void RegionAnchorsResolveNamesAndDistinguishExplicitNilFromOmittedTargets()
    {
        using var session = new EmulatorSession();

        var result = session.Lua.Evaluate(
            "(function() " +
            "local parent=CreateFrame('Frame','AnchorParent',UIParent); " +
            "local target=CreateFrame('Frame','NamedAnchorTarget',UIParent); " +
            "local named=CreateFrame('Frame','NamedAnchorChild',parent); " +
            "named:SetPoint('TOPLEFT','NamedAnchorTarget','BOTTOMRIGHT',3,4); " +
            "local np,nr,nrp,nx,ny=named:GetPoint(); " +
            "local omitted=CreateFrame('Frame','OmittedAnchorChild',parent); " +
            "omitted:SetPoint('CENTER'); local _,omittedRelative=omitted:GetPoint(); " +
            "local explicitNil=CreateFrame('Frame','NilAnchorChild',parent); " +
            "explicitNil:SetPoint('CENTER',nil); local _,nilRelative=explicitNil:GetPoint(); " +
            "local all=CreateFrame('Frame','NamedAllPointsChild',parent); " +
            "all:SetAllPoints('NamedAnchorTarget'); local _,allRelative=all:GetPoint(); " +
            "named:SetPoint('TOPLEFT','MissingAnchorTarget','TOPLEFT',99,99); " +
            "local _,preservedRelative,_,preservedX,preservedY=named:GetPoint(); " +
            "all:SetAllPoints('MissingAllPointsTarget'); local _,preservedAllRelative=all:GetPoint(); " +
            "return table.concat({" +
            "np,tostring(nr==target),nrp,nx,ny,tostring(omittedRelative==parent)," +
            "tostring(nilRelative==UIParent),tostring(allRelative==target)," +
            "tostring(preservedRelative==target),preservedX,preservedY," +
            "tostring(preservedAllRelative==target)},':') end)()");

        Assert.Equal(
            "TOPLEFT:true:BOTTOMRIGHT:3:4:true:true:true:true:3:4:true",
            result);
        Assert.Contains(
            session.Log.Snapshot(),
            entry => entry.Message.Contains(
                "SetPoint: Couldn't find region named 'MissingAnchorTarget'",
                StringComparison.Ordinal));
        Assert.Contains(
            session.Log.Snapshot(),
            entry => entry.Message.Contains(
                "SetAllPoints: Couldn't find region named 'MissingAllPointsTarget'",
                StringComparison.Ordinal));
    }

