                "local missing=pcall(function() frame:SetPoint() end); " +
                "local numeric=pcall(function() frame:SetPoint(7) end); " +
                "local invalid=pcall(function() frame:SetPoint('NOWHERE') end); " +
                "local badRelative=pcall(function() " +
                "frame:SetPoint('TOPLEFT',parent,'NOWHERE',9,9) end); " +
                "local count=frame:GetNumPoints(); " +
                "local cp,_,_,cx,cy=frame:GetPointByName('CENTER'); " +
                "frame:SetPoint('BOTTOMLEFT',parent,5); " +
                "local bp,_,_,bx,by=frame:GetPointByName('BOTTOMLEFT'); " +
                "frame:SetPoint('top',3,4); " +
                "local tp,_,_,tx,ty=frame:GetPointByName('TOP'); " +
                "return table.concat({tostring(missing),tostring(numeric),tostring(invalid)," +
                "tostring(badRelative),count,cp,cx,cy,bp,bx,by,tp,tx,ty},':')"));
        Assert.Contains(
            session.Log.Snapshot(),
            entry => entry.Message.Contains(
                "SetPoint: Invalid region point NOWHERE",
                StringComparison.Ordinal));
        Assert.Contains(
            session.Log.Snapshot(),
            entry => entry.Message.Contains(
                "SetPoint: Unknown region point NOWHERE",
                StringComparison.Ordinal));
    }

