        session.Lua.Units.Player.LocalizedDisplayFactionGroup = "Horde";
        session.Lua.Units.Player.PowerTypes[2] =
            new WowUnitPowerTypeState(3, "ENERGY", 1, 1, 0);
        session.Lua.Units.Player.Cast = new WowUnitCastState(
            "Fireball", "Fireball", 135812, 1000, 3000, false,
            "cast-1", false, 133, "castbar-1", 25);
        session.Lua.Units.Player.ThreatSituation = 2;
        session.Lua.Units.Player.IsGroupLeader = true;
        session.Lua.Units.Player.GroupLeaderByPartyCategory[0] = false;
        session.Lua.Units.Player.GroupLeaderByPartyCategory[1] = true;
        session.Lua.Units.Player.IsPvp = true;
        session.Lua.Units.Player.IsPvpFreeForAll = false;
        session.Lua.Client.TutorialFlags.Add(58);
        session.Lua.Client.IsResting = true;
        session.Lua.Client.HasPartialPlayTime = true;
        session.Lua.Client.ThreatWarningEnabled = true;
        session.Lua.Group.IsInRaid = true;

        var result = session.Lua.Evaluate(
            "(function() local hour,minute=GetGameTime(); " +
            "return table.concat({" +
            "tostring(UnitExists('player')),tostring(UnitExists('target'))," +
            "UnitLevel('player'),UnitEffectiveLevel('player'),UnitLevel('target'),UnitEffectiveLevel('target')," +
            "(function() local tag,name=UnitFactionGroup('player'); return tag..','..name end)()," +
            "(function() local tag,name=UnitFactionGroup('player',true); return tag..','..name end)()," +
            "select('#',UnitFactionGroup('target'))," +
            "UnitHealth('player'),UnitHealthMax('player'),UnitHealth('target')," +
            "UnitPower('player'),UnitPowerMax('player'),UnitPower('target')," +
            "(function() local id,token,r,g,b=UnitPowerType('player',2); " +
            "return table.concat({id,token,r,g,b},',') end)()," +
            "select('#',UnitPowerType('target')),select('#',UnitPowerType('player',3))," +
            "select('#',UnitCastingInfo('target')),select('#',UnitChannelInfo('player'))," +
            "(function() local name,_,_,_,_,_,_,_,spellId,_,delay=UnitCastingInfo('player'); " +
            "return name..','..spellId..','..delay end)()," +
            "UnitRealmRelationship('player'),tostring(UnitRealmRelationship('target')==nil)," +
            "tostring(UnitIsDead('player')),tostring(UnitIsGhost('player'))," +
            "tostring(UnitIsDead('target')),tostring(UnitIsGhost('target'))," +
            "tostring(UnitIsPVP('player')),tostring(UnitIsPVPFreeForAll('player'))," +
            "tostring(UnitIsPVP('target')),tostring(UnitIsPVPFreeForAll('target'))," +
            "tostring(UnitIsGroupLeader('player')),tostring(UnitIsGroupLeader('player',0))," +
            "tostring(UnitIsGroupLeader('player',1)),tostring(UnitIsGroupLeader('target'))," +
            "tostring(UnitIsPlayer('player')),tostring(UnitGUID('target')==nil)," +
            "UnitThreatSituation('player'),tostring(UnitThreatSituation('target')==nil)," +
            "GetFileStreamingStatus(),GetBackgroundLoadingStatus()," +
            "tostring(IsInRaid())," +
            "tostring(IsResting())," +
            "select('#',PartialPlayTime()),tostring(PartialPlayTime()),select('#',NoPlayTime())," +
            "tostring(IsThreatWarningEnabled())," +
            "tostring(IsTutorialFlagged(58)),tostring(hour>=0 and hour<=23)," +
            "tostring(minute>=0 and minute<=59)},':') end)()");

        Assert.Equal(
            "true:false:42:42:0:0:Alliance,Alliance:Horde,Horde:2:42:125:0:73:140:0:3,ENERGY,1,1,0:0:0:" +
            "0:0:Fireball,133,25:1:true:false:false:false:false:true:false:false:false:" +
            "true:false:true:false:true:true:2:true:" +
            "0:0:true:true:1:true:1:true:true:true:true",
            result);
    }

