                "local talent=C_SpecializationInfo.GetPvpTalentInfo(901); " +
                "local slot=C_SpecializationInfo.GetPvpTalentSlotInfo(2); " +
                "return table.concat({talent.talentID,talent.name,talent.icon," +
                "tostring(talent.selected),talent.spellID," +
                "talent.dependenciesUnmetReason,tostring(slot.enabled),slot.level," +
                "slot.selectedTalentID,#slot.availableTalentIDs," +
                "slot.availableTalentIDs[1],slot.availableTalentIDs[2]," +
                "C_SpecializationInfo.GetInspectSelectedPvpTalent('target',2)," +
                "select('#',C_SpecializationInfo.GetPvpTalentInfo(999))," +
                "tostring(C_SpecializationInfo.GetPvpTalentSlotInfo(999))},':')"));

        Assert.Equal(
            "true:false:0:true:0:0:false:false:false:false:false",
            session.Lua.Evaluate(
                "local events=0; local listener=CreateFrame('Frame'); " +
                "listener:RegisterEvent('ACTIVE_TALENT_GROUP_CHANGED'); " +
                "listener:SetScript('OnEvent',function() events=events+1 end); " +
                "C_SpecializationInfo.SetPvpTalentLocked(901,true); " +
                "local before=C_SpecializationInfo.IsPvpTalentLocked(901); " +
                "C_SpecializationInfo.SetPvpTalentLocked(901,false); " +
                "local after=C_SpecializationInfo.IsPvpTalentLocked(901); " +
                "local petCount=select('#',C_SpecializationInfo.SetPetSpecialization(2,7)); " +
                "local setResult=C_SpecializationInfo.SetSpecialization(3); " +
                "local badLoot=pcall(SetLootSpecialization,{}); " +
                "local badCount=pcall(C_SpecializationInfo.GetNumSpecializationsForClassID);" +
                "local badSet=pcall(C_SpecializationInfo.SetSpecialization,0); " +
                "local badLock=pcall(C_SpecializationInfo.SetPvpTalentLocked,1,1); " +
                "local badInfo=pcall(GetSpecializationInfoForClassID,1,0); " +
                "return table.concat({tostring(before),tostring(after),petCount," +
                "tostring(setResult),tostring(events)," +
                "select('#',C_SpecializationInfo.GetSpecializationInfo(99))," +
                "tostring(badLoot),tostring(badCount),tostring(badSet)," +
                "tostring(badLock),tostring(badInfo)},':')"));
        Assert.Equal(62, session.Lua.Client.LootSpecializationId);
        Assert.Equal(3, session.Lua.Client.SpecializationIndex);
        Assert.Equal(2, session.Lua.Specializations.PetSpecializationIndex);
        Assert.Equal((uint)7, session.Lua.Specializations.PetNumber);

        Assert.Equal(
            "10:71:Arms:Two-handed weapon master:132355:DAMAGER:1:7:" +
            "Interface/TalentFrame/Arms:3:true",
            session.Lua.Evaluate(
                "local id,name,description,icon,role,primaryStat,pointsSpent," +
                "background,previewPointsSpent,isUnlocked=" +
                "C_SpecializationInfo.GetSpecializationInfo(2); " +
                "return table.concat({select('#'," +
                "C_SpecializationInfo.GetSpecializationInfo(2)),id,name,description," +
                "icon,role,primaryStat,pointsSpent,background,previewPointsSpent," +
                "tostring(isUnlocked)},':')"));
    }

    [Fact]
    public void ChatWindowAndLanguageApisRoundTripTypedRuntimeState()
    {
        using var session = new EmulatorSession();
        session.Lua.Client.DefaultLanguage = "Orcish";
        session.Lua.Client.DefaultLanguageId = 1;
        session.Lua.Client.AlternativeDefaultLanguage = "Gutterspeak";
        session.Lua.Client.AlternativeDefaultLanguageId = 33;
        session.Lua.Chat.GetWindow(3).Channels.Add(
            new WowChatChannelState("General - Zone", 1));

        var result = session.Lua.Evaluate(
            "(function() " +
            "SetChatWindowName(3,'Loot'); SetChatWindowSize(3,15); " +
            "SetChatWindowColor(3,.1,.2,.3); SetChatWindowAlpha(3,.4); " +
            "SetChatWindowShown(3,true); SetChatWindowLocked(3,true); " +
            "SetChatWindowDocked(3,2); SetChatWindowUninteractable(3,true); " +
            "SetChatWindowSavedDimensions(3,420,180); " +
            "SetChatWindowSavedPosition(3,'BOTTOMLEFT',.25,.5); " +
            "AddChatWindowMessages(3,'SAY'); AddChatWindowMessages(3,'EMOTE'); " +
            "AddChatWindowMessages(3,'say'); RemoveChatWindowMessages(3,'SAY'); " +
            "AddChatWindowChannel(3,'Custom'); " +
            "local n,s,r,g,b,a,shown,locked,docked,uninteractable=GetChatWindowInfo(3); " +
            "local w,h=GetChatWindowSavedDimensions(3); " +
            "local p,x,y=GetChatWindowSavedPosition(3); " +
            "local l1,i1=GetLanguageByIndex(1); local l2,i2=GetLanguageByIndex(2); " +
            "local messages={GetChatWindowMessages(3)}; local channels={GetChatWindowChannels(3)}; " +
            "return string.format('%s:%d:%.1f:%.1f:%.1f:%.1f:%s:%s:%d:%s:%d:%d:%s:%.2f:%.2f:%d:%s:%d:%s:%d:%d:%s:%d:%s:%d'," +
            "n,s,r,g,b,a,tostring(shown),tostring(locked),docked,tostring(uninteractable)," +
            "w,h,p,x,y,GetNumLanguages(),l1,i1,l2,i2,select('#',GetLanguageByIndex(3))," +
            "table.concat(messages,','),#channels,channels[1],channels[2]) end)()");

        Assert.Equal(
            "Loot:15:0.1:0.2:0.3:0.4:true:true:2:true:420:180:BOTTOMLEFT:0.25:0.50:2:Orcish:1:Gutterspeak:33:0:EMOTE:4:General - Zone:1",
            result);
    }

