    [Fact]
    public void ChatInfoEmoteAndAddonMessageApisUseNativeResultContracts()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "true:3:0:0:0",
            session.Lua.Evaluate(
                "return table.concat({tostring(C_ChatInfo.PerformEmote('READ',nil,true))," +
                "C_ChatInfo.GetNumReservedChatWindows()," +
                "C_ChatInfo.RegisterAddonMessagePrefix('TEST')," +
                "C_ChatInfo.SendAddonMessage('TEST','payload','WHISPER','Player')," +
                "C_ChatInfo.SendAddonMessageLogged('TEST','payload','WHISPER','Player')},':')"));
        Assert.Equal("READ", session.Lua.Chat.LastEmoteName);
        Assert.Null(session.Lua.Chat.LastEmoteTarget);
        Assert.True(session.Lua.Chat.LastEmoteSuppressMoveError);

        Assert.Equal(
            "1:2:1:2:4:5:10:6:true:false:false:false",
            session.Lua.Evaluate(
                "return table.concat({" +
                "C_ChatInfo.RegisterAddonMessagePrefix('TEST')," +
                "C_ChatInfo.RegisterAddonMessagePrefix('12345678901234567')," +
                "C_ChatInfo.SendAddonMessage('12345678901234567','payload','WHISPER','Player')," +
                "C_ChatInfo.SendAddonMessage('TEST','','WHISPER','Player')," +
                "C_ChatInfo.SendAddonMessage('TEST','payload','SAY')," +
                "C_ChatInfo.SendAddonMessage('TEST','payload','PARTY')," +
                "C_ChatInfo.SendAddonMessage('TEST','payload','GUILD')," +
                "C_ChatInfo.SendAddonMessage('TEST','payload','WHISPER')," +
                "tostring(C_ChatInfo.CanPlayerSpeakLanguage(7))," +
                "tostring(C_ChatInfo.CanPlayerSpeakLanguage(999))," +
                "tostring(pcall(C_ChatInfo.CanPlayerSpeakLanguage))," +
                "tostring(pcall(C_ChatInfo.PerformEmote))},':')"));

        session.Lua.Chat.OutgoingAddonChatMessagesRestricted = true;
        Assert.Equal(
            "11:true",
            session.Lua.Evaluate(
                "return table.concat({" +
                "C_ChatInfo.SendAddonMessage('TEST','payload','WHISPER','Player')," +
                "tostring(C_ChatInfo.AreOutgoingAddonChatMessagesRestricted())},':')"));
        session.Lua.Chat.OutgoingAddonChatMessagesRestricted = false;

        Assert.Equal(
            "true:false:false:0",
            session.Lua.Evaluate(
                "local sent=pcall(C_ChatInfo.SendChatMessage,'hello',nil,7,'Player'); " +
                "return table.concat({tostring(sent)," +
                "tostring(pcall(C_ChatInfo.SendChatMessage,'hello','UNKNOWN'))," +
                "tostring(pcall(C_ChatInfo.SendAddonMessage,'TEST','payload',{}))," +
                "select('#',C_ChatInfo.SendChatMessage('hello'))},':')"));
        Assert.Equal("hello", session.Lua.Chat.LastSentChatMessage?.Message);
        Assert.Equal("SAY", session.Lua.Chat.LastSentChatMessage?.ChatType);
        Assert.Null(session.Lua.Chat.LastSentChatMessage?.Target);

        using var maxPrefixSession = new EmulatorSession();
        for (var index = 0; index < 512; index++)
            maxPrefixSession.Lua.Chat.RegisteredAddonMessagePrefixes.Add($"P{index}");
        Assert.Equal(
            "3",
            maxPrefixSession.Lua.Evaluate(
                "return C_ChatInfo.RegisterAddonMessagePrefix('OVERFLOW')"));
    }

