    [Fact]
    public void AccountApisMatchNativeExpansionAndRestrictionContracts()
    {
        using var session = new EmulatorSession();
        var account = session.Lua.Account;
        account.IsAccountSecured = false;
        account.RestrictedMaximumLevel = 20;
        account.RestrictedMaximumMoney = 1_000_000;
        account.RestrictedProfessionCap = 100;
        account.MaximumLevelForPlayerExpansion = 70;
        account.MaximumPlayerLevel = 90;
        account.MaximumExpansionLevel = 11;
        account.MinimumExpansionLevel = 2;
        account.NumberOfExpansions = 12;
        account.ServerExpansionLevel = 10;
        account.ExpansionDisplayInfoByLevelAndReleaseType[(10, 2)] =
            new WowExpansionDisplayInfoState(
                101,
                202,
                [new WowExpansionDisplayInfoFeatureState(303, "Feature")],
                404,
                505,
                "warwithin",
                606,
                null,
                707);

        Assert.Equal(
            "20:1000000:100:false:70:90:80:90:12:11:2:10:" +
            "101:202:1:303:Feature:404:505:warwithin:606:nil:707",
            session.Lua.Evaluate(
                "local level,money,profession=GetRestrictedAccountData(); " +
                "local info=GetExpansionDisplayInfo(10,2); " +
                "return table.concat({" +
                "level,money,profession,tostring(IsAccountSecured())," +
                "GetMaxLevelForPlayerExpansion(),GetMaxPlayerLevel()," +
                "GetMaxLevelForLatestExpansion(),GetMaxLevelForExpansionLevel(11)," +
                "GetNumExpansions(),GetMaximumExpansionLevel()," +
                "GetMinimumExpansionLevel(),GetServerExpansionLevel()," +
                "info.logo,info.banner,#info.features,info.features[1].icon," +
                "info.features[1].text,info.highResBackgroundID," +
                "info.lowResBackgroundID,info.textureKit," +
                "info.glueAmbianceSoundKit,tostring(info.glueMusicSoundKit)," +
                "info.glueCreditsSoundKit},':')"));

        Assert.Equal(
            "0:true:false:1:nil:true:true:true:true:true:true",
            session.Lua.Evaluate(
                "local unknown=GetExpansionDisplayInfo(9); " +
                "return table.concat({" +
                "GetMaxLevelForExpansionLevel(12)," +
                "tostring(ClassicExpansionAtLeast(4294967295))," +
                "tostring(ClassicExpansionAtMost(4294967295))," +
                "select('#',GetExpansionDisplayInfo(9)),tostring(unknown)," +
                "tostring(not pcall(GetMaxLevelForExpansionLevel))," +
                "tostring(not pcall(GetMaxLevelForExpansionLevel,-1))," +
                "tostring(not pcall(GetExpansionDisplayInfo,'bad'))," +
                "tostring(not pcall(GetExpansionDisplayInfo,10,'bad'))," +
                "tostring(not pcall(ClassicExpansionAtLeast,'bad'))," +
                "tostring(not pcall(ClassicExpansionAtMost,'bad'))" +
                "},':')"));

        account.ExpansionTrialRemainingSeconds = 30;
        Assert.Equal(
            "false:nil",
            session.Lua.Evaluate(
                "local active,remaining=GetExpansionTrialInfo(); " +
                "return tostring(active)..':'..tostring(remaining)"));
        account.IsExpansionTrial = true;
        Assert.Equal(
            "true:30",
            session.Lua.Evaluate(
                "local active,remaining=GetExpansionTrialInfo(); " +
                "return tostring(active)..':'..remaining"));
    }

