    [Fact]
    public void FrameEventRegistrationUsesNativeChangeResultsAndUnitFiltering()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "true:false:true:false:false:false:4",
            session.Lua.Evaluate(
                "(function() EventAuditCount=0; EventAuditAll=0; " +
                "local frame=CreateFrame('Frame','EventAuditFrame'); " +
                "frame:SetScript('OnEvent',function() EventAuditCount=EventAuditCount+1 end); " +
                "local first=frame:RegisterEvent('EMULATOR_AUDIT'); " +
                "local duplicate=frame:RegisterEvent('EMULATOR_AUDIT'); " +
                "local removed=frame:UnregisterEvent('EMULATOR_AUDIT'); " +
                "local absent=frame:UnregisterEvent('EMULATOR_AUDIT'); " +
                "local missing=pcall(frame.RegisterEvent,frame); " +
                "local unitFirst=frame:RegisterUnitEvent(" +
                "'EMULATOR_UNIT_AUDIT','player','target','focus','party1','boss1'); " +
                "local registered,a,b,c,d=frame:IsEventRegistered('EMULATOR_UNIT_AUDIT'); " +
                "EventAuditUnits={a,b,c,d}; " +
                "return table.concat({tostring(first),tostring(duplicate),tostring(removed)," +
                "tostring(absent),tostring(missing),tostring(not unitFirst),#EventAuditUnits},':') end)()"));

        session.Lua.TriggerEvent("EMULATOR_UNIT_AUDIT", "player");
        session.Lua.TriggerEvent("EMULATOR_UNIT_AUDIT", "boss1");
        Assert.Equal("1", session.Lua.Evaluate("return EventAuditCount"));

        session.Lua.Evaluate(
            "local all=CreateFrame('Frame','AllEventAuditFrame'); " +
            "all:SetScript('OnEvent',function() EventAuditAll=EventAuditAll+1 end); " +
            "all:RegisterAllEvents()");
        session.Lua.TriggerEvent("EMULATOR_UNREGISTERED_EVENT");
        Assert.Equal("1", session.Lua.Evaluate("return EventAuditAll"));
        session.Lua.Evaluate("AllEventAuditFrame:UnregisterAllEvents()");
        session.Lua.TriggerEvent("EMULATOR_ANOTHER_EVENT");
        Assert.Equal("1", session.Lua.Evaluate("return EventAuditAll"));
    }

