    [Fact]
    public void FrameHighlightLockUsesRequiredBooleanAndResetsToDefault()
    {
        using var session = new EmulatorSession();
        session.Lua.Evaluate(
            "HighlightLockAudit=CreateFrame('Button','HighlightLockAudit',UIParent); " +
            "HighlightLockAudit:SetHighlightLocked(0)");
        var button = session.Ui.Find("HighlightLockAudit")!;
        Assert.True(button.HighlightLocked);

        Assert.Equal(
            "false",
            session.Lua.Evaluate(
                "return tostring(pcall(HighlightLockAudit.SetHighlightLocked,HighlightLockAudit))"));
        Assert.True(button.HighlightLocked);

        Assert.Equal(
            "true",
            session.Lua.Evaluate(
                "return tostring(pcall(HighlightLockAudit.SetHighlightLocked,HighlightLockAudit,nil))"));
        Assert.False(button.HighlightLocked);

        session.Lua.Evaluate(
            "HighlightLockAudit:LockHighlight(); HighlightLockAudit:SetToDefaults()");
        Assert.False(button.HighlightLocked);
    }

