    [Fact]
    public void CVarApiRetainsDefaultsFlagsAndOneBasedBitfields()
    {
        using var session = new EmulatorSession();
        session.Lua.CVars.Define("closedInfoFrames", "0");
        session.Lua.CVars.Define("readOnlyCVar", "original", isReadOnly: true);

        Assert.Equal(
            "0:true:true:true:7:0:nil:original:0",
            session.Lua.Evaluate(
                "(function() local default=C_CVar.GetCVarDefault('closedInfoFrames'); " +
                "local set=C_CVar.SetCVar('closedInfoFrames','0'); " +
                "local bitSet=C_CVar.SetCVarBitfield('closedInfoFrames',3,true); " +
                "local bit=C_CVar.GetCVarBitfield('closedInfoFrames',3); " +
                "local infoCount=select('#',C_CVar.GetCVarInfo('closedInfoFrames')); " +
                "local lockedCount=select('#'," +
                "C_CVar.SetCVar('readOnlyCVar','changed')); " +
                "local locked=C_CVar.SetCVar('readOnlyCVar','changed'); " +
                "return table.concat({default,tostring(set),tostring(bitSet)," +
                "tostring(bit),infoCount,lockedCount," +
                "tostring(locked)," +
                "C_CVar.GetCVar('readOnlyCVar'),select('#'," +
                "C_CVar.GetCVarDefault('unknown'))},':') end)()"));

        Assert.Equal(
            "true:nil:true:false:false:false:false:false:false:false:0:0",
            session.Lua.Evaluate(
                "C_CVar.RegisterCVar('nativeBool','enabled'); " +
                "local badGet=pcall(C_CVar.GetCVar,{}); " +
                "local badDefault=pcall(C_CVar.GetCVarDefault); " +
                "local badBit=pcall(C_CVar.GetCVarBitfield,'closedInfoFrames',{}); " +
                "local badSet=pcall(C_CVar.SetCVar,'closedInfoFrames',{}); " +
                "local badSetBit=pcall(" +
                "C_CVar.SetCVarBitfield,'closedInfoFrames',1); " +
                "local rangeSet=pcall(" +
                "C_CVar.SetCVarBitfield,'closedInfoFrames',1525,true); " +
                "return table.concat({" +
                "tostring(C_CVar.GetCVarBool('nativeBool'))," +
                "tostring(C_CVar.GetCVarBool('unknown'))," +
                "tostring(C_CVar.GetCVarBitfield('closedInfoFrames',3))," +
                "tostring(C_CVar.GetCVarBitfield('closedInfoFrames',4))," +
                "tostring(badGet),tostring(badDefault),tostring(badBit)," +
                "tostring(badSet),tostring(badSetBit),tostring(rangeSet)," +
                "select('#',C_CVar.SetCVar('unknown','x'))," +
                "select('#',C_CVar.SetCVarBitfield('unknown',1,true))},':')"));
    }

