    [Fact]
    public void TotemApiMatchesNativeEmptyInvalidAndMutationSemantics()
    {
        using var session = new EmulatorSession();
        var first = session.Lua.Totems.Set(1);
        first.Duration = 10;
        first.ModRate = 2;
        first.CannotDismiss = true;
        session.Lua.Totems.TargetedSlot = 1;
        session.Tick(1);
        session.Tick(1);

        Assert.Equal(
            "false::0:0:0:0:0:0:false:nil:0:4.75:10:2",
            session.Lua.Evaluate(
                "(function() " +
                "local have,name,start,duration,icon,rate,spell=GetTotemInfo(3); " +
                "local d=GetTotemDuration(1); " +
