    [Fact]
    public void VoiceSettingsApisUseClientDefaultsAndRetainProxyState()
    {
        using var session = new EmulatorSession();
        session.Lua.VoiceChat.OutputDevices.Add(new WowVoiceAudioDeviceState
        {
            DeviceId = "output-default",
            DisplayName = "System Default",
            IsSystemDefault = true
        });

        Assert.Equal(
            "50:50:43:1:0:1:output-default:true",
            session.Lua.Evaluate(
                "(function() " +
                "C_VoiceChat.SetOutputDevice('output-default'); " +
                "local outputs=C_VoiceChat.GetAvailableOutputDevices(); " +
                "return table.concat({" +
                "C_VoiceChat.GetOutputVolume(),C_VoiceChat.GetInputVolume()," +
                "C_VoiceChat.GetVADSensitivity(),C_VoiceChat.GetMasterVolumeScale()," +
                "C_VoiceChat.GetCommunicationMode(),#outputs,outputs[1].deviceID," +
                "tostring(outputs[1].isActive)},':') end)()"));

        Assert.Equal(
            "50:50:43:1",
            session.Lua.Evaluate(
                "return table.concat({" +
                "C_CVar.GetCVarDefault('VoiceOutputVolume')," +
                "C_CVar.GetCVarDefault('VoiceInputVolume')," +
                "C_CVar.GetCVarDefault('VoiceVADSensitivity')," +
                "C_CVar.GetCVarDefault('VoiceChatMasterVolumeScale')},':')"));

        session.Lua.Evaluate(
            "C_VoiceChat.SetOutputVolume(75); C_VoiceChat.SetInputVolume(25); " +
            "C_VoiceChat.SetVADSensitivity(120); C_VoiceChat.SetMasterVolumeScale(-1); " +
            "C_VoiceChat.SetCommunicationMode(Enum.CommunicationMode.OpenMic); " +
            "C_VoiceChat.BeginLocalCapture(true)");

        Assert.Equal(75, session.Lua.VoiceChat.OutputVolume);
        Assert.Equal(25, session.Lua.VoiceChat.InputVolume);
        Assert.Equal(100, session.Lua.VoiceChat.VadSensitivity);
        Assert.Equal(0, session.Lua.VoiceChat.MasterVolumeScale);
        Assert.Equal(1, session.Lua.VoiceChat.CommunicationMode);
        Assert.True(session.Lua.VoiceChat.IsCapturingLocally);
        Assert.True(session.Lua.VoiceChat.ListenToLocalUser);

        session.Lua.Evaluate("C_VoiceChat.EndLocalCapture()");
        Assert.False(session.Lua.VoiceChat.IsCapturingLocally);
    }

    [Fact]
    public void VoiceChatApiUsesNativeRequiredAndOptionalContracts()
    {
        using var session = new EmulatorSession();
        var voiceChat = session.Lua.VoiceChat;
        voiceChat.AreInputDevicesAvailable = false;
        voiceChat.AreOutputDevicesAvailable = false;
        voiceChat.IsCommunicationModeAvailable = false;
        voiceChat.IsInputVolumeAvailable = false;
        voiceChat.IsOutputVolumeAvailable = false;
        voiceChat.IsVadSensitivityAvailable = false;

        Assert.Equal(
            "nil:nil:nil:nil:nil:nil:0:1:2:0:1",
            session.Lua.Evaluate(
                "(function() return table.concat({" +
                "type(C_VoiceChat.GetAvailableInputDevices())," +
                "type(C_VoiceChat.GetAvailableOutputDevices())," +
                "type(C_VoiceChat.GetCommunicationMode())," +
                "type(C_VoiceChat.GetInputVolume())," +
                "type(C_VoiceChat.GetOutputVolume())," +
                "type(C_VoiceChat.GetVADSensitivity())," +
                "Enum.CommunicationMode.PushToTalk,Enum.CommunicationMode.OpenMic," +
                "Enum.CommunicationModeMeta.NumValues," +
                "Enum.CommunicationModeMeta.MinValue," +
                "Enum.CommunicationModeMeta.MaxValue},':') end)()"));

        Assert.Equal(
            "false:false:false:false:false:false:false:false",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(pcall(C_VoiceChat.BeginLocalCapture))," +
                "tostring(pcall(C_VoiceChat.BeginLocalCapture,nil))," +
                "tostring(pcall(C_VoiceChat.SetCommunicationMode,2))," +
                "tostring(pcall(C_VoiceChat.SetInputDevice,nil))," +
                "tostring(pcall(C_VoiceChat.SetOutputDevice,{}))," +
                "tostring(pcall(C_VoiceChat.SetInputVolume,'bad'))," +
                "tostring(pcall(C_VoiceChat.SetOutputVolume))," +
                "tostring(pcall(C_VoiceChat.SetMasterVolumeScale,{}))},':')"));

        session.Lua.Evaluate(
            "C_VoiceChat.BeginLocalCapture(false); " +
            "C_VoiceChat.SetInputVolume(-50); " +
            "C_VoiceChat.SetOutputVolume(150); " +
            "C_VoiceChat.SetVADSensitivity(101)");
        Assert.True(voiceChat.IsCapturingLocally);
        Assert.False(voiceChat.ListenToLocalUser);
        Assert.Equal(0, voiceChat.InputVolume);
        Assert.Equal(100, voiceChat.OutputVolume);
        Assert.Equal(100, voiceChat.VadSensitivity);
    }

