    [Fact]
    public void PrivateAuraAnchorsRetainNativeAnchorLifecycleState()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "1",
            session.Lua.Evaluate(
                "(function() local parent=CreateFrame('Frame','PrivateAuraParent',UIParent); " +
                "local id=C_UnitAuras.AddPrivateAuraAnchor({" +
                "unitToken='player',auraIndex=2,parent=parent,showCountdownFrame=true," +
                "showCountdownNumbers=false,isContainer=false," +
                "iconInfo={iconAnchor={point='CENTER',relativeTo=parent,relativePoint='CENTER'," +
                "offsetX=0,offsetY=0},iconWidth=18,iconHeight=20,borderScale=1.25}}); " +
                "return id end)()"));

        var anchor = Assert.Single(session.Lua.UnitAuras.PrivateAuraAnchors.Values);
        Assert.Equal("player", anchor.UnitToken);
        Assert.Equal((uint)2, anchor.AuraIndex);
        Assert.True(anchor.ShowCountdownFrame);
        Assert.False(anchor.ShowCountdownNumbers);
        Assert.Equal(18, anchor.IconWidth);
        Assert.Equal(20, anchor.IconHeight);
        Assert.Equal(1.25, anchor.BorderScale);

        session.Lua.Evaluate($"C_UnitAuras.RemovePrivateAuraAnchor({anchor.Id})");
        Assert.Empty(session.Lua.UnitAuras.PrivateAuraAnchors);

        session.Lua.Evaluate(
            "local relative=CreateFrame('Frame','PrivateWarningRelative',UIParent); " +
            "C_UnitAuras.TriggerPrivateAuraShowDispelType(true); " +
            "C_UnitAuras.SetPrivateWarningTextAnchor(PrivateAuraParent," +
            "{point='TOP',relativeTo=relative,relativePoint='BOTTOM',offsetX=4,offsetY=-6})");
        Assert.True(session.Lua.UnitAuras.PrivateAuraShowDispelType);
        var warningAnchor = session.Lua.UnitAuras.PrivateWarningTextAnchor!;
        Assert.Equal(session.Ui.Find("PrivateAuraParent")!.Id, warningAnchor.ParentObjectId);
        Assert.Equal(session.Ui.Find("PrivateWarningRelative")!.Id, warningAnchor.RelativeToObjectId);
        Assert.Equal("TOP", warningAnchor.Point);
        Assert.Equal(-6, warningAnchor.OffsetY);
    }

