    [Fact]
    public void UnitAuraGeneratedContractsPreservePaginationSortingAndTableShape()
    {
        using var session = new EmulatorSession();
        session.Lua.UnitAuras.ForUnit("player").Add(new WowUnitAuraInfoState
        {
            AuraInstanceId = 30,
            Name = "Zulu",
            SpellId = 300,
            ExpirationTime = 20,
            IsHelpful = true,
            IsFromPlayerOrPlayerPet = true,
            HideOnPartyFrames = true
        });
        session.Lua.UnitAuras.ForUnit("player").Add(new WowUnitAuraInfoState
        {
            AuraInstanceId = 10,
            Name = "Alpha",
            SpellId = 100,
            ExpirationTime = 0,
            IsHarmful = true
        });
        session.Lua.UnitAuras.ForUnit("player").Add(new WowUnitAuraInfoState
        {
            AuraInstanceId = 20,
            Name = "Middle",
            SpellId = 200,
            ExpirationTime = 10,
            IsHelpful = true
        });
        session.Lua.Spells.Add(300, "Zulu").IsBigDefensive = true;

        Assert.Equal(
            "0:1:30:nil:1:2:20,30:30,20:30:true:true:true:true:true",
            session.Lua.Evaluate(
                "(function() " +
                "local filter='HELPFUL'; " +
                "local zeroToken=C_UnitAuras.GetAuraSlots('player',filter,0); " +
                "local endToken=C_UnitAuras.GetAuraSlots('player',filter,nil,999); " +
                "local all=C_UnitAuras.GetUnitAuras('player',filter); " +
                "local byName=C_UnitAuras.GetUnitAuraInstanceIDs('player',filter,nil," +
                "Enum.UnitAuraSortRule.NameOnly,Enum.UnitAuraSortDirection.Normal); " +
                "local reverse=C_UnitAuras.GetUnitAuraInstanceIDs('player',filter,nil," +
                "Enum.UnitAuraSortRule.NameOnly,Enum.UnitAuraSortDirection.Reverse); " +
                "local aura=C_UnitAuras.GetAuraDataBySpellName('player','Zulu'); " +
                "local link=C_UnitAuras.GetPlayerAuraBySpellID('|Hspell:300:0|h[Zulu]|h'); " +
                "return table.concat({zeroToken,select('#',C_UnitAuras.GetAuraSlots('player',filter,0))," +
                "all[1].auraInstanceID,tostring(endToken)," +
                "select('#',C_UnitAuras.GetAuraSlots('player',filter,nil,999)),#all," +
                "table.concat(byName,','),table.concat(reverse,','),link.auraInstanceID," +
                "tostring(aura.hideOnPartyFrames),tostring(aura.charges==nil)," +
                "tostring(Enum.UnitAuraSortRuleMeta.NumValues==7)," +
                "tostring(select(1,C_UnitAuras.GetAuraSlots('player'))==nil)," +
                "tostring(C_UnitAuras.GetUnitAuras('player','HARMFUL')[1].auraInstanceID==10)" +
                "},':') end)()"));

        Assert.Equal(
            "true:true:true:false:false",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(C_UnitAuras.AuraIsBigDefensive(300))," +
                "tostring(C_UnitAuras.AuraIsBigDefensive('Zulu'))," +
                "tostring(C_UnitAuras.AuraIsBigDefensive(" +
                "'|Hspell:300:0|h[Zulu]|h'))," +
                "tostring(C_UnitAuras.AuraIsBigDefensive(999))," +
                "tostring(pcall(C_UnitAuras.AuraIsBigDefensive,{}))},':')"));

        Assert.Equal(
            "false:false:false:false:false:false:false:false",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(pcall(C_UnitAuras.GetUnitAuras,'player'))," +
                "tostring(pcall(C_UnitAuras.GetAuraDataByIndex,'player','bad'))," +
                "tostring(pcall(C_UnitAuras.GetAuraDataBySlot,'player',math.huge))," +
                "tostring(pcall(C_UnitAuras.GetPlayerAuraBySpellID,{}))," +
                "tostring(pcall(C_UnitAuras.AddBlockedAura,'player',4294967295))," +
                "tostring(pcall(C_UnitAuras.RemovePrivateAuraAnchor,-1))," +
                "tostring(pcall(C_UnitAuras.TriggerPrivateAuraShowDispelType))," +
                "tostring(pcall(C_UnitAuras.AddPrivateAuraAnchor,{}))},':')"));
    }

    [Fact]
    public void UnitAurasPrivateMatchesNativeContractsAndAppliesStoredAnchors()
    {
        using var session = new EmulatorSession();
        session.Lua.UnitAuras.ForUnit("player").Add(new WowUnitAuraInfoState
        {
            AuraInstanceId = 71,
            Name = "Public Aura",
            SpellId = 701,
            IsHelpful = true
        });
        session.Lua.UnitAuras.ForUnit("player").Add(new WowUnitAuraInfoState
        {
            AuraInstanceId = 72,
            Name = "Private Aura",
            SpellId = 702,
            IsHelpful = true,
            IsPrivate = true
        });
        session.Lua.UnitAuras.PrivateAuraAppliedSounds.Add(
            new WowPrivateAuraAppliedSoundInfoState(
                "player",
                702,
                "PrivateAura.ogg",
                9001,
                "Dialog"));

        Assert.Equal(
            "1:Private Aura:Private Aura:1:player:702:PrivateAura.ogg:9001:Dialog:true:" +
            "CENTER:true:CENTER:3:-4:TOP:true:BOTTOM:5:6",
            session.Lua.Evaluate(
                "(function() " +
                "local parent=CreateFrame('Frame','PrivateNativeParent',UIParent); " +
                "local relative=CreateFrame('Frame','PrivateNativeRelative',parent); " +
                "local id=C_UnitAuras.AddPrivateAuraAnchor({" +
                "unitToken='player',auraIndex=2,parent=parent," +
                "showCountdownFrame=true,showCountdownNumbers=true,isContainer=false," +
                "iconInfo={iconAnchor={point='CENTER',relativeTo=relative," +
                "relativePoint='CENTER',offsetX=3,offsetY=-4},iconWidth=18,iconHeight=18}," +
                "durationAnchor={point='TOP',relativeTo=relative,relativePoint='BOTTOM'," +
                "offsetX=5,offsetY=6}}); " +
                "local auraFrame=CreateFrame('Frame','PrivateBoundAura',UIParent); " +
                "local icon=auraFrame:CreateTexture('PrivateBoundIcon'); " +
                "local duration=CreateFrame('Cooldown','PrivateBoundDuration',auraFrame); " +
                "C_UnitAurasPrivate.AnchorPrivateAura(auraFrame,icon,duration,id); " +
                "local private=C_UnitAurasPrivate.GetAllPrivateAuras('player'); " +
                "local byID=C_UnitAurasPrivate.GetAuraDataByAuraInstanceIDPrivate('player',72); " +
                "local sounds=C_UnitAurasPrivate.GetAuraAppliedSoundsForSpell('player',702); " +
                "local ip,ir,irp,ix,iy=icon:GetPoint(1); " +
                "local dp,dr,drp,dx,dy=duration:GetPoint(1); " +
                "return table.concat({#private,private[1].name,byID.name,#sounds," +
                "sounds[1].unitToken,sounds[1].spellID,sounds[1].soundFileName," +
                "sounds[1].soundFileID,sounds[1].outputChannel," +
                "tostring(auraFrame:GetParent()==parent),ip,tostring(ir==relative),irp,ix,iy," +
                "dp,tostring(dr==relative),drp,dx,dy},':') end)()"));

        var bound = session.Ui.Find("PrivateBoundAura")!;
        var parent = session.Ui.Find("PrivateNativeParent")!;
        Assert.Equal(parent.Id, bound.ParentId);
        Assert.Equal(parent.Id, bound.AllPointsTargetId);
        var binding = Assert.Single(session.Lua.UnitAuras.PrivateAuraBindings.Values);
        Assert.Equal(bound.Id, binding.AuraFrameObjectId);

        session.Lua.Evaluate(
            "local first=C_FunctionContainers.CreateCallback(function() end); " +
            "local second=C_FunctionContainers.CreateCallback(function() end); " +
            "C_UnitAurasPrivate.AddPrivateAuraUpdateCallback('player',first); " +
            "C_UnitAurasPrivate.AddPrivateAuraUpdateCallback('player',second); " +
            "C_UnitAurasPrivate.RemovePrivateAuraUpdateCallback('player',first)");
        Assert.Single(
            session.Lua.UnitAuras.PrivateAuraUpdateCallbackReferences["player"]);

        Assert.Equal(
            "false:false:false:false:false:false:false:false:false",
            session.Lua.Evaluate(
                "local texture=PrivateNativeParent:CreateTexture(); " +
                "return table.concat({" +
                "tostring(pcall(C_UnitAurasPrivate.AddPrivateAuraUpdateCallback,'player'))," +
                "tostring(pcall(C_UnitAurasPrivate.RemovePrivateAuraUpdateCallback,'player'))," +
                "tostring(pcall(C_UnitAurasPrivate.AnchorPrivateAura,texture,texture,texture,1))," +
                "tostring(pcall(C_UnitAurasPrivate.GetAllPrivateAuras))," +
                "tostring(pcall(C_UnitAurasPrivate.GetAuraAppliedSoundsForSpell,'player',{}))," +
                "tostring(pcall(C_UnitAurasPrivate.GetAuraDataByAuraInstanceIDPrivate,'player',-1))," +
                "tostring(pcall(C_UnitAurasPrivate.SetPrivateAuraAnchorAddedCallback,nil))," +
                "tostring(pcall(C_UnitAurasPrivate.SetShowDispelTypeCallback,nil))," +
                "tostring(pcall(C_UnitAurasPrivate.SetPrivateWarningTextFrame,texture))},':')"));
    }

