                "local opened; local loaded=0; local frame=CreateFrame('Frame'); " +
                "frame:RegisterEvent('SETTINGS_LOADED'); frame:RegisterEvent('SETTINGS_PANEL_OPEN'); " +
                "frame:SetScript('OnEvent',function(_,event,category,element) " +
                "if event=='SETTINGS_LOADED' then loaded=loaded+1 " +
                "else opened=tostring(category)..':'..element end end); " +
                "C_SettingsUtil.NotifySettingsLoaded(); C_SettingsUtil.NotifySettingsLoaded(); " +
                "C_SettingsUtil.OpenSettingsPanel(7,'VoiceChat'); " +
                "return MakeModifiers()..':'..opened..':'..loaded"));
        Assert.True(session.Lua.SettingsUtil.SettingsLoaded);
