        Assert.Equal(
            "false:false",
            session.Lua.Evaluate(
                "local a=pcall(C_SettingsUtil.OpenSettingsPanel,{});" +
                "local b=pcall(C_SettingsUtil.OpenSettingsPanel,1,{});" +
                "return tostring(a)..':'..tostring(b)"));
