    [Fact]
    public void MouseButtonStateMatchesNativeOptionalButtonFiltering()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "false:false:false:false",
            session.Lua.Evaluate(
                "return table.concat({tostring(IsMouseButtonDown())," +
                "tostring(IsMouseButtonDown('LeftButton'))," +
                "tostring(IsMouseButtonDown('missing'))," +
                "tostring(IsMouseButtonDown({}))},':')"));

        session.MouseButton("LeftButton", true);
        Assert.Equal(
            "true:true:true:true:false:false:true",
            session.Lua.Evaluate(
                "return table.concat({tostring(IsMouseButtonDown())," +
                "tostring(IsMouseButtonDown('LeftButton'))," +
                "tostring(IsMouseButtonDown('button1'))," +
                "tostring(IsMouseButtonDown(1.9))," +
                "tostring(IsMouseButtonDown('RightButton'))," +
                "tostring(IsMouseButtonDown(2))," +
                "tostring(C_Input.IsMouseButtonDown())},':')"));

        session.MouseButton("RightButton", true);
        session.MouseButton("LeftButton", false);
        Assert.Equal(
            "true:false:true:true",
            session.Lua.Evaluate(
                "return table.concat({tostring(IsMouseButtonDown())," +
                "tostring(IsMouseButtonDown('LeftButton'))," +
                "tostring(IsMouseButtonDown('RightButton'))," +
                "tostring(IsMouseButtonDown(2))},':')"));

        session.MouseButton("RightButton", false);
        Assert.Equal("false", session.Lua.Evaluate("return tostring(IsMouseButtonDown())"));
    }

