    [Fact]
    public void PvpPredicatesAndWarModeFollowNativeEnumAndDirectionContracts()
    {
        using var session = new EmulatorSession();
        session.Lua.Pvp.ActiveMatchState = 3;
        session.Lua.Pvp.CanEnableWarMode = true;
        session.Lua.Pvp.CanDisableWarMode = false;
        session.Lua.Pvp.CanToggleWarModeInArea = false;
        session.Lua.Pvp.AreTrainingGroundsEnabled = true;
        session.Lua.Pvp.CanPlayerUseRatedPvpUi = false;
        session.Lua.Pvp.RatedPvpUiFailureReason = "Rated unavailable";
        session.Lua.Pvp.CanPlayerUseTrainingGroundsUi = true;
        session.Lua.Pvp.TrainingGroundsUiFailureReason = string.Empty;
        session.Lua.Pvp.BattlegroundEnlistmentBonusActive = true;
        session.Lua.Pvp.BrawlEnlistmentBonusActive = false;

        Assert.Equal(
            "false:true:false:false:true:false:true:false:false:true:" +
            "Rated unavailable::true:true:false",
            session.Lua.Evaluate(
                "(function() " +
                "local missing=pcall(C_PvP.CanToggleWarMode); " +
                "local canEnable=C_PvP.CanToggleWarMode(true); " +
                "local canDisable=C_PvP.CanToggleWarMode(false); " +
                "local nilMeansFalse=C_PvP.CanToggleWarMode(nil); " +
                "C_PvP.ToggleWarMode(); local enabled=C_PvP.IsWarModeDesired(); " +
                "C_PvP.ToggleWarMode(); local stillEnabled=C_PvP.IsWarModeDesired(); " +
                "local rated,ratedReason=C_PvP.CanPlayerUseRatedPVPUI(); " +
                "local training,trainingReason=C_PvP.CanPlayerUseTrainingGroundsUI(); " +
                "local battleground,brawl=C_PvP.IsBattlegroundEnlistmentBonusActive(); " +
                "return table.concat({tostring(missing)," +
                "tostring(C_PvP.IsMatchActive()),tostring(C_PvP.IsMatchComplete())," +
                "tostring(canDisable),tostring(canEnable),tostring(nilMeansFalse)," +
                "tostring(enabled),tostring(C_PvP.CanToggleWarModeInArea())," +
                "tostring(rated),tostring(training),ratedReason,trainingReason," +
                "tostring(C_PvP.AreTrainingGroundsEnabled())," +
                "tostring(battleground),tostring(brawl)},':') end)()"));
        Assert.True(session.Lua.Pvp.IsWarModeDesired);

        session.Lua.Pvp.ActiveMatchState = 5;
        Assert.Equal(
            "false:true",
            session.Lua.Evaluate(
                "return tostring(C_PvP.IsMatchActive())..':'.." +
                "tostring(C_PvP.IsMatchComplete())"));
    }

    [Fact]
    public void LegacyPvpGlobalsUseNativeAritiesValidationAndRequestState()
    {
        using var session = new EmulatorSession();
        session.Lua.Pvp.ArenaOpponentSpecCount = 2;
        session.Lua.Pvp.ArenaOpponentSpecializations[1] = 250;
        session.Lua.Pvp.ArenaOpponentGenders[1] = 1;
        session.Lua.Pvp.ArenaOpponentSpecializations[2] = 577;
        session.Lua.Pvp.ArenaOpponentGenders[2] = 2;
        session.Lua.Pvp.PlayerRoleTank = true;
        session.Lua.Pvp.PlayerRoleHealer = false;
        session.Lua.Pvp.PlayerRoleDamage = true;
        session.Lua.Pvp.CurrentArenaSeason = 42;
        session.Lua.Pvp.QuestRewardDataAvailable.Add(9001);

        Assert.Equal(
            "250:1:0:0:2:true:false:true:42:true:false:1:false",
            session.Lua.Evaluate(
                "(function() " +
                "local spec,gender=GetArenaOpponentSpec('1.9'); " +
                "local tank,healer,damage=GetPVPRoles(); " +
                "local invalid=pcall(HaveQuestRewardData,'quest'); " +
                "return table.concat({spec,gender," +
                "select('#',GetArenaOpponentSpec(3))," +
                "select('#',GetArenaOpponentSpec('bad'))," +
                "GetNumArenaOpponentSpecs(),tostring(tank),tostring(healer)," +
                "tostring(damage),GetCurrentArenaSeason()," +
                "tostring(HaveQuestRewardData('9001'))," +
                "tostring(HaveQuestRewardData(9002))," +
                "select('#',HaveQuestRewardData(0)),tostring(invalid)},':') end)()"));

        Assert.Contains(9002, session.Lua.Pvp.RequestedQuestRewardDataIds);
        Assert.DoesNotContain(0, session.Lua.Pvp.RequestedQuestRewardDataIds);

        session.Lua.Evaluate(
            "RequestPVPRewards(); RequestPVPOptionsEnabled(); " +
            "RequestRandomBattlegroundInstanceInfo(); RequestRatedInfo()");
        Assert.Equal(1, session.Lua.Pvp.PvpRewardsRequestCount);
        Assert.Equal(1, session.Lua.Pvp.PvpOptionsEnabledRequestCount);
        Assert.Equal(
            1,
            session.Lua.Pvp.RandomBattlegroundInstanceInfoRequestCount);
        Assert.Equal(1, session.Lua.Pvp.RatedInfoRequestCount);
    }

