                "local blitzArity=select('#',C_PvP.JoinRatedBGBlitz()); " +
                "local trainingArity=" +
                "select('#',C_PvP.JoinTrainingGround(-1)); " +
                "local crowdArity=select('#'," +
                "C_PvP.RequestCrowdControlSpell('player')); " +
                "C_PvP.JoinBattlefield(65537); " +
                "C_PvP.JoinBrawl(true); C_PvP.JoinBrawl(nil); " +
                "local badBattlefield=pcall(C_PvP.JoinBattlefield,-1); " +
                "local badTraining=pcall(C_PvP.JoinTrainingGround,{}); " +
                "local badUnit=pcall(" +
                "C_PvP.RequestCrowdControlSpell,'unknown'); " +
                "return table.concat({" +
                "battlefieldArity,brawlArity,randomArity,blitzArity," +
                "trainingArity,crowdArity," +
                "tostring(false),tostring(true),tostring(false)," +
                "4294967295,2,1,1,'player'," +
                "tostring(badBattlefield),tostring(badTraining)," +
                "tostring(badUnit)" +
                "},':') end)()"));

        Assert.Equal(
            [(ushort)12, (ushort)1],
            session.Lua.Pvp.BattlefieldJoinRequests);
        Assert.Equal(
            [false, true, false],
            session.Lua.Pvp.BrawlJoinRequests);
        Assert.Equal(
            1,
            session.Lua.Pvp.RandomTrainingGroundJoinRequestCount);
        Assert.Equal(1, session.Lua.Pvp.RatedBgBlitzJoinRequestCount);
        Assert.Equal(
            [uint.MaxValue],
            session.Lua.Pvp.TrainingGroundJoinRequests);
        Assert.Equal(
            ["player"],
            session.Lua.Pvp.CrowdControlSpellRequestUnitTokens);
    }

