    [Fact]
    public void ConcreteXmlAnchorsReplaceInheritedTemplateAnchors()
    {
        var root = Path.Combine(Path.GetTempPath(), $"wow-addon-lab-{Guid.NewGuid():N}");
        var addon = CreateAddon(
            root,
            "XmlAnchorOverride",
            ["layout.xml"],
            [
                "<Ui>" +
                "<Frame name=\"AnchorBase\" virtual=\"true\">" +
                "<Anchors>" +
                "<Anchor point=\"TOPLEFT\"/>" +
                "<Anchor point=\"BOTTOMRIGHT\"/>" +
                "</Anchors>" +
                "</Frame>" +
                "<Frame name=\"AnchorTarget\" parent=\"UIParent\">" +
                "<Size x=\"300\" y=\"200\"/>" +
                "<Anchors><Anchor point=\"CENTER\"/></Anchors>" +
                "</Frame>" +
                "<Frame name=\"AnchorOverride\" parent=\"UIParent\" inherits=\"AnchorBase\">" +
                "<Anchors>" +
                "<Anchor point=\"TOPLEFT\" relativeTo=\"AnchorTarget\"/>" +
                "<Anchor point=\"BOTTOMLEFT\" relativeTo=\"AnchorTarget\"/>" +
                "<Anchor point=\"RIGHT\" relativeTo=\"AnchorTarget\"/>" +
                "</Anchors>" +
                "</Frame>" +
                "</Ui>"
            ]);
        try
        {
            using var session = new EmulatorSession();
            session.Load(addon);

            Assert.Equal(
                "3:300:200",
                session.Lua.Evaluate(
                    "return table.concat({" +
                    "AnchorOverride:GetNumPoints()," +
                    "AnchorOverride:GetWidth()," +
                    "AnchorOverride:GetHeight()},':')"));
        }
        finally
        {
            Directory.Delete(root, recursive: true);
        }
    }

