    [Fact]
    public void ArtifactUiUsesNativeRecordsMissArityAndStatePredicates()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "0:0:0:0:true:true:false:nil",
            session.Lua.Evaluate(
                "return table.concat({" +
                "select('#',C_ArtifactUI.GetArtifactArtInfo())," +
                "select('#',C_ArtifactUI.GetArtifactInfo())," +
                "select('#',C_ArtifactUI.GetEquippedArtifactArtInfo())," +
                "select('#',C_ArtifactUI.GetEquippedArtifactInfo())," +
                "tostring(C_ArtifactUI.IsArtifactDisabled())," +
                "tostring(C_ArtifactUI.IsEquippedArtifactDisabled())," +
                "tostring(C_ArtifactUI.IsViewedArtifactEquipped())," +
                "tostring(C_ArtifactUI.GetArtifactTier())},':')"));

        var colors = new[]
        {
            new WowArtifactColorState(0.1, 0.2, 0.3, 0.4),
            new WowArtifactColorState(0.5, 0.6, 0.7, 0.8),
            new WowArtifactColorState(0.9, 0.8, 0.7, 0.6)
        };
        var artInfo = new WowArtifactArtInfoState(
            "Arcane",
            "The Forge",
            colors[0],
            colors[1],
            colors[2],
            77,
            88);
        var info = new WowArtifactInfoState(
            128820,
            128821,
            "Felo'melorn",
            12345,
            9876.5,
            14,
            6,
            101,
            102,
            103,
            104,
            true,
            5);
        session.Lua.Artifact.ViewedArtifact =
            new WowArtifactInstanceState("artifact-guid", info, artInfo)
            {
                Tier = 5
            };
        session.Lua.Artifact.EquippedArtifact =
            new WowArtifactInstanceState("artifact-guid", info, artInfo);
        session.Lua.Artifact.PurchasedPowerRanks.Add(2);
        session.Lua.Artifact.PurchasedPowerRanks.Add(255);
        session.Lua.Artifact.NumObtainedArtifacts = 4;
        session.Lua.Artifact.IsArtifactDisabled = false;
        session.Lua.Artifact.IsEquippedArtifactDisabled = false;
        session.Lua.Artifact.IsEquippedArtifactMaxed = true;
        session.Lua.Artifact.IsMaxedByRulesOrEffect = true;
        session.Lua.Artifact.IsAtForge = true;

        Assert.Equal(
            "Arcane:The Forge:0.1:0.8:77:88",
            session.Lua.Evaluate(
                "local a=C_ArtifactUI.GetArtifactArtInfo(); " +
                "return table.concat({a.textureKit,a.titleName,a.titleColor.r," +
                "a.barConnectedColor.a,a.uiModelSceneID,a.spellVisualKitID},':')"));
        Assert.Equal(
            "13:128820:128821:Felo'melorn:12345:9876.5:14:6:101:102:103:104:true:5",
            session.Lua.Evaluate(
                "local i={C_ArtifactUI.GetArtifactInfo()}; " +
                "i[12]=tostring(i[12]); " +
                "return table.concat({#i,unpack(i)},':')"));
        Assert.Equal(
            "13:5:257:4:true:true:false:false:true:true:true",
            session.Lua.Evaluate(
                "return table.concat({" +
                "select('#',C_ArtifactUI.GetEquippedArtifactInfo())," +
                "C_ArtifactUI.GetArtifactTier()," +
                "C_ArtifactUI.GetTotalPurchasedRanks()," +
                "C_ArtifactUI.GetNumObtainedArtifacts()," +
                "tostring(C_ArtifactUI.IsViewedArtifactEquipped())," +
                "tostring(HasArtifactEquipped())," +
                "tostring(C_ArtifactUI.IsArtifactDisabled())," +
                "tostring(C_ArtifactUI.IsEquippedArtifactDisabled())," +
                "tostring(C_ArtifactUI.IsEquippedArtifactMaxed())," +
                "tostring(C_ArtifactUI.IsMaxedByRulesOrEffect())," +
                "tostring(C_ArtifactUI.IsAtForge())},':')"));
        Assert.Equal(
            "0:0:0:false:true",
            session.Lua.Evaluate(
                "return table.concat({" +
                "select('#',C_ArtifactUI.Clear())," +
                "select('#',C_ArtifactUI.GetArtifactArtInfo())," +
                "select('#',C_ArtifactUI.GetArtifactInfo())," +
                "tostring(C_ArtifactUI.IsViewedArtifactEquipped())," +
                "tostring(C_ArtifactUI.IsAtForge())},':')"));
        Assert.Equal(1, session.Lua.Artifact.ClearCount);
    }

