    [Fact]
    public void AddonBindingsXmlRegistersNativeBindingCatalogMetadata()
    {
        var root = Path.Combine(Path.GetTempPath(), $"bindings-xml-{Guid.NewGuid():N}");
        var addon = CreateAddon(root, "BindingsCatalog", ["main.lua"], [string.Empty]);
        File.WriteAllText(
            Path.Combine(addon, "Bindings.xml"),
            """
            <Bindings>
              <Binding name="MOVEFORWARD" category="BINDING_HEADER_MOVEMENT"
                       header="BLANK8" searchTags="BINDING_TAG_MOVE">bindingResult=keystate</Binding>
              <Binding name="TOGGLE_VOICE_PUSH_TO_TALK" category="BINDING_HEADER_CHAT"
                       preface="VOICE_BINDINGS" bindingContext="HousingEditorBasicDecorMode"
                       customBindingID="VoicePushToTalk" runOnUp="true">noop()</Binding>
            </Bindings>
            """);
        File.WriteAllText(
            Path.Combine(addon, "DefaultBindings.wtf"),
            "bind W MOVEFORWARD\nbind SHIFT-V TOGGLE_VOICE_PUSH_TO_TALK\n");

        try
        {
            using var session = new EmulatorSession();
            session.GlobalStringProvider = new TestGlobalStringProvider();
            session.Load(addon);

            Assert.Equal(
                "4:HEADER_BLANK8:MOVEFORWARD:BINDING_HEADER_MOVEMENT:2:4:0:2:1:Move Forward:Move:W:SHIFT-V",
                session.Lua.Evaluate(
                    "local h=GetBinding(1); local a,c=GetBinding(2); " +
                    "local tags=C_KeyBindings.GetSearchTagsForAction(a); " +
                    "return table.concat({GetNumBindings(),h,a,c," +
                    "C_KeyBindings.GetBindingIndex(a)," +
                    "C_KeyBindings.GetBindingIndex('TOGGLE_VOICE_PUSH_TO_TALK')," +
                    "C_KeyBindings.GetCustomBindingType(4)," +
                    "C_KeyBindings.GetBindingContextForAction('TOGGLE_VOICE_PUSH_TO_TALK')," +
                    "#tags,GetBindingName(a),tags[1]," +
                    "GetBindingKey(a),GetBindingKey('TOGGLE_VOICE_PUSH_TO_TALK')},':')"));
            Assert.True(session.Lua.Bindings.RunsOnUp("TOGGLE_VOICE_PUSH_TO_TALK"));
            Assert.Equal(
                "down:up:nil",
                session.Lua.Evaluate(
                    "RunBinding('MOVEFORWARD'); local down=bindingResult; " +
                    "RunBinding('MOVEFORWARD','up'); " +
                    "return table.concat({down,bindingResult,tostring(keystate)},':')"));
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

