    [Fact]
    public void BindingGlobalsAndNamespaceUseNativeContractsAndContextState()
    {
        using var session = new EmulatorSession();
        session.Lua.Bindings.SetKeys("MOVEFORWARD", "W", "UP", "PADLSTICKUP");
        session.Lua.Bindings.SetCategory("MOVEFORWARD", "MOVEMENT");
        session.Lua.Bindings.SetContext("MOVEFORWARD", 2);
        session.Lua.Bindings.SetCustomBindingType("MOVEFORWARD", 0);
        session.Lua.Bindings.SetSearchTags("MOVEFORWARD", "move", "forward");

        Assert.Equal(
            "5:MOVEFORWARD:MOVEMENT:W:UP:PADLSTICKUP:3:1:MOVEFORWARD:2:0:2:move:forward:" +
            "9:2:0:nil:false:true:2:true:nil",
            session.Lua.Evaluate(
                "local command,category,key1,key2,key3=GetBinding(1); " +
                "local tags=C_KeyBindings.GetSearchTagsForAction('MOVEFORWARD'); " +
                "C_KeyBindings.ActivateBindingContext(2); " +
                "local active=C_KeyBindings.IsBindingContextActive(2); " +
                "C_KeyBindings.SetTurnStrafeStyle(2); " +
                "local before=C_KeyBindings.GetBindingByKey('W',2); " +
                "C_KeyBindings.DeactivateBindingContext(2); " +
                "return table.concat({select('#',GetBinding(1)),command,category,key1,key2,key3," +
                "select('#',GetBindingKey('MOVEFORWARD'))," +
                "C_KeyBindings.GetBindingIndex('MOVEFORWARD'),before," +
                "C_KeyBindings.GetBindingContextForAction('MOVEFORWARD')," +
                "C_KeyBindings.GetCustomBindingType(1),#tags,tags[1],tags[2]," +
                "Enum.BindingContext.ReservedFutureFeatureBinding01," +
                "Enum.TurnStrafeStyle.Custom,Enum.CustomBindingType.VoicePushToTalk," +
                "tostring(C_KeyBindings.GetBindingIndex('UNKNOWN'))," +
                "tostring(C_KeyBindings.IsBindingContextActive(2))," +
                "tostring(type(GetBindingName)=='function'),C_KeyBindings.GetTurnStrafeStyle()," +
                "tostring(active),tostring(C_KeyBindings.GetBindingByKey('W',1))},':')"));

        Assert.Equal(
            "false:false:false",
            session.Lua.Evaluate(
                "local okIndex=pcall(GetBinding,0); " +
                "local okType=pcall(GetBinding,{}); " +
                "local okContext=pcall(C_KeyBindings.ActivateBindingContext,10); " +
                "return table.concat({tostring(okIndex),tostring(okType),tostring(okContext)},':')"));
    }

