    [Fact]
    public void WeeklyRewardsUseNativeRecordsOptionalityAndCommandGates()
    {
        using var session = new EmulatorSession();
        var weekly = session.Lua.WeeklyRewards;
        weekly.StoredRewardPeriodId = 40;
        weekly.CurrentRewardPeriodId = 41;
        weekly.GeneratedRewards = true;
        weekly.HasRewardPayload = true;
        weekly.InteractionActive = true;
        weekly.IsWeeklyChestRetired = true;
        weekly.ShouldShowFinalRetirementMessage = true;
        weekly.ShouldShowRetirementMessage = false;
        weekly.Activities.Add(
            new WowWeeklyRewardActivityState(
                2,
                2,
                8,
                5,
                101,
                202,
                12,
                303,
                "Raid",
                [new WowWeeklyRewardState(4, 404, 2, 505)]));
        weekly.Activities.Add(
            new WowWeeklyRewardActivityState(
                1,
                0,
                2,
                1,
                102,
                203,
                4,
                null,
                null,
                [new WowWeeklyRewardState(5, 405, 1, null)]));
        weekly.EncounterInfo[(2, 2)] =
            [new WowWeeklyRewardEncounterState(606, 16, 7, 707)];
        weekly.ConquestWeeklyProgress =
            new WowConquestWeeklyProgressState(10, 20, 2, 1, 3, "item:808");
        weekly.DifficultyIdsByActivityTier[unchecked((uint)-9)] = 23;
        weekly.ExampleRewardItemHyperlinks[12] =
            new WowWeeklyRewardExampleHyperlinksState("item:1", "item:2");
        weekly.ItemHyperlinks[9007199254740991] = "item:max";
        weekly.NextActivitiesIncreases[(202, 12)] =
            new WowNextActivitiesIncreaseState(true, 204, 13, 700);
        weekly.NextMythicPlusIncreases[12] =
            new WowNextMythicPlusIncreaseState(true, 13, 710);
        weekly.CompletedDungeonRuns =
            new WowCompletedDungeonRunsState(4, 5, 6);
        weekly.SortedProgress[(2, true)] =
            [new WowWeeklyRewardActivityTierProgressState(202, 16, 8)];

        Assert.Equal(
            "1:2:3:8:5:101:202:12:303:Raid:4:404:2:505:" +
            "606:16:7:707:10:20:2:1:3:item:808:23:item:1:item:2:item:max:" +
            "true:204:13:700:true:13:710:4:5:6:202:16:8:" +
            "true:true:true:true:true:true:false",
            session.Lua.Evaluate(
                "local a=C_WeeklyRewards.GetActivities(2)[1]; " +
                "local r=a.rewards[1]; " +
                "local e=C_WeeklyRewards.GetActivityEncounterInfo(2,3)[1]; " +
                "local c=C_WeeklyRewards.GetConquestWeeklyProgress(); " +
                "local h1,h2=C_WeeklyRewards.GetExampleRewardItemHyperlinks(12); " +
                "local sa,at,nl,il=C_WeeklyRewards.GetNextActivitiesIncrease(202,12); " +
                "local sm,ml,mil=C_WeeklyRewards.GetNextMythicPlusIncrease(12); " +
                "local heroic,mythic,plus=C_WeeklyRewards.GetNumCompletedDungeonRuns(); " +
                "local p=C_WeeklyRewards.GetSortedProgressForActivity(2,true)[1]; " +
                "return table.concat({#C_WeeklyRewards.GetActivities(2)," +
                "a.type,a.index,a.threshold,a.progress,a.id,a.activityTierID,a.level," +
                "a.claimID,a.raidString,r.type,r.id,r.quantity,r.itemDBID," +
                "e.encounterID,e.bestDifficulty,e.uiOrder,e.instanceID," +
                "c.progress,c.maxProgress,c.displayType,c.unlocksCompleted,c.maxUnlocks," +
                "c.sampleItemHyperlink,C_WeeklyRewards.GetDifficultyIDForActivityTier(-9)," +
                "h1,h2,C_WeeklyRewards.GetItemHyperlink(9007199254740991)," +
                "tostring(sa),at,nl,il,tostring(sm),ml,mil,heroic,mythic,plus," +
                "p.activityTierID,p.difficulty,p.numPoints," +
                "tostring(C_WeeklyRewards.AreRewardsForCurrentRewardPeriod())," +
                "tostring(C_WeeklyRewards.CanClaimRewards())," +
                "tostring(C_WeeklyRewards.HasAvailableRewards())," +
                "tostring(C_WeeklyRewards.HasGeneratedRewards())," +
                "tostring(C_WeeklyRewards.HasInteraction())," +
                "tostring(C_WeeklyRewards.IsWeeklyChestRetired())," +
                "tostring(C_WeeklyRewards.ShouldShowRetirementMessage())},':')"));

        Assert.Equal(
            "0:0:0:nil:nil:nil:false:0:item:max",
            session.Lua.Evaluate(
                "local a=C_WeeklyRewards.GetActivities(1)[1]; " +
                "return table.concat({" +
                "select('#',C_WeeklyRewards.GetActivityEncounterInfo(1,1))," +
                "select('#',C_WeeklyRewards.GetDifficultyIDForActivityTier(1))," +
                "select('#',C_WeeklyRewards.GetExampleRewardItemHyperlinks(1))," +
                "tostring(a.claimID),tostring(a.raidString),tostring(a.rewards[1].itemDBID)," +
                "tostring(C_WeeklyRewards.GetNextActivitiesIncrease(1,1))," +
                "select('#',C_WeeklyRewards.GetItemHyperlink(1))," +
                "tostring(C_WeeklyRewards.GetItemHyperlink(9007199254740991))},':')"));

        Assert.Equal(
            "false:true:false:false:false",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(pcall(C_WeeklyRewards.GetActivityEncounterInfo,7,1))," +
                "tostring(pcall(C_WeeklyRewards.GetActivityEncounterInfo,1,0))," +
                "tostring(pcall(C_WeeklyRewards.GetSortedProgressForActivity,1))," +
                "tostring(pcall(C_WeeklyRewards.GetDifficultyIDForActivityTier))," +
                "tostring(pcall(C_WeeklyRewards.GetItemHyperlink,-1))},':')"));

        session.Lua.Evaluate(
            "C_WeeklyRewards.ClaimReward(77); " +
            "C_WeeklyRewards.ClaimReward(88); " +
            "C_WeeklyRewards.OnUIInteract(); C_WeeklyRewards.CloseInteraction()");
        Assert.True(weekly.ClaimInProgress);
        Assert.Equal(77, weekly.ClaimedRewardId);
        Assert.Equal(1, weekly.UiInteractRequests);
        Assert.Equal(1, weekly.CloseInteractionRequests);
        Assert.False(weekly.InteractionActive);
    }

