    [Fact]
    public void MythicPlusUsesNativeRecordsFiltersOptionalityAndCommandShapes()
    {
        using var session = new EmulatorSession();
        var mythic = session.Lua.MythicPlus;
        var date = new WowMythicPlusDateState(2026, 7, 29, 15, 42, 3);
        var members = new[]
        {
            new WowMythicPlusMemberState("Mage", 63, 8),
            new WowMythicPlusMemberState("Priest", 257, 5)
        };
        var best = new WowMythicPlusBestRunState(
            1875,
            12,
            date,
            [9, 10],
            members,
            321);

        mythic.CurrentAffixes =
        [
            new WowMythicPlusAffixState(9, 18),
            new WowMythicPlusAffixState(10, 18)
        ];
        mythic.CurrentSeason = 18;
        mythic.CurrentSeasonValues = new WowMythicPlusSeasonValuesState(18, 17, 16);
        mythic.CurrentUiDisplaySeason = 18;
        mythic.EndOfRunGearSequenceLevels[12] = 7;
        mythic.OwnedKeystoneChallengeMapId = 503;
        mythic.OwnedKeystoneLevel = 12;
        mythic.OwnedKeystoneMapId = 2662;
        mythic.RewardLevelsByDifficulty[16] =
            new WowMythicPlusRewardLevelsState(678, 665);
        mythic.RewardLevelsByKeystoneLevel[12] = 665;
        mythic.RunHistory.Add(new WowMythicPlusRunState(
            503, 12, true, true, 321, 1875, date, 18));
        mythic.RunHistory.Add(new WowMythicPlusRunState(
            504, 8, false, false, 0, 2400, date, 17));
        mythic.SeasonBestAffixScores[503] = new WowMythicPlusAffixScoreInfoState(
            [new WowMythicPlusAffixScoreState("Tyrannical", 321, 12, 1875, false)],
            642);
        mythic.SeasonBestsByMap[503] = new WowMythicPlusSeasonBestState(best, null);
        mythic.SeasonBestRatingFromExpansion =
            new WowMythicPlusExpansionRatingState(18, 2875);
        mythic.WeeklyBestsByMap[503] = best;
        mythic.WeeklyChestReward =
            new WowMythicPlusWeeklyChestRewardState(12, 678, 691, 14);
        mythic.IsActive = true;

        Assert.Equal(
            "2:9:18:18:17:16:18:7:503:12:2662:678:665:665:true",
            session.Lua.Evaluate(
                "local a=C_MythicPlus.GetCurrentAffixes(); " +
                "local display,milestone,reward=C_MythicPlus.GetCurrentSeasonValues(); " +
                "local weekly,eor=C_MythicPlus.GetRewardLevelForDifficultyLevel(16); " +
                "return table.concat({#a,a[1].id,a[1].seasonID," +
                "display,milestone,reward,C_MythicPlus.GetCurrentUIDisplaySeason()," +
                "C_MythicPlus.GetEndOfRunGearSequenceLevel(12)," +
                "C_MythicPlus.GetOwnedKeystoneChallengeMapID()," +
                "C_MythicPlus.GetOwnedKeystoneLevel(),C_MythicPlus.GetOwnedKeystoneMapID()," +
                "weekly,eor,C_MythicPlus.GetRewardLevelFromKeystoneLevel(12)," +
                "tostring(C_MythicPlus.IsMythicPlusActive())},':')"));

        Assert.Equal(
            "1:503:12:true:true:321:1875:2026:7:29:15:42:4:18:2",
            session.Lua.Evaluate(
                "local runs=C_MythicPlus.GetRunHistory(false,false,true); local r=runs[1]; " +
                "return table.concat({#runs,r.mapChallengeModeID,r.level,tostring(r.thisWeek)," +
                "tostring(r.completed),r.runScore,r.durationSec,r.completionDate.year," +
                "r.completionDate.month,r.completionDate.day,r.completionDate.hour," +
                "r.completionDate.minute,r.completionDate.weekday,r.season," +
                "#C_MythicPlus.GetRunHistory(true,true,false)},':')"));

        Assert.Equal(
            "Tyrannical:321:12:1875:false:642:1875:12:4:2:9:Mage:63:8:321",
            session.Lua.Evaluate(
                "local scores,total=C_MythicPlus.GetSeasonBestAffixScoreInfoForMap(503); " +
                "local s=scores[1]; local intime,overtime=C_MythicPlus.GetSeasonBestForMap(503); " +
                "return table.concat({s.name,s.score,s.level,s.durationSec,tostring(s.overTime)," +
                "total,intime.durationSec,intime.level,intime.completionDate.weekday," +
                "#intime.affixIDs,intime.affixIDs[1],intime.members[1].name," +
                "intime.members[1].specID,intime.members[1].classID,intime.dungeonScore},':')"));

        Assert.Equal(
            "1875:12:4:2:9:2:Mage:63:8:321:18:2875:12:678:691:14",
            session.Lua.Evaluate(
                "local duration,level,date,affixes,people,score=" +
                "C_MythicPlus.GetWeeklyBestForMap(503); " +
                "local season,rating=C_MythicPlus.GetSeasonBestMythicRatingFromThisExpansion(); " +
                "local current,reward,nextReward,nextBest=C_MythicPlus.GetWeeklyChestRewardLevel(); " +
                "return table.concat({duration,level,date.weekday,#affixes,affixes[1]," +
                "#people,people[1].name,people[1].specID,people[1].classID,score," +
                "season,rating,current,reward,nextReward,nextBest},':')"));

        mythic.OwnedKeystoneLevel = null;
        mythic.SeasonBestRatingFromExpansion = null;
        Assert.Equal(
            "1:nil:0:0:0:0:0:2:nil",
            session.Lua.Evaluate(
                "return table.concat({" +
                "select('#',C_MythicPlus.GetEndOfRunGearSequenceLevel(1))," +
                "tostring(C_MythicPlus.GetEndOfRunGearSequenceLevel(1))," +
                "select('#',C_MythicPlus.GetOwnedKeystoneLevel())," +
                "select('#',C_MythicPlus.GetSeasonBestAffixScoreInfoForMap(999))," +
                "select('#',C_MythicPlus.GetSeasonBestMythicRatingFromThisExpansion())," +
                "select('#',C_MythicPlus.GetWeeklyBestForMap(999))," +
                "select('#',C_MythicPlus.GetLastWeeklyBestInformation())," +
                "select('#',C_MythicPlus.GetSeasonBestForMap(999))," +
                "tostring(select(1,C_MythicPlus.GetSeasonBestForMap(999)))},':')"));

        Assert.Equal(
            "false:false:false:false",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(pcall(C_MythicPlus.GetEndOfRunGearSequenceLevel))," +
                "tostring(pcall(C_MythicPlus.GetRewardLevelForDifficultyLevel))," +
                "tostring(pcall(C_MythicPlus.GetSeasonBestForMap))," +
                "tostring(pcall(C_MythicPlus.GetWeeklyBestForMap))},':')"));

        session.Lua.Evaluate(
            "C_MythicPlus.RequestCurrentAffixes(); " +
            "C_MythicPlus.RequestMapInfo(); C_MythicPlus.RequestRewards(); return ''");
        Assert.Equal(1, mythic.CurrentAffixRequestCount);
        Assert.Equal(1, mythic.MapInfoRequestCount);
        Assert.Equal(1, mythic.RewardsRequestCount);
    }

    [Fact]
    public void MajorFactionsUseNativeRecordsOptionalityAndArgumentContracts()
    {
        using var session = new EmulatorSession();
        var major = session.Lua.MajorFactions;
        major.RenownNpcFactionId = 999;
        major.Factions[2507] = new WowMajorFactionDataState(
            "Dragonscale Expedition",
            "Explore the Dragon Isles",
            [new WowRenownHighlightState("Climbing", null, 6)],
            2507,
            9,
            500,
            true,
            false,
            null,
            3,
            12,
            25,
            1400,
            2500,
            "dragonflight",
            123,
            456,
            new WowMajorFactionColorState("DRAGONSCALE", 0.1, 0.2, 0.3, 1),
            77,
            null);
        major.CurrentRenownLevels[2507] = 12;
        major.RenownInfo[2507] = new WowMajorFactionRenownInfoState(12, 1400, 2500);
        major.RenownLevels[2507] =
        [
            new WowMajorFactionRenownLevelState(2507, 12, false, true, false)
        ];
        major.RenownRewards[(2507, 12)] =
        [
            new WowMajorFactionRenownRewardState(
                88, 2, true, 190001, null, 1234, null, null, null, null,
                456789, "Reward", null, "Unlocked!", 3, true)
        ];
        major.MaximumRenownFactions.Add(2507);
        major.HiddenFromExpansionPageFactions.Add(2507);
        major.WeeklyCappedFactions.Add(2507);
        major.JourneyDisplayFactions.Add(2507);
        major.JourneyRewardTrackFactions.Add(2507);

        Assert.Equal(
            "12:1:2507:1:0:999:true:true:true:true:true",
            session.Lua.Evaluate(
                "local ids=C_MajorFactions.GetMajorFactionIDs(9); " +
                "return table.concat({C_MajorFactions.GetCurrentRenownLevel(2507)," +
                "#ids,ids[1],#C_MajorFactions.GetRenownLevels(2507)," +
                "#C_MajorFactions.GetMajorFactionIDs(8)," +
                "C_MajorFactions.GetRenownNPCFactionID()," +
                "tostring(C_MajorFactions.HasMaximumRenown(2507))," +
                "tostring(C_MajorFactions.IsMajorFactionHiddenFromExpansionPage(2507))," +
                "tostring(C_MajorFactions.IsWeeklyRenownCapped(2507))," +
                "tostring(C_MajorFactions.ShouldDisplayMajorFactionAsJourney(2507))," +
                "tostring(C_MajorFactions.ShouldUseJourneyRewardTrack(2507))},':')"));

        Assert.Equal(
            "Dragonscale Expedition:Explore the Dragon Isles:Climbing:nil:6:" +
            "2507:9:500:true:false:nil:3:12:25:1400:2500:dragonflight:123:456:" +
            "DRAGONSCALE:0.1:0.2:0.3:1:77:nil",
            session.Lua.Evaluate(
                "local d=C_MajorFactions.GetMajorFactionData(2507); " +
                "local r,g,b,a=d.factionFontColor.color:GetRGBA(); " +
                "return table.concat({d.name,d.description,d.highlights[1].title," +
                "tostring(d.highlights[1].description),d.highlights[1].level," +
                "d.factionID,d.expansionID,d.bountySetID,tostring(d.isUnlocked)," +
                "tostring(d.useJourneyUnlockToast),tostring(d.unlockDescription)," +
                "d.uiPriority,d.renownLevel,d.maxLevel,d.renownReputationEarned," +
                "d.renownLevelThreshold,d.textureKit,d.celebrationSoundKit," +
                "d.renownFanfareSoundKitID,d.factionFontColor.baseTag,r,g,b,a," +
                "d.renownTrackLevelEffectID,tostring(d.playerCompanionID)},':')"));

        Assert.Equal(
            "12:1400:2500:2507:12:false:true:false:88:2:true:190001:nil:" +
            "1234:456789:Reward:nil:Unlocked!:3:true",
            session.Lua.Evaluate(
                "local i=C_MajorFactions.GetMajorFactionRenownInfo(2507); " +
                "local l=C_MajorFactions.GetRenownLevels(2507)[1]; " +
                "local r=C_MajorFactions.GetRenownRewardsForLevel(2507,12)[1]; " +
                "return table.concat({i.renownLevel,i.renownReputationEarned," +
                "i.renownLevelThreshold,l.factionID,l.level,tostring(l.locked)," +
                "tostring(l.isMilestone),tostring(l.isCapstone),r.renownRewardID," +
                "r.uiOrder,tostring(r.isAccountUnlock),r.itemID,tostring(r.spellID)," +
                "r.mountID,r.icon,r.name,tostring(r.description),r.toastDescription," +
                "r.rewardType,tostring(r.isCollected)},':')"));

        Assert.Equal(
            "1:nil:1:nil:1:0:1:0",
            session.Lua.Evaluate(
                "return table.concat({" +
                "select('#',C_MajorFactions.GetMajorFactionData(1))," +
                "tostring(C_MajorFactions.GetMajorFactionData(1))," +
                "select('#',C_MajorFactions.GetMajorFactionRenownInfo(1))," +
                "tostring(C_MajorFactions.GetMajorFactionRenownInfo(1))," +
                "select('#',C_MajorFactions.GetMajorFactionIDs())," +
                "#C_MajorFactions.GetMajorFactionIDs(8)," +
                "select('#',C_MajorFactions.GetRenownRewardsForLevel(1,1))," +
                "#C_MajorFactions.GetRenownRewardsForLevel(1,1)},':')"));

        Assert.Equal(
            "false:false:false:false:false",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(pcall(C_MajorFactions.GetCurrentRenownLevel))," +
                "tostring(pcall(C_MajorFactions.GetMajorFactionData))," +
                "tostring(pcall(C_MajorFactions.GetRenownLevels))," +
                "tostring(pcall(C_MajorFactions.GetRenownRewardsForLevel,1))," +
                "tostring(pcall(C_MajorFactions.HasMaximumRenown))},':')"));
    }

