    [Fact]
    public void EditModeAuraProviderAndClientSessionFunctionsExposeTheirNativeLifecycle()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "false:true",
            session.Lua.Evaluate(
                "local states={}; local listener=CreateFrame('Frame'); " +
                "listener:RegisterEvent('AURA_DATA_PROVIDER_SWITCH'); " +
                "listener:RegisterEvent('UPDATE_GM_STATUS'); " +
                "listener:SetScript('OnEvent',function(_,event,value) " +
                "if event=='AURA_DATA_PROVIDER_SWITCH' then table.insert(states,tostring(value)) " +
                "else table.insert(states,tostring(value)) end end); " +
                "C_UnitAuras.SwitchAuraDataProvider(); C_UnitAuras.ResetAuraDataProvider(); " +
                "GetGMStatus(); Logout(); Quit(); return table.concat(states,':')"));
        Assert.Equal(1, session.Lua.GmTicket.GmStatusRequestCount);
        Assert.Equal("Quit", session.Lua.Client.SessionActionRequested);
    }

