    {
        using var session = new EmulatorSession();
        session.Lua.Evaluate(
            "mouseParent=CreateFrame('Frame',nil,UIParent); mouseParent:SetPoint('BOTTOMLEFT',100,100); " +
            "mouseParent:SetSize(100,100); mouseParent:EnableMouse(true); " +
            "mouseChild=CreateFrame('Button',nil,mouseParent); mouseChild:SetPoint('CENTER'); " +
            "mouseChild:SetSize(20,20); mouseTexture=mouseParent:CreateTexture(); " +
            "mouseTexture:SetAllPoints(mouseParent)");

        session.MouseMove(150, 150);
        Assert.Equal(
            "true:true:true:false",
            session.Lua.Evaluate(
                "return table.concat({tostring(mouseParent:IsMouseOver())," +
                "tostring(mouseChild:IsMouseOver()),tostring(mouseTexture:IsMouseOver())," +
                "tostring(mouseParent:IsMouseMotionFocus())},':')"));

