    [Fact]
    public void MouseMotionFocusUsesTheNativePropagatedFocusStack()
    {
        using var session = new EmulatorSession();
        session.Lua.Evaluate(
            "motionBottom=CreateFrame('Frame',nil,UIParent); " +
            "motionBottom:SetPoint('BOTTOMLEFT',100,100); motionBottom:SetSize(100,100); " +
            "motionBottom:EnableMouse(true); " +
            "motionTop=CreateFrame('Frame',nil,UIParent); " +
            "motionTop:SetPoint('BOTTOMLEFT',100,100); motionTop:SetSize(100,100); " +
            "motionTop:EnableMouse(true)");

        session.MouseMove(150, 150);
        Assert.Equal(
            "1:true:false:true:true",
            session.Lua.Evaluate(
                "local foci=GetMouseFoci(); return table.concat({#foci," +
                "tostring(foci[1]==motionTop),tostring(motionBottom:IsMouseMotionFocus())," +
                "tostring(motionTop.GetPropagateMouseMotion==nil)," +
                "tostring(motionTop.GetPropagateMouseClicks==nil)},':')"));

        session.Lua.Evaluate("motionTop:SetPropagateMouseMotion(true)");
        session.MouseMove(150, 150);
        Assert.Equal(
            "2:true:true:true:true",
            session.Lua.Evaluate(
                "local foci=GetMouseFoci(); return table.concat({#foci," +
                "tostring(foci[1]==motionTop),tostring(foci[2]==motionBottom)," +
                "tostring(motionTop:IsMouseMotionFocus())," +
                "tostring(motionBottom:IsMouseMotionFocus())},':')"));

        session.Lua.Evaluate("motionTop:SetPropagateMouseMotion(false)");
        session.MouseMove(150, 150);
        Assert.Equal(
            "false:true",
            session.Lua.Evaluate(
                "return tostring(motionBottom:IsMouseMotionFocus())..':'.." +
                "tostring(motionTop:IsMouseMotionFocus())"));
    }

