            "hoverRight:SetPoint('BOTTOMLEFT',150,100); hoverRight:SetSize(50,50); " +
            "hoverTrace=''; hoverTooltipOwner=nil; hoverTooltipShown=false; " +
            "local function enter(self) " +
            "hoverTrace=hoverTrace..'enter:'..self:GetName()..';'; " +
            "hoverTooltipOwner=self:GetName(); hoverTooltipShown=true end; " +
            "local function leave(self) " +
            "hoverTrace=hoverTrace..'leave:'..self:GetName()..';'; " +
            "hoverTooltipShown=false end; " +
