    [Fact]
    public void EditModeProfilesPersistInsideTheSelectedEmulatorProfile()
    {
        var root = Path.Combine(Path.GetTempPath(), $"wow-addon-lab-edit-mode-{Guid.NewGuid():N}");
        try
        {
            using (var session = new EmulatorSession(savedVariablesDirectory: root))
            {
                session.Lua.Evaluate(
                    "C_EditMode.SaveLayouts({activeLayout=3,layouts={" +
                    "{layoutName='Modern',layoutType=0,systems={}}," +
                    "{layoutName='Classic',layoutType=0,systems={}}," +
                    "{layoutName='Local',layoutType=1,systems={{system=7," +
                    "anchorInfo={point='CENTER',relativeTo='UIParent',relativePoint='CENTER'," +
                    "offsetX=42,offsetY=-17},settings={{setting=4,value=9}}," +
                    "isInDefaultPosition=false}}}}}); " +
                    "C_EditMode.SetAccountSetting(4,9)");
            }

            Assert.True(File.Exists(Path.Combine(root, "Client", "EditMode.json")));

            using var restored = new EmulatorSession(savedVariablesDirectory: root);
            Assert.Equal(
                "3:1:Local:1:42:-17:9:9",
                restored.Lua.Evaluate(
                    "local state=C_EditMode.GetLayouts(); local layout=state.layouts[1]; " +
                    "local system=layout.systems[1]; local account=C_EditMode.GetAccountSettings(); " +
                    "local value; for _,entry in ipairs(account) do " +
                    "if entry.setting==4 then value=entry.value end end; " +
                    "return table.concat({state.activeLayout,#state.layouts,layout.layoutName," +
                    "layout.layoutType,system.anchorInfo.offsetX,system.anchorInfo.offsetY," +
                    "system.settings[1].value,value},':')"));
        }
        finally
        {
            if (Directory.Exists(root))
                Directory.Delete(root, true);
        }
    }

