    [Fact]
    public void MultipleAddonsReceiveNameAndPersistentPrivateTable()
    {
        var root = Path.Combine(Path.GetTempPath(), $"wow-addon-lab-{Guid.NewGuid():N}");
        var first = CreateAddon(
            root,
            "Library",
            ["first.lua", "second.lua"],
            [
                "local name, private = ...; private.value = name",
                "local name, private = ...; addonArgumentResult = private.value .. ':' .. name"
            ]);
        var second = CreateAddon(
            root,
            "Consumer",
            ["main.lua"],
            ["local name = ...; secondAddonArgument = name"]);
        try
        {
            using var session = new EmulatorSession();
            session.Load([first, second]);

            Assert.Equal("Library:Library", session.Lua.Evaluate("addonArgumentResult"));
            Assert.Equal("Consumer", session.Lua.Evaluate("secondAddonArgument"));
            Assert.Equal(2, session.Manifests.Count);
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

    [Fact]
    public void SecureAddonsRetainTheirEnvironmentAfterOrdinaryGlobalCleanup()
    {
        var root = Path.Combine(Path.GetTempPath(), $"wow-addon-lab-{Guid.NewGuid():N}");
        var secureBootstrap = CreateAddon(
            root,
            "Blizzard_SecureBootstrap",
            ["main.lua"],
            [
                "local secureType=type(C_WowTokenSecure); " +
                "SwapToGlobalEnvironment(); secureTypeBeforeCleanup=secureType"
            ],
            "## UseSecureEnvironment: 1");
        var cleanup = CreateAddon(
            root,
            "Blizzard_EnvironmentCleanup",
            ["main.lua"],
            ["C_WowTokenSecure=nil"]);
        var secureConsumer = CreateAddon(
            root,
            "Blizzard_SecureConsumer",
            ["main.lua", "main.xml"],
            [
                "SecureEnvironmentMixin={}; " +
                "function SecureEnvironmentMixin:CaptureSecureType() " +
                "local secureType=type(C_WowTokenSecure); SwapToGlobalEnvironment(); " +
                "secureXmlTypeAfterCleanup=secureType end",
                "<Ui><Frame name=\"SecureEnvironmentTemplate\" virtual=\"true\" " +
                "mixin=\"SecureEnvironmentMixin\"><Scripts><OnLoad>" +
                "self:CaptureSecureType()" +
                "</OnLoad></Scripts></Frame></Ui>"
            ],
            "## UseSecureEnvironment: 1");
        var ordinaryConsumer = CreateAddon(
            root,
            "OrdinaryConsumer",
            ["main.lua"],
            ["local frame=CreateFrame('Frame',nil,nil,'SecureEnvironmentTemplate'); " +
             "secureTemplateMethodType=type(frame.CaptureSecureType)"]);
        try
        {
            using var session = new EmulatorSession();
            session.Load([secureBootstrap, cleanup, secureConsumer, ordinaryConsumer]);

            Assert.Equal(
                "table:table:function:nil",
                session.Lua.Evaluate(
                    "return secureTypeBeforeCleanup..':'..secureXmlTypeAfterCleanup..':'.." +
                    "secureTemplateMethodType..':'..type(C_WowTokenSecure)"));
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

