                "local missing=C_GameRules.GetCurrentGameModeRecordID(); " +
                "return table.concat({" +
                "missing,C_GameRules.GetNumDisplayedGameModes()," +
                "C_GameRules.GetDisplayedGameModeRecordIDAtIndex(1)," +
                "tostring(C_GameRules.DoesGameModeHavePromo(77))," +
                "C_GameRules.GetGameModePromoGlobalString(77)," +
                "C_GameRules.GetGameModeGlueScreenName()," +
                "info.logo,byID.logoHeight,info.logoVerticalOffset," +
                "info.logoShrunkenHeight,tostring(info.logoUsesDarkBackdrop)," +
                "info.characterCreateExtraHeight,info.characterCreateOuterBorder," +
