    [Fact]
    public void CursorGlobalsSeparateHardwareCursorFromTheCarriedPayload()
    {
        using var session = new EmulatorSession();
        session.Lua.Client.Money = 1_000;

        Assert.Equal(
            "false:function:function:function:0",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(C_ChatInfo.AreOutgoingAddonChatMessagesRestricted())," +
                "type(SetCursor),type(ResetCursor),type(C_Cursor.GetCursorItem)," +
                "select('#',C_Cursor.GetCursorItem())},':')"));

        session.Lua.Cursor.SetItem(
            WowItemLocation.Bag(2, 7),
            "item",
            19019,
            "item:19019");
        Assert.Equal(
            "2:7:true:item:19019:item:19019",
            session.Lua.Evaluate(
                "local location=C_Cursor.GetCursorItem(); " +
                "local kind,id,link=GetCursorInfo(); " +
                "return table.concat({location.bagID,location.slotIndex," +
                "tostring(CursorHasItem()),kind,id,link},':')"));
        session.Lua.Cursor.ClearPayload();

        Assert.Equal(
            "false:0:0",
            session.Lua.Evaluate(
                "local valid=pcall(PickupPlayerMoney,'bad'); PickupPlayerMoney(1001); " +
                "return table.concat({tostring(valid),GetCursorMoney()," +
                "select('#',GetCursorInfo())},':')"));

        Assert.Equal(
            "money:250:2:true:false:false:false",
            session.Lua.Evaluate(
                "PickupPlayerMoney(250); local kind,amount=GetCursorInfo(); " +
                "return table.concat({kind,amount,select('#',GetCursorInfo())," +
                "tostring(CursorHasMoney()),tostring(CursorHasItem())," +
                "tostring(CursorHasMacro()),tostring(CursorHasSpell())},':')"));

        Assert.Equal(
            "1:true:0:true",
            session.Lua.Evaluate(
                "local count=select('#',SetCursor(" +
                "'Interface\\\\CURSOR\\\\UI-Cursor-Move.blp')); " +
                "local result=SetCursor('Interface\\\\CURSOR\\\\UI-Cursor-Move.blp'); " +
                "local resetCount=select('#',ResetCursor()); " +
                "return table.concat({count,tostring(result),resetCount," +
                "tostring(CursorHasMoney())},':')"));
        Assert.Equal(250UL, session.Lua.Cursor.Money);
        Assert.Null(session.Ui.CursorAsset);

        var setResult = session.Lua.Evaluate(
            "return tostring(SetCursor('Interface\\\\CURSOR\\\\UI-Cursor-Move.blp'))");
        Assert.Equal("false", setResult);
        Assert.Equal("Interface\\CURSOR\\UI-Cursor-Move.blp", session.Ui.CursorAsset);

        Assert.Equal(
            "false:false:true",
            session.Lua.Evaluate(
                "return table.concat({tostring(SetCursorByMode(0))," +
                "tostring(SetCursorByMode(91)),tostring(SetCursorByMode(12))},':')"));
        Assert.Equal(12, session.Lua.Cursor.HardwareMode);
        Assert.Null(session.Ui.CursorAsset);

        session.Lua.Cursor.SetPayload(WowCursorPayloadKind.Macro, "macro", 7);
        Assert.Equal(
            "macro:7:true:false",
            session.Lua.Evaluate(
                "local kind,index=GetCursorInfo(); return table.concat({" +
                "kind,index,tostring(CursorHasMacro()),tostring(CursorHasMoney())},':')"));

        Assert.Equal(
            "0:false:0",
            session.Lua.Evaluate(
                "local count=select('#',ClearCursor()); return table.concat({" +
                "count,tostring(CursorHasMacro()),select('#',GetCursorInfo())},':')"));
    }

    [Fact]
    public void BootstrapAddonsRunBeforeUserAddonsAndRemainSeparatelyReported()
    {
        var root = Path.Combine(Path.GetTempPath(), $"wow-addon-lab-{Guid.NewGuid():N}");
        var bootstrap = CreateAddon(
            root,
            "Blizzard_TestBootstrap",
            ["main.lua"],
            ["bootstrapOrder = 'bootstrap'"]);
        var user = CreateAddon(
            root,
            "UserAddon",
            ["main.lua"],
            ["observedOrder = bootstrapOrder .. ':user'"]);
        try
        {
            using var session = new EmulatorSession();
            session.Load([user], bootstrapAddonPaths: [bootstrap]);

            Assert.Equal("bootstrap:user", session.Lua.Evaluate("observedOrder"));
            Assert.Equal("UserAddon", Assert.Single(session.Manifests).Name);
            Assert.Equal("Blizzard_TestBootstrap", Assert.Single(session.BootstrapManifests).Name);
            Assert.Null(session.LastError);
            Assert.Null(session.BootstrapLastError);
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

    [Fact]
    public void LoadAddOnLoadsAvailableDependenciesIntoTheLiveState()
    {
        var root = Path.Combine(Path.GetTempPath(), $"wow-addon-lab-{Guid.NewGuid():N}");
        var dependency = CreateAddon(
            root,
            "Blizzard_DemandDependency",
            ["main.lua"],
            ["local name, private = ...; demandOrder = 'dependency'; demandDependencyName = name; demandDependencyPrivate = private"]);
        var demand = CreateAddon(
            root,
            "Blizzard_DemandMain",
            ["main.lua"],
            ["local name, private = ...; demandOrder = demandOrder .. ':main'; demandMainName = name; demandMainPrivate = private"],
            "## Dependencies: Blizzard_DemandDependency\n## Title: Demand Main");
        var observer = CreateAddon(
            root,
            "ObserverAddon",
            ["main.lua"],
            [
                "demandEvents = {}; local frame=CreateFrame('Frame'); frame:RegisterEvent('ADDON_LOADED'); " +
                "frame:SetScript('OnEvent', function(_,_,name) table.insert(demandEvents,name) end)"
            ]);
        try
        {
            using var session = new EmulatorSession();
            session.Load([observer], availableAddonPaths: [dependency, demand]);

            Assert.Equal(
                "true:true:true:dependency:main:Blizzard_DemandDependency:" +
                "Blizzard_DemandMain:true:true:Demand Main:" +
                "ObserverAddon,Blizzard_DemandDependency,Blizzard_DemandMain",
                session.Lua.Evaluate(
                    "C_AddOns.EnableAddOn('Blizzard_DemandDependency'); " +
                    "C_AddOns.EnableAddOn('Blizzard_DemandMain'); " +
                    "local loaded=C_AddOns.LoadAddOn('Blizzard_DemandMain'); " +
                    "return table.concat({tostring(loaded)," +
                    "tostring(C_AddOns.IsAddOnLoaded('Blizzard_DemandDependency'))," +
                    "tostring(C_AddOns.IsAddOnLoaded('Blizzard_DemandMain'))," +
                    "string.match(demandOrder,'^([^:]+)'),string.match(demandOrder,':(.+)$')," +
                    "demandDependencyName,demandMainName," +
                    "tostring(type(demandDependencyPrivate)=='table')," +
                    "tostring(type(demandMainPrivate)=='table')," +
                    "C_AddOns.GetAddOnMetadata('Blizzard_DemandMain','Title')," +
                    "table.concat(demandEvents,',')},':')"));
            Assert.Equal(2, session.AvailableAddonManifests.Count);
            Assert.Empty(session.BootstrapManifests);
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

