    [Fact]
    public void BootstrapAndUserLoadFailuresRemainMachineReadableAndSeparate()
    {
        var root = Path.Combine(Path.GetTempPath(), $"wow-addon-lab-{Guid.NewGuid():N}");
        var bootstrap = CreateAddon(
            root,
            "Blizzard_FailingBootstrap",
            ["bootstrap.lua"],
            ["error('bootstrap failure')"]);
        var user = CreateAddon(
            root,
            "FailingUserAddon",
            ["user.lua"],
            ["error('user failure')"]);
        try
        {
            using var session = new EmulatorSession();
            session.Load([user], bootstrapAddonPaths: [bootstrap]);

            var failures = session.Lua.AddonLoadFailures;
            Assert.Collection(
                failures,
                failure =>
                {
                    Assert.Equal("Blizzard_FailingBootstrap", failure.AddonName);
                    Assert.Equal("bootstrap.lua", failure.File);
                    Assert.Equal("lua", failure.Phase);
                    Assert.Contains("bootstrap failure", failure.Message);
                },
                failure =>
                {
                    Assert.Equal("FailingUserAddon", failure.AddonName);
                    Assert.Equal("user.lua", failure.File);
                    Assert.Equal("lua", failure.Phase);
                    Assert.Contains("user failure", failure.Message);
                });
            Assert.Contains("Blizzard_FailingBootstrap", session.BootstrapLastError);
            Assert.Contains("FailingUserAddon", session.LastError);
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

