    [Theory]
    [InlineData(false, "account", "character")]
    [InlineData(true, "code", "code")]
    public void SavedVariablesRespectWowLoadOrderAndRemainSeparate(
        bool loadSavedFirst,
        string expectedAccount,
        string expectedCharacter)
    {
        var root = Path.Combine(Path.GetTempPath(), $"wow-addon-lab-{Guid.NewGuid():N}");
        var metadata =
            "## SavedVariables: AccountData\n" +
            "## SavedVariablesPerCharacter: CharacterData\n" +
            (loadSavedFirst ? "## LoadSavedVariablesFirst: 1" : "");
        var addon = CreateAddon(
            root,
            "SavedOrder",
            ["main.lua"],
            ["AccountData = 'code'; CharacterData = 'code'"],
            metadata);
        var savedRoot = Path.Combine(root, "emulator-data");
        Directory.CreateDirectory(Path.Combine(savedRoot, "Account"));
        Directory.CreateDirectory(Path.Combine(savedRoot, "Character"));
        File.WriteAllText(
            Path.Combine(savedRoot, "Account", "SavedOrder.lua"),
            "AccountData = 'account'");
        File.WriteAllText(
            Path.Combine(savedRoot, "Character", "SavedOrder.lua"),
            "CharacterData = 'character'");
        try
        {
            using var session = new EmulatorSession(savedVariablesDirectory: savedRoot);
            session.Load(addon, savedRoot);

            Assert.Equal(expectedAccount, session.Lua.Evaluate("AccountData"));
            Assert.Equal(expectedCharacter, session.Lua.Evaluate("CharacterData"));
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

