    [Fact]
    public void ButtonRegistrationMasksValidateAndClearLikeClient()
    {
        using var session = new EmulatorSession();
        session.Lua.Evaluate(
            "registrationTrace=''; " +
            "local b=CreateFrame('Button','RegistrationMaskButton',UIParent); " +
            "b:SetSize(100,50); b:SetPoint('CENTER'); " +
            "b:SetScript('OnMouseDown',function() registrationTrace=registrationTrace..'D' end); " +
            "b:SetScript('OnMouseUp',function() registrationTrace=registrationTrace..'U' end); " +
            "b:SetScript('OnClick',function() registrationTrace=registrationTrace..'C' end)");

        var button = session.Ui.Find("RegistrationMaskButton")!;
        Assert.Equal(new[] { "LeftButtonUp" }, button.ClickRegistrations);
        Assert.Equal(
            new[] { "AnyDown", "AnyUp" },
            button.MouseRegistrations.Order(StringComparer.Ordinal).ToArray());

        var center = session.Ui.ResolveBounds(button.Id).Center;
        session.MouseMove(center.X, center.Y);
        session.MouseButton("LeftButton", true);
        session.MouseButton("LeftButton", false);
        Assert.Equal("DUC", session.Lua.Evaluate("registrationTrace"));

        Assert.Equal(
            "false:false",
            session.Lua.Evaluate(
                "local clickOk=pcall(function() RegistrationMaskButton:RegisterForClicks('Bogus') end); " +
                "local mouseOk=pcall(function() RegistrationMaskButton:RegisterForMouse(7) end); " +
                "return tostring(clickOk)..':'..tostring(mouseOk)"));
        Assert.Equal(new[] { "LeftButtonUp" }, button.ClickRegistrations);
        Assert.Equal(
            new[] { "AnyDown", "AnyUp" },
            button.MouseRegistrations.Order(StringComparer.Ordinal).ToArray());

        session.Lua.Evaluate(
            "RegistrationMaskButton:RegisterForClicks('button31down','ANYUP'); " +
            "RegistrationMaskButton:RegisterForMouse()");
        Assert.Equal(
            new[] { "AnyUp", "Button31Down" },
            button.ClickRegistrations.Order(StringComparer.Ordinal).ToArray());
        Assert.Empty(button.MouseRegistrations);

        session.MouseButton("LeftButton", true);
        session.MouseButton("LeftButton", false);
        Assert.Equal("DUC", session.Lua.Evaluate("registrationTrace"));

        session.Lua.Evaluate(
            "RegistrationMaskButton:RegisterForMouse('LeftButtonDown','LeftButtonUp'); " +
            "RegistrationMaskButton:RegisterForClicks()");
        session.MouseButton("LeftButton", true);
        session.MouseButton("LeftButton", false);
        Assert.Equal("DUCDU", session.Lua.Evaluate("registrationTrace"));
    }

