    [Fact]
    public void ButtonStateUsesClientEnumAndLockControlsMouseTransitions()
    {
        using var session = new EmulatorSession();
        session.Lua.Evaluate(
            "local b = CreateFrame('Button', 'StatefulButton', UIParent); " +
            "b:SetSize(100, 50); b:SetPoint('CENTER'); " +
            "local normal = b:CreateTexture('StatefulNormal'); b:SetNormalTexture(normal); " +
            "local pushed = b:CreateTexture('StatefulPushed'); b:SetPushedTexture(pushed)");

        Assert.Equal("NORMAL", session.Lua.Evaluate("StatefulButton:GetButtonState()"));

        session.Lua.Evaluate("StatefulButton:SetButtonState('PUSHED', true)");
        var button = session.Ui.Find("StatefulButton")!;
        Assert.Equal(UiButtonState.Pushed, button.ButtonState);
        Assert.True(button.ButtonStateLocked);
        Assert.False(session.Ui.Find("StatefulNormal")!.Shown);
        Assert.True(session.Ui.Find("StatefulPushed")!.Shown);

        session.MouseMove(800, 450);
        session.MouseButton("LeftButton", true);
        session.MouseButton("LeftButton", false);
        Assert.Equal("PUSHED", session.Lua.Evaluate("StatefulButton:GetButtonState()"));

        session.Lua.Evaluate("StatefulButton:SetButtonState('NORMAL', false)");
        session.MouseButton("LeftButton", true);
        Assert.Equal("PUSHED", session.Lua.Evaluate("StatefulButton:GetButtonState()"));
        session.MouseButton("LeftButton", false);
        Assert.Equal("NORMAL", session.Lua.Evaluate("StatefulButton:GetButtonState()"));
        Assert.Equal("nil", session.Lua.Evaluate("tostring(UIParent.GetButtonState)"));
    }

    [Fact]
    public void ButtonStateRetainsPreviousTextureWhenRequestedStateHasNoTexture()
    {
        using var session = new EmulatorSession();
        session.Lua.Evaluate(
            "local b=CreateFrame('Button','FallbackTextureButton',UIParent); " +
            "local normal=b:CreateTexture('FallbackNormal'); normal:SetTexture(1); " +
            "b:SetNormalTexture(normal); " +
