    [Fact]
    public void ButtonTextureSettersReuseAssignedRegionsAndResolveRegisteredAtlasAssets()
    {
        using var session = new EmulatorSession();
        session.AtlasProvider = new TestAtlasProvider();
        session.Lua.Evaluate(
            "TextureButton=CreateFrame('Button','TextureButton',UIParent); " +
            "local b=TextureButton; " +
            "b:SetNormalTexture(b:CreateTexture('OriginalNormal')); " +
            "b:SetPushedTexture(b:CreateTexture('OriginalPushed')); " +
            "b:SetDisabledTexture(b:CreateTexture('OriginalDisabled')); " +
            "b:SetHighlightTexture(b:CreateTexture('OriginalHighlight'))");
        var objectCount = session.Ui.Objects.Count;

        Assert.Equal(
            "true:true:true:true:TestAtlas:77",
            session.Lua.Evaluate(
                "local b=TextureButton; " +
                "b:SetNormalTexture('TestAtlas'); b:SetNormalTexture('TestAtlas'); " +
                "b:SetPushedTexture('TestAtlas'); b:SetPushedTexture('TestAtlas'); " +
                "b:SetDisabledTexture('TestAtlas'); b:SetDisabledTexture('TestAtlas'); " +
                "b:SetHighlightTexture('TestAtlas'); b:SetHighlightTexture('TestAtlas'); " +
                "return table.concat({" +
                "tostring(b:GetNormalTexture()==OriginalNormal)," +
                "tostring(b:GetPushedTexture()==OriginalPushed)," +
                "tostring(b:GetDisabledTexture()==OriginalDisabled)," +
                "tostring(b:GetHighlightTexture()==OriginalHighlight)," +
                "tostring(b:GetNormalTexture():GetAtlas())," +
                "tostring(b:GetNormalTexture():GetTexture())},':')"));
        Assert.Equal(objectCount, session.Ui.Objects.Count);

        session.Lua.Evaluate(
            "TextureButton:ClearNormalTexture(); TextureButton:ClearPushedTexture(); " +
            "TextureButton:ClearDisabledTexture(); TextureButton:ClearHighlightTexture()");
        Assert.Equal(
            "true:true:true:true:nil:nil:nil:nil:ADD",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(TextureButton:GetNormalTexture()==OriginalNormal)," +
                "tostring(TextureButton:GetPushedTexture()==OriginalPushed)," +
                "tostring(TextureButton:GetDisabledTexture()==OriginalDisabled)," +
                "tostring(TextureButton:GetHighlightTexture()==OriginalHighlight)," +
                "tostring(TextureButton:GetNormalTexture():GetTexture())," +
                "tostring(TextureButton:GetPushedTexture():GetTexture())," +
                "tostring(TextureButton:GetDisabledTexture():GetTexture())," +
                "tostring(TextureButton:GetHighlightTexture():GetTexture())," +
                "TextureButton:GetHighlightTexture():GetBlendMode()},':')"));
        Assert.True(session.Ui.Find("OriginalNormal")!.Shown);
        Assert.False(session.Ui.Find("OriginalPushed")!.Shown);
        Assert.False(session.Ui.Find("OriginalDisabled")!.Shown);
        Assert.True(session.Ui.Find("OriginalHighlight")!.Shown);
    }

