                "ExternalNormal=UIParent:CreateTexture('ExternalNormal'); " +
                "ExternalNormal:SetTexture(123); " +
                "ExternalHighlight=UIParent:CreateTexture('ExternalHighlight'); " +
                "ExternalHighlight:SetTexture(456); " +
                "TextureOwnerButton:SetNormalTexture(ExternalNormal); " +
                "TextureOwnerButton:SetHighlightTexture(ExternalHighlight,'MOD'); " +
                "return table.concat({" +
                "tostring(ExternalNormal:GetParent()==TextureOwnerButton)," +
                "tostring(ExternalHighlight:GetParent()==TextureOwnerButton)," +
                "ExternalNormal:GetTexture()," +
                "ExternalHighlight:GetBlendMode()},':')"));

        var button = session.Ui.Find("TextureOwnerButton")!;
        var normal = session.Ui.Find("ExternalNormal")!;
        var highlight = session.Ui.Find("ExternalHighlight")!;
        Assert.Equal(button.Id, normal.ParentId);
        Assert.Equal(button.Id, normal.AllPointsTargetId);
        Assert.Equal(button.Id, highlight.ParentId);
        Assert.Equal(button.Id, highlight.AllPointsTargetId);

        Assert.Equal(
            "true:true:nil:nil:ADD",
            session.Lua.Evaluate(
                "TextureOwnerButton:ClearNormalTexture(); " +
                "TextureOwnerButton:ClearHighlightTexture(); " +
                "return table.concat({" +
                "tostring(TextureOwnerButton:GetNormalTexture()==ExternalNormal)," +
                "tostring(TextureOwnerButton:GetHighlightTexture()==ExternalHighlight)," +
                "tostring(ExternalNormal:GetTexture())," +
                "tostring(ExternalHighlight:GetTexture())," +
                "ExternalHighlight:GetBlendMode()},':')"));

        Assert.Equal(
            "true:nil:true:TestAtlas:BLEND",
            session.Lua.Evaluate(
                "TextureOwnerButton:SetNormalTexture(999); " +
                "TextureOwnerButton:SetNormalTexture(nil); " +
                "TextureOwnerButton:SetHighlightAtlas('TestAtlas','BLEND'); " +
                "return table.concat({" +
                "tostring(TextureOwnerButton:GetNormalTexture()==ExternalNormal)," +
                "tostring(ExternalNormal:GetTexture())," +
                "tostring(TextureOwnerButton:GetHighlightTexture()==ExternalHighlight)," +
                "ExternalHighlight:GetAtlas()," +
                "ExternalHighlight:GetBlendMode()},':')"));

        Assert.Equal(
            "true:true:true:nil",
            session.Lua.Evaluate(
                "ReplacementNormal=UIParent:CreateTexture('ReplacementNormal'); " +
                "TextureOwnerButton:SetNormalTexture(ReplacementNormal); " +
                "TextureOwnerButton:ClearNormalTexture(); " +
                "return table.concat({" +
                "tostring(TextureOwnerButton:GetNormalTexture()==ReplacementNormal)," +
                "tostring(ReplacementNormal:GetParent()==TextureOwnerButton)," +
                "tostring(ExternalNormal:GetParent()==TextureOwnerButton)," +
                "tostring(ReplacementNormal:GetTexture())},':')"));
        Assert.False(normal.Shown);

        Assert.Equal(
            "false:false:false:false",
            session.Lua.Evaluate(
                "local frame=CreateFrame('Frame',nil,UIParent); " +
                "return table.concat({" +
                "tostring(pcall(function() TextureOwnerButton:SetNormalTexture() end))," +
                "tostring(pcall(function() TextureOwnerButton:SetNormalTexture(frame) end))," +
                "tostring(pcall(function() TextureOwnerButton:SetNormalAtlas(frame) end))," +
                "tostring(pcall(function() TextureOwnerButton:SetHighlightTexture(nil,'BOGUS') end))" +
                "},':')"));
    }

    [Fact]
    public void ButtonFontStatesMotionAndNativeGettersFollowClient()
    {
        using var session = new EmulatorSession();
        session.Lua.Evaluate(
            "ButtonNormalFont=CreateFont('ButtonNormalFont'); " +
            "ButtonNormalFont:SetFont('Fonts\\\\FRIZQT__.TTF',10); " +
            "ButtonHighlightFont=CreateFont('ButtonHighlightFont'); " +
            "ButtonHighlightFont:SetFont('Fonts\\\\FRIZQT__.TTF',20); " +
            "ButtonDisabledFont=CreateFont('ButtonDisabledFont'); " +
            "ButtonDisabledFont:SetFont('Fonts\\\\FRIZQT__.TTF',30); " +
            "ButtonAudit=CreateFrame('Button','ButtonAudit',UIParent); " +
            "ButtonAudit:SetSize(160,60); ButtonAudit:SetPoint('CENTER'); " +
            "ButtonAudit:EnableMouse(true); " +
            "ButtonAudit:SetNormalFontObject('ButtonNormalFont'); " +
            "ButtonAudit:SetHighlightFontObject(ButtonHighlightFont); " +
            "ButtonAudit:SetDisabledFontObject(ButtonDisabledFont); " +
            "ButtonAudit:SetText('State'); " +
            "buttonMotionTrace=''; " +
            "ButtonAudit:SetScript('OnEnter',function() buttonMotionTrace=buttonMotionTrace..'enter' end); " +
            "ButtonAudit:SetScript('OnLeave',function() buttonMotionTrace=buttonMotionTrace..'leave' end)");

        var button = session.Ui.Find("ButtonAudit")!;
        var fontString = session.Ui.Find(button.ButtonFontStringId!.Value)!;
        Assert.Equal(10, fontString.Font!.FontSize);
        Assert.Equal(
            "State:false:0:0:true:true:true",
            session.Lua.Evaluate(
                "local x,y=ButtonAudit:GetPushedTextOffset(); " +
                "return table.concat({" +
                "ButtonAudit:GetText()," +
                "tostring(ButtonAudit:GetMotionScriptsWhileDisabled())," +
                "x,y," +
                "tostring(ButtonAudit:GetTextHeight()>0)," +
                "tostring(ButtonAudit:GetNormalFontObject()==ButtonNormalFont)," +
                "tostring(ButtonAudit:GetDisabledFontObject()==ButtonDisabledFont)" +
                "},':')"));

        session.MouseMove(800, 450);
        Assert.Equal(20, fontString.Font.FontSize);
        session.MouseMove(1200, 700);
        Assert.Equal(10, fontString.Font.FontSize);

        session.Lua.Evaluate("ButtonAudit:LockHighlight()");
        Assert.Equal(20, fontString.Font.FontSize);
        session.Lua.Evaluate(
            "ButtonAudit:UnlockHighlight(); ButtonAudit:Disable(); buttonMotionTrace=''");
        Assert.Equal(30, fontString.Font.FontSize);

        session.MouseMove(800, 450);
        Assert.Equal(string.Empty, session.Lua.Evaluate("buttonMotionTrace"));
        session.Lua.Evaluate("ButtonAudit:SetMotionScriptsWhileDisabled(true)");
        session.MouseMove(801, 450);
        Assert.Equal("enter", session.Lua.Evaluate("buttonMotionTrace"));
        Assert.Equal(30, fontString.Font.FontSize);

        Assert.Equal(
            "false:false:false:true:true",
            session.Lua.Evaluate(
                "ButtonAudit:Enable(); ButtonAudit:SetEnabled(); " +
                "local old=ButtonAudit:GetNormalFontObject(); " +
                "return table.concat({" +
                "tostring(ButtonAudit:IsEnabled())," +
                "tostring(pcall(ButtonAudit.SetMotionScriptsWhileDisabled,ButtonAudit))," +
                "tostring(pcall(ButtonAudit.SetMotionScriptsWhileDisabled,ButtonAudit,nil))," +
                "tostring(not pcall(ButtonAudit.SetNormalFontObject,ButtonAudit,nil))," +
                "tostring(ButtonAudit:GetNormalFontObject()==old)" +
                "},':')"));
    }

