    [Fact]
    public void RegionPointOffsetsTranslateAnchorsWithoutReplacingThem()
    {
        using var session = new EmulatorSession();

        session.Lua.Evaluate(
            "OffsetTexture=UIParent:CreateTexture('OffsetTexture'); local texture=OffsetTexture; " +
            "texture:SetSize(10, 12); " +
            "texture:SetPoint('BOTTOMLEFT', UIParent, 'BOTTOMLEFT', 20, 30); " +
            "texture:SetPointsOffset(5, -2)");

        var texture = session.Ui.Find("OffsetTexture")!;
        var translated = session.Ui.ResolveBounds(texture.Id);
        Assert.Equal(5, translated.Left);
        Assert.Equal(-2, translated.Bottom);
        Assert.Single(texture.Anchors);
        Assert.Equal(5, texture.Anchors[0].X);
        Assert.Equal(-2, texture.Anchors[0].Y);

        session.Lua.Evaluate("OffsetTexture:AdjustPointsOffset(3, 4)");
        Assert.Equal(8, texture.Anchors[0].X);
        Assert.Equal(2, texture.Anchors[0].Y);
        Assert.Equal(8, session.Ui.ResolveBounds(texture.Id).Left);

        session.Lua.Evaluate("OffsetTexture:ClearPointsOffset()");
        Assert.Single(texture.Anchors);
        Assert.Equal(0, texture.Anchors[0].X);
        Assert.Equal(0, texture.Anchors[0].Y);
        Assert.Equal(0, session.Ui.ResolveBounds(texture.Id).Left);
        Assert.Equal(0, session.Ui.ResolveBounds(texture.Id).Bottom);

        Assert.Equal(
            "false:false:false",
            session.Lua.Evaluate(
                "OffsetTexture:SetPointsOffset('6.5', '7.25'); " +
                "local setMissingOk = pcall(function() OffsetTexture:SetPointsOffset(2) end); " +
                "local setInvalidOk = pcall(function() OffsetTexture:SetPointsOffset({}, 3) end); " +
                "local adjustMissingOk = pcall(function() OffsetTexture:AdjustPointsOffset() end); " +
                "return table.concat({tostring(setMissingOk),tostring(setInvalidOk)," +
                "tostring(adjustMissingOk)}, ':')"));
        Assert.Equal(6.5f, texture.Anchors[0].X);
        Assert.Equal(7.25f, texture.Anchors[0].Y);
        Assert.Equal(6.5f, session.Ui.ResolveBounds(texture.Id).Left);
        Assert.Equal(7.25f, session.Ui.ResolveBounds(texture.Id).Bottom);
    }

