            session.Lua.Evaluate(
                "local frame=CreateFrame('Frame','DesaturationRoot',UIParent); " +
                "local texture=frame:CreateTexture('DesaturatedTexture'); " +
                "local nested=CreateFrame('Frame',nil,frame); " +
                "local nestedTexture=nested:CreateTexture('NestedDesaturatedTexture'); " +
                "frame:DesaturateHierarchy(0.35); " +
                "local text=frame:CreateFontString('TruncatedText'); " +
                "text:SetFont('Fonts\\\\FRIZQT__.TTF',12); text:SetSize(20,20); " +
                "text:SetText('This text is too wide'); " +
                "local before=text:IsTruncated(); text:SetWidth(500); " +
                "return tostring(before)..':'..tostring(text:IsTruncated())"));

        Assert.Equal(0.35f, session.Ui.Find("DesaturatedTexture")!.Texture!.Desaturation);
        Assert.Equal(0.35f, session.Ui.Find("NestedDesaturatedTexture")!.Texture!.Desaturation);

