    [Fact]
    public void StatusBarBindingsFollowNativeFillTextureAndRangeContracts()
    {
        using var session = new EmulatorSession();

        var result = session.Lua.Evaluate(
            "(function() local b=CreateFrame('StatusBar','VerifiedStatusBar',UIParent); " +
            "local values=0; local ranges=0; " +
            "b:SetScript('OnValueChanged',function() values=values+1 end); " +
            "b:SetScript('OnMinMaxChanged',function() ranges=ranges+1 end); " +
            "local min0,max0=b:GetMinMaxValues(); local value0=b:GetValue(); " +
            "b:SetStatusBarColor(0.2,0.3,0.4,0.5); " +
            "b:SetStatusBarDesaturation(0.75); b:SetRotatesTexture(true); " +
            "local nilSuccess=b:SetStatusBarTexture(nil); " +
            "local r0,g0,b0,a0=b:GetStatusBarColor(); " +
            "local beforeRotate=b:GetRotatesTexture(); b:SetRotatesTexture(true); " +
            "b:SetStatusBarColor(0.2,0.3,0.4,0.5); b:SetStatusBarDesaturation(0.75); " +
            "local r,g,blue,a=b:GetStatusBarColor(); " +
            "b:SetStatusBarDesaturated(); local cleared=b:GetStatusBarDesaturation(); " +
            "b:SetMinMaxValues(10,5); local min1,max1=b:GetMinMaxValues(); " +
            "local uninitialized=b:GetValue(); b:SetValue(5); b:SetValue(5); " +
            "b:SetFillStyle(2); local reverse0=b:GetReverseFill(); " +
            "b:SetReverseFill(true); local style=b:GetFillStyle(); " +
            "return table.concat({min0,max0,value0,tostring(nilSuccess)," +
            "tostring(b:GetStatusBarTexture()~=nil),r0,g0,b0,a0,tostring(beforeRotate)," +
            "tostring(b:GetRotatesTexture()),string.format('%.6f',r)," +
            "string.format('%.6f',g),string.format('%.6f',blue),string.format('%.6f',a)," +
            "cleared,min1,max1,uninitialized,values,ranges,tostring(reverse0),style},':') end)()");

        Assert.Equal(
            "0:0:0:false:true:1:1:1:1:false:true:" +
            "0.200000:0.301961:0.400000:0.501961:0:5:5:5:1:1:false:3",
            result);
    }

