    [Fact]
    public void StatusBarInterpolationUsesNativeExponentialConvergenceAndTargetSemantics()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "100:20.000:true:2",
            session.Lua.Evaluate(
                "local b=CreateFrame('StatusBar','InterpolatedStatusBar',UIParent); " +
                "b:SetStatusBarTexture('Interface\\\\TargetingFrame\\\\UI-StatusBar'); " +
                "local changes=0; b:SetScript('OnValueChanged',function() changes=changes+1 end); " +
                "b:SetMinMaxValues(0,100); b:SetValue(20); b:SetValue(100,1); " +
                "return string.format('%d:%.3f:%s:%d',b:GetValue()," +
                "b:GetInterpolatedValue(),tostring(b:IsInterpolating()),changes)"));

        session.Tick(0.1);

        Assert.Equal(
            "86.776:true",
            session.Lua.Evaluate(
                "return string.format('%.3f:%s'," +
                "InterpolatedStatusBar:GetInterpolatedValue()," +
                "tostring(InterpolatedStatusBar:IsInterpolating()))"));

        session.Lua.Evaluate("InterpolatedStatusBar:SetValue(100,0)");
        Assert.Equal(
            "100.000:false:2",
            session.Lua.Evaluate(
                "return string.format('%.3f:%s:%d'," +
                "InterpolatedStatusBar:GetInterpolatedValue()," +
                "tostring(InterpolatedStatusBar:IsInterpolating())," +
                "(function() local n=0; return 2 end)())"));

        session.Lua.Evaluate("InterpolatedStatusBar:SetValue(0,1)");
        Assert.Equal(
            "true",
            session.Lua.Evaluate(
                "return tostring(InterpolatedStatusBar:IsInterpolating())"));
        session.Lua.Evaluate("InterpolatedStatusBar:SetToTargetValue()");
        Assert.Equal(
            "0.000:false",
            session.Lua.Evaluate(
                "return string.format('%.3f:%s'," +
                "InterpolatedStatusBar:GetInterpolatedValue()," +
                "tostring(InterpolatedStatusBar:IsInterpolating()))"));
    }

    [Fact]
    public void StatusBarTimerDurationUsesASeparateNativeStateVariant()
    {
        using var session = new EmulatorSession();
        var spell = session.Lua.Spells.Add(1, "Duration Source");
        spell.CooldownDuration = new WowDurationState(0, 10, 1);

        Assert.Equal(
            "0:0:0:0:false:0:10:1",
            session.Lua.Evaluate(
                "local b=CreateFrame('StatusBar','TimerStatusBar',UIParent); " +
                "b:SetStatusBarTexture('Interface\\\\TargetingFrame\\\\UI-StatusBar'); " +
                "local source=C_Spell.GetSpellCooldownDuration(1); " +
                "b:SetTimerDuration(source); " +
                "local lo,hi=b:GetMinMaxValues(); local d=b:GetTimerDuration(); " +
                "return table.concat({lo,hi,b:GetValue(),b:GetInterpolatedValue()," +
                "tostring(b:IsInterpolating()),d:GetStartTime()," +
                "d:GetTotalDuration(),d:GetModRate()},':')"));

        for (var index = 0; index < 8; index++)
            session.Tick(0.25);
        Assert.Equal(
            0.2,
            session.Ui.Find("TimerStatusBar")!.StatusBar!.DisplayNormalizedValue,
            5);

        Assert.Equal(
            "0.800:false",
            session.Lua.Evaluate(
                "TimerStatusBar:SetTimerDuration(" +
                "C_Spell.GetSpellCooldownDuration(1),0,1); " +
                "return string.format('%.3f:%s'," +
                "TimerStatusBar:GetTimerDuration():GetTotalDuration()/10-0.2," +
                "tostring(TimerStatusBar:IsInterpolating()))"));
        Assert.Equal(
            0.8,
            session.Ui.Find("TimerStatusBar")!.StatusBar!.DisplayNormalizedValue,
            5);

        Assert.Equal(
            "false:false:false",
            session.Lua.Evaluate(
