    [Fact]
    public void XmlSymbolicColorsResolveFromTheClientDatabaseBeforeLuaProjection()
    {
        var root = Path.Combine(Path.GetTempPath(), $"xml-global-color-{Guid.NewGuid():N}");
        var addon = CreateAddon(
            root,
            "XmlGlobalColor",
            ["ui.xml"],
            [
                """
                <Ui xmlns="http://www.blizzard.com/wow/ui/">
                  <Font name="DatabaseColoredFont" virtual="true">
                    <Color color="NORMAL_FONT_COLOR"/>
                  </Font>
                </Ui>
                """
            ]);

        try
        {
            using var session = new EmulatorSession();
            session.GlobalColorProvider = new TestGlobalColorProvider();
            session.Load(addon);

            var font = session.Ui.Find("DatabaseColoredFont")!.Font!;
            Assert.Equal(new Vector4(1, .824f, 0, 1), font.Color);
            Assert.Equal(
                "nil",
                session.Lua.Evaluate("return type(NORMAL_FONT_COLOR)"));
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

