    [Fact]
    public void GameTooltipAnchorAppendCopyAndFadeUseRecoveredNativeState()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "ANCHOR_TOPRIGHT:base plus:right:false:false",
            session.Lua.Evaluate(
                "(function() local owner=CreateFrame('Frame','AnchorOwner',UIParent); " +
                "GameTooltip:SetOwner(owner,'ANCHOR_LEFT'); " +
                "GameTooltip:SetAnchorType('ANCHOR_TOPRIGHT',4,5); " +
                "GameTooltip:AddDoubleLine('base','right'); " +
                "GameTooltip:AppendText(' plus'); GameTooltip:CopyTooltip(); " +
                "GameTooltip:Show(); GameTooltip:FadeOut(); " +
                "return table.concat({GameTooltip:GetAnchorType()," +
                "GameTooltip:GetLeftLine(1):GetText()," +
                "GameTooltip:GetRightLine(1):GetText()," +
                "tostring(pcall(GameTooltip.SetAnchorType,GameTooltip,'BAD'))," +
                "tostring(pcall(GameTooltip.SetOwner,GameTooltip,GameTooltip))},':') end)()"));

        Assert.Equal("base plus\t\t\t\tright", session.Lua.LastCopiedTooltipText);
        session.Tick(0.25);
        Assert.True(session.Ui.Find("GameTooltip")!.Shown);
        for (var index = 0; index < 7; index++)
            session.Tick(0.25);
        Assert.False(session.Ui.Find("GameTooltip")!.Shown);
    }

    [Fact]
    public void GameTooltipTextureMethodsUseTheNativeThirtySlotPoolAndInfoDefaults()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "false:false:false",
            session.Lua.Evaluate(
                "(function() GameTooltip:SetText('row'); " +
                "GameTooltip:AddTexture(12345,{width=16,height=18,verticalOffset=2," +
                "margin={left=1,right=3,top=4,bottom=5},anchor=1,region=0," +
                "texCoords={left=.1,right=.9,top=.2,bottom=.8}," +
                "vertexColor={r=.2,g=.3,b=.4,a=.5},desaturation=.75}); " +
                "GameTooltip:AddAtlas('missing-atlas',0,1,0,1); " +
                "return table.concat({" +
                "tostring(pcall(GameTooltip.AddTexture,GameTooltip))," +
                "tostring(pcall(GameTooltip.AddTexture,GameTooltip,1,0,1))," +
                "tostring(pcall(GameTooltip.AddAtlas,GameTooltip))},':') end)()"));

        var tooltip = session.Ui.Find("GameTooltip")!.Tooltip!;
        Assert.Equal(2, tooltip.Textures.Count);
        var inserted = tooltip.Textures[0];
        Assert.Equal(16, inserted.Width);
        Assert.Equal(18, inserted.Height);
        Assert.Equal(2, inserted.VerticalOffset);
        Assert.Equal(new UiInsets(1, 3, 4, 5), inserted.Margin);
        Assert.Equal(1, inserted.Anchor);
        Assert.Equal(0, inserted.RelativeRegion);
        var texture = session.Ui.Find(inserted.TextureId)!;
        Assert.Equal((uint)12345, texture.Texture!.FileDataId);
        Assert.Equal(new Vector2(.1f, .2f), texture.Texture.LocalUv[0]);
        Assert.Equal(new Vector2(.9f, .8f), texture.Texture.LocalUv[3]);
        Assert.Equal(.75f, texture.Texture.Desaturation);
        Assert.True(texture.Shown);

        session.Lua.Evaluate("GameTooltip:ClearLines()");
        Assert.Empty(tooltip.Textures);
        Assert.False(texture.Shown);
    }

