            session.Lua.Evaluate(
                "local owner=CreateFrame('Frame','AnimationTargetOwner',UIParent); " +
                "local child=CreateFrame('Frame',nil,owner); child:SetParentKey('Glow'); " +
                "local named=CreateFrame('Frame','NamedAnimationTarget',UIParent); " +
                "local group=owner:CreateAnimationGroup(); " +
                "local alpha=group:CreateAnimation('Alpha'); " +
                "local initial=alpha:IsStopped() and alpha:GetRegionParent()==owner and " +
                "alpha:GetTarget()==owner; " +
                "local childKey=alpha:SetChildKey('Glow') and alpha:GetTarget()==child; " +
                "local missingChild=alpha:SetChildKey('Missing') and alpha:GetTarget()==owner; " +
                "local targetKey=alpha:SetTargetKey('$parent.$parent.Glow') and " +
                "alpha:GetTarget()==child; " +
                "local missingTargetKey=alpha:SetTargetKey('Missing') and alpha:GetTarget()==nil; " +
                "local direct=alpha:SetTarget(child) and alpha:GetTarget()==child; " +
                "local namedTarget=alpha:SetTargetName('NamedAnimationTarget') and " +
                "alpha:GetTarget()==named; " +
                "local invalidDirect=not alpha:SetTarget(group) and alpha:GetTarget()==named; " +
                "local vertex=group:CreateAnimation('VertexColor'); " +
                "local invalidAnimation=not alpha:SetTarget(vertex) and alpha:GetTarget()==named; " +
                "local parent=alpha:SetTargetParent() and alpha:GetTarget()==owner; " +
                "alpha:SetStartDelay(1); alpha:SetDuration(1); alpha:SetEndDelay(1); " +
                "local delaying=alpha:IsDelaying(); alpha:SetStartDelay(0); " +
                "local activeDelay=alpha:IsDelaying(); " +
                "local missingChildArg=pcall(function() alpha:SetChildKey() end); " +
                "local missingTarget=pcall(function() alpha:SetTarget() end); " +
                "local missingKey=pcall(function() alpha:SetTargetKey() end); " +
                "local missingName=pcall(function() alpha:SetTargetName() end); " +
                "return table.concat({tostring(initial),tostring(childKey)," +
                "tostring(missingChild),tostring(targetKey),tostring(missingTargetKey)," +
                "tostring(direct),tostring(namedTarget),tostring(invalidDirect)," +
                "tostring(invalidAnimation)," +
                "tostring(parent),tostring(delaying),tostring(activeDelay)," +
                "tostring(missingChildArg),tostring(missingTarget)," +
                "tostring(missingKey),tostring(missingName)},':')"));
    }

