    [Fact]
    public void DerivedAnimationProgressAppliesNativeTransformAndUvFormulas()
    {
        using var session = new EmulatorSession(1000, 700);

        session.Lua.Evaluate(
            "local owner=CreateFrame('Frame','AnimationTransformOwner',UIParent); " +
            "owner:SetSize(100,50); owner:SetPoint('CENTER'); " +
            "AnimationTransformGroup=owner:CreateAnimationGroup('AnimationTransformGroup'); " +
            "local group=AnimationTransformGroup; " +
            "local alpha=group:CreateAnimation('Alpha'); alpha:SetDuration(100); " +
            "alpha:SetFromAlpha(0); alpha:SetToAlpha(1); " +
            "local translation=group:CreateAnimation('Translation'); " +
            "translation:SetDuration(100); translation:SetOffset(20,10); " +
            "local scale=group:CreateAnimation('Scale'); scale:SetDuration(100); " +
            "scale:SetScale(2,3); " +
            "local rotation=group:CreateAnimation('Rotation'); rotation:SetDuration(100); " +
            "rotation:SetDegrees(90); " +
            "local texture=owner:CreateTexture('AnimationUvTarget'); texture:SetAllPoints(owner); " +
            "AnimationUvGroup=texture:CreateAnimationGroup('AnimationUvGroup'); " +
            "local uvGroup=AnimationUvGroup; " +
            "local uv=uvGroup:CreateAnimation('TextureCoord'); uv:SetDuration(100); " +
            "uv:SetOffset(.5,.25)");

        var owner = session.Ui.Find("AnimationTransformOwner")!;
        var before = session.Ui.ResolveBounds(owner.Id);
        session.Lua.Evaluate(
            "AnimationTransformGroup:Play(false,50); AnimationUvGroup:Play(false,50)");
        var after = session.Ui.ResolveBounds(owner.Id);
        var texture = session.Ui.Find("AnimationUvTarget")!.Texture!;

        Assert.Equal(150, after.Width, 3);
        Assert.Equal(100, after.Height, 3);
        Assert.Equal(before.Left - 15, after.Left, 3);
        Assert.Equal(before.Bottom - 20, after.Bottom, 3);
        Assert.Equal(127 / 255f, owner.Alpha, 6);
        Assert.Equal(MathF.PI / 4, owner.AnimationRotation, 6);
        Assert.Equal(new Vector2(.25f, .125f), texture.LocalUv[0]);
        Assert.Equal(texture.LocalUv[0], texture.Uv[0]);
    }

