    [Fact]
    public void LineAnimationsUseTheNativeLineQuadAdapters()
    {
        using var session = new EmulatorSession();
        session.Lua.Evaluate(
            "local parent=CreateFrame('Frame','AnimatedLineParent',UIParent); " +
            "parent:SetSize(16,16); parent:SetPoint('CENTER'); " +
            "local line=parent:CreateLine('AnimatedLine','OVERLAY'); " +
            "line:SetThickness(2); " +
            "line:SetStartPoint('LEFT',parent,'LEFT',2,0); " +
            "line:SetEndPoint('RIGHT',parent,'RIGHT',-2,0); " +
            "local group=line:CreateAnimationGroup(); " +
            "local translation=group:CreateAnimation('LineTranslation'); " +
            "translation:SetOffset(4,6); translation:SetDuration(100); " +
            "local scale=group:CreateAnimation('LineScale'); " +
            "scale:SetScale(2,3); scale:SetDuration(100); " +
            "group:Play(false,50)");

        var line = session.Ui.Find("AnimatedLine")!;
        Assert.Equal(Vector2.Zero, line.AnimationOffset);
        Assert.Equal(Vector2.One, line.AnimationScale);
        Assert.Equal(new Vector2(2, 3), line.LineAnimationOffset);
        Assert.Equal(new Vector2(1.5f, 2), line.LineAnimationScale);

        var quad = session.Ui.ResolveLineQuad(line);
        var start = (quad[0] + quad[1]) * .5f;
        var end = (quad[2] + quad[3]) * .5f;
        Assert.Equal(24, Vector2.Distance(start, end), 3);
        Assert.Equal(4, Vector2.Distance(quad[0], quad[1]), 3);
        Assert.Equal(802, (start.X + end.X) * .5f, 3);
        Assert.Equal(447, (start.Y + end.Y) * .5f, 3);
    }

