            "function:NONE:-1:2:true:true:SMOOTH:0:7:1:0:1:7:nil:nil:false:false:false",
            session.Lua.Evaluate(
                "local owner=CreateFrame('Frame',nil,UIParent); " +
                "local group=owner:CreateAnimationGroup(); " +
                "local path=group:CreateAnimation('Path'); " +
                "local createType=type(path.CreateControlPoint); " +
                "local initialCurve=path:GetCurveType(); " +
                "local initialMax=path:GetMaxControlPointOrder(); " +
                "local first=path:CreateControlPoint('FirstPathPoint',nil,2); " +
                "local second=path:CreateControlPoint('SecondPathPoint',nil,5); " +
                "first:SetOffset(10,20); second:SetOffset(30,40); " +
                "local a,b=path:GetControlPoints(); " +
                "local count=select('#',path:GetControlPoints()); " +
                "path:SetCurveType('smooth'); first:SetOrder(-5); second:SetOrder(500); " +
                "local path2=group:CreateAnimation('Path'); second:SetParent(path2,7); " +
                "local oldCount=select('#',path:GetControlPoints()); " +
                "local newCount=select('#',path2:GetControlPoints()); " +
                "local missingCurve=pcall(function() path:SetCurveType() end); " +
                "local badCurve=pcall(function() path:SetCurveType('BEZIER') end); " +
                "local missingOffset=pcall(function() first:SetOffset() end); " +
                "return table.concat({createType,initialCurve,initialMax,count," +
                "tostring(a==first),tostring(b==second),path:GetCurveType()," +
                "first:GetOrder(),second:GetOrder(),oldCount,path:GetMaxControlPointOrder()," +
                "newCount,path2:GetMaxControlPointOrder(),type(first.GetDuration)," +
                "type(path.GetOffset),tostring(missingCurve),tostring(badCurve)," +
                "tostring(missingOffset)},':')"));
