    [Fact]
    public void CooldownMethodsRetainNativeTimingAndVisualState()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "12500:3250:3250:3250:true:false:true:90:true",
            session.Lua.Evaluate(
                "local cooldown=CreateFrame('Cooldown','NativeCooldown',UIParent); " +
                "cooldown:SetCooldown(12.5,3.25); cooldown:SetSwipeColor(0.1,0.2,0.3,0.4); " +
                "cooldown:SetCountdownAbbrevThreshold(90); cooldown:SetUseAuraDisplayTime(true); " +
                "cooldown:SetCountdownFont('GameFontHighlightOutline'); " +
                "cooldown:SetDrawSwipe(true); cooldown:SetDrawEdge(false); cooldown:SetReverse(true); " +
                "local start,duration=cooldown:GetCooldownTimes(); " +
                "return start..':'..duration..':'..cooldown:GetCooldownDuration()..':'.." +
                "cooldown:GetCooldownDisplayDuration()..':'.." +
                "tostring(cooldown:GetDrawSwipe())..':'..tostring(cooldown:GetDrawEdge())..':'.." +
                "tostring(cooldown:GetReverse())..':'..cooldown:GetCountdownAbbrevThreshold()..':'.." +
                "tostring(cooldown:GetUseAuraDisplayTime())"));

        var cooldown = session.Ui.Find("NativeCooldown")!.Cooldown!;
        Assert.Equal(
            new System.Numerics.Vector4(26 / 255f, 51 / 255f, 77 / 255f, 102 / 255f),
            cooldown.SwipeColor);
        Assert.Equal(90_000, cooldown.CountdownAbbreviationThresholdMilliseconds);
        Assert.Equal("GameFontHighlightOutline", cooldown.CountdownFontName);
        Assert.True(cooldown.UseAuraDisplayTime);

        session.Lua.Evaluate("NativeCooldown:Clear()");
        Assert.Equal(0, cooldown.StartTimeMilliseconds);
        Assert.Equal(0, cooldown.DisplayDurationMilliseconds);
        Assert.Equal(1, cooldown.ModRate);
    }

