    [Fact]
    public void XmlOnLoadRunsAfterTheCompleteInheritedSubtreeAndKeyValuesExist()
    {
        var root = Path.Combine(Path.GetTempPath(), $"wow-addon-lab-{Guid.NewGuid():N}");
        Directory.CreateDirectory(root);
        try
        {
            File.WriteAllText(
                Path.Combine(root, "Lifecycle.lua"),
                "loadTrace=''; " +
                "LifecycleParentMixin={OnLoad=function(self) self.parentLoaded=true; loadTrace=loadTrace..'P' end}; " +
                "LifecycleControllerMixin={OnLoad=function(self) " +
                "local parent=self:GetParent(); parent.controllerSawAtlas=parent.atlasName; " +
                "parent.controllerSawParentLoad=parent.parentLoaded; " +
                "loadTrace=loadTrace..'C' end}");
            File.WriteAllText(
                Path.Combine(root, "Lifecycle.xml"),
                "<Ui>" +
                "<Button name=\"LifecycleBase\" virtual=\"true\" mixin=\"LifecycleParentMixin\">" +
                "<Frames><Frame parentKey=\"Controller\" mixin=\"LifecycleControllerMixin\">" +
                "<Scripts><OnLoad method=\"OnLoad\"/></Scripts></Frame></Frames>" +
                "<Scripts><OnLoad method=\"OnLoad\"/></Scripts></Button>" +
                "<Button name=\"LifecycleDerived\" virtual=\"true\" inherits=\"LifecycleBase\">" +
                "<KeyValues><KeyValue key=\"atlasName\" value=\"128-RedButton\" type=\"string\"/>" +
                "</KeyValues></Button>" +
                "<Button name=\"LifecycleInstance\" inherits=\"LifecycleDerived\"/>" +
                "</Ui>");
            File.WriteAllText(
                Path.Combine(root, "Lifecycle.toc"),
                "## Interface: 1\n## Title: Lifecycle\nLifecycle.lua\nLifecycle.xml\n");

            using var session = new EmulatorSession();
            session.Load(root);

            Assert.Equal(
                "128-RedButton:nil:CP",
                session.Lua.Evaluate(
                    "return LifecycleInstance.controllerSawAtlas..':'.." +
                    "tostring(LifecycleInstance.controllerSawParentLoad)..':'..loadTrace"));
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

    [Fact]
    public void DragStartsAfterThresholdAndSuppressesClick()
    {
        using var session = new EmulatorSession();
        session.Lua.Evaluate(
            "clickCount = 0; dragStartCount = 0; dragStopCount = 0; " +
            "local b = CreateFrame('Button', 'Draggable', UIParent); " +
            "b:SetSize(100, 50); b:SetPoint('CENTER'); b:RegisterForDrag('LeftButton'); " +
            "b:SetScript('OnClick', function() clickCount = clickCount + 1 end); " +
            "b:SetScript('OnDragStart', function() dragStartCount = dragStartCount + 1 end); " +
            "b:SetScript('OnDragStop', function() dragStopCount = dragStopCount + 1 end)");

        session.MouseMove(800, 450);
        session.MouseButton("LeftButton", true);
        session.MouseMove(803, 450);
        session.MouseButton("LeftButton", false);
        Assert.Equal("1:0:0", session.Lua.Evaluate("clickCount..':'..dragStartCount..':'..dragStopCount"));

        session.MouseButton("LeftButton", true);
        session.MouseMove(810, 450);
        session.MouseButton("LeftButton", false);
        Assert.Equal("1:1:1", session.Lua.Evaluate("clickCount..':'..dragStartCount..':'..dragStopCount"));
    }

    [Fact]
    public void SliderThumbDragUsesNativeValueMappingAndStepSemantics()
    {
        using var session = new EmulatorSession();
        session.Lua.Evaluate(
            "sliderTrace={}; " +
            "local s=CreateFrame('Slider','InputSlider',UIParent); " +
            "s:SetSize(200,20); s:SetPoint('CENTER'); s:EnableMouse(true); " +
            "local thumb=s:CreateTexture('InputSliderThumb'); thumb:SetSize(20,20); " +
            "s:SetThumbTexture(thumb); s:SetMinMaxValues(0,100); " +
            "s:SetValueStep(10); s:SetObeyStepOnDrag(true); s:SetValue(50); " +
            "s:SetScript('OnValueChanged',function(_,value,userInput) " +
            "table.insert(sliderTrace,value..':'..tostring(userInput)) end); " +
            "s:SetScript('OnMouseDown',function(self) " +
            "downDragging=tostring(self:IsDraggingThumb()) end); " +
            "s:SetScript('OnMouseUp',function(self) " +
            "upDragging=tostring(self:IsDraggingThumb()) end)");

        var thumb = session.Ui.Find("InputSliderThumb")!;
        Assert.Equal(new Vector2(800, 450), session.Ui.ResolveBounds(thumb.Id).Center);

        session.MouseMove(800, 450);
        session.MouseButton("LeftButton", true);
        session.MouseMove(890, 450);
        session.MouseButton("LeftButton", false);

        Assert.Equal(
            "50:true,100:true:true:false",
            session.Lua.Evaluate(
                "return table.concat(sliderTrace,',')..':'..downDragging..':'..upDragging"));
        Assert.Equal(new Vector2(890, 450), session.Ui.ResolveBounds(thumb.Id).Center);

        session.Lua.Evaluate(
            "InputSlider:SetValue(50); sliderTrace={}; InputSlider:SetStepsPerPage(2)");
        session.MouseMove(720, 450);
        session.MouseButton("LeftButton", true);
        session.MouseButton("LeftButton", false);

        Assert.Equal(
            "30:false:2",
            session.Lua.Evaluate(
                "return table.concat(sliderTrace,',')..':'..InputSlider:GetStepsPerPage()"));
    }

