            "local s=CreateFrame('Slider','VerticalInputSlider',UIParent); " +
            "s:SetSize(20,200); s:SetPoint('CENTER',UIParent,'CENTER',100,0); " +
            "s:EnableMouse(true); s:SetOrientation('VERTICAL'); " +
            "local thumb=s:CreateTexture('VerticalInputThumb'); thumb:SetSize(20,20); " +
            "s:SetThumbTexture(thumb); s:SetMinMaxValues(0,100); " +
            "s:SetValueStep(10); s:SetObeyStepOnDrag(true); s:SetValue(0); " +
            "s:SetScript('OnValueChanged',function(_,value,userInput) " +
            "table.insert(sliderTrace,value..':'..tostring(userInput)) end)");

        session.MouseMove(900, 360);
        session.MouseButton("LeftButton", true);
        session.MouseMove(900, 540);
        session.MouseButton("LeftButton", false);

        Assert.Equal(
            "100:true,0:true",
            session.Lua.Evaluate("return table.concat(sliderTrace,',')"));
        Assert.Equal(
            "10:20:16:false",
            session.Lua.Evaluate(
                "sliderTrace={}; VerticalInputSlider:SetValue(14,true); local a=VerticalInputSlider:GetValue(); " +
                "VerticalInputSlider:SetValue(16,true); local b=VerticalInputSlider:GetValue(); " +
                "VerticalInputSlider:SetObeyStepOnDrag(false); VerticalInputSlider:SetValue(16,true); " +
                "return a..':'..b..':'..VerticalInputSlider:GetValue()..':'.." +
                "tostring(VerticalInputSlider:IsDraggingThumb())"));
    }

    [Fact]
    public void SliderSettersUseNativeValidationQuantizationAndEventRules()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "6:-1:1:2:2:4:4:false,4:true,5:true,6:false:" +
            "false:false:false:false:false:false:false:false:false",
            session.Lua.Evaluate(
                "(function() " +
                "local s=CreateFrame('Slider','AuditedSlider',UIParent); " +
                "local values={}; local ranges=0; local enables=0; local disables=0; " +
                "s:SetScript('OnValueChanged',function(_,v,mouse) " +
                "table.insert(values,v..':'..tostring(mouse)) end); " +
                "s:SetScript('OnMinMaxChanged',function() ranges=ranges+1 end); " +
                "s:SetScript('OnEnable',function() enables=enables+1 end); " +
                "s:SetScript('OnDisable',function() disables=disables+1 end); " +
                "s:SetMinMaxValues(0,10); s:SetValueStep(2); s:SetValue(3); s:SetValue(4); " +
                "s:SetValue(4,true); s:SetObeyStepOnDrag(false); s:SetValue(5,true); s:SetValue(5); " +
                "s:SetStepsPerPage(255); s:Enable(); s:Enable(); s:Disable(); s:Disable(); " +
                "local missingValue=pcall(s.SetValue,s); " +
                "local missingStep=pcall(s.SetValueStep,s); " +
                "local missingPage=pcall(s.SetStepsPerPage,s); " +
                "local missingObey=pcall(s.SetObeyStepOnDrag,s); " +
                "local badOrientation=pcall(s.SetOrientation,s,'DIAGONAL'); " +
                "local missingEnabled=pcall(s.SetEnabled,s); " +
                "local missingRange=pcall(s.SetMinMaxValues,s,0); " +
                "local invertedRange=pcall(s.SetMinMaxValues,s,10,0); " +
                "local missingThumb=pcall(s.SetThumbTexture,s); " +
                "return table.concat({s:GetValue(),s:GetStepsPerPage(),ranges,enables,disables," +
                "#values,table.concat(values,','),tostring(missingValue),tostring(missingStep)," +
                "tostring(missingPage),tostring(missingObey),tostring(badOrientation)," +
                "tostring(missingEnabled),tostring(missingRange),tostring(invertedRange)," +
                "tostring(missingThumb)},':') end)()"));
    }

