    [Fact]
    public void WowColorMarkupProducesColoredSpansAndSearchablePlainText()
    {
        const string title = "|cff33ccffScene|r Machine || Tools";

        var spans = WowTextMarkup.ParseColorSpans(title);

        Assert.Equal("Scene Machine | Tools", WowTextMarkup.PlainText(title));
        Assert.Equal(
            [
                new WowTextSpan("Scene", 0xff33ccff),
                new WowTextSpan(" Machine | Tools", null)
            ],
            spans);
        Assert.Equal(
            "https://support.blizzard.com/article/42673",
            WowTextMarkup.PlainText(
                "|HurlIndex:64|h|cnVISITABLE_URL_DEFAULT_CHAT_LINK_COLOR:" +
                "https://support.blizzard.com/article/42673|r|h"));
    }

    [Fact]
    public void WowTextMarkupResolvesClientPluralGrammar()
    {
        Assert.Equal(
            "0 Empty Slots (Total)",
            WowTextMarkup.PlainText("0 Empty |4Slot:Slots; (Total)"));
        Assert.Equal(
            "1 Empty Slot (Total)",
            WowTextMarkup.PlainText("1 Empty |4Slot:Slots; (Total)"));
        Assert.Equal(
            "2 few, 21 one, 25 many, 12 many",
            WowTextMarkup.PlainText(
                "2 |4one:few:many;, 21 |4one:few:many;, 25 |4one:few:many;, 12 |4one:few:many;"));
        Assert.Equal(
            "2 Millions",
            WowTextMarkup.PlainText("2 |7Million:Millions;"));
    }

