    {
        using var session = new EmulatorSession();
        session.Lua.Evaluate(
            "local parent=CreateFrame('Frame','LineParent',UIParent); " +
            "parent:SetSize(16,16); parent:SetPoint('CENTER'); " +
            "local line=parent:CreateLine('TestLine','OVERLAY'); " +
            "line:SetStartPoint('LEFT',parent,'LEFT',2,0); " +
            "line:SetEndPoint('RIGHT',parent,'RIGHT',-2,0)");

        var line = session.Ui.Find("TestLine")!.Line!;
        var start = session.Ui.ResolveAnchor(line.Start!);
        var end = session.Ui.ResolveAnchor(line.End!);

        Assert.Equal(start.Y, end.Y);
