        Assert.Equal(808, end.X);
        Assert.Contains(session.Ui.Find("TestLine"), session.Ui.RenderOrder());
        Assert.Equal(16, session.Ui.ResolveBounds(session.Ui.Find("TestLine")!.Id).Width);
    }

