    [Fact]
    public void LineTextureAndTexCoordsUseTheInheritedTextureState()
    {
        using var session = new EmulatorSession();
        session.Lua.Evaluate(
            "local parent=CreateFrame('Frame','TexturedLineParent',UIParent); " +
            "local line=parent:CreateLine('TexturedLine','OVERLAY'); " +
            "line:SetTexture(134400); line:SetTexCoord(.1,.9,.2,.8); " +
            "line:SetVertexColor(.25,.5,.75,.8)");

        var texture = session.Ui.Find("TexturedLine")!.Line!.Texture;
        Assert.Equal(134400u, texture.FileDataId);
        Assert.False(texture.IsColor);
        Assert.Equal(new System.Numerics.Vector2(.1f, .2f), texture.Uv[0]);
        Assert.Equal(new System.Numerics.Vector2(.1f, .8f), texture.Uv[1]);
        Assert.Equal(new System.Numerics.Vector2(.9f, .2f), texture.Uv[2]);
        Assert.Equal(new System.Numerics.Vector2(.9f, .8f), texture.Uv[3]);
        Assert.Equal(
            new System.Numerics.Vector4(64 / 255f, 128 / 255f, 191 / 255f, 204 / 255f),
            texture.VertexColor);
    }

