            ["layout.xml", "main.lua"],
            [
                "<Ui><Line name=\"DynamicLineTemplate\" virtual=\"true\" " +
                "mixin=\"DynamicLineMixin\"><KeyValues>" +
                "<KeyValue key=\"isGridLine\" value=\"true\" type=\"boolean\"/>" +
                "</KeyValues></Line></Ui>",
                "DynamicLineMixin={SetupLine=function(self) self.wasSetup=true end}; " +
                "local parent=CreateFrame('Frame','DynamicLineParent',UIParent); " +
                "DynamicLine=parent:CreateLine(nil,'OVERLAY','DynamicLineTemplate',3); " +
                "DynamicLine:SetupLine()"
            ]);
        try
