    [Fact]
    public void XmlScriptListsAndNestedIncludesLoadInDocumentOrder()
    {
        var root = Path.Combine(Path.GetTempPath(), $"wow-addon-lab-{Guid.NewGuid():N}");
        var addon = CreateAddon(
            root,
            "XmlLoader",
            ["loader.xml"],
            [
                "<Ui xmlns=\"http://www.blizzard.com/wow/ui/\">" +
                "<Script file=\"first.lua\"/>" +
                "<Include file=\"included.lua\"/>" +
                "<Include file=\"nested.xml\"/>" +
                "</Ui>"
            ]);
        File.WriteAllText(
            Path.Combine(addon, "first.lua"),
            "local name, private = ...; private.order = name");
        File.WriteAllText(
            Path.Combine(addon, "included.lua"),
            "local _, private = ...; private.order = private.order .. ':included'");
        File.WriteAllText(
            Path.Combine(addon, "nested.xml"),
            "<Ui><Script file=\"second.lua\"/></Ui>");
        File.WriteAllText(
            Path.Combine(addon, "second.lua"),
            "local name, private = ...; xmlLoadResult = private.order .. ':' .. name");
        try
        {
            using var session = new EmulatorSession();
            session.Load(addon);

            Assert.Equal("XmlLoader:included:XmlLoader", session.Lua.Evaluate("xmlLoadResult"));
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

