                "</Gradient></Texture>" +
                "<Texture parentKey=\"Tinted\" file=\"Interface\\\\Buttons\\\\White8x8\" " +
                "alphaMode=\"MOD\" hWrapMode=\"REPEAT\" vWrapMode=\"CLAMPTOBLACKADDITIVE\" " +
                "rotation=\"90\" desaturated=\"true\">" +
                "<Color r=\"0.2\" g=\"0.4\" b=\"0.6\" a=\"0.8\"/>" +
                "<TexCoords left=\"0.1\" right=\"0.9\" top=\"0.2\" bottom=\"0.8\"/>" +
                "</Texture></Layer></Layers></Frame></Ui>"
            ]);
        try
        {
            using var session = new EmulatorSession();
            session.Load(addon);

            var texture = session.Ui.Find("GradientOwner")!.Children
                .Select(session.Ui.Find)
                .Single(value => value?.Texture?.Gradient is not null)!
                .Texture!;
            Assert.True(texture.IsColor);
            var gradient = Assert.NotNull(texture.Gradient);
            Assert.Equal("VERTICAL", gradient.Orientation);
            Assert.Equal(new System.Numerics.Vector4(0.23f, 0.19f, 0, 0.8f), gradient.Minimum);
            Assert.Equal(new System.Numerics.Vector4(0, 0, 0, 1), gradient.Maximum);

            var tinted = session.Ui.Find("GradientOwner")!.Children
                .Select(session.Ui.Find)
                .Single(value => value?.Texture?.Asset is not null)!
                .Texture!;
            Assert.False(tinted.IsColor);
            Assert.Equal(new System.Numerics.Vector4(0.2f, 0.4f, 0.6f, 0.8f), tinted.VertexColor);
            Assert.Equal(new System.Numerics.Vector2(0.1f, 0.2f), tinted.Uv[0]);
            Assert.Equal(new System.Numerics.Vector2(0.9f, 0.8f), tinted.Uv[3]);
            Assert.Equal("MOD", tinted.BlendMode);
            Assert.Equal("REPEAT", tinted.WrapHorizontal);
            Assert.Equal("CLAMPTOBLACKADDITIVE", tinted.WrapVertical);
            Assert.Equal(MathF.PI / 2, tinted.Rotation, 5);
            Assert.Equal(1, tinted.Desaturation);
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

