    [Fact]
    public void XmlButtonTexturesBeginInTheNativeButtonState()
    {
        var root = Path.Combine(Path.GetTempPath(), $"wow-addon-lab-{Guid.NewGuid():N}");
        var addon = CreateAddon(
            root,
            "XmlButtonTextures",
            ["layout.xml"],
            [
                "<Ui><Button name=\"XmlStateButton\"><Size x=\"100\" y=\"30\"/>" +
                "<NormalTexture parentKey=\"Normal\" setAllPoints=\"true\"/>" +
                "<PushedTexture parentKey=\"Pushed\" setAllPoints=\"true\"/>" +
                "<DisabledTexture parentKey=\"Disabled\" setAllPoints=\"true\"/>" +
                "<HighlightTexture parentKey=\"Highlight\" setAllPoints=\"true\"/>" +
                "</Button></Ui>"
            ]);
        try
        {
            using var session = new EmulatorSession();
            session.Load(addon);

            var button = session.Ui.Find("XmlStateButton")!;
            var highlight = button.Children
                .Select(session.Ui.Find)
                .Single(value => value?.Name is null && value?.DrawLayer == "HIGHLIGHT")!;
            Assert.DoesNotContain("HIGHLIGHT", button.EnabledDrawLayers);

            Assert.Equal(
                "true:false:false:true",
                session.Lua.Evaluate(
                    "return table.concat({" +
                    "tostring(XmlStateButton.Normal:IsShown())," +
                    "tostring(XmlStateButton.Pushed:IsShown())," +
                    "tostring(XmlStateButton.Disabled:IsShown())," +
                    "tostring(XmlStateButton.Highlight:IsShown())},':')"));
            session.Ui.SetMouseFoci([button]);
            Assert.Contains("HIGHLIGHT", button.EnabledDrawLayers);
            session.Ui.SetMouseFoci([]);
            Assert.DoesNotContain("HIGHLIGHT", button.EnabledDrawLayers);
            Assert.Equal(
                "false:true:false",
                session.Lua.Evaluate(
                    "XmlStateButton:SetButtonState('PUSHED'); return table.concat({" +
                    "tostring(XmlStateButton.Normal:IsShown())," +
                    "tostring(XmlStateButton.Pushed:IsShown())," +
                    "tostring(XmlStateButton.Disabled:IsShown())},':')"));
            Assert.Equal(
                "false:false:true",
                session.Lua.Evaluate(
                    "XmlStateButton:Disable(); return table.concat({" +
                    "tostring(XmlStateButton.Normal:IsShown())," +
                    "tostring(XmlStateButton.Pushed:IsShown())," +
                    "tostring(XmlStateButton.Disabled:IsShown())},':')"));
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

