        var addon = CreateAddon(
            root,
            "XmlTemplateInfo",
            ["layout.xml"],
            [
                "<Ui><Frame name=\"BaseXmlInfo\" virtual=\"true\"><Size x=\"80\" y=\"30\"/>" +
                "</Frame><Frame name=\"DerivedXmlInfo\" inherits=\"BaseXmlInfo\" virtual=\"true\">" +
                "<KeyValues><KeyValue key=\"count\" keyType=\"number\" type=\"number\" " +
                "value=\"7\"/></KeyValues></Frame></Ui>"
            ]);
        try
        {
            using var session = new EmulatorSession();
            session.Load(addon);

            Assert.Equal(
                "Frame:80:30:BaseXmlInfo:count:number:number:7:true:0",
                session.Lua.Evaluate(
                    "local info=C_XMLUtil.GetTemplateInfo('DerivedXmlInfo');" +
                    "local value=info.keyValues[1];" +
                    "return table.concat({info.type,info.width,info.height,info.inherits," +
                    "value.key,value.keyType,value.type,value.value," +
                    "tostring(info.sourceLocation:match('layout.xml$')~=nil)," +
                    "select('#',C_XMLUtil.GetTemplateInfo('MissingXmlInfo'))},':')"));

            Assert.Equal(
                "false:false:false",
                session.Lua.Evaluate(
                    "local a=pcall(C_XMLUtil.GetTemplateInfo);" +
                    "local b=pcall(C_XMLUtil.GetTemplateInfo,7);" +
                    "local c=pcall(C_XMLUtil.GetTemplateInfo,'DerivedXmlInfo',true);" +
                    "return table.concat({tostring(a),tostring(b),tostring(c)},':')"));
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

