    [Fact]
    public void QuestPoiAndFogOfWarWidgetsPreserveNativeStateAndNotifyMapChanges()
    {
        using var session = new EmulatorSession();
        session.AtlasProvider = new TestAtlasProvider();

        Assert.Equal(
            "84:0:84:1",
            session.Lua.Evaluate(
                "local quest=CreateFrame('QuestPOIFrame'); " +
                "quest:SetFillTexture('fill'); quest:SetBorderTexture('border'); " +
                "quest:SetFillAlpha(102); quest:SetBorderAlpha(178); quest:SetBorderScalar(2); " +
                "quest:SetMapID(84); quest:DrawBlob(12,true); " +
                "local fog=CreateFrame('FogOfWarFrame'); local changed=0; " +
                "fog:SetScript('OnUiMapChanged',function(self,id) changed=changed+1 end); " +
                "fog:SetUiMapID(84); fog:SetUiMapID(84); " +
                "fog:SetFogOfWarBackgroundAtlas('TestAtlas'); " +
                "fog:SetFogOfWarMaskAtlas('TestAtlas'); fog:SetMaskScalar(1.5); " +
                "return quest:GetMapID()..':'..quest:GetNumTooltips()..':'.." +
                "fog:GetUiMapID()..':'..changed"));

        var quest = session.Ui.Objects.Values.Single(value =>
            value.ObjectType.Equals("QuestPOIFrame", StringComparison.OrdinalIgnoreCase));
        Assert.Equal("fill", quest.Blob!.FillTexture);
        Assert.Equal("border", quest.Blob.BorderTexture);
        Assert.Equal((byte)102, quest.Blob.FillAlpha);
        Assert.Equal((byte)178, quest.Blob.BorderAlpha);
        Assert.Equal(2, quest.Blob.BorderScalar);
        Assert.Equal([12], quest.Blob.DrawnBlobIds);

        var fog = session.Ui.Objects.Values.Single(value =>
            value.ObjectType.Equals("FogOfWarFrame", StringComparison.OrdinalIgnoreCase));
        Assert.Equal("TestAtlas", fog.FogOfWar!.BackgroundAtlas);
        Assert.Equal("TestAtlas", fog.FogOfWar.MaskAtlas);
        Assert.Equal(1.5f, fog.FogOfWar.MaskScalar);
    }

    [Fact]
    public void FogOfWarWidgetApisFollowNativeRequiredInputsAndStateTransitions()
    {
        using var session = new EmulatorSession();
        session.AtlasProvider = new TestAtlasProvider();

        Assert.Equal(
            "0:1:true:true:false:false:false:false:false:false:false:false:" +
            "TestAtlas:TestAtlas:-2:2:true:123:456",
            session.Lua.Evaluate(
                "local fog=CreateFrame('FogOfWarFrame','FogContract'); " +
                "local defaultMap=fog:GetUiMapID(); local defaultScalar=fog:GetMaskScalar(); " +
                "local defaultBackground=fog:GetFogOfWarBackgroundTexture()==nil; " +
                "local defaultMask=fog:GetFogOfWarMaskTexture()==nil; " +
                "local missingMap=pcall(function() fog:SetUiMapID() end); " +
                "local missingScalar=pcall(function() fog:SetMaskScalar() end); " +
                "local badScalar=pcall(function() fog:SetMaskScalar(0/0) end); " +
                "local missingBackgroundAtlas=pcall(function() " +
                "fog:SetFogOfWarBackgroundAtlas() end); " +
                "local missingBackgroundTexture=pcall(function() " +
                "fog:SetFogOfWarBackgroundTexture() end); " +
                "local missingBackgroundTiles=pcall(function() " +
                "fog:SetFogOfWarBackgroundTexture(123,true) end); " +
                "local missingMaskAtlas=pcall(function() " +
                "fog:SetFogOfWarMaskAtlas() end); " +
                "local missingMaskTexture=pcall(function() " +
                "fog:SetFogOfWarMaskTexture() end); " +
                "fog:SetFogOfWarBackgroundAtlas('TestAtlas'); " +
                "fog:SetFogOfWarBackgroundAtlas('MissingAtlas'); " +
                "local retainedBackgroundAtlas=fog:GetFogOfWarBackgroundAtlas(); " +
                "fog:SetFogOfWarMaskAtlas('TestAtlas'); " +
                "fog:SetFogOfWarMaskAtlas('MissingAtlas'); " +
                "local retainedMaskAtlas=fog:GetFogOfWarMaskAtlas(); " +
                "fog:SetFogOfWarBackgroundTexture(123,true,nil); " +
                "fog:SetFogOfWarMaskTexture(456); fog:SetMaskScalar(0); " +
                "local changes=0; fog:SetScript('OnUiMapChanged',function() changes=changes+1 end); " +
                "fog:SetUiMapID(84); fog:SetUiMapID(84); fog:SetUiMapID(-2); " +
                "return table.concat({" +
                "defaultMap,defaultScalar,tostring(defaultBackground),tostring(defaultMask)," +
                "tostring(missingMap),tostring(missingScalar),tostring(badScalar)," +
                "tostring(missingBackgroundAtlas),tostring(missingBackgroundTexture)," +
                "tostring(missingBackgroundTiles),tostring(missingMaskAtlas)," +
                "tostring(missingMaskTexture),retainedBackgroundAtlas,retainedMaskAtlas," +
                "fog:GetUiMapID(),changes,tostring(fog:GetMaskScalar()>0.009 and " +
                "fog:GetMaskScalar()<0.011),fog:GetFogOfWarBackgroundTexture()," +
                "fog:GetFogOfWarMaskTexture()},':')"));

        var fog = session.Ui.Objects.Values.Single(value => value.Name == "FogContract");
        Assert.Equal(-2, fog.FogOfWar!.UiMapId);
        Assert.Null(fog.FogOfWar.BackgroundAtlas);
        Assert.Equal((uint)123, fog.FogOfWar.BackgroundTextureFileDataId);
        Assert.True(fog.FogOfWar.BackgroundTextureTilesHorizontally);
        Assert.False(fog.FogOfWar.BackgroundTextureTilesVertically);
        Assert.Null(fog.FogOfWar.MaskAtlas);
        Assert.Equal((uint)456, fog.FogOfWar.MaskTextureFileDataId);
        Assert.Equal(0.01f, fog.FogOfWar.MaskScalar);

        Assert.Equal(
            "true:true",
            session.Lua.Evaluate(
                "FogContract:SetFogOfWarBackgroundTexture(0,false,false); " +
                "FogContract:SetFogOfWarMaskTexture(0); " +
                "return tostring(FogContract:GetFogOfWarBackgroundTexture()==nil)..':'.." +
                "tostring(FogContract:GetFogOfWarMaskTexture()==nil)"));
    }

    [Fact]
