    [Fact]
    public void BlobFrameDefaultsAndSettersFollowNativeRanges()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "0:false:false:false:false:false:false",
            session.Lua.Evaluate(
                "local defaults=CreateFrame('QuestPOIFrame','BlobDefaults'); " +
                "local q=CreateFrame('QuestPOIFrame','BlobMutated'); " +
                "local missingMap=pcall(function() q:SetMapID() end); " +
                "local missingAlpha=pcall(function() q:SetFillAlpha() end); " +
                "local badAlpha=pcall(function() q:SetBorderAlpha(256) end); " +
                "local badTexture=pcall(function() q:SetFillTexture(nil) end); " +
                "local badScalar=pcall(function() q:SetBorderScalar(0/0) end); " +
                "local badSpline=pcall(function() q:SetNumSplinePoints() end); " +
                "q:EnableMerging(); q:EnableSmoothing(); " +
                "q:SetFillAlpha(254.9); q:SetBorderAlpha(12.9); " +
                "q:SetBorderScalar(20); q:SetMergeThreshold(0); " +
                "q:SetNumSplinePoints(100); q:SetFillTexture(1234); " +
                "return defaults:GetMapID()..':'.." +
                "table.concat({tostring(missingMap),tostring(missingAlpha)," +
                "tostring(badAlpha),tostring(badTexture),tostring(badScalar)," +
                "tostring(badSpline)},':')"));

        var defaults = session.Ui.Objects.Values.Single(value =>
            value.Name == "BlobDefaults");
        Assert.Equal((byte)255, defaults.Blob!.FillAlpha);
        Assert.Equal((byte)255, defaults.Blob.BorderAlpha);
        Assert.Equal(1, defaults.Blob.BorderScalar);
        Assert.Equal(0.25f, defaults.Blob.MergeThreshold);
        Assert.Equal(20, defaults.Blob.NumSplinePoints);
        Assert.True(defaults.Blob.MergingEnabled);
        Assert.True(defaults.Blob.SmoothingEnabled);

        var quest = session.Ui.Objects.Values.Single(value =>
            value.Name == "BlobMutated");
        Assert.Equal((byte)254, quest.Blob!.FillAlpha);
        Assert.Equal((byte)12, quest.Blob.BorderAlpha);
        Assert.Equal(10, quest.Blob.BorderScalar);
        Assert.Equal(0.1f, quest.Blob.MergeThreshold);
        Assert.Equal(30, quest.Blob.NumSplinePoints);
        Assert.False(quest.Blob.MergingEnabled);
        Assert.False(quest.Blob.SmoothingEnabled);
        Assert.Equal((uint)1234, quest.Blob.FillTextureFileDataId);
    }

