            var blob = session.Ui.Find("XmlBlob")!.Blob!;
            Assert.Equal(@"Interface\\Fill", blob.FillTexture);
            Assert.Equal((uint)12345, blob.BorderTextureFileDataId);
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

    [Fact]
    public void BlobFrameDrawMethodsFollowDerivedNativeVirtuals()
    {
        using var session = new EmulatorSession();

        session.Lua.Evaluate(
            "quest=CreateFrame('QuestPOIFrame'); " +
            "for i=1,9 do quest:DrawBlob(i,true) end; " +
            "quest:DrawBlob(2); quest:DrawBlob(9,true); quest:DrawAll(); " +
            "scenario=CreateFrame('ScenarioPOIFrame'); " +
            "scenario:DrawBlob(77,true); scenario:DrawAll()");

        var quest = session.Ui.Objects.Values.Single(value =>
            value.ObjectType.Equals("QuestPOIFrame", StringComparison.OrdinalIgnoreCase));
        Assert.Equal([1, 3, 4, 5, 6, 7, 8, 9], quest.Blob!.DrawnBlobIds);
        Assert.False(quest.Blob.DrawAll);

        var scenario = session.Ui.Objects.Values.Single(value =>
            value.ObjectType.Equals("ScenarioPOIFrame", StringComparison.OrdinalIgnoreCase));
        Assert.Empty(scenario.Blob!.DrawnBlobIds);
        Assert.True(scenario.Blob.DrawAll);

        session.Lua.Evaluate("quest:DrawNone(); scenario:DrawNone()");
        Assert.Empty(quest.Blob.DrawnBlobIds);
        Assert.Empty(scenario.Blob.DrawnBlobIds);
        Assert.False(scenario.Blob.DrawAll);
    }

