    [Fact]
    public void UnitPositionFrameApisFollowNativeArgumentAndMutationContracts()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "0:1.00:false:false:true:false:false:false:false:false",
            session.Lua.Evaluate(
                "unitPositionAuditFrame=CreateFrame('UnitPositionFrame'); " +
                "local f=unitPositionAuditFrame; " +
                "local defaultMap,defaultScale=f:GetUiMapID(),f:GetPlayerPingScale(); " +
                "local mapMissing=pcall(function() f:SetUiMapID() end); " +
                "local scaleMissing=pcall(function() f:SetPlayerPingScale() end); " +
                "local zeroScale=pcall(function() f:SetPlayerPingScale(0) end); " +
                "local badTextureType=pcall(function() " +
                "f:SetPlayerPingTexture(3,'bad') end); " +
                "local missingTexture=pcall(function() " +
                "f:SetPlayerPingTexture(0) end); " +
                "local badTextureSize=pcall(function() " +
                "f:SetPlayerPingTexture(0,'bad','wide') end); " +
                "local badUnitSize=pcall(function() " +
                "f:AddUnit('player','bad','wide') end); " +
                "f:AddUnit('unknown-unit','ignored'); " +
                "f:AddUnit('nameplate150','edge'); " +
                "f:AddUnit('nameplate151','past-edge'); " +
                "f:AddUnit('player','first',10,11,.1,.2,.3); " +
                "f:AddUnit('player','duplicate',90,91,1,1,1,1); " +
                "local missingColor=pcall(function() " +
                "f:SetUnitColor('player',.1,.2,.3) end); " +
                "local invalidColorUnit=pcall(function() " +
                "f:SetUnitColor('unknown-unit',1,1,1,1) end); " +
                "local badPing=pcall(function() f:StartPlayerPing('bad') end); " +
                "return string.format('%d:%.2f:%s:%s:%s:%s:%s:%s:%s:%s'," +
                "defaultMap,defaultScale,tostring(mapMissing),tostring(scaleMissing)," +
                "tostring(zeroScale),tostring(badTextureType),tostring(missingTexture)," +
                "tostring(badTextureSize),tostring(badUnitSize)," +
                "tostring(missingColor or invalidColorUnit or badPing))"));

        var frame = session.Ui.Objects.Values.Single(value =>
            value.ObjectType.Equals("UnitPositionFrame", StringComparison.OrdinalIgnoreCase));
        Assert.Equal(0, frame.UnitPosition!.UiMapId);
        Assert.Equal(1, frame.UnitPosition.PlayerPingScale);
        Assert.Single(frame.UnitPosition.Units);
        Assert.DoesNotContain("nameplate150", frame.UnitPosition.Units.Keys);
        Assert.DoesNotContain("nameplate151", frame.UnitPosition.Units.Keys);
        Assert.Equal("first", frame.UnitPosition.Units["player"].Asset);
        Assert.Equal(System.Numerics.Vector4.One, frame.UnitPosition.Units["player"].Color);
        Assert.Empty(frame.UnitPosition.PlayerPingTextures);

        session.Lua.Evaluate(
            "local f=unitPositionAuditFrame; " +
            "f:SetUiMapID(-7); f:SetPlayerPingScale(.75); " +
            "f:SetPlayerPingTexture(2,123,16,17); " +
            "f:SetUnitColor('player',.1,.2,.3,.4); " +
            "f:StartPlayerPing(-2,.5)");

        Assert.Equal(-7, frame.UnitPosition.UiMapId);
        Assert.Equal(.75f, frame.UnitPosition.PlayerPingScale);
        Assert.Equal((uint)123, frame.UnitPosition.PlayerPingTextures[2].FileDataId);
        Assert.Equal(16, frame.UnitPosition.PlayerPingTextures[2].Width);
        Assert.True(frame.UnitPosition.PlayerPingActive);
        Assert.Equal(0, frame.UnitPosition.PlayerPingDuration);
        Assert.Equal(0, frame.UnitPosition.PlayerPingFadeDuration);

        session.Lua.Evaluate(
            "unitPositionAuditFrame:StopPlayerPing()");
        Assert.False(frame.UnitPosition.PlayerPingActive);
    }

