    [Fact]
    public void WowLabsDataManagerMatchesNativeRecordsRequestsAndDeferredCirclePush()
    {
        using var session = new EmulatorSession();
        session.Lua.WowLabsDataManager.ConfirmedAreaId = 45;
        session.Lua.WowLabsDataManager.InPrematch = true;
        session.Lua.WowLabsDataManager.Areas.Add(
            new WowLabsAreaInfo(45, 3, 1.25f, 2.5f, 3.75f));
        session.Lua.GameRules.RuleValueOverrides[14] = 1;

        Assert.Equal(
            "nil",
            session.Lua.Evaluate(
                "local frame=CreateFrame('Frame'); _G.wowLabsCircleResult=nil; " +
                "frame:RegisterEvent('WOW_LABS_DATA_BR_CIRCLE'); " +
                "frame:SetScript('OnEvent',function(self,event,startTime,lerpTime) " +
                "_G.wowLabsCircleResult=startTime..':'..lerpTime end); " +
                "C_WowLabsDataManager.PushCircleInfoToLua(); " +
                "return tostring(_G.wowLabsCircleResult)"));

        session.Tick(0);

        Assert.Equal(
            "-1:-1:true:45:1:45:3:1.25:2.5:3.75",
            session.Lua.Evaluate(
                "local areas=C_WowLabsDataManager.GetWoWLabsAreaInfo(); local area=areas[1];" +
                "return table.concat({_G.wowLabsCircleResult," +
                "tostring(C_WowLabsDataManager.IsInPrematch())," +
                "C_WowLabsDataManager.GetConfirmedWoWLabsArea(),#areas," +
                "area.wowLabsAreaID,area.areaType,area.x,area.y,area.z},':')"));

        Assert.Equal(1, session.Lua.WowLabsDataManager.CircleInfoPushRequestCount);
        Assert.False(session.Lua.WowLabsDataManager.CircleInfoDirty);
        Assert.Equal(
            "false:false:false",
            session.Lua.Evaluate(
                "C_WowLabsDataManager.QuerySelectedWoWLabsArea();" +
                "C_WowLabsDataManager.QueryWoWLabsAreaInfo();" +
                "C_WowLabsDataManager.SelectWoWLabsArea(92);" +
                "local a=pcall(C_WowLabsDataManager.IsInPrematch,true);" +
                "local b=pcall(C_WowLabsDataManager.SelectWoWLabsArea);" +
                "local c=pcall(C_WowLabsDataManager.SelectWoWLabsArea,{});" +
                "return table.concat({tostring(a),tostring(b),tostring(c)},':')"));
        Assert.Equal(1, session.Lua.WowLabsDataManager.SelectedAreaQueryCount);
        Assert.Equal(1, session.Lua.WowLabsDataManager.AreaInfoQueryCount);
        Assert.Equal([92], session.Lua.WowLabsDataManager.SelectedAreaRequests);
    }

