    [Fact]
    public void EventSchedulerExposesNativeRecordsAndReminderLifecycle()
    {
        using var session = new EmulatorSession();
        var now = new DateTimeOffset(2026, 7, 30, 12, 0, 0, TimeSpan.Zero);
        session.Lua.DateAndTime.CurrentTimeOverride = now;
        var scheduler = session.Lua.EventScheduler;
        scheduler.CanShowEvents = true;
        scheduler.HasData = true;
        scheduler.UiMapIdByAreaPoiId[501] = 84;
        scheduler.ZoneNameByAreaPoiId[501] = "Stormwind";
        scheduler.OngoingEvents.Add(new WowOngoingEvent(
            501,
            true,
            new WowEventSchedulerDisplayInfo(true, false, "poi-atlas", 77)));
        scheduler.ScheduledEvents.Add(new WowScheduledEvent(
            "future",
            42,
            501,
            now.ToUnixTimeSeconds() + 300,
            now.ToUnixTimeSeconds() + 900,
            600,
            false,
            new WowEventSchedulerDisplayInfo(false, true)));
        scheduler.ScheduledEvents.Add(new WowScheduledEvent(
            "past",
            43,
            501,
            now.ToUnixTimeSeconds() - 300,
            now.ToUnixTimeSeconds() - 1,
            299,
            true,
            new WowEventSchedulerDisplayInfo(false, false)));

        Assert.Equal(
            "true:true:84:Stormwind:501:true:true:false:poi-atlas:77:" +
            "42:501:600:false:true:1:2:false",
            session.Lua.Evaluate(
                "local updates=0; local listener=CreateFrame('Frame');" +
                "listener:RegisterEvent('EVENT_SCHEDULER_UPDATE');" +
                "listener:SetScript('OnEvent',function() updates=updates+1 end);" +
                "local ongoing=C_EventScheduler.GetOngoingEvents();" +
                "C_EventScheduler.SetReminder('future');" +
                "C_EventScheduler.SetReminder('past');" +
                "local scheduled=C_EventScheduler.GetScheduledEvents();" +
                "local saved=C_EventScheduler.HasSavedReminders();" +
                "C_EventScheduler.ClearReminder('future');" +
                "return table.concat({" +
                "tostring(C_EventScheduler.CanShowEvents())," +
                "tostring(C_EventScheduler.HasData())," +
                "C_EventScheduler.GetEventUiMapID(501)," +
                "C_EventScheduler.GetEventZoneName(501)," +
                "ongoing[1].areaPoiID,tostring(ongoing[1].rewardsClaimed)," +
                "tostring(ongoing[1].displayInfo.hideTimeLeft)," +
                "tostring(ongoing[1].displayInfo.hideDescription)," +
                "ongoing[1].displayInfo.overrideAtlas," +
                "ongoing[1].displayInfo.overrideTooltipWidgetSetID," +
                "scheduled[1].eventID,scheduled[1].areaPoiID," +
                "scheduled[1].duration,tostring(scheduled[1].rewardsClaimed)," +
                "tostring(scheduled[1].hasReminder),#ongoing,#scheduled," +
                "tostring(C_EventScheduler.HasSavedReminders())},':')"));
    }

