    {
        using var session = new EmulatorSession();
        var clock = 10_000L;
        session.Lua.EventScheduler.MonotonicMillisecondsProvider = () => clock;

        Assert.Equal(
            "1:nil:1:nil:false:false:false:false:true:true",
            session.Lua.Evaluate(
                "local map=C_EventScheduler.GetEventUiMapID(1);" +
                "local zone=C_EventScheduler.GetEventZoneName(1);" +
                "local a=pcall(C_EventScheduler.GetEventUiMapID);" +
                "local b=pcall(C_EventScheduler.GetEventZoneName,'x');" +
                "local c=pcall(C_EventScheduler.SetReminder,1);" +
                "local d=pcall(C_EventScheduler.ClearReminder);" +
                "local e=pcall(C_EventScheduler.CanShowEvents,1);" +
                "local f=pcall(C_EventScheduler.RequestEvents,1);" +
                "C_EventScheduler.RequestEvents();" +
                "C_EventScheduler.RequestEvents();" +
                "return table.concat({" +
                "select('#',C_EventScheduler.GetEventUiMapID(1)),tostring(map)," +
                "select('#',C_EventScheduler.GetEventZoneName(1)),tostring(zone)," +
