                "local child=CreateFrame('Frame',nil,parent); " +
                "local shown,hidden=0,0; " +
                "child:SetScript('OnShow',function() shown=shown+1 end); " +
                "child:SetScript('OnHide',function() hidden=hidden+1 end); " +
                "child:Hide(); child:Show(); " +
