                "changes=changes+1; lastName=name end); " +
                "frame:SetAttributeNoHandler('STATE','base'); " +
                "frame:SetAttribute('*state*','both'); " +
                "frame:SetAttribute('Pstate*','suffix'); " +
                "frame:SetAttribute('*stateS','prefix'); " +
