    [Fact]
    public void XmlFlipBooksCropTheirTargetAndExposeAnimationProperties()
    {
        var root = Path.Combine(Path.GetTempPath(), $"wow-addon-lab-{Guid.NewGuid():N}");
        var addon = CreateAddon(
            root,
            "XmlFlipBook",
            ["animations.xml"],
            [
                "<Ui><Texture name=\"FlipBookTexture\">" +
                "<Animations><AnimationGroup parentKey=\"Anim\">" +
                "<FlipBook parentKey=\"Frames\" flipBookRows=\"2\" flipBookColumns=\"4\" " +
                "flipBookFrames=\"8\" duration=\"0.25\"/>" +
                "</AnimationGroup></Animations>" +
                "</Texture></Ui>"
            ]);
        try
        {
            using var session = new EmulatorSession();
            session.Load(addon);
            var texture = session.Ui.Find("FlipBookTexture")!.Texture!;

            Assert.Equal(
                "2:4:8:0:0",
                session.Lua.Evaluate(
                    "local a=FlipBookTexture.Anim.Frames; " +
                    "return a:GetFlipBookRows()..':'..a:GetFlipBookColumns()..':'.." +
                    "a:GetFlipBookFrames()..':'..a:GetFlipBookFrameWidth()..':'.." +
                    "a:GetFlipBookFrameHeight()"));
            session.Lua.Evaluate("FlipBookTexture.Anim:Play(); FlipBookTexture.Anim:Pause()");
            Assert.Equal(new Vector2(0.25f, 0.5f), texture.LocalUv[3]);

            session.Lua.Evaluate("FlipBookTexture.Anim:Play()");
            session.Tick(0.125);
            Assert.Equal(new Vector2(0, 0.5f), texture.LocalUv[0]);
            Assert.Equal(new Vector2(0.25f, 1), texture.LocalUv[3]);

            session.Lua.Evaluate("FlipBookTexture.Anim:Play(true)");
            Assert.Equal(new Vector2(0, 0.5f), texture.LocalUv[0]);
            Assert.Equal(new Vector2(0.25f, 1), texture.LocalUv[3]);
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

    [Fact]
    public void FlipBookFrameSelectionAndPixelSizingFollowNativeTextureAdapterRules()
    {
        using var session = new EmulatorSession();

        session.Lua.Evaluate(
            "local function setup(name,rows,columns,frames,width,height) " +
            "local texture=UIParent:CreateTexture(name); " +
            "local group=texture:CreateAnimationGroup(); " +
            "local flip=group:CreateAnimation('FlipBook'); flip:SetDuration(100); " +
            "flip:SetFlipBookRows(rows); flip:SetFlipBookColumns(columns); " +
            "flip:SetFlipBookFrames(frames); flip:SetFlipBookFrameWidth(width); " +
            "flip:SetFlipBookFrameHeight(height); _G[name..'Group']=group; end; " +
            "setup('ZeroDimensionFlipBook',0,2,4,0,0); " +
            "setup('DefaultFrameCountFlipBook',2,3,0,0,0); " +
            "setup('UnclampedFrameCountFlipBook',2,2,8,0,0); " +
            "setup('PartialPixelSizeFlipBook',2,2,4,10,0); " +
            "setup('PixelSizeFlipBook',2,2,4,10,20)");

        var partialPixel = session.Ui.Find("PartialPixelSizeFlipBook")!.Texture!;
        partialPixel.AtlasWidth = 100;
        partialPixel.AtlasHeight = 200;
        var pixel = session.Ui.Find("PixelSizeFlipBook")!.Texture!;
        pixel.AtlasWidth = 100;
        pixel.AtlasHeight = 200;

        session.Lua.Evaluate(
            "ZeroDimensionFlipBookGroup:Play(false,50); " +
            "DefaultFrameCountFlipBookGroup:Play(false,50); " +
            "UnclampedFrameCountFlipBookGroup:Play(false,60); " +
            "PartialPixelSizeFlipBookGroup:Play(false,25); " +
            "PixelSizeFlipBookGroup:Play(false,25)");

        var zeroDimension = session.Ui.Find("ZeroDimensionFlipBook")!.Texture!;
        Assert.Equal(Vector2.Zero, zeroDimension.LocalUv[0]);
        Assert.Equal(Vector2.One, zeroDimension.LocalUv[3]);

        var defaultCount = session.Ui.Find("DefaultFrameCountFlipBook")!.Texture!;
        Assert.Equal(new Vector2(0, .5f), defaultCount.LocalUv[0]);
        Assert.Equal(new Vector2(1f / 3, 1), defaultCount.LocalUv[3]);

        var unclamped = session.Ui.Find("UnclampedFrameCountFlipBook")!.Texture!;
        Assert.Equal(new Vector2(0, 1), unclamped.LocalUv[0]);
        Assert.Equal(new Vector2(.5f, 1.5f), unclamped.LocalUv[3]);

        Assert.Equal(new Vector2(.5f, 0), partialPixel.LocalUv[0]);
        Assert.Equal(new Vector2(1, .5f), partialPixel.LocalUv[3]);
        Assert.Equal(new Vector2(.1f, 0), pixel.LocalUv[0]);
        Assert.Equal(new Vector2(.2f, .1f), pixel.LocalUv[3]);
    }

    [Fact]
    public void XmlScaleAndRotationOriginsUseNativeAnchorAndOffsetGeometry()
    {
        var root = Path.Combine(Path.GetTempPath(), $"wow-addon-lab-{Guid.NewGuid():N}");
        var addon = CreateAddon(
            root,
            "XmlAnimationOrigins",
            ["animations.xml"],
            [
                "<Ui>" +
                "<Frame name=\"OriginScaleFrame\" parent=\"UIParent\">" +
                "<Size x=\"100\" y=\"50\"/>" +
                "<Anchors><Anchor point=\"BOTTOMLEFT\" x=\"100\" y=\"100\"/></Anchors>" +
                "<Animations><AnimationGroup parentKey=\"Anim\">" +
                "<Scale parentKey=\"Scale\" fromScaleX=\"1\" fromScaleY=\"1\" " +
                "toScaleX=\"2\" toScaleY=\"2\" duration=\"1\">" +
                "<Origin point=\"BOTTOMLEFT\"><Offset><AbsDimension x=\"10\" y=\"5\"/>" +
                "</Offset></Origin></Scale>" +
                "</AnimationGroup></Animations></Frame>" +
                "<Frame name=\"OriginRotationFrame\" parent=\"UIParent\">" +
                "<Animations><AnimationGroup parentKey=\"Anim\">" +
                "<Rotation parentKey=\"Rotation\" degrees=\"10\" radians=\"1.57079632679\" " +
                "duration=\"1\"><Origin point=\"TOPLEFT\" x=\"3\" y=\"4\"/></Rotation>" +
                "</AnimationGroup></Animations></Frame>" +
                "</Ui>"
            ]);
        try
        {
            using var session = new EmulatorSession();
            session.Load(addon);

            var scaleFrame = session.Ui.Find("OriginScaleFrame")!;
            var scale = session.Ui.Find(scaleFrame.Children
                .Select(session.Ui.Find)
                .Single(value => value?.AnimationGroup is not null)!
                .Children
                .Select(session.Ui.Find)
                .Single(value => value?.ObjectType == "Scale")!.Id)!.Animation!;
            Assert.Equal(Vector2.One, scale.ScaleFrom);
            Assert.Equal(new Vector2(2, 2), scale.ScaleTo);
            Assert.Equal("BOTTOMLEFT", scale.OriginPoint);
            Assert.Equal(new Vector2(10, 5), scale.OriginOffset);

            session.Lua.Evaluate("OriginScaleFrame.Anim:Play(false,.5)");
            var bounds = session.Ui.ResolveBounds(scaleFrame.Id);
            Assert.Equal(95, bounds.Left, 3);
            Assert.Equal(97.5, bounds.Bottom, 3);
            Assert.Equal(150, bounds.Width, 3);
            Assert.Equal(75, bounds.Height, 3);

            var rotationFrame = session.Ui.Find("OriginRotationFrame")!;
            var rotation = rotationFrame.Children
                .Select(session.Ui.Find)
                .Single(value => value?.AnimationGroup is not null)!
                .Children
                .Select(session.Ui.Find)
                .Single(value => value?.ObjectType == "Rotation")!.Animation!;
            Assert.Equal(90, rotation.Degrees, 3);
            Assert.Equal("TOPLEFT", rotation.OriginPoint);
            Assert.Equal(new Vector2(3, 4), rotation.OriginOffset);
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

