    [Fact]
    public void AtlasProviderDrivesTextureCoordinatesSizeAndLuaMetadata()
    {
        using var session = new EmulatorSession();
        session.AtlasProvider = new TestAtlasProvider();

        Assert.Equal(
            "true:TestAtlas:32:16:32:16:77:test.blp:3:2:4:1:1",
            session.Lua.Evaluate(
                "AtlasTexture=UIParent:CreateTexture('AtlasTexture'); local texture=AtlasTexture; " +
                "local applied=texture:SetAtlas('TestAtlas', true); " +
                "local info=C_Texture.GetAtlasInfo('TestAtlas'); " +
                "local left,top,right,bottom=texture:GetTextureSliceMargins(); " +
                "return tostring(applied)..':'..texture:GetAtlas()..':'..texture:GetWidth()..':'.." +
                "texture:GetHeight()..':'..info.rawSize.x..':'..info.rawSize.y..':'.." +
                "info.file..':'..info.filename..':'..left..':'..top..':'..right..':'.." +
                "bottom..':'..texture:GetTextureSliceMode()"));
        var texture = session.Ui.Find("AtlasTexture")!;
        Assert.Equal((uint)77, texture.Texture!.FileDataId);
        Assert.Equal(32, texture.Texture.AtlasWidth);
        Assert.Equal(16, texture.Texture.AtlasHeight);
        Assert.Equal(
            new UiTextureSliceData(3, 2, 4, 1, UiTextureSliceMode.Tiled),
            texture.Texture.SliceData);
        Assert.Equal(new System.Numerics.Vector2(0.25f, 0.125f), texture.Texture.Uv[0]);
        Assert.Equal(new System.Numerics.Vector2(0.75f, 0.875f), texture.Texture.Uv[3]);
        Assert.Equal(
            "0.000:0.000:1.000:1.000",
            session.Lua.Evaluate(
                "AtlasTexture:SetAtlas('TestAtlas'); AtlasTexture:SetAtlas('TestAtlas'); " +
                "local ulx,uly,_,_,_,_,lrx,lry=AtlasTexture:GetTexCoord(); " +
                "return string.format('%.3f:%.3f:%.3f:%.3f',ulx,uly,lrx,lry)"));
        Assert.Equal(
            "1.000:0.000:0.000:1.000:0.000:0.000:1.000:1.000",
            session.Lua.Evaluate(
                "AtlasTexture:SetTexCoord(1,0,0,1); AtlasTexture:SetAtlas('TestAtlas'); " +
                "local ulx,uly,_,_,_,_,lrx,lry=AtlasTexture:GetTexCoord(); " +
                "AtlasTexture:ResetTexCoord(); " +
                "local rulx,ruly,_,_,_,_,rlrx,rlry=AtlasTexture:GetTexCoord(); " +
                "return string.format('%.3f:%.3f:%.3f:%.3f:%.3f:%.3f:%.3f:%.3f'," +
                "ulx,uly,lrx,lry,rulx,ruly,rlrx,rlry)"));
        Assert.Equal(
            "nil",
            session.Lua.Evaluate(
                "AtlasTexture:SetTexture('Interface\\\\Icons\\\\INV_Misc_QuestionMark'); " +
                "return tostring(AtlasTexture:GetAtlas())"));
        Assert.Equal(
            "true:false",
            session.Lua.Evaluate(
                "return tostring(C_Texture.GetAtlasExists('TestAtlas'))..':'.." +
            "tostring(C_Texture.GetAtlasExists('MissingAtlas'))"));
        Assert.Equal(
            "0:false:false:false",
            session.Lua.Evaluate(
                "local count=select('#',C_Texture.GetAtlasInfo('MissingAtlas')); " +
                "local missingExists=pcall(C_Texture.GetAtlasExists); " +
                "local badExists=pcall(C_Texture.GetAtlasExists,{}); " +
                "local badInfo=pcall(C_Texture.GetAtlasInfo,nil); " +
                "return count..':'..tostring(missingExists)..':'.." +
                "tostring(badExists)..':'..tostring(badInfo)"));
        Assert.Equal(
            "901:902:0:0:TestAtlas:test.blp::0:2:4",
            session.Lua.Evaluate(
                "local atlases=C_Texture.GetAtlasElements('ignored'); " +
                "return table.concat({" +
                "C_Texture.GetAtlasID('TestAtlas')," +
                "C_Texture.GetAtlasElementID('TestAtlas')," +
                "C_Texture.GetAtlasID('MissingAtlas')," +
                "C_Texture.GetAtlasElementID('MissingAtlas')," +
                "atlases[1]," +
                "C_Texture.GetFilenameFromFileDataID(77)," +
                "C_Texture.GetFilenameFromFileDataID(78)," +
                "Enum.TitleIconVersion.Small," +
                "Enum.TitleIconVersionMeta.MaxValue," +
                "Enum.UrlTextureResult.NotAllowed},':')"));
        Assert.Equal(
            "false:false:false:false",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(pcall(C_Texture.GetAtlasID))," +
                "tostring(pcall(C_Texture.GetAtlasElementID,{}))," +
                "tostring(pcall(C_Texture.GetFilenameFromFileDataID))," +
                "tostring(pcall(C_Texture.GetFilenameFromFileDataID,{}))},':')"));

        Assert.Equal(
            "false:0:false:nil",
            session.Lua.Evaluate(
                "TitleIconTexture=UIParent:CreateTexture('TitleIconTexture'); " +
                "TitleIconTexture:SetTexture(77); local callbackReady,callbackFile; " +
                "C_Texture.GetTitleIconTexture('not-registered',Enum.TitleIconVersion.Small," +
                "function(ready,file) callbackReady=ready; callbackFile=file end); " +
                "local ready=C_Texture.IsTitleIconTextureReady(" +
                "'not-registered',Enum.TitleIconVersion.Small); " +
                "C_Texture.SetTitleIconTexture(" +
                "TitleIconTexture,'not-registered',Enum.TitleIconVersion.Small); " +
                "return tostring(callbackReady)..':'..callbackFile..':'.." +
                "tostring(ready)..':'..tostring(TitleIconTexture:GetTexture())"));
        Assert.Equal(
            "nil:false:false:false:false",
            session.Lua.Evaluate(
                "TitleIconTexture:SetTexture(77); " +
                "C_Texture.ClearTitleIconTexture(TitleIconTexture); " +
                "return table.concat({tostring(TitleIconTexture:GetTexture())," +
                "tostring(pcall(C_Texture.ClearTitleIconTexture,UIParent))," +
                "tostring(pcall(C_Texture.GetTitleIconTexture,'id',0,{}))," +
                "tostring(pcall(C_Texture.IsTitleIconTextureReady,'id',3))," +
                "tostring(pcall(C_Texture.SetTitleIconTexture,TitleIconTexture,{},0))},':')"));
        Assert.Equal(
            "77:false:false",
            session.Lua.Evaluate(
                "TitleIconTexture:SetTexture(77); " +
                "C_Texture.SetURLTexture(TitleIconTexture,'https://example.invalid/icon'); " +
                "return table.concat({TitleIconTexture:GetTexture()," +
                "tostring(pcall(C_Texture.SetURLTexture,UIParent,'url'))," +
                "tostring(pcall(C_Texture.SetURLTexture,TitleIconTexture,{}))},':')"));
    }

