    [Fact]
    public void TextureGradientRequiresOrientationAndCompleteQuantizedColorTables()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "false:false:false",
            session.Lua.Evaluate(
                "GradientTexture=UIParent:CreateTexture('GradientTexture'); " +
                "local color={r=1,g=1,b=1,a=1}; " +
                "local invalidOrientation=pcall(GradientTexture.SetGradient, GradientTexture, 'DIAGONAL', color, color); " +
                "local missingAlpha=pcall(GradientTexture.SetGradient, GradientTexture, 'HORIZONTAL', {r=1,g=1,b=1}, color); " +
                "local nonTable=pcall(GradientTexture.SetGradient, GradientTexture, 'VERTICAL', 1, color); " +
                "GradientTexture:SetGradient('vertical', " +
                "{r=-1,g=0.5,b=2,a=0.25}, {r=0.1,g=0.2,b=0.3,a=0.4}); " +
                "return tostring(invalidOrientation)..':'..tostring(missingAlpha)..':'.." +
                "tostring(nonTable)"));

        var gradient = session.Ui.Find("GradientTexture")!.Texture!.Gradient!.Value;
        Assert.Equal("VERTICAL", gradient.Orientation);
        Assert.Equal(0, gradient.Minimum.X);
        Assert.Equal(128 / 255f, gradient.Minimum.Y);
        Assert.Equal(1, gradient.Minimum.Z);
        Assert.Equal(64 / 255f, gradient.Minimum.W);
        Assert.Equal(26 / 255f, gradient.Maximum.X);
        Assert.Equal(51 / 255f, gradient.Maximum.Y);
        Assert.Equal(77 / 255f, gradient.Maximum.Z);
        Assert.Equal(102 / 255f, gradient.Maximum.W);
    }

