    [Fact]
    public void FontStringSizingAndWrappingStateFollowClientParsers()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "false:false:true:-3.5:false:false:true:true:false:false:false:" +
            "3430008:3:false:true:true:3",
            session.Lua.Evaluate(
                "local text=UIParent:CreateFontString(); " +
                "text:SetFont('Fonts\\\\FRIZQT__.TTF', 12, ''); " +
                "local missingHeight=pcall(text.SetFontHeight, text); " +
                "local badHeight=pcall(text.SetFontHeight, text, {}); " +
                "local negativeHeight=pcall(text.SetFontHeight, text, -3.5); " +
                "local storedHeight=text:GetFontHeight(false); " +
                "local missingWrap=pcall(text.SetIndentedWordWrap, text); " +
                "local nilWrap=pcall(text.SetIndentedWordWrap, text, nil); " +
                "text:SetIndentedWordWrap('truthy'); local truthyWrap=text:GetIndentedWordWrap(); " +
                "text:SetIndentedWordWrap(false); local falseWrap=not text:GetIndentedWordWrap(); " +
                "local missingMax=pcall(text.SetMaxLines, text); " +
                "local negativeMax=pcall(text.SetMaxLines, text, -1); " +
                "local tooLargeMax=pcall(text.SetMaxLines, text, 4294967296); " +
                "text:SetMaxLines(305419896.9); local maskedMax=text:GetMaxLines(); " +
                "text:SetMaxLines(3.9); local truncatedMax=text:GetMaxLines(); " +
                "local missingScale=pcall(text.SetTextScale, text); " +
                "text:SetTextScale(2.5); text:SetTextScale(0); " +
                "local zeroPreserved=text:GetTextScale() == 2.5; " +
                "text:SetTextScale(0.00000001); " +
                "local tinyPreserved=text:GetTextScale() == 2.5; " +
                "text:SetTextScale(3); local finalScale=text:GetTextScale(); " +
                "return tostring(missingHeight)..':'..tostring(badHeight)..':'.." +
                "tostring(negativeHeight)..':'..storedHeight..':'.." +
                "tostring(missingWrap)..':'..tostring(nilWrap)..':'.." +
                "tostring(truthyWrap)..':'..tostring(falseWrap)..':'.." +
                "tostring(missingMax)..':'..tostring(negativeMax)..':'.." +
                "tostring(tooLargeMax)..':'..maskedMax..':'..truncatedMax..':'.." +
                "tostring(missingScale)..':'..tostring(zeroPreserved)..':'.." +
                "tostring(tinyPreserved)..':'..finalScale"));
    }

