    [Fact]
    public void FontStringTextWrapAndTextHeightContractsFollowClient()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "true:true:abc:true:false:false:true:true:false:false:true:true:" +
            "false:false:true:true:14",
            session.Lua.Evaluate(
                "local text=UIParent:CreateFontString(); " +
                "text:SetFont('Fonts\\\\FRIZQT__.TTF', 12, ''); " +
                "local initiallyNil=text:GetText() == nil; " +
                "text:SetText(); local missingIsNil=text:GetText() == nil; " +
                "text:SetText('abc'); local content=text:GetText(); " +
                "text:SetText(''); local emptyIsNil=text:GetText() == nil; " +
                "local missingWord=pcall(text.SetWordWrap, text); " +
                "local nilWord=pcall(text.SetWordWrap, text, nil); " +
                "text:SetWordWrap('truthy'); local wordTruthy=text:CanWordWrap(); " +
                "text:SetWordWrap(false); local wordFalse=not text:CanWordWrap(); " +
                "local missingNonSpace=pcall(text.SetNonSpaceWrap, text); " +
                "local nilNonSpace=pcall(text.SetNonSpaceWrap, text, nil); " +
                "text:SetNonSpaceWrap('truthy'); local nonSpaceTruthy=text:CanNonSpaceWrap(); " +
                "text:SetNonSpaceWrap(false); local nonSpaceFalse=not text:CanNonSpaceWrap(); " +
                "local missingHeight=pcall(text.SetTextHeight, text); " +
                "local badHeight=pcall(text.SetTextHeight, text, {}); " +
                "text:SetTextHeight(14); text:SetTextHeight(0); " +
                "local zeroPreserved=text:GetFontHeight(false) == 14; " +
                "text:SetTextHeight(-3); " +
                "local negativePreserved=text:GetFontHeight(false) == 14; " +
                "return tostring(initiallyNil)..':'..tostring(missingIsNil)..':'..content..':'.." +
                "tostring(emptyIsNil)..':'..tostring(missingWord)..':'..tostring(nilWord)..':'.." +
                "tostring(wordTruthy)..':'..tostring(wordFalse)..':'.." +
                "tostring(missingNonSpace)..':'..tostring(nilNonSpace)..':'.." +
                "tostring(nonSpaceTruthy)..':'..tostring(nonSpaceFalse)..':'.." +
                "tostring(missingHeight)..':'..tostring(badHeight)..':'.." +
                "tostring(zeroPreserved)..':'..tostring(negativePreserved)..':'.." +
                "text:GetFontHeight(false)"));

        Assert.Equal(
            "false:false:4095",
            session.Lua.Evaluate(
                "local text=UIParent:CreateFontString(); " +
                "text:SetFont('Fonts\\\\FRIZQT__.TTF', 12, ''); " +
                "local badText=pcall(text.SetText, text, {}); " +
                "local badFit=pcall(text.SetTextToFit, text, {}); " +
                "text:SetFormattedText('%s', string.rep('x', 5000)); " +
                "return tostring(badText)..':'..tostring(badFit)..':'..#text:GetText()"));
    }

