    [Fact]
    public void XmlMouseAndDragRegistrationsReachTheNativeInputState()
    {
        var root = Path.Combine(Path.GetTempPath(), $"wow-addon-lab-{Guid.NewGuid():N}");
        var addon = CreateAddon(
            root,
            "XmlInputRegistrations",
            ["layout.xml"],
            [
                "<Ui><Frame name=\"XmlDragFrame\" enableMouse=\"true\" " +
                "registerForDrag=\"LeftButton,RightButton\"><Size x=\"100\" y=\"100\"/>" +
                "<Anchors><Anchor point=\"BOTTOMLEFT\"/></Anchors><Scripts>" +
                "<OnDragStart>XmlDragStarts=(XmlDragStarts or 0)+1</OnDragStart>" +
                "<OnDragStop>XmlDragStops=(XmlDragStops or 0)+1</OnDragStop>" +
                "</Scripts></Frame><Button name=\"XmlClickButton\" enableMouse=\"true\" " +
                "registerForClicks=\"LeftButtonDown,RightButtonUp\"><Size x=\"100\" y=\"100\"/>" +
                "<Anchors><Anchor point=\"BOTTOMLEFT\" x=\"200\"/></Anchors><Scripts>" +
                "<OnClick>XmlClicks=(XmlClicks or '')..button..':'..tostring(down)..','</OnClick>" +
                "</Scripts></Button></Ui>"
            ]);
        try
        {
            using var session = new EmulatorSession();
            session.Load(addon);

            session.MouseMove(20, 20);
            session.MouseButton("LeftButton", true);
            session.MouseMove(30, 30);
            session.MouseButton("LeftButton", false);

            Assert.Equal("1:1", session.Lua.Evaluate("return XmlDragStarts..':'..XmlDragStops"));
            var clickButton = session.Ui.Find("XmlClickButton")!;
            Assert.Contains("LeftButtonDown", clickButton.ClickRegistrations);
            Assert.Contains("RightButtonUp", clickButton.ClickRegistrations);
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

