    [Fact]
    public void FrameLevelStrataFixedFlagsAndPublicRangesFollowNativeRules()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "21:21:21:DIALOG:DIALOG:LOW:10000:false:false:false:false:true:true:false:false:30:31:true",
            session.Lua.Evaluate(
                "(function() " +
                "local parent=CreateFrame('Frame',nil,UIParent); " +
                "parent:SetFrameStrata('DIALOG'); parent:SetFrameLevel(20); " +
                "local child=CreateFrame('Frame',nil,parent); " +
                "local initial=child:GetFrameLevel(); " +
                "child:SetFixedFrameLevel(true); parent:SetFrameLevel(30); " +
                "local fixed=child:GetFrameLevel(); child:SetFrameLevel(99); " +
                "local ignored=child:GetFrameLevel(); " +
                "child:SetFixedFrameStrata(true); parent:SetFrameStrata('HIGH'); " +
                "local fixedStrata=child:GetFrameStrata(); " +
                "child:SetFixedFrameStrata(false); local inherited=child:GetFrameStrata(); " +
                "parent:SetFrameStrata('LOW'); local changed=child:GetFrameStrata(); " +
                "child:SetFixedFrameLevel(false); child:SetFrameLevel(65535); " +
                "local capped=child:GetFrameLevel(); " +
                "local missingLevel=pcall(child.SetFrameLevel,child); " +
                "local negativeLevel=pcall(child.SetFrameLevel,child,-1); " +
                "local invalidStrata=pcall(child.SetFrameStrata,child,'BOGUS'); " +
                "local missingFixed=pcall(child.SetFixedFrameLevel,child); " +
                "local nilFixedLevel=pcall(child.SetFixedFrameLevel,child,nil); " +
                "local nilFixedStrata=pcall(child.SetFixedFrameStrata,child,nil); " +
                "local initialUsing=child:IsUsingParentLevel(); " +
                "local missingUsing=pcall(child.SetUsingParentLevel,child); " +
                "child:SetUsingParentLevel(true); local parentLevel=child:GetFrameLevel(); " +
                "child:SetUsingParentLevel(nil); local childLevel=child:GetFrameLevel(); " +
                "local nilUsing=pcall(child.SetUsingParentLevel,child,nil); " +
                "return table.concat({initial,fixed,ignored,fixedStrata,inherited,changed,capped," +
                "tostring(missingLevel),tostring(negativeLevel),tostring(invalidStrata),tostring(missingFixed)," +
                "tostring(nilFixedLevel),tostring(nilFixedStrata),tostring(initialUsing),tostring(missingUsing)," +
                "parentLevel,childLevel,tostring(nilUsing)},':') " +
                "end)()"));
    }

