    [Fact]
    public void VisibleFramePickingReturnsTheTopmostDrawnRegionOwnerWithoutMouseInput()
    {
        var ui = new UiSystem();
        ui.Resize(400, 300);
        var root = ui.Create("Frame", "UIParent", null);

        var back = ui.Create("Frame", "Back", root.Id);
        back.Width = 200;
        back.Height = 100;
        back.Anchors.Add(new UiAnchor("CENTER", root.Id, "CENTER", 0, 0));
        var backTexture = ui.Create("Texture", "BackTexture", back.Id);
        backTexture.AllPointsTargetId = back.Id;
        backTexture.Texture!.IsColor = true;

        var front = ui.Create("Frame", "Front", root.Id);
        front.Width = 100;
        front.Height = 60;
        front.Anchors.Add(new UiAnchor("CENTER", root.Id, "CENTER", 0, 0));
        ui.SetFrameLevel(front, 10);
        var frontTexture = ui.Create("Texture", "FrontTexture", front.Id);
        frontTexture.AllPointsTargetId = front.Id;
        frontTexture.Texture!.IsColor = true;

        var point = new System.Numerics.Vector2(200, 150);
        Assert.Null(ui.HitTest(point));
        Assert.Equal(front.Id, ui.HitTestVisibleFrame(point)?.Id);

        front.Shown = false;
        Assert.Equal(back.Id, ui.HitTestVisibleFrame(point)?.Id);
    }

    [Fact]
    public void RaisedToplevelSubtreeRendersAndHitTestsAboveEarlierHigherLevelFrame()
    {
        var ui = new UiSystem();
        ui.Resize(400, 300);
        var root = ui.Create("Frame", "UIParent", null);
        var manager = ui.Create("Frame", "Manager", root.Id);
        manager.FrameStrata = "DIALOG";
        ui.SetFrameLevel(manager, 10003);
        manager.Width = 300;
        manager.Height = 200;
        manager.MouseEnabled = true;
        manager.Anchors.Add(new UiAnchor("CENTER", root.Id, "CENTER", 0, 0));

        var helpTip = ui.Create("Frame", "HelpTip", manager.Id);
        helpTip.FrameStrata = "DIALOG";
        ui.SetFrameLevel(helpTip, 9000);
        ui.SetToplevel(helpTip, true);
        ui.Raise(helpTip);
        helpTip.Width = 180;
        helpTip.Height = 80;
        helpTip.Anchors.Add(new UiAnchor("CENTER", manager.Id, "CENTER", 0, 0));
        var next = ui.Create("Button", "Next", helpTip.Id);
        next.Width = 100;
        next.Height = 30;
        next.Anchors.Add(new UiAnchor("CENTER", helpTip.Id, "CENTER", 0, 0));

        var order = ui.RenderOrder().ToList();
        Assert.True(order.IndexOf(manager) < order.IndexOf(helpTip));
        Assert.True(order.IndexOf(helpTip) < order.IndexOf(next));
        Assert.Equal(next.Id, ui.HitTest(new System.Numerics.Vector2(200, 150))?.Id);
    }

