    [Fact]
    public void RaisedToplevelFrameDoesNotOccludeInputForItsOwnDescendantButton()
    {
        using var session = new EmulatorSession();
        session.Lua.Evaluate(
            "RaisedRoot=CreateFrame('Frame','RaisedRoot',UIParent); " +
            "RaisedRoot:SetSize(300,200); RaisedRoot:SetPoint('CENTER'); " +
            "RaisedRoot:SetToplevel(true); RaisedRoot:EnableMouse(true); " +
            "RaisedBorder=CreateFrame('Frame','RaisedBorder',RaisedRoot); " +
            "RaisedBorder:SetAllPoints(RaisedRoot); RaisedBorder:SetFrameStrata('HIGH'); " +
            "RaisedClose=CreateFrame('Button','RaisedClose',RaisedBorder); " +
            "RaisedClose:SetSize(24,24); RaisedClose:SetPoint('CENTER'); " +
            "RaisedClose:SetFrameStrata('MEDIUM'); " +
            "RaisedClose:SetScript('OnClick',function() RaisedRoot:Hide() end); " +
            "RaisedRoot:Raise()");

        session.MouseMove(800, 450);

        Assert.Equal(
            "true:true:true",
            session.Lua.Evaluate(
                "local focus=GetMouseFoci()[1]; return table.concat({" +
                "tostring(focus==RaisedClose),tostring(RaisedClose:IsMouseMotionFocus())," +
                "tostring(RaisedClose:IsDrawLayerEnabled('HIGHLIGHT'))},':')"));

        session.MouseButton("LeftButton", true);
        session.MouseButton("LeftButton", false);

        Assert.Equal("false", session.Lua.Evaluate("return tostring(RaisedRoot:IsShown())"));
    }

    [Fact]
    public void MouseScriptsImplicitlyEnableInputAndWheelTargetsIgnoreMotionFocus()
    {
        using var session = new EmulatorSession();
        session.Lua.Evaluate(
            "wheelResult=''; " +
            "WheelUnder=CreateFrame('Frame','WheelUnder',UIParent); " +
            "WheelUnder:SetSize(200,200); WheelUnder:SetPoint('CENTER'); " +
            "WheelUnder:SetScript('OnMouseWheel',function(_,delta) wheelResult='under:'..delta end); " +
            "WheelOverlay=CreateFrame('Frame','WheelOverlay',UIParent); " +
            "WheelOverlay:SetSize(200,200); WheelOverlay:SetPoint('CENTER'); " +
            "WheelOverlay:SetFrameLevel(WheelUnder:GetFrameLevel()+1); " +
            "WheelOverlay:SetScript('OnEnter',function() end)");

        Assert.Equal(
            "true:true",
            session.Lua.Evaluate(
                "tostring(WheelUnder:IsMouseWheelEnabled())..':'.." +
                "tostring(WheelOverlay:IsMouseEnabled())"));

        session.MouseMove(800, 450);
        session.MouseWheel(-1);
        Assert.Equal("under:-1", session.Lua.Evaluate("wheelResult"));

        session.Lua.Evaluate(
            "WheelOverlay:SetScript('OnMouseWheel'," +
            "function(_,delta) wheelResult='overlay:'..delta end)");
        session.MouseWheel(1);
        Assert.Equal("overlay:1", session.Lua.Evaluate("wheelResult"));

        session.Lua.Evaluate("WheelOverlay:SetScript('OnMouseWheel',nil)");
        session.MouseWheel(-1);
        Assert.Equal("under:-1", session.Lua.Evaluate("wheelResult"));
    }

