    [Fact]
    public void ModelSceneCameraSettersUseRequiredFloatsAndNativeClamps()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "false:false:false:true:true:true:true:true:true:false:false",
            session.Lua.Evaluate(
                "(function() " +
                "local scene=CreateFrame('ModelScene','StrictCameraScene',UIParent); " +
                "scene:SetSize(800,600); " +
                "scene:SetCameraPosition(1,2,3); " +
                "local badPosition=pcall(scene.SetCameraPosition,scene,9,8); " +
                "scene:SetCameraOrientationByYawPitchRoll(.2,.3,.4); " +
                "local badOrientation=pcall(" +
                "scene.SetCameraOrientationByYawPitchRoll,scene,.9,.8); " +
                "local badFov=pcall(scene.SetCameraFieldOfView,scene,1/0); " +
                "scene:SetCameraFieldOfView(-1); " +
                "local lowFov=scene:GetCameraFieldOfView()==0; " +
                "scene:SetCameraFieldOfView(99); " +
                "local highFov=math.abs(scene:GetCameraFieldOfView()-math.pi*2)<.00001; " +
                "scene:SetCameraNearClip(-3); scene:SetCameraFarClip(-4); " +
                "local nearZero=scene:GetCameraNearClip()==0; " +
                "local farZero=scene:GetCameraFarClip()==0; " +
                "scene:SetViewInsets(1,2,3,4); " +
                "local insetCount=select('#',scene:GetViewInsets()); " +
                "local l,r,t,b=scene:GetViewInsets(); " +
                "local insetsMatch=l==1 and r==2 and t==3 and b==4; " +
                "local badInsets=pcall(scene.SetViewInsets,scene,9,8,7); " +
                "local badProject=pcall(scene.Project3DPointTo2D,scene,0,1); " +
                "return table.concat({tostring(badPosition),tostring(badOrientation)," +
                "tostring(badFov),tostring(lowFov),tostring(highFov)," +
                "tostring(nearZero),tostring(farZero),tostring(insetCount==4)," +
                "tostring(insetsMatch),tostring(badInsets),tostring(badProject)},':') end)()"));

        var scene = session.Ui.Find("StrictCameraScene")!.ModelScene!;
        Assert.Equal(new Vector3(1, 2, 3), scene.CameraPosition);
        Assert.Equal(0.2f, scene.Yaw);
        Assert.Equal(0.3f, scene.Pitch);
        Assert.Equal(0.4f, scene.Roll);
        Assert.Equal(MathF.Tau, scene.FieldOfView);
        Assert.Equal(0, scene.NearClip);
        Assert.Equal(0, scene.FarClip);
        Assert.Equal(new UiInsets(1, 2, 3, 4), scene.ViewInsets);
    }

    [Fact]
    public void ModelSceneLightingFogAndActorFanOutUseNativeContracts()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "false:false:false:false:false:false:false:false:false:true:false",
            session.Lua.Evaluate(
                "(function() " +
                "local scene=CreateFrame('ModelScene','StrictStateScene',UIParent); " +
                "local first=scene:CreateActor('StrictStateActorOne'); " +
                "scene:SetDesaturation(2); " +
                "local second=scene:CreateActor('StrictStateActorTwo'); " +
                "first:SetModelByFileID(1); second:SetModelByFileID(2); " +
                "scene:SetPaused(true); scene:SetPaused(false,false); " +
                "scene:SetLightAmbientColor(.1,.2,.3,{}); " +
                "scene:SetLightDiffuseColor(2,-1,.5); " +
                "scene:SetLightDirection(1,2,3); scene:SetLightPosition(4,5,6); " +
                "scene:SetLightType(1); scene:SetLightType(2); " +
                "scene:SetLightVisible(); local visibleByDefault=scene~=nil; " +
                "scene:SetLightVisible(nil); " +
                "scene:SetFogColor(.25,.5,.75,{}); scene:SetFogFar(42); scene:ClearFog(); " +
                "scene:SetAllowOverlappedModels(true); " +
                "local badDesaturation=pcall(scene.SetDesaturation,scene); " +
                "local badPaused=pcall(scene.SetPaused,scene); " +
                "local badAmbient=pcall(scene.SetLightAmbientColor,scene,1,1); " +
                "local badDiffuse=pcall(scene.SetLightDiffuseColor,scene,1,1); " +
                "local badDirection=pcall(scene.SetLightDirection,scene,1,2); " +
                "local badPosition=pcall(scene.SetLightPosition,scene,1,2); " +
                "local badType=pcall(scene.SetLightType,scene); " +
                "local badFogColor=pcall(scene.SetFogColor,scene,1,1); " +
                "local badFogFar=pcall(scene.SetFogFar,scene); " +
                "local badOverlap=pcall(scene.SetAllowOverlappedModels,scene); " +
                "scene:SetAllowOverlappedModels(nil); " +
                "return table.concat({tostring(badDesaturation),tostring(badPaused)," +
                "tostring(badAmbient),tostring(badDiffuse),tostring(badDirection)," +
                "tostring(badPosition),tostring(badType),tostring(badFogColor)," +
                "tostring(badFogFar),tostring(visibleByDefault)," +
                "tostring(badOverlap)},':') end)()"));

        var sceneObject = session.Ui.Find("StrictStateScene")!;
        var scene = sceneObject.ModelScene!;
        var first = session.Ui.Find("StrictStateActorOne")!;
        var second = session.Ui.Find("StrictStateActorTwo")!;

        Assert.Equal(0, sceneObject.ModelDesaturation);
        Assert.Equal(1, first.ModelDesaturation);
        Assert.Equal(0, second.ModelDesaturation);
        Assert.False(first.ModelPaused);
        Assert.True(first.ModelGlobalPaused);
        Assert.False(second.ModelPaused);
        Assert.True(second.ModelGlobalPaused);
        Assert.Equal(
            new Vector3(26 / 255f, 51 / 255f, 77 / 255f),
            scene.AmbientLight);
        Assert.Equal(new Vector3(1, 0, 128 / 255f), scene.DiffuseLight);
        Assert.Equal(Vector3.Normalize(new Vector3(1, 2, 3)), scene.LightDirection);
        Assert.Equal(new Vector3(4, 5, 6), scene.LightPosition);
        Assert.Equal(1, scene.LightType);
        Assert.False(scene.LightVisible);
        Assert.Equal(new Vector4(64 / 255f, 128 / 255f, 191 / 255f, 1), scene.FogColor);
        Assert.Equal(10_000_000, scene.FogNear);
        Assert.Equal(100_000_000, scene.FogFar);
        Assert.False(scene.FogEnabled);
        Assert.False(scene.AllowOverlappedModels);
    }

