                "local creaturePath=actor:GetModelPath(); " +
                "local missingUnit=pcall(actor.SetModelByUnit,actor); " +
                "local invalidUnit=actor:SetModelByUnit('not-a-unit'); " +
                "local unitSuccess=actor:SetModelByUnit('player'); " +
                "local unitAutoDress=actor:GetAutoDress(); " +
                "actor:SetModelByUnit('player',false,false); " +
                "local explicitAutoDress=actor:GetAutoDress(); " +
                "actor:SetPaused(true); actor:ClearModel(); " +
                "local paused,globalPaused=actor:GetPaused(); " +
                "return table.concat({initialPath,tostring(initialLoaded),tostring(initialGeo)," +
                "tostring(initialAutoDress),tostring(badAutoDress)," +
                "tostring(actor:GetAutoDress()),tostring(zeroFile),tostring(fileSuccess)," +
                "tostring(fileLoaded),filePath,tostring(pathSuccess),path," +
                "tostring(badCreature),preservedPath,tostring(creatureSuccess),creaturePath," +
                "tostring(missingUnit),tostring(invalidUnit),tostring(unitSuccess)," +
                "tostring(unitAutoDress),tostring(explicitAutoDress)," +
                "tostring(actor:IsLoaded()),tostring(actor:IsGeoReady())," +
                "tostring(paused),tostring(globalPaused),actor:GetModelPath()},':') end)()"));

        var actor = session.Ui.Find("StrictResourceActor")!;
        Assert.Null(actor.ModelFileDataId);
        Assert.Null(actor.ModelCreatureDisplayId);
        Assert.Null(actor.ModelPath);
        Assert.Null(actor.ModelUnitToken);
        Assert.False(actor.ModelPaused);
        Assert.False(actor.ModelGlobalPaused);
    }

    [Fact]
    public void ModelSceneCreateActorAppliesItsXmlTemplateMixinAndLifecycle()
    {
        var root = Path.Combine(Path.GetTempPath(), $"wow-addon-lab-{Guid.NewGuid():N}");
        var addon = CreateAddon(
            root,
            "ModelSceneActorTemplateTest",
            ["main.lua", "layout.xml"],
            [
                "ActorLifecycleMixin={" +
                "OnLoad=function(self) self.loadedFromActorTemplate=true end," +
                "OnModelLoaded=function(self) self.modelLoadedFromActorTemplate=true; " +
                "self.modelLifecycle=(self.modelLifecycle or '')..'loaded,' end," +
                "OnModelLoading=function(self) " +
                "self.modelLifecycle=(self.modelLifecycle or '')..'loading,' end," +
                "OnModelCleared=function(self) self.modelClearedFromActorTemplate=true; " +
                "self.modelClearedWhileLoaded=self:IsLoaded(); " +
                "self.modelLifecycle=(self.modelLifecycle or '')..'cleared' end," +
                "OnReleased=function(self) self.releasedFromActorTemplate=true end}",
                "<Ui><Actor name=\"ActorLifecycleTemplate\" virtual=\"true\" " +
                "mixin=\"ActorLifecycleMixin\">" +
                "<Scripts><OnLoad method=\"OnLoad\"/>" +
                "<OnModelLoaded method=\"OnModelLoaded\"/>" +
                "<OnModelLoading method=\"OnModelLoading\"/>" +
                "<OnModelCleared method=\"OnModelCleared\"/></Scripts></Actor></Ui>"
            ]);
        try
        {
            using var session = new EmulatorSession();
            var resources = new TestModelResourceProvider();
            resources.ExistingFileDataIds.Add(123);
            session.ModelResourceProvider = resources;
            session.Load(addon);

            Assert.Equal(
                "true:function:ModelSceneActor:true:true:789:loaded,loading,",
                session.Lua.Evaluate(
                    "(function() local scene=CreateFrame('ModelScene',nil,UIParent); " +
                    "local actor=scene:CreateActor('ActorLifecycleInstance','ActorLifecycleTemplate'); " +
                    "actor:SetModelByFileID(123); actor:PlayAnimationKit(456); " +
                    "actor:SetSpellVisualKit(789); actor:UseUnitSheatheCategory(true); " +
                    "actor:StopAnimationKit(); " +
                    "return tostring(actor.loadedFromActorTemplate)..':'.." +
                    "type(actor.OnReleased)..':'..actor:GetObjectType()..':'.." +
                    "tostring(actor:IsLoaded())..':'.." +
                    "tostring(actor.modelLoadedFromActorTemplate)..':'.." +
                    "actor:GetSpellVisualKit()..':'..actor.modelLifecycle end)()"));
            var actor = session.Ui.Find("ActorLifecycleInstance")!;
            Assert.Null(actor.ModelAnimationKitId);
            Assert.Equal((uint)789, actor.ModelSpellVisualKitId);
            Assert.True(actor.ModelUsesUnitSheatheCategory);
            Assert.Equal(
                "false:true:false:loaded,loading,cleared",
                session.Lua.Evaluate(
                    "ActorLifecycleInstance:ClearModel(); return " +
                    "tostring(ActorLifecycleInstance:IsLoaded())..':'.." +
                    "tostring(ActorLifecycleInstance.modelClearedFromActorTemplate)..':'.." +
                    "tostring(ActorLifecycleInstance.modelClearedWhileLoaded)..':'.." +
                    "ActorLifecycleInstance.modelLifecycle"));
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

    [Fact]
    public void ModelSceneActorAnimationKitSpellVisualAndSheatheUseNativeContracts()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "false:false:false:4294967295:false:false",
            session.Lua.Evaluate(
                "(function() " +
                "local scene=CreateFrame('ModelScene',nil,UIParent); " +
                "local actor=scene:CreateActor('ActorControlContract'); " +
                "actor:PlayAnimationKit(-7,true); " +
                "local missingKit=pcall(actor.PlayAnimationKit,actor); " +
                "local invalidKit=pcall(actor.PlayAnimationKit,actor,'bad'); " +
                "actor:SetSpellVisualKit(-1,true); " +
                "local invalidVisual=pcall(actor.SetSpellVisualKit,actor,'bad'); " +
                "actor:UseUnitSheatheCategory(true); " +
                "local missingSheathe=pcall(actor.UseUnitSheatheCategory,actor); " +
                "return table.concat({" +
                "tostring(missingKit),tostring(invalidKit)," +
                "tostring(invalidVisual),tostring(actor:GetSpellVisualKit())," +
                "tostring(missingSheathe),tostring(actor:IsLoaded())},':') end)()"));

        var actor = session.Ui.Find("ActorControlContract")!;
        Assert.Equal(-7, actor.ModelAnimationKitId);
        Assert.True(actor.ModelAnimationKitLooping);
        Assert.Equal(uint.MaxValue, actor.ModelSpellVisualKitId);
        Assert.True(actor.ModelSpellVisualOneShot);
        Assert.True(actor.ModelUsesUnitSheatheCategory);

        Assert.Equal(
            "0",
            session.Lua.Evaluate(
                "ActorControlContract:SetSpellVisualKit(nil); " +
                "ActorControlContract:PlayAnimationKit(12,nil); " +
                "ActorControlContract:UseUnitSheatheCategory(nil); " +
                "return ActorControlContract:GetSpellVisualKit()"));
        Assert.Equal(12, actor.ModelAnimationKitId);
        Assert.False(actor.ModelAnimationKitLooping);
        Assert.Equal((uint)0, actor.ModelSpellVisualKitId);
        Assert.False(actor.ModelSpellVisualOneShot);
        Assert.False(actor.ModelUsesUnitSheatheCategory);

        session.Lua.Evaluate("ActorControlContract:StopAnimationKit()");
        Assert.Null(actor.ModelAnimationKitId);
        Assert.False(actor.ModelAnimationKitLooping);
    }

    [Fact]
    public void ModelSceneActorAnimationAndBlendOperationUseNativeContracts()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "0:-1:1",
            session.Lua.Evaluate(
                "local scene=CreateFrame('ModelScene',nil,UIParent); " +
                "local actor=scene:CreateActor('ActorAnimationContract'); " +
                "return actor:GetAnimation()..':'..actor:GetAnimationVariation()..':'.." +
                "actor:GetAnimationBlendOperation()"));

        session.Lua.Evaluate(
            "ActorAnimationContract:SetAnimation(91,4.9,2.5,1.2345); " +
            "ActorAnimationContract:SetAnimationBlendOperation(0)");
        var actor = session.Ui.Find("ActorAnimationContract")!;
        Assert.Equal((ushort)91, actor.ModelAnimationId);
        Assert.Equal(4, actor.ModelAnimationVariation);
        Assert.Equal(2.5f, actor.ModelAnimationSpeed);
        Assert.Equal(1234, actor.ModelAnimationTimeOffsetMilliseconds);
        Assert.Equal(0, actor.ModelAnimationBlendOperation);
        Assert.Equal(
            "91:4:0",
            session.Lua.Evaluate(
                "return ActorAnimationContract:GetAnimation()..':'.." +
                "ActorAnimationContract:GetAnimationVariation()..':'.." +
                "ActorAnimationContract:GetAnimationBlendOperation()"));

        Assert.Equal(
            "true:true:false:false",
            session.Lua.Evaluate(
                "local nonNumeric=pcall(ActorAnimationContract.SetAnimation," +
                "ActorAnimationContract,'bad'); " +
                "local outOfRange=pcall(ActorAnimationContract.SetAnimation," +
                "ActorAnimationContract,1858); " +
                "local badSpeed=pcall(ActorAnimationContract.SetAnimation," +
                "ActorAnimationContract,7,nil,'bad'); " +
                "local badBlend=pcall(ActorAnimationContract.SetAnimationBlendOperation," +
                "ActorAnimationContract,2); " +
                "return table.concat({tostring(nonNumeric),tostring(outOfRange)," +
                "tostring(badSpeed),tostring(badBlend)},':')"));
        Assert.Equal((ushort)91, actor.ModelAnimationId);
        Assert.Equal(4, actor.ModelAnimationVariation);
        Assert.Equal(2.5f, actor.ModelAnimationSpeed);
        Assert.Equal(1234, actor.ModelAnimationTimeOffsetMilliseconds);
        Assert.Equal(0, actor.ModelAnimationBlendOperation);

        session.Lua.Evaluate(
            "ActorAnimationContract:SetAnimation('65536'); " +
            "ActorAnimationContract:SetAnimationBlendOperation(1)");
        Assert.Equal((ushort)0, actor.ModelAnimationId);
        Assert.Equal(-1, actor.ModelAnimationVariation);
        Assert.Equal(1f, actor.ModelAnimationSpeed);
        Assert.Equal(0, actor.ModelAnimationTimeOffsetMilliseconds);
        Assert.Equal(1, actor.ModelAnimationBlendOperation);
    }

    [Fact]
    public void ModelSceneActorMountOperationsUseNativeContracts()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "false:1:false:false:false",
            session.Lua.Evaluate(
                "(function() " +
                "local scene=CreateFrame('ModelScene',nil,UIParent); " +
                "local mount=scene:CreateActor('MountContract'); " +
                "local rider=scene:CreateActor('RiderContract'); " +
                "local unloaded=mount:AttachToMount(rider); " +
                "local scale=mount:CalculateMountScale(rider); " +
                "local badAttach=pcall(mount.AttachToMount,mount,UIParent); " +
                "local badScale=pcall(mount.CalculateMountScale,mount,nil); " +
                "local badDetach=pcall(mount.DetachFromMount,mount,UIParent); " +
                "return table.concat({tostring(unloaded),tostring(scale)," +
                "tostring(badAttach),tostring(badScale),tostring(badDetach)},':') end)()"));

        session.Lua.Evaluate(
            "MountContract:SetModelByFileID(100); " +
            "RiderContract:SetModelByFileID(200)");
        Assert.Equal(
            "true:91:0:true",
            session.Lua.Evaluate(
                "local attached=MountContract:AttachToMount(RiderContract); " +
                "return table.concat({tostring(attached),RiderContract:GetAnimation()," +
                "RiderContract:GetAnimationVariation()," +
                "tostring(MountContract:DetachFromMount(RiderContract))},':')"));

        var mount = session.Ui.Find("MountContract")!;
        var rider = session.Ui.Find("RiderContract")!;
        Assert.Null(mount.ModelMountedRiderActorId);
        Assert.Null(rider.ModelMountedToActorId);

        Assert.Equal(
            "true:123:4294967295",
            session.Lua.Evaluate(
                "local attached=MountContract:AttachToMount(RiderContract,123,-1); " +
                "return table.concat({tostring(attached),RiderContract:GetAnimation()," +
                "RiderContract:GetSpellVisualKit()},':')"));
        Assert.Equal(rider.Id, mount.ModelMountedRiderActorId);
        Assert.Equal(mount.Id, rider.ModelMountedToActorId);
        Assert.Equal((ushort)123, rider.ModelAnimationId);
        Assert.Equal((uint)uint.MaxValue, rider.ModelSpellVisualKitId);

        Assert.Equal(
            "false:false",
            session.Lua.Evaluate(
                "MountContract:ClearModel(); " +
                "return tostring(MountContract:DetachFromMount(RiderContract))..':'.." +
                "tostring(pcall(MountContract.AttachToMount,MountContract," +
                "RiderContract,1858))"));
        Assert.Equal(rider.Id, mount.ModelMountedRiderActorId);
        Assert.Equal(mount.Id, rider.ModelMountedToActorId);
    }

    [Fact]
    public void ModelPresentationFlagsUseActorAndDressUpModelContracts()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "false:false:false:false:false:false:false:false",
            session.Lua.Evaluate(
                "(function() " +
                "local scene=CreateFrame('ModelScene',nil,UIParent); " +
                "local actor=scene:CreateActor('PresentationActor'); " +
                "local a=pcall(actor.SetObeyHideInTransmogFlag,actor); " +
                "local b=pcall(actor.SetUseTransmogChoices,actor); " +
                "local c=pcall(actor.SetUseTransmogSkin,actor); " +
                "local d=pcall(actor.SetSheathed,actor); " +
                "return table.concat({tostring(actor:GetObeyHideInTransmogFlag())," +
                "tostring(actor:GetUseTransmogChoices())," +
                "tostring(actor:GetUseTransmogSkin()),tostring(actor:GetSheathed())," +
                "tostring(a),tostring(b),tostring(c),tostring(d)},':') end)()"));

        Assert.Equal(
            "true:true:true:true",
            session.Lua.Evaluate(
                "PresentationActor:SetObeyHideInTransmogFlag(true); " +
                "PresentationActor:SetUseTransmogChoices(true); " +
                "PresentationActor:SetUseTransmogSkin(true); " +
                "PresentationActor:SetSheathed(true,true); " +
                "PresentationActor:SetUseCenterForOrigin(true,false,true); " +
                "return table.concat({" +
                "tostring(PresentationActor:GetObeyHideInTransmogFlag())," +
                "tostring(PresentationActor:GetUseTransmogChoices())," +
                "tostring(PresentationActor:GetUseTransmogSkin())," +
                "tostring(PresentationActor:GetSheathed())},':')"));
        var actor = session.Ui.Find("PresentationActor")!;
        Assert.True(actor.ModelHideWeapons);
        Assert.True(actor.ModelUseCenterForOriginX);
        Assert.False(actor.ModelUseCenterForOriginY);
        Assert.True(actor.ModelUseCenterForOriginZ);

        Assert.Equal(
            "true:true:true:true:false:false:false:false",
            session.Lua.Evaluate(
                "(function() " +
                "local model=CreateFrame('DressUpModel','PresentationDressUp',UIParent); " +
                "model:SetObeyHideInTransmogFlag(true); " +
                "model:SetUseTransmogChoices(true); model:SetUseTransmogSkin(true); " +
                "model:SetSheathed(true,true); " +
                "local before={model:GetObeyHideInTransmogFlag()," +
                "model:GetUseTransmogChoices(),model:GetUseTransmogSkin()," +
                "model:GetSheathed()}; " +
                "model:SetObeyHideInTransmogFlag(); model:SetUseTransmogChoices(); " +
                "model:SetUseTransmogSkin(); model:SetSheathed(); " +
                "return table.concat({tostring(before[1]),tostring(before[2])," +
                "tostring(before[3]),tostring(before[4])," +
                "tostring(model:GetObeyHideInTransmogFlag())," +
                "tostring(model:GetUseTransmogChoices())," +
                "tostring(model:GetUseTransmogSkin())," +
                "tostring(model:GetSheathed())},':') end)()"));
        Assert.False(session.Ui.Find("PresentationDressUp")!.ModelHideWeapons);

        session.Lua.Evaluate(
            "PresentationActor:SetObeyHideInTransmogFlag(nil); " +
            "PresentationActor:SetUseTransmogChoices(nil); " +
            "PresentationActor:SetUseTransmogSkin(nil); " +
            "PresentationActor:SetSheathed(nil)");
        Assert.False(actor.ModelObeyHideInTransmogFlag);
        Assert.False(actor.ModelUseTransmogChoices);
        Assert.False(actor.ModelUseTransmogSkin);
        Assert.False(actor.ModelSheathed);
        Assert.False(actor.ModelHideWeapons);
    }

