    [Fact]
    public void ModelSceneActorItemTransmogInfoUsesNativeValueAndSlotContracts()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "19:0:0:0:0:false:false:false:false",
            session.Lua.Evaluate(
                "(function() " +
                "local scene=CreateFrame('ModelScene',nil,UIParent); " +
                "local actor=scene:CreateActor('TransmogContractActor'); " +
                "local list=actor:GetItemTransmogInfoList(); " +
                "return table.concat({" +
                "#list,list[1].appearanceID,list[1].secondaryAppearanceID," +
                "list[1].illusionID,select('#',actor:GetItemTransmogInfo(1))," +
                "tostring(pcall(actor.GetItemTransmogInfo,actor))," +
                "tostring(pcall(actor.SetItemTransmogInfo,actor))," +
                "tostring(pcall(actor.SetItemTransmogInfo,actor,{}))," +
                "tostring(pcall(actor.SetItemTransmogInfo,actor," +
                "{appearanceID=1,secondaryAppearanceID=2,illusionID=3},'slot'))" +
                "},':') end)()"));

        Assert.Equal(
            "0:101:-1:303:101:-1:303:true",
            session.Lua.Evaluate(
                "ItemTransmogInfoMixin={IsEmulatorMixed=function() return true end}; " +
                "local reason=TransmogContractActor:SetItemTransmogInfo(" +
                "{appearanceID=101,secondaryAppearanceID=-1,illusionID=303},16,true); " +
                "local exact=TransmogContractActor:GetItemTransmogInfo(16); " +
                "local listed=TransmogContractActor:GetItemTransmogInfoList()[16]; " +
                "return table.concat({reason,exact.appearanceID," +
                "exact.secondaryAppearanceID,exact.illusionID,listed.appearanceID," +
                "listed.secondaryAppearanceID,listed.illusionID," +
                "tostring(exact:IsEmulatorMixed())},':')"));

        Assert.Equal(
            "0:202:0:0:0:0:2",
            session.Lua.Evaluate(
                "local reason=TransmogContractActor:SetItemTransmogInfo(" +
                "{appearanceID=101,secondaryAppearanceID=202,illusionID=303},16); " +
                "local exact=TransmogContractActor:GetItemTransmogInfo(16); " +
                "local list=TransmogContractActor:GetItemTransmogInfoList(); " +
                "return table.concat({reason,exact.secondaryAppearanceID," +
                "list[16].secondaryAppearanceID,list[17].appearanceID," +
                "list[17].secondaryAppearanceID,list[17].illusionID," +
                "TransmogContractActor:SetItemTransmogInfo(" +
                "{appearanceID=1,secondaryAppearanceID=0,illusionID=0},1)},':')"));

        session.Lua.Evaluate(
            "TransmogContractActor:SetItemTransmogInfo(" +
            "{appearanceID=401,secondaryAppearanceID=-1,illusionID=0},17); " +
            "TransmogContractActor:UndressSlot(16)");
        Assert.Equal(
            "0:1:401",
            session.Lua.Evaluate(
                "local list=TransmogContractActor:GetItemTransmogInfoList(); " +
                "return table.concat({" +
                "select('#',TransmogContractActor:GetItemTransmogInfo(16))," +
                "select('#',TransmogContractActor:GetItemTransmogInfo(17))," +
                "list[17].appearanceID},':')"));

        session.Lua.Evaluate("TransmogContractActor:Undress(false)");
        Assert.Equal(
            "1",
            session.Lua.Evaluate(
                "return select('#',TransmogContractActor:GetItemTransmogInfo(17))"));
        session.Lua.Evaluate("TransmogContractActor:Undress()");
        Assert.Equal(
            "0",
            session.Lua.Evaluate(
                "return select('#',TransmogContractActor:GetItemTransmogInfo(17))"));
    }

