    [Fact]
    public void SimpleModelTransformsAndViewTranslationUseNativeEntryContracts()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "false:false:false:false:true:false:7.5:-4.0:7.5:-4.0:" +
            "1.6:3.3:4.9:true:false",
            session.Lua.Evaluate(
                "(function() " +
                "local model=CreateFrame('Model','TransformContractModel'); " +
                "model:SetTransform({x=1,y=2,z=3},{x=.1,y=.2,z=.3},2.5); " +
                "local unloaded=model:GetWorldScale(); " +
                "local missingCenter=pcall(model.UseModelCenterToTransform,model); " +
                "model:UseModelCenterToTransform(nil); " +
                "local nilCenter=model:IsUsingModelCenterToTransform(); " +
                "model:UseModelCenterToTransform(true); " +
                "local trueCenter=model:IsUsingModelCenterToTransform(); " +
                "local badTranslation=pcall(model.SetViewTranslation,model,1); " +
                "model:SetViewTranslation(7.5,-4); local x,y=model:GetViewTranslation(); " +
                "model:SetModel(123); " +
                "model:SetTransform({x=1,y=2,z=3},{x=.1,y=.2,z=.3},2.5); " +
                "local badTransform=pcall(model.SetTransform,model,{x=1,y=2}); " +
                "local x2,y2=model:GetViewTranslation(); " +
                "model:SetModelScale(2); " +
                "Mixin=function(value,mixin) for k,v in pairs(mixin) do value[k]=v end return value end; " +
                "Vector3DMixin={mixed=true}; " +
                "local result=model:TransformCameraSpaceToModelSpace({x=1,y=2,z=3}); " +
                "local badVector=pcall(" +
                "model.TransformCameraSpaceToModelSpace,model,{x=1,y=2}); " +
                "return string.format(" +
                "'%s:%s:%s:%s:%s:%s:%.1f:%.1f:%.1f:%.1f:" +
                "%.1f:%.1f:%.1f:%s:%s'," +
                "tostring(unloaded~=1),tostring(missingCenter)," +
                "tostring(nilCenter),tostring(badTranslation)," +
                "tostring(trueCenter),tostring(badTransform),x,y," +
                "x2,y2,result.x,result.y,result.z," +
                "tostring(result.mixed),tostring(badVector)) end)()"));

        var model = session.Ui.Find("TransformContractModel")!;
        Assert.True(model.ModelTransformEnabled);
        Assert.Equal(new Vector3(1, 2, 3), model.ModelTransformTranslation);
        Assert.Equal(new Vector3(.1f, .2f, .3f), model.ModelTransformRotation);
        Assert.Equal(2.5f, model.ModelTransformScale);
        var expectedWorldScale = 2.5f * MathF.Cos(.2f) * MathF.Cos(.3f);
        Assert.Equal(expectedWorldScale, model.ModelWorldScale, 5);
        Assert.Equal(expectedWorldScale, model.ModelTransformMatrix.M11, 5);
        Assert.Equal(1, model.ModelTransformMatrix.M41);
        Assert.Equal(2, model.ModelTransformMatrix.M42);
        Assert.Equal(3, model.ModelTransformMatrix.M43);

        Assert.Equal(
            "11.0:-6.0:2",
            session.Lua.Evaluate(
                "(function() " +
                "local scene=CreateFrame('ModelScene',nil,UIParent); " +
                "scene:SetViewTranslation(11,-6); local x,y=scene:GetViewTranslation(); " +
                "return string.format('%.1f:%.1f:%d',x,y," +
                "select('#',scene:GetViewTranslation())) end)()"));

        var acceptedTransform = model.ModelTransformMatrix;
        session.Lua.Evaluate("TransformContractModel:SetTransform()");
        Assert.True(model.ModelTransformEnabled);
        Assert.Equal(0, model.ModelTransformScale);
        Assert.Equal(acceptedTransform, model.ModelTransformMatrix);
        Assert.Equal(expectedWorldScale, model.ModelWorldScale, 5);

        session.Lua.Evaluate("TransformContractModel:ClearTransform()");
        Assert.False(model.ModelTransformEnabled);
        Assert.Equal(expectedWorldScale, model.ModelWorldScale, 5);
    }

    [Fact]
    public void SimpleModelResourceAndSequenceMethodsUseNativeLiveModelContracts()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "777:false:0.0:0:0:false:false:false",
            session.Lua.Evaluate(
                "(function() " +
                "local model=CreateFrame('Model','ResourceContractModel'); " +
                "model:SetShadowEffect(4); model:SetSequenceTime(9,-30); " +
                "model:ReplaceIconTexture(456); " +
                "local setReturns=select('#',model:SetModel(777,true)); " +
                "local advanceReturns=select('#',model:AdvanceTime()); " +
                "local missingModel=pcall(model.SetModel,model); " +
                "local missingIcon=pcall(model.ReplaceIconTexture,model); " +
                "local missingSequence=pcall(model.SetSequence,model); " +
                "return string.format('%d:%s:%.1f:%d:%d:%s:%s:%s'," +
                "model:GetModelFileID(),tostring(model:HasAttachmentPoints())," +
                "model:GetShadowEffect(),setReturns,advanceReturns," +
                "tostring(missingModel),tostring(missingIcon)," +
                "tostring(missingSequence)) end)()"));

        var model = session.Ui.Find("ResourceContractModel")!;
        Assert.Equal(777u, model.ModelFileDataId);
        Assert.True(model.ModelNoMip);
        Assert.Equal(0u, model.ModelSequenceId);
        Assert.Equal(0, model.ModelSequenceTimeOffset);
        Assert.Null(model.ModelIconTextureFileDataId);
        Assert.Equal(0, model.ModelShadowEffectStrength);

        model.ModelHasAttachmentPoints = true;
        Assert.Equal(
            "true:0.00:false:true",
            session.Lua.Evaluate(
                "(function() " +
                "local model=ResourceContractModel; " +
                "model:SetSequenceTime(42,-19); " +
                "model:ReplaceIconTexture(888); model:SetShadowEffect(2.5); " +
                "model:SetDesaturation(3.25); " +
                "local highSequence=pcall(model.SetSequence,model,1858); " +
                "return string.format('%s:%.2f:%s:%s'," +
                "tostring(model:HasAttachmentPoints()),model:GetShadowEffect()," +
                "tostring(highSequence)," +
                "tostring(select('#',model:SetSequence(7))==0)) end)()"));
        Assert.Equal(7u, model.ModelSequenceId);
        Assert.Equal(0, model.ModelSequenceTimeOffset);
        Assert.Equal(888u, model.ModelIconTextureFileDataId);
        Assert.Equal(0, model.ModelShadowEffectStrength);
        Assert.Equal(1, model.ModelDesaturation);

        session.Lua.Evaluate(
            "ResourceContractModel:SetShadowEffect(-1); " +
            "ResourceContractModel:ClearModel()");
        Assert.Null(model.ModelFileDataId);
        Assert.False(model.ModelNoMip);
        Assert.False(model.ModelHasAttachmentPoints);
        Assert.Equal(0, model.ModelShadowEffectStrength);
        Assert.Equal(0, model.ModelDesaturation);
    }

