        model.ModelAvailableAnimationIds.Add(91);

        Assert.Equal(
            "true:false:false:false:0:false:0:0",
            session.Lua.Evaluate(
                "(function() local model=CharacterAnimationContractModel; " +
                "local has91=model:HasAnimation(91); " +
                "local has92=model:HasAnimation(92); " +
                "local badAnimation=pcall(model.SetAnimation,model,1858); " +
                "local badFreeze=pcall(model.FreezeAnimation,model,4,2); " +
                "model:SetAnimation(91,7); " +
                "model:FreezeAnimation(4,4294967295,70000); " +
                "model:PlayAnimKit(-12,true); " +
                "model:ApplySpellVisualKit(-7,true); " +
                "model:SetRotation(-1.25,nil); " +
                "local canReturns=select('#',model:CanSetUnit('player')); " +
                "local missingCan=pcall(model.CanSetUnit,model); " +
                "model:StopAnimKit(); " +
                "return table.concat({tostring(has91),tostring(has92)," +
                "tostring(badAnimation),tostring(badFreeze)," +
                "tostring(canReturns),tostring(missingCan)," +
                "select('#',model:SetRotation(0,false))," +
                "select('#',model:StopAnimKit())},':') end)()"));

        Assert.Equal((ushort)4, model.ModelAnimationId);
        Assert.Equal(-1, model.ModelAnimationVariation);
        Assert.Equal(unchecked((ushort)70000), model.ModelAnimationFrozenFrame);
        Assert.Equal(0, model.ModelAnimationSpeed);
        Assert.Null(model.ModelAnimationKitId);
        Assert.False(model.ModelAnimationKitLooping);
        Assert.Equal(unchecked((uint)-7), model.ModelSpellVisualKitId);
        Assert.True(model.ModelSpellVisualOneShot);
        Assert.Equal(0, model.ModelYaw);
        Assert.False(model.ModelRotationAnimating);
    }

    [Fact]
    public void CharacterModelSourceMethodsUseNativeSourceAndArgumentContracts()
    {
        using var session = new EmulatorSession();
        Assert.Equal(
            "0:false:false:false:false:false",
            session.Lua.Evaluate(
                "(function() " +
                "local model=CreateFrame('PlayerModel','CharacterSourceContractModel'); " +
                "return table.concat({" +
                "model:GetDisplayInfo()," +
                "tostring(pcall(model.SetDisplayInfo,model))," +
                "tostring(pcall(model.SetCreature,model))," +
                "tostring(pcall(model.SetItem,model))," +
                "tostring(pcall(model.SetItemAppearance,model))," +
                "tostring(pcall(model.SetUnit,model))},':') end)()"));

        var model = session.Ui.Find("CharacterSourceContractModel")!;
        session.Lua.Evaluate(
            "CharacterSourceContractModel:SetDisplayInfo(-5,-6)");
        Assert.Equal(-5, model.ModelDisplayId);
        Assert.Equal(-6, model.ModelMountDisplayId);
        Assert.Null(model.ModelCreatureDisplayId);

        session.Lua.Evaluate(
            "CharacterSourceContractModel:SetDisplayInfo(77,88)");
        Assert.Equal(77, model.ModelDisplayId);
        Assert.Equal(88, model.ModelMountDisplayId);
        Assert.Equal(77u, model.ModelCreatureDisplayId);

        session.Lua.Evaluate(
            "CharacterSourceContractModel:SetCreature(12,99)");
        Assert.Equal(12, model.ModelCreatureId);
        Assert.Equal(99, model.ModelDisplayId);
        Assert.Equal(99u, model.ModelCreatureDisplayId);

        session.Lua.Evaluate(
            "CharacterSourceContractModel:SetItem(-3,-4,-5)");
        Assert.Equal(-3, model.ModelItemId);
        Assert.Equal(-4, model.ModelItemAppearanceModifierId);
        Assert.Equal(-5, model.ModelItemVisualId);
        Assert.Equal(0, model.ModelDisplayId);

        Assert.Equal(
            "false",
            session.Lua.Evaluate(
                "(function() local model=CharacterSourceContractModel; " +
                "model:SetItemAppearance(-6,-7,20); " +
                "return tostring(pcall(model.SetItemAppearance,model,1,2,21)) end)()"));
        Assert.Equal(-6, model.ModelItemAppearanceId);
        Assert.Equal(-7, model.ModelItemVisualId);
        Assert.Equal(20, model.ModelItemSubclass);

        session.Lua.Evaluate(
            "CharacterSourceContractModel:SetDisplayInfo(44,55); " +
            "CharacterSourceContractModel:SetAnimation(7,8); " +
            "CharacterSourceContractModel:SetDoBlend(false); " +
            "CharacterSourceContractModel:SetBarberShopAlternateForm()");
        Assert.Equal(44, model.ModelDisplayId);
        Assert.Equal(0, model.ModelMountDisplayId);
        Assert.True(model.ModelBarberShopAlternateForm);
        Assert.True(model.ModelDoBlend);
        Assert.Equal((ushort)0, model.ModelAnimationId);
        Assert.Equal(-1, model.ModelAnimationVariation);

        Assert.Equal(
            "false:true:false",
            session.Lua.Evaluate(
                "(function() local model=CharacterSourceContractModel; " +
                "local unknown=model:SetUnit('missing-unit',false,false); " +
                "local known=model:SetUnit('player',false,false); " +
                "local hidden=CreateFrame('PlayerModel','HiddenCharacterSourceModel'); " +
                "hidden:Hide(); " +
                "return table.concat({tostring(unknown),tostring(known)," +
                "tostring(hidden:SetUnit('player'))},':') end)()"));
        Assert.Equal("player", model.ModelUnitToken);
        Assert.False(model.ModelDoBlend);
        Assert.False(model.ModelUseNativeForm);

        var hidden = session.Ui.Find("HiddenCharacterSourceModel")!;
        Assert.Equal("player", hidden.ModelUnitToken);
        Assert.True(hidden.ModelDoBlend);
        Assert.True(hidden.ModelUseNativeForm);
    }

