    [Fact]
    public void CinematicModelVectorsTimingAndPanUseNativeContracts()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "false:false:false:false:false:false:false",
            session.Lua.Evaluate(
                "(function() " +
                "local model=CreateFrame('CinematicModel','CinematicPanContractModel'); " +
                "return table.concat({" +
                "tostring(pcall(model.SetCameraPosition,model,1,2))," +
                "tostring(pcall(model.SetCameraTarget,model,1,2,1/0))," +
                "tostring(pcall(model.SetFadeTimes,model,1))," +
                "tostring(pcall(model.SetJumpInfo,model,1,1/0))," +
                "tostring(pcall(model.StartPan,model))," +
                "tostring(pcall(model.StartPan,model,1,'bad'))," +
                "tostring(pcall(model.StartPan,model,1,2,false,'bad'))" +
                "},':') end)()"));

        var model = session.Ui.Find("CinematicPanContractModel")!;
        Assert.Equal(Vector3.Zero, model.ModelCameraPosition);
        Assert.Equal(Vector3.Zero, model.ModelCameraTarget);
        Assert.Equal(.1f, model.ModelCinematicFadeInSeconds);
        Assert.Equal(.2f, model.ModelCinematicFadeOutSeconds);
        Assert.Equal(.5f, model.ModelCinematicJumpLength);
        Assert.Equal(2.5f, model.ModelCinematicJumpHeight);
        Assert.False(model.ModelCinematicPanActive);

        session.Lua.Evaluate(
            "local model=CinematicPanContractModel; " +
            "model:SetCameraPosition(1,2,3); model:SetCameraTarget(4,5,6); " +
            "model:SetFadeTimes(-.5,1.75); model:SetJumpInfo(3,4); " +
            "model:StartPan(6,8,true,123,.25,1.5); model:StopPan()");

        Assert.Equal(new Vector3(1, 2, 3), model.ModelCameraPosition);
        Assert.Equal(new Vector3(4, 5, 6), model.ModelCameraTarget);
        Assert.Equal(-.5f, model.ModelCinematicFadeInSeconds);
        Assert.Equal(1.75f, model.ModelCinematicFadeOutSeconds);
        Assert.Equal(3f, model.ModelCinematicJumpLength);
        Assert.Equal(4f, model.ModelCinematicJumpHeight);
        Assert.Equal(5, model.ModelCinematicPanType);
        Assert.Equal(8f, model.ModelCinematicPanDurationSeconds);
        Assert.Equal(8f, model.ModelCinematicPanElapsedSeconds);
        Assert.True(model.ModelCinematicPanDoFade);
        Assert.Equal(123, model.ModelCinematicPanVisualKitId);
        Assert.Equal(.25f, model.ModelCinematicPanStartPositionScale);
        Assert.Equal(1.5f, model.ModelCinematicPanSpeedMultiplier);
        Assert.True(model.ModelCinematicPanActive);

        session.Lua.Evaluate(
            "local model=CinematicPanContractModel; " +
            "model:StartPan(2,0,false,999,3,4); model:StartPan(2,4)");

        Assert.Equal(1, model.ModelCinematicPanType);
        Assert.Equal(4f, model.ModelCinematicPanDurationSeconds);
        Assert.Equal(0, model.ModelCinematicPanElapsedSeconds);
        Assert.False(model.ModelCinematicPanDoFade);
        Assert.Equal(0, model.ModelCinematicPanVisualKitId);
        Assert.Equal(0, model.ModelCinematicPanStartPositionScale);
        Assert.Equal(1, model.ModelCinematicPanSpeedMultiplier);
        Assert.True(model.ModelCinematicPanActive);
    }

