    [Fact]
    public void ModelSceneProjectionUsesWowReverseDepthRange()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "400.000:300.000:1.001012:0.303752:0.956705:1.049984",
            session.Lua.Evaluate(
                "(function() " +
                "local scene=CreateFrame('ModelScene',nil,UIParent); " +
                "scene:SetSize(800,600); scene:SetPoint('CENTER'); " +
                "scene:SetCameraPosition(0,0,0); " +
                "scene:SetCameraOrientationByYawPitchRoll(0,0,0); " +
                "scene:SetCameraFieldOfView(math.rad(100)); " +
                "scene:SetCameraNearClip(0.05); scene:SetCameraFarClip(15); " +
                "local x,y=scene:Project3DPointTo2D(0,1,0); " +
                "local _,_,near=scene:Project3DPointTo2D(0,0.05,0); " +
                "local _,_,far=scene:Project3DPointTo2D(0,15,0); " +
                "local _,_,middle=scene:Project3DPointTo2D(0,1,0); " +
                "local _,_,behind=scene:Project3DPointTo2D(0,-1,0); " +
                "return string.format('%.3f:%.3f:%.6f:%.6f:%.6f:%.6f'," +
                "x,y,near,far,middle,behind) end)()"));
        Assert.Equal(
            "true:true",
            session.Lua.Evaluate(
                "(function() " +
                "local scene=CreateFrame('ModelScene',nil,UIParent); scene:SetSize(800,600); " +
                "scene:SetCameraPosition(0,0,0); " +
                "scene:SetCameraOrientationByYawPitchRoll(0,0,math.pi/2); " +
                "local rx,ry,rz=scene:GetCameraRight(); local ux,uy,uz=scene:GetCameraUp(); " +
                "return tostring(math.abs(rz + 1) < 0.0001)..':'.." +
                "tostring(math.abs(ux - 1) < 0.0001) end)()"));
    }

    [Fact]
    public void ModelSceneUsesWowCameraDirectionsAndDiagonalFieldOfView()
    {
        var scene = new ModelSceneState
        {
            CameraPosition = System.Numerics.Vector3.Zero,
            Yaw = -MathF.PI / 2,
            Pitch = 0,
            FieldOfView = MathF.PI / 2
        };

        Assert.True(System.Numerics.Vector3.Distance(
            scene.Forward,
            System.Numerics.Vector3.UnitX) < 0.0001f);

        scene.Yaw = 0;
        scene.Pitch = -MathF.PI / 2;
        Assert.True(System.Numerics.Vector3.Distance(
            scene.Forward,
            System.Numerics.Vector3.UnitZ) < 0.0001f);

        scene.Pitch = 0;
        var projected = scene.Project(new System.Numerics.Vector3(1, 1, 0), 800, 600);
        var verticalFieldOfView = scene.FieldOfView / MathF.Sqrt(
            MathF.Pow(800f / 600f, 2) + 1);
        var expectedX = 400 + 400 / (
            MathF.Tan(verticalFieldOfView / 2) * (800f / 600f));
        Assert.Equal(expectedX, projected.X, 3);
    }

    [Fact]
    public void XmlScriptInheritOrderPlacesTheInheritedHandlerOnTheNamedSide()
    {
        var root = Path.Combine(Path.GetTempPath(), $"wow-addon-lab-{Guid.NewGuid():N}");
        var addon = CreateAddon(
            root,
            "XmlScriptInheritOrder",
            ["layout.xml"],
            [
                "<Ui>" +
                "<Frame name=\"ScriptOrderTemplate\" virtual=\"true\">" +
                "<Scripts><OnLoad>self.order = (self.order or '') .. 'B'</OnLoad></Scripts>" +
                "</Frame>" +
                "<Frame name=\"AppendOrder\" inherits=\"ScriptOrderTemplate\">" +
                "<Scripts><OnLoad inherit=\"append\">self.order = (self.order or '') .. 'A'</OnLoad></Scripts>" +
                "</Frame>" +
                "<Frame name=\"PrependOrder\" inherits=\"ScriptOrderTemplate\">" +
                "<Scripts><OnLoad inherit=\"prepend\">self.order = (self.order or '') .. 'P'</OnLoad></Scripts>" +
                "</Frame>" +
                "<Frame name=\"ReplaceOrder\" inherits=\"ScriptOrderTemplate\">" +
                "<Scripts><OnLoad>self.order = (self.order or '') .. 'R'</OnLoad></Scripts>" +
                "</Frame>" +
                "</Ui>"
            ]);
        try
        {
            using var session = new EmulatorSession();
            session.Load(addon);

            Assert.Equal(
                "AB:BP:R",
                session.Lua.Evaluate(
                    "return AppendOrder.order .. ':' .. PrependOrder.order .. ':' .. ReplaceOrder.order"));
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

