    [Fact]
    public void BrowserApisFollowNativeArgumentAndNavigationContracts()
    {
        var root = Path.Combine(Path.GetTempPath(), $"wow-addon-lab-{Guid.NewGuid():N}");
        var addon = CreateAddon(
            root,
            "XmlBrowser",
            ["layout.xml"],
            [
                "<Ui><Browser name=\"BrowserTest\">" +
                "<Size x=\"400\" y=\"300\"/>" +
                "<Scripts><OnButtonUpdate>self.loadedAction = action</OnButtonUpdate></Scripts>" +
                "</Browser></Ui>"
            ]);
        try
        {
            using var session = new EmulatorSession();
            session.Load(addon);

            Assert.Equal(
                "Browser:true",
                session.Lua.Evaluate(
                    "local names={'ClearFocus','CopyExternalLink','DeleteCookies','NavigateBack'," +
                    "'NavigateForward','NavigateHome','NavigateReload','NavigateStop','NavigateTo'," +
                    "'OpenExternalLink','OpenTicket','SetFocus','SetZoom'}; " +
                    "local present=true; for _,name in ipairs(names) do " +
                    "present=present and type(BrowserTest[name])=='function' end; " +
                    "return BrowserTest:GetObjectType()..':'..tostring(present)"));

            Assert.Equal(
                "false:false:false:false:false:false",
                session.Lua.Evaluate(
                    "local homeMissing=pcall(function() BrowserTest:NavigateHome() end); " +
                    "local toMissing=pcall(function() BrowserTest:NavigateTo() end); " +
                    "local ticketMissing=pcall(function() BrowserTest:OpenTicket() end); " +
                    "local ticketNegative=pcall(function() BrowserTest:OpenTicket(-1) end); " +
                    "local zoomMissing=pcall(function() BrowserTest:SetZoom() end); " +
                    "local zoomInfinite=pcall(function() BrowserTest:SetZoom(1/0) end); " +
                    "return table.concat({tostring(homeMissing),tostring(toMissing)," +
                    "tostring(ticketMissing),tostring(ticketNegative),tostring(zoomMissing)," +
                    "tostring(zoomInfinite)},':')"));

            BrowserTestNavigate(session);
            session.Tick(1.0 / 60.0);
            Assert.Equal("nil", session.Lua.Evaluate("return tostring(BrowserTest.loadedAction)"));

            var browser = session.Ui.Find("BrowserTest")!;
            Assert.Equal("GMTicketStatus", browser.BrowserPage);
            Assert.Equal((uint)42, browser.BrowserTicketIndex);
            Assert.Equal(1.25, browser.BrowserZoom);
            Assert.Null(browser.BrowserExternalLink);
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

    private static void BrowserTestNavigate(EmulatorSession session)
    {
        Assert.Equal(
            "true:true",
            session.Lua.Evaluate(
                "BrowserTest:NavigateHome('KnowledgeBase'); " +
                "BrowserTest:NavigateHome('UnknownPage'); " +
                "BrowserTest:NavigateTo('https://example.invalid/'); " +
                "BrowserTest:NavigateBack(); BrowserTest:NavigateForward(); " +
                "BrowserTest:NavigateReload(); BrowserTest:NavigateStop(); " +
                "BrowserTest:DeleteCookies(); BrowserTest:CopyExternalLink('ignored'); " +
                "BrowserTest:OpenExternalLink('ignored'); BrowserTest:SetZoom(1.25); " +
                "BrowserTest:SetFocus(); local focused=GetCurrentKeyBoardFocus()==BrowserTest; " +
                "BrowserTest:ClearFocus(); local cleared=GetCurrentKeyBoardFocus()==nil; " +
                "BrowserTest:OpenTicket(42); return tostring(focused)..':'..tostring(cleared)"));
    }

