    [Fact]
    public void MapWaypointsFollowNativeValidityProjectionAndEventContracts()
    {
        using var session = new EmulatorSession();
        session.Lua.Maps.MapOverrides[900] =
            new WowMapDetails(900, "Cosmic", 4, 0, 0);
        session.Lua.Maps.MapOverrides[901] =
            new WowMapDetails(901, "Waypoint Cosmic", 4, 0, 0x10000);

        Assert.Equal(
            "false:true:true:0:0:1:true:0.25:0.75:1:3:3:false:0",
            session.Lua.Evaluate(
                "local events=0; local frame=CreateFrame('Frame');" +
                "frame:RegisterEvent('USER_WAYPOINT_UPDATED');" +
                "frame:SetScript('OnEvent',function() events=events+1 end);" +
                "local denied={uiMapID=900,position={x=.1,y=.2}};" +
                "local point={uiMapID=901,position={x=.25,y=.75},z=4};" +
                "C_Map.SetUserWaypoint(denied);" +
                "local deniedEvents=events;" +
                "C_Map.SetUserWaypoint(point,'ignored');" +
                "C_Map.SetUserWaypoint(point);" +
                "local position=C_Map.GetUserWaypointPositionForMap(901);" +
                "local missing=select('#',C_Map.GetUserWaypointPositionForMap(902));" +
                "C_Map.SetUserWaypoint({uiMapID=901,position={x=.25,y=.75},z=5});" +
                "C_Map.ClearUserWaypoint('ignored');" +
                "local afterClear=events;" +
                "C_Map.ClearUserWaypoint();" +
                "local badPoint=pcall(C_Map.SetUserWaypoint,{uiMapID=901,position={x=2,y=0}});" +
                "return table.concat({" +
                "tostring(C_Map.CanSetUserWaypointOnMap(900))," +
                "tostring(C_Map.CanSetUserWaypointOnMap(901,'ignored'))," +
                "tostring(deniedEvents~=1),missing,deniedEvents,events-afterClear+1," +
                "tostring(position~=nil),position.x,position.y,afterClear-2,afterClear," +
                "events,tostring(badPoint),select('#',C_Map.GetUserWaypointPositionForMap(901))},':')"));
    }

