    [Fact]
    public void CloseWorldMapInteractionTargetsOnlyTheNativeWorldMapInteractionType()
    {
        using var session = new EmulatorSession();
        var interactions = session.Lua.PlayerInteractions;
        interactions.HasActiveInteraction = true;
        interactions.HasPendingInteraction = true;
        interactions.CurrentInteractionType = 29;
        interactions.PendingInteractionType = 29;
        interactions.ValidNpcInteractionTypes.Add(29);

        Assert.Equal(
            "0",
            session.Lua.Evaluate(
                "return select('#',C_Map.CloseWorldMapInteraction('ignored'))"));
        Assert.False(interactions.HasActiveInteraction);
        Assert.False(interactions.HasPendingInteraction);
        Assert.Equal(0, interactions.CurrentInteractionType);
        Assert.Equal(0, interactions.PendingInteractionType);
        Assert.Empty(interactions.ValidNpcInteractionTypes);
        Assert.Equal(1, interactions.ClearInteractionRequests);
        Assert.Equal(29, interactions.LastClearInteractionType);

        interactions.HasActiveInteraction = true;
        interactions.CurrentInteractionType = 4;
        interactions.ValidNpcInteractionTypes.Add(4);
        session.Lua.Evaluate("C_Map.CloseWorldMapInteraction()");

        Assert.True(interactions.HasActiveInteraction);
        Assert.Equal(4, interactions.CurrentInteractionType);
        Assert.Contains(4, interactions.ValidNpcInteractionTypes);
        Assert.Equal(2, interactions.ClearInteractionRequests);
        Assert.Equal(29, interactions.LastClearInteractionType);
    }

