        var links = new[]
        {
            new WowMapLink(1, 84, 85, 0, .1, .1, .9, .9, 0),
            new WowMapLink(2, 84, 86, 99, .4, .4, .7, .7, 0),
            new WowMapLink(3, 84, 87, -99, .49, .49, .63, .63, 0,
                PlayerConditionId: 123)
