    [Fact]
    public void MapAssignmentsProjectChildWorldRegionsIntoParentUiCoordinates()
    {
        var easternKingdoms = new WowMapAssignment(
            39325, 13, 0, 0, 0,
            0, 0, 1, 1,
            -15368.8, -22666.7, -1000000,
            12372.9, 18945.8, 1000000);
        var elwynnForest = new WowMapAssignment(
            39462, 37, 0, 0, 12,
            0, 0, 1, 1,
            -10254.2, -1935.42, -1000000,
            -7939.58, 1535.42, 1000000);

        Assert.True(WowMapHighlightGeometry.TryProjectWorldRegionToUi(
            easternKingdoms,
            elwynnForest,
            out var minimumX,
            out var minimumY,
            out var maximumX,
            out var maximumY));
        Assert.InRange(minimumX, 0, 1);
        Assert.InRange(minimumY, 0, 1);
        Assert.InRange(maximumX, 0, 1);
        Assert.InRange(maximumY, 0, 1);

        Assert.True(WowMapHighlightGeometry.TryMapUiPositionToWorld(
            easternKingdoms,
            (minimumX + maximumX) * .5,
            (minimumY + maximumY) * .5,
            out var worldX,
            out var worldY));
        Assert.Equal(
            (elwynnForest.RegionMinimumX + elwynnForest.RegionMaximumX) * .5,
            worldX,
            6);
        Assert.Equal(
            (elwynnForest.RegionMinimumY + elwynnForest.RegionMaximumY) * .5,
            worldY,
            6);
    }

