    [Fact]
    public void CatalogShopProductWritersPreserveAllNestedNativeFieldShapes()
    {
        using var session = new EmulatorSession();
        var display = new WowCatalogShopProductDisplayInfo
        {
            DefaultPreviewModelSceneId = 1,
            DefaultCardModelSceneId = 2,
            DefaultWideCardModelSceneId = 3,
            ItemId = 4,
            OverridePreviewModelSceneId = 5,
