        };
        display.CreatureDisplayInfoIds.Add(10);
        display.SpellVisualIds.Add(11);
        display.ItemModifiedAppearanceIds.Add(12);
        display.AdditionalProductPmtUrls.Add("extra-url");
        session.Lua.CatalogShop.ProductDisplayInfos[40] = display;

        var product = new WowCatalogShopProductInfo
        {
