            Name = "Bundle",
            Type = "decor",
            Description = "Description",
            IconTexture = "icon",
            Price = "20.00",
            OriginalPrice = "25.00",
            DiscountPercentage = 20,
            IsBundle = true,
            BundleChildrenSize = 1,
            SubItemsLoaded = true,
            DecorQuantity = new WowCatalogShopDecorQuantity(2, 3),
            IsVcProduct = true,
            ContainsHousingItem = true
        };
        product.SubItems.Add(
            new WowCatalogShopProductSubItem("Sword", 100, 101, "INVTYPE_WEAPON", 4));
        product.VirtualCurrencies.Add(
            new WowCatalogShopVirtualCurrencyGrant(500, "TOK"));
        session.Lua.CatalogShop.Products[40] = product;

        Assert.Equal(
            "1:2:3:4:5:10:11:12:6:shop-kit:mount:A mount:true:" +
            "product-url:extra-url:2:house-atlas",
            session.Lua.Evaluate(
                "local value=C_CatalogShop.GetCatalogShopProductDisplayInfo(40);" +
                "return table.concat({value.defaultPreviewModelSceneID," +
                "value.defaultCardModelSceneID,value.defaultWideCardModelSceneID," +
                "value.itemID,value.overridePreviewModelSceneID," +
                "value.creatureDisplayInfoIDs[1],value.spellVisualIDs[1]," +
                "value.itemModifiedAppearanceIDs[1],value.iconFileDataID," +
                "value.iconTextureKit,value.productType,value.itemDescription," +
                "tostring(value.hasUnknownLicense),value.productPMTURL," +
                "value.additionalProductPMTURLs[1],value.quantity," +
