                "local item=value.subItems[1];" +
                "local currency=value.virtualCurrencies[1];" +
                "return table.concat({value.catalogShopProductID,value.name,value.type," +
                "value.price,value.originalPrice,value.discountPercentage," +
                "tostring(value.isBundle),value.bundleChildrenSize,item.name,item.itemID," +
                "item.itemAppearanceID,item.invType,item.quality,currency.amount," +
                "currency.currencyCode,value.decorQuantity.placedQuantity," +
                "value.decorQuantity.storedQuantity,tostring(value.isVCProduct)," +
                "tostring(value.containsHousingItem)},':')"));
    }

    [Fact]
    public void CatalogShopCommandsValidateNativeArgumentsAndRetainRequests()
    {
        using var session = new EmulatorSession();
        var shop = session.Lua.CatalogShop;
        shop.BulkPurchaseResult = true;
        shop.PurchaseResults[30] = true;
        shop.BestCurrencyProducts[("TOK", 25)] = 77;

        Assert.Equal(
            "false:false:false:false:false:true:true:77",
            session.Lua.Evaluate(
                "local a=pcall(C_CatalogShop.PurchaseProduct);" +
                "local b=pcall(C_CatalogShop.BulkPurchaseProducts,30);" +
                "local c=pcall(C_CatalogShop.BulkRefundDecors,{30});" +
                "local d=pcall(C_CatalogShop.ProductDisplayedTelemetry,1,2);" +
                "local e=pcall(C_CatalogShop.ProductSelectedTelemetry,1,2,3);" +
                "return table.concat({tostring(a),tostring(b),tostring(c),tostring(d)," +
                "tostring(e),tostring(C_CatalogShop.BulkPurchaseProducts({30,31}))," +
                "tostring(C_CatalogShop.PurchaseProduct(30))," +
                "C_CatalogShop.FindBestCurrencyProductForNeededAmount('TOK',25)},':')"));

        var houseSession = session.Lua.Evaluate(
            "return C_CatalogShop.OpenCatalogShopInteractionFromHouse()");
        Assert.False(string.IsNullOrWhiteSpace(houseSession));
        Assert.Equal(WowCatalogShopInteractionSource.House, shop.InteractionSource);
        Assert.Equal(
            houseSession,
            session.Lua.Evaluate(
                "return C_CatalogShop.OpenCatalogShopInteractionFromShop()"));
        Assert.Equal(WowCatalogShopInteractionSource.Shop, shop.InteractionSource);

        session.Lua.Evaluate(
            "C_CatalogShop.ProductDisplayedTelemetry(1,2,30);" +
            "C_CatalogShop.ProductSelectedTelemetry(1,2,30,true);" +
            "C_CatalogShop.OnLegalDisclaimerClicked(30);" +
            "C_CatalogShop.RefreshVirtualCurrencyBalance('TOK');" +
            "C_CatalogShop.RefreshRefundableDecors();" +
            "C_CatalogShop.StartHousingVCPurchaseConfirmation(30);" +
            "C_CatalogShop.CloseCatalogShopInteraction()");

        Assert.Collection(
            shop.Telemetry,
            entry => Assert.Equal(
                new WowCatalogShopTelemetryEntry(
                    "ProductDisplayedTelemetry",
                    1,
                    2,
                    30),
                entry),
            entry => Assert.Equal(
                new WowCatalogShopTelemetryEntry(
                    "ProductSelectedTelemetry",
                    1,
                    2,
                    30,
                    true),
                entry));
        Assert.Equal("TOK", shop.LastVirtualCurrencyRefreshCode);
        Assert.Equal(1, shop.RefreshRefundableDecorsCount);
        Assert.Equal(30, shop.PendingHousingVcProductId);
        Assert.Null(shop.ShoppingSessionUuid);
        Assert.Equal(WowCatalogShopInteractionSource.None, shop.InteractionSource);
        Assert.Contains(
            shop.Requests,
            request => request.Operation == "OnLegalDisclaimerClicked" &&
                       Assert.IsType<int>(request.Arguments[0]) == 30);
    }

    [Fact]
    public void XmlFrameAttributesAreTypedAndInheritedBeforeOnLoad()
    {
        var root = Path.Combine(Path.GetTempPath(), $"wow-addon-lab-{Guid.NewGuid():N}");
        var addon = CreateAddon(
            root,
            "FrameAttributes",
            ["layout.xml"],
            [
                "<Ui>" +
                "<Frame name=\"AttributeTemplate\" virtual=\"true\"><Attributes>" +
                "<Attribute name=\"offset\" type=\"number\" value=\"-116\"/>" +
                "<Attribute name=\"enabled\" type=\"boolean\" value=\"true\"/>" +
                "<Attribute name=\"label\" value=\"ready\"/>" +
                "</Attributes></Frame>" +
                "<Frame name=\"AttributeFrame\" inherits=\"AttributeTemplate\">" +
                "<Scripts><OnLoad>self.loadedOffset=self:GetAttribute('offset')</OnLoad></Scripts>" +
                "</Frame></Ui>"
            ]);
        try
        {
            using var session = new EmulatorSession();
            session.Load(addon);

            Assert.Equal(
                "-116:true:ready:-116",
                session.Lua.Evaluate(
                    "return table.concat({" +
                    "AttributeFrame:GetAttribute('offset')," +
                    "tostring(AttributeFrame:GetAttribute('enabled'))," +
                    "AttributeFrame:GetAttribute('label'),AttributeFrame.loadedOffset},':')"));
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

