    [Fact]
    public void ItemInteractionUsesNativeTablesEnumsPendingEventsAndRequests()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "10:1:nil:false:false:0:0:0:0:4:5:16:5",
            session.Lua.Evaluate(
                "local count=0; for _ in pairs(C_ItemInteraction) do " +
                "count=count+1 end;" +
                "local arity=select('#'," +
                "C_ItemInteraction.GetItemInteractionInfo());" +
                "local okCost=pcall(" +
                "C_ItemInteraction.GetItemConversionCurrencyCost);" +
                "local okItem=pcall(" +
                "C_ItemInteraction.SetPendingItem,'bad');" +
                "local charge=C_ItemInteraction.GetChargeInfo();" +
                "return table.concat({" +
                "count,arity,tostring(" +
                "C_ItemInteraction.GetItemInteractionInfo())," +
                "tostring(okCost),tostring(okItem)," +
                "C_ItemInteraction.GetItemInteractionSpellId()," +
                "charge.newChargeAmount,charge.rechargeRate," +
                "charge.timeToNextCharge," +
                "Enum.UIItemInteractionType.ItemConversion," +
                "Enum.UIItemInteractionTypeMeta.NumValues," +
                "Enum.UIItemInteractionFlags.AddCurrency," +
                "Enum.UIItemInteractionFlagsMeta.NumValues},':')"));

        var interaction = session.Lua.ItemInteraction;
        var item = WowItemLocation.Bag(2, 5);
        var invalidItem = WowItemLocation.Equipment(10);
        interaction.ChargeInfo =
            new WowItemInteractionChargeInfo(3, 4, 5);
        interaction.InteractionSpellId = 456;
        interaction.InteractionRecordId = 123;
        interaction.SlotIndex = 7;
        interaction.Info = new WowItemInteractionInfo(
            "plunderstorm",
            10,
            11,
            "Title",
            "Tutorial",
            "Go",
            4,
            21,
            "Description",
            "Button tip",
            "Confirm",
            "Slot tip",
            99,
            200,
            12);
        interaction.ConversionCosts[item] =
            new WowItemInteractionConversionCost(1904, 25);
        interaction.EligiblePendingItems.Add(item);
        session.Lua.Cursor.SetPayload(
            WowCursorPayloadKind.Item,
            "item",
            999);
        session.Lua.PlayerInteractions.HasActiveInteraction = true;
        session.Lua.PlayerInteractions.CurrentInteractionType = 44;

        Assert.Equal(
            "3:4:5:1904:25:15:plunderstorm:10:11:Title:Tutorial:Go:" +
            "4:21:Description:Button tip:Confirm:Slot tip:99:200:12:456:" +
            "true:1:true:1:false:2:nil:false:3:nil:4:nil",
            session.Lua.Evaluate(
                "itemInteractionSelections={};" +
                "local listener=CreateFrame('Frame');" +
                "listener:RegisterEvent(" +
                "'ITEM_INTERACTION_ITEM_SELECTION_UPDATED');" +
                "listener:SetScript('OnEvent',function(_,_,selected) " +
                "itemInteractionSelections[" +
                "#itemInteractionSelections+1]=selected and " +
                "((selected.bagID or -1)..'/'.." +
                "selected.slotIndex) or 'nil' end);" +
                "local charge=C_ItemInteraction.GetChargeInfo();" +
                "local cost=C_ItemInteraction." +
                "GetItemConversionCurrencyCost({bagID=2,slotIndex=5});" +
                "local info=C_ItemInteraction.GetItemInteractionInfo();" +
                "local fields=0; for _ in pairs(info) do fields=fields+1 end;" +
                "local first=C_ItemInteraction." +
                "SetPendingItem({bagID=2,slotIndex=5});" +
                "local firstEvents=#itemInteractionSelections;" +
                "local same=C_ItemInteraction." +
                "SetPendingItem({bagID=2,slotIndex=5});" +
                "local sameEvents=#itemInteractionSelections;" +
                "C_ItemInteraction.PerformItemInteraction();" +
                "local invalid=C_ItemInteraction." +
                "SetPendingItem({equipmentSlotIndex=10});" +
                "local invalidEvents=#itemInteractionSelections;" +
                "local invalidEvent=itemInteractionSelections[" +
                "invalidEvents];" +
                "local empty=C_ItemInteraction.SetPendingItem();" +
                "local emptyEvents=#itemInteractionSelections;" +
                "local emptyEvent=itemInteractionSelections[emptyEvents];" +
                "C_ItemInteraction.ClearPendingItem();" +
                "local clearEvents=#itemInteractionSelections;" +
                "local clearEvent=itemInteractionSelections[clearEvents];" +
                "return table.concat({" +
                "charge.newChargeAmount,charge.rechargeRate," +
                "charge.timeToNextCharge,cost.currencyID,cost.amount,fields," +
                "info.textureKit,info.openSoundKitID,info.closeSoundKitID," +
                "info.titleText,info.tutorialText,info.buttonText," +
                "info.interactionType,info.flags,info.description," +
                "info.buttonTooltip,info.confirmationDescription," +
                "info.slotTooltip,info.cost,info.currencyTypeId," +
                "info.dropInSlotSoundKitId," +
                "C_ItemInteraction.GetItemInteractionSpellId()," +
                "tostring(first),firstEvents,tostring(same),sameEvents," +
                "tostring(invalid),invalidEvents,invalidEvent," +
                "tostring(empty),emptyEvents,emptyEvent," +
                "clearEvents,clearEvent},':')"));

        Assert.Null(session.Lua.Cursor.Payload);
        Assert.Null(interaction.PendingItem);
        Assert.Equal(
            [new WowItemInteractionPerformRequest(item, 7)],
            interaction.PerformRequests);

        Assert.Equal(
            "5:5:6:6",
            session.Lua.Evaluate(
                "C_ItemInteraction.SetPendingItem(" +
                "{bagID=2,slotIndex=5});" +
                "local selected=#itemInteractionSelections;" +
                "C_ItemInteraction.InitializeFrame();" +
                "local initialized=#itemInteractionSelections;" +
                "C_ItemInteraction.SetPendingItem(" +
                "{bagID=2,slotIndex=5});" +
                "local selectedAgain=#itemInteractionSelections;" +
                "C_ItemInteraction.Reset();" +
                "return table.concat({selected,initialized,selectedAgain," +
                "#itemInteractionSelections},':')"));
        Assert.Null(interaction.PendingItem);
        Assert.Equal(-1, interaction.SlotIndex);
        Assert.Equal(0, interaction.InteractionRecordId);

        session.Lua.Evaluate("C_ItemInteraction.CloseUI()");
        Assert.False(session.Lua.PlayerInteractions.HasActiveInteraction);
        Assert.Equal(
            44,
            session.Lua.PlayerInteractions.LastClearInteractionType);
    }

