    [Fact]
    public void AdventureMapUsesNativeInteractionTuplesAndStrictArguments()
    {
        using var session = new EmulatorSession();
        session.Lua.PlayerInteractions.HasActiveInteraction = true;
        session.Lua.PlayerInteractions.CurrentInteractionType = 28;

        var adventureMap = session.Lua.AdventureMap;
        adventureMap.MapId = 2274;
        adventureMap.TextureKit = "midnight-adventure-map";
        adventureMap.ZoneChoices.Add(
            new WowAdventureMapZoneChoiceState(
                101,
                "zone-kit",
                "Zone",
                "Zone description",
                0.25,
                0.75,
                2));
        adventureMap.QuestOffers.Add(
            new WowAdventureMapQuestOfferState(
                102,
                true,
                2,
                false,
                "Offer",
                "Offer description",
                0.4,
                0.6,
                3));
        var inset = new WowAdventureMapInsetState(
            2275,
            "Inset",
            "Inset description",
            "inset-icon",
            99,
            12,
            0.1,
            0.9,
            77);
        inset.DetailTileFileIds.Add(123456);
        inset.DetailTileFileIds.Add(null);
        adventureMap.Insets.Add(inset);
        adventureMap.Quests[101] =
            new WowAdventureMapQuestInfoState(
                "Quest",
                "Quest description",
                "Quest objective");
        adventureMap.QuestPortraits[101] =
            new WowAdventureMapQuestPortraitInfoState(
                501,
                502,
                "Portrait",
                "Portrait text",
                601);
        adventureMap.StartableQuestIds.Add(101);

        Assert.Equal(
            "midnight-adventure-map:2274:1:1:1:" +
            "7:101:zone-kit:Zone:Zone description:0.25:0.75:2:" +
            "9:102:true:2:false:Offer:Offer description:0.4:0.6:3:" +
            "9:2275:Inset:Inset description:inset-icon:99:12:0.1:0.9:77:" +
            "123456:0:3:Quest:Quest description:Quest objective:" +
            "501:502:Portrait:Portrait text:601:false:false:false",
            session.Lua.Evaluate(
                "local z={C_AdventureMap.GetZoneChoiceInfo(1)};" +
                "local o={C_AdventureMap.GetQuestOfferInfo('1')};" +
                "local i={C_AdventureMap.GetMapInsetInfo(1)};" +
                "local q={C_AdventureMap.GetQuestInfo(101)};" +
                "local p=C_AdventureMap.GetQuestPortraitInfo('101');" +
                "local function join(t) local r={};" +
                "for n=1,#t do r[n]=tostring(t[n]) end return table.concat(r,':') end;" +
                "return table.concat({" +
                "C_AdventureMap.GetAdventureMapTextureKit()," +
                "C_AdventureMap.GetMapID()," +
                "C_AdventureMap.GetNumZoneChoices()," +
                "C_AdventureMap.GetNumQuestOffers()," +
                "C_AdventureMap.GetNumMapInsets()," +
                "#z,join(z),#o,join(o),#i,join(i)," +
                "C_AdventureMap.GetMapInsetDetailTileInfo(1,1)," +
                "select('#',C_AdventureMap.GetMapInsetDetailTileInfo(1,2))," +
                "#q,join(q),p.portraitDisplayID,p.mountPortraitDisplayID," +
                "p.name,p.text,p.modelSceneID," +
                "tostring(pcall(C_AdventureMap.GetZoneChoiceInfo))," +
                "tostring(pcall(C_AdventureMap.GetMapInsetDetailTileInfo,1,{}))," +
                "tostring(pcall(C_AdventureMap.GetQuestPortraitInfo,math.huge))" +
                "},':')"));

        session.Lua.Evaluate("C_AdventureMap.StartQuest('101')");
        Assert.Equal(101, adventureMap.LastStartedQuestId);

        Assert.Equal(
            "1:0:0",
            session.Lua.Evaluate(
                "local closed=0; local f=CreateFrame('Frame');" +
                "f:RegisterEvent('ADVENTURE_MAP_CLOSE');" +
                "f:SetScript('OnEvent',function() closed=closed+1 end);" +
                "C_AdventureMap.Close();" +
                "return table.concat({closed," +
                "select('#',C_AdventureMap.GetMapID())," +
                "select('#',C_AdventureMap.GetNumMapInsets())},':')"));
        Assert.False(session.Lua.PlayerInteractions.HasActiveInteraction);
        Assert.Equal(28, session.Lua.PlayerInteractions.LastClearInteractionType);
    }

