    [Fact]
    public void XmlGlobalKeyValuesUseGlobalNamesInsteadOfLuaExpressions()
    {
        var root = Path.Combine(Path.GetTempPath(), $"wow-addon-lab-{Guid.NewGuid():N}");
        var addon = CreateAddon(
            root,
            "XmlGlobalKeys",
            ["layout.xml"],
            [
                "<Ui><Frame name=\"GlobalKeyFrame\"><KeyValues>" +
                "<KeyValue key=\"valid\" value=\"TEST_XML_GLOBAL\" type=\"global\"/>" +
                "<KeyValue key=\"nested\" value=\"TEST_XML_GLOBAL.Nested.Value\" type=\"global\"/>" +
                "<KeyValue key=\"missing\" value=\"Missing Global Name\" type=\"global\"/>" +
                "</KeyValues></Frame></Ui>"
            ]);
        var runtimeFile = Path.Combine(root, "globals.lua");
        File.WriteAllText(
            runtimeFile,
            "TEST_XML_GLOBAL = { answer = 42, Nested = { Value = 'resolved' } }");
        try
        {
            using var session = new EmulatorSession();
            session.Load([addon], bootstrapRuntimeFiles: [runtimeFile]);

            Assert.Equal(
                "table:42:resolved:nil",
                session.Lua.Evaluate(
                    "return type(GlobalKeyFrame.valid)..':'.." +
                    "GlobalKeyFrame.valid.answer..':'.." +
                    "GlobalKeyFrame.nested..':'..type(GlobalKeyFrame.missing)"));
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

