    [Fact]
    public void ClubFinderMutatorsAndRequestsFollowNativeArgumentContracts()
    {
        using var session = new EmulatorSession();
        var finder = session.Lua.ClubFinder;
        finder.PostClubSucceeds = true;
        finder.PostingInformationAvailableForClubIds.Add(55);

        Assert.Equal(
            "false:true:false:false:true:true:false",
            session.Lua.Evaluate(
                "C_ClubFinder.SetPlayerApplicantSettings(6,true);" +
                "C_ClubFinder.SetPlayerApplicantSettings(7,true);" +
                "C_ClubFinder.SetRecruitmentSettings(1,false);" +
                "local player=C_ClubFinder.GetPlayerApplicantSettings();" +
                "local recruitment=C_ClubFinder.GetClubRecruitmentSettings();" +
                "local strict=pcall(C_ClubFinder.SetRecruitmentSettings,1,1);" +
                "C_ClubFinder.LookupClubPostingFromClubFinderGUID('ClubFinder-1',true);" +
                "C_ClubFinder.RequestClubsList(true,'search',{62,63});" +
                "C_ClubFinder.RequestMembershipToClub('ClubFinder-1','hello',{62});" +
                "C_ClubFinder.RequestNextCommunityPage(10,25);" +
                "C_ClubFinder.RequestNextGuildPage(20,50);" +
                "C_ClubFinder.RespondToApplicant(" +
                "'ClubFinder-1','Player-1',true,2,'Name',false,true);" +
                "C_ClubFinder.SendChatWhisper(" +
                "'ClubFinder-1','Player-1',2,'Name');" +
                "local posted=C_ClubFinder.PostClub(" +
                "55,610,'Club','Description',123,{62,63},2,true);" +
                "local available=C_ClubFinder.RequestPostingInformationFromClubId(55);" +
                "return table.concat({" +
                "tostring(player.sizeSmall),tostring(player.sizeMedium)," +
                "tostring(player.sizeLarge),tostring(recruitment.playStyleDungeon)," +
                "tostring(recruitment.playStyleSocial),tostring(posted)," +
                "tostring(strict and available)},':')"));

        Assert.Equal(
            new WowClubFinderLookupRequest("ClubFinder-1", true),
            Assert.Single(finder.LookupRequests));
        var clubsListRequest = Assert.Single(finder.ClubsListRequests);
        Assert.True(clubsListRequest.GuildListRequested);
        Assert.Equal("search", clubsListRequest.SearchString);
        Assert.Equal([62, 63], clubsListRequest.SpecIds);
        var membershipRequest = Assert.Single(finder.MembershipRequests);
        Assert.Equal("ClubFinder-1", membershipRequest.ClubFinderGuid);
        Assert.Equal("hello", membershipRequest.Comment);
        Assert.Equal([62], membershipRequest.SpecIds);
        Assert.Equal(
            new WowClubFinderPageRequest(10, 25),
            Assert.Single(finder.CommunityPageRequests));
        Assert.Equal(
            new WowClubFinderPageRequest(20, 50),
            Assert.Single(finder.GuildPageRequests));
        Assert.Equal(
            new WowClubFinderApplicantResponse(
                "ClubFinder-1",
                "Player-1",
                true,
                2,
                "Name",
                false,
                true),
            Assert.Single(finder.ApplicantResponses));
        Assert.Equal(
            new WowClubFinderWhisperRequest(
                "ClubFinder-1",
                "Player-1",
                2,
                "Name"),
            Assert.Single(finder.WhisperRequests));
        var postClubRequest = Assert.Single(finder.PostClubRequests);
        Assert.Equal<ulong>(55, postClubRequest.ClubId);
        Assert.Equal(610, postClubRequest.ItemLevelRequirement);
        Assert.Equal("Club", postClubRequest.Name);
        Assert.Equal("Description", postClubRequest.Description);
        Assert.Equal<uint>(123, postClubRequest.AvatarId);
        Assert.Equal([62, 63], postClubRequest.SpecIds);
        Assert.Equal(2, postClubRequest.ClubType);
        Assert.True(postClubRequest.CrossFaction);
        Assert.Equal<ulong>(55, Assert.Single(finder.PostingInformationRequests));
    }

