    [Fact]
    public void XmlInitialOnShowRunsAfterOnLoadOnlyForEffectivelyVisibleFrames()
    {
        var root = Path.Combine(Path.GetTempPath(), $"wow-addon-lab-{Guid.NewGuid():N}");
        var addon = CreateAddon(
            root,
            "XmlInitialShow",
            ["layout.xml"],
            [
                "<Ui>" +
                "<Frame name=\"InitialShowTemplate\" virtual=\"true\">" +
                "<Scripts>" +
                "<OnLoad>self.loaded=true</OnLoad>" +
                "<OnShow>self.showCount=(self.showCount or 0)+1;" +
                "self.showSawLoad=self.loaded</OnShow>" +
                "</Scripts></Frame>" +
                "<Frame name=\"VisibleInitialShow\" inherits=\"InitialShowTemplate\"/>" +
                "<Frame name=\"HiddenInitialShow\" hidden=\"true\">" +
                "<Frames><Frame parentKey=\"Child\" inherits=\"InitialShowTemplate\"/></Frames>" +
                "</Frame>" +
                "</Ui>"
            ]);
        try
        {
            using var session = new EmulatorSession();
            session.Load(addon);

            Assert.Equal(
                "1:true:nil:1:true",
                session.Lua.Evaluate(
                    "local dynamic=CreateFrame('Frame',nil,UIParent,'InitialShowTemplate');" +
                    "return table.concat({" +
                    "VisibleInitialShow.showCount,tostring(VisibleInitialShow.showSawLoad)," +
                    "tostring(HiddenInitialShow.Child.showCount)," +
                    "dynamic.showCount,tostring(dynamic.showSawLoad)},':')"));
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

    [Fact]
    public void XmlHiddenAttributeIsAppliedBeforeOnLoadWithoutDispatchingOnHide()
    {
        var root = Path.Combine(Path.GetTempPath(), $"wow-addon-lab-{Guid.NewGuid():N}");
        var addon = CreateAddon(
            root,
            "XmlInitialHide",
            ["layout.xml"],
            [
                "<Ui>" +
                "<Frame name=\"InitialHiddenOwner\" hidden=\"true\">" +
                "<Frames><StatusBar parentKey=\"SearchProgress\" hidden=\"false\"/></Frames>" +
                "<Scripts><OnLoad>self.loadSawShown=self:IsShown()</OnLoad><OnHide>" +
                "self.hideCount=(self.hideCount or 0)+1;" +
                "self.hideSawLoad=self.loadSawShown~=nil;self.SearchProgress:Hide()" +
                "</OnHide></Scripts></Frame>" +
                "</Ui>"
            ]);
        try
        {
