                    "return table.concat({" +
                    "tostring(InitialHiddenOwner.hideCount)," +
                    "tostring(InitialHiddenOwner.loadSawShown)," +
                    "tostring(InitialHiddenOwner:IsShown())," +
                    "tostring(InitialHiddenOwner.SearchProgress:IsShown())},':')"));
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

