    [Fact]
    public void CommentatorQueryBatchMatchesNativeContractsAndReturnShapes()
    {
        using var session = new EmulatorSession();
        var commentator = session.Lua.Commentator;
        commentator.CanUseCommentatorCheats = true;
        commentator.IsUsingSmartCamera = true;
        commentator.DampeningPercent = 23;
        commentator.MatchDuration = 91.5;
        commentator.TeamPlayerCounts[0] = 3;
        commentator.TeamPlayerCounts[1] = 4;
        commentator.IndirectSpellIdsByTrackedSpellId[100] = 200;
        commentator.PlayerOverrideNames["Original"] = "Override";
        commentator.TrackedAurasByUnit["player"] =
            new WowCommentatorTrackedAuraState(true, false);
        commentator.TrackedSpellsByUnit[
            WowCommentatorTrackedSpellKey.Create(
                "player",
                WowTrackedSpellCategory.Offensive)] =
            new WowCommentatorTrackedSpellsState([100, 101]);

        Assert.Equal(
            "nil:1",
            session.Lua.Evaluate(
                "return type(C_Commentator.GetTimeLeftInMatch())..':'.." +
                "select('#',C_Commentator.GetTimeLeftInMatch())"));

        commentator.TimeLeftInMatch = 12.5;
        Assert.Equal(
            "true:true:23:91.5:12.5:3:4:0:200:100:999:" +
            "true:false:2:100:101:0:nil:1:true:false:true:true:false:" +
            "Override:A:0:B:0",
            session.Lua.Evaluate(
                "local offensive,defensive=C_Commentator.HasTrackedAuras('player');" +
                "local spells,result=C_Commentator.GetTrackedSpellsByUnit('player',1);" +
                "local missing,missingResult=C_Commentator.GetTrackedSpellsByUnit('target',1);" +
                "local series=C_Commentator.GetOrCreateSeries('A','B');" +
                "return table.concat({" +
                "tostring(C_Commentator.CanUseCommentatorCheats())," +
                "tostring(C_Commentator.IsUsingSmartCamera())," +
                "C_Commentator.GetDampeningPercent()," +
                "C_Commentator.GetMatchDuration()," +
                "C_Commentator.GetTimeLeftInMatch()," +
                "C_Commentator.GetNumPlayers(1),C_Commentator.GetNumPlayers(2)," +
                "select('#',C_Commentator.GetNumPlayers(3))," +
                "C_Commentator.GetIndirectSpellID(100)," +
                "C_Commentator.GetTrackedSpellID(200)," +
                "C_Commentator.GetTrackedSpellID(999)," +
                "tostring(offensive),tostring(defensive),#spells,spells[1],spells[2],result," +
                "type(missing),missingResult," +
                "tostring(C_Commentator.IsTrackedSpellByUnit('player',101,1))," +
                "tostring(C_Commentator.IsTrackedSpellByUnit('player',102,1))," +
                "tostring(C_Commentator.SpellUsesItemCharges(6262))," +
                "tostring(C_Commentator.SpellUsesItemCharges(452930))," +
                "tostring(C_Commentator.SpellUsesItemCharges(1))," +
                "C_Commentator.GetPlayerOverrideName('Original')," +
                "series.teams[1].name,series.teams[1].score," +
                "series.teams[2].name,series.teams[2].score},':')"));

        Assert.Equal(
            "false:false:false:false:false:false:false:false",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(pcall(C_Commentator.GetIndirectSpellID))," +
                "tostring(pcall(C_Commentator.GetNumPlayers))," +
                "tostring(pcall(C_Commentator.GetOrCreateSeries,'A'))," +
                "tostring(pcall(C_Commentator.GetPlayerOverrideName))," +
                "tostring(pcall(C_Commentator.GetTrackedSpellsByUnit,'player',5))," +
                "tostring(pcall(C_Commentator.HasTrackedAuras,'not-a-unit'))," +
                "tostring(pcall(C_Commentator.IsTrackedSpellByUnit,'player',1))," +
                "tostring(pcall(C_Commentator.SpellUsesItemCharges))},':')"));
    }

    [Fact]
    public void CommentatorCommandBatchMatchesNativeParsingAndStateMutation()
    {
        using var session = new EmulatorSession();
        var commentator = session.Lua.Commentator;
        commentator.CanUseCommentatorCheats = true;
        commentator.TeamPlayerCounts[0] = 2;
        commentator.TeamPlayerCounts[1] = 1;
        commentator.TeamIndexByUnit["player"] = 1;
        commentator.FieldOfViewTarget = 0;

        Assert.Equal(
            "true:0:true",
            session.Lua.Evaluate(
                "local eventValue=nil;" +
                "local listener=CreateFrame('Frame');" +
                "listener:RegisterEvent('COMMENTATOR_TEAMS_SWAPPED');" +
                "listener:SetScript('OnEvent',function(_,_,value) eventValue=value end);" +
                "C_Commentator.ExitInstance();" +
                "C_Commentator.FollowPlayer(1,2,true);" +
                "C_Commentator.LookAtPlayer(2,1,2);" +
                "C_Commentator.ResetFoVTarget();" +
                "C_Commentator.SetAdditionalCameraWeightByToken('player',1.25);" +
                "C_Commentator.SetSmartCameraLocked(true);" +
                "C_Commentator.SetUseSmartCamera({});" +
                "C_Commentator.SetCameraPosition(1,2,3,false);" +
                "C_Commentator.SetCameraPosition(4,5,6,true);" +
                "C_Commentator.SetFollowCameraSpeeds(2.5,1.5);" +
                "C_Commentator.SetMouseDisabled({});" +
                "C_Commentator.SetMoveSpeed(99);" +
                "C_Commentator.SetSpeedFactor(-2);" +
                "C_Commentator.SnapCameraLookAtPoint();" +
                "C_Commentator.SetSeriesScore('A','B','A',3);" +
                "C_Commentator.SetSeriesScore('B','A','B',4);" +
                "C_Commentator.SwapTeamSides();" +
                "local series=C_Commentator.GetOrCreateSeries('A','B');" +
                "C_Commentator.ResetSeriesScores('A','B');" +
                "return table.concat({tostring(eventValue)," +
                "select('#',C_Commentator.SnapCameraLookAtPoint())," +
                "tostring(series.teams[1].score==3 and series.teams[2].score==4)},':')"));

        Assert.True(commentator.ExitInstanceRequested);
        Assert.Equal(new WowCommentatorFollowRequest(1, 2, true), commentator.FollowRequest);
        Assert.Equal(new WowCommentatorLookAtRequest(2, 1, 2), commentator.LookAtRequest);
        Assert.Equal(MathF.PI / 2, commentator.FieldOfViewTarget);
        Assert.Equal(1.25f, commentator.AdditionalCameraWeightsByUnit["player"]);
        Assert.True(commentator.IsUsingSmartCamera);
        Assert.False(commentator.IsSmartCameraLocked);
        Assert.Equal(new WowCommentatorVector3(4, 5, 6), commentator.CameraPosition);
        Assert.Equal(new WowCommentatorVector3(4, 5, 6), commentator.CameraTargetPosition);
        Assert.Equal(2.5f, commentator.FollowCameraElasticSpeed);
        Assert.Equal(1.5f, commentator.FollowCameraMinimumSpeed);
        Assert.True(commentator.IsMouseDisabled);
        Assert.Equal(40, commentator.MoveSpeed);
        Assert.Equal(0, commentator.SpeedFactor);
        Assert.True(commentator.CameraLookAtPointSnapped);
        Assert.True(commentator.TeamsSwapped);
        Assert.All(commentator.Series.Single().Teams, team => Assert.Equal(0u, team.Score));

        Assert.Equal(
            "false:true:false:false:false:false:false:false:false:false",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(pcall(C_Commentator.FollowPlayer,1))," +
                "tostring(pcall(C_Commentator.LookAtPlayer,1,1,3))," +
                "tostring(pcall(C_Commentator.ResetSeriesScores,'A'))," +
                "tostring(pcall(C_Commentator.SetAdditionalCameraWeightByToken,'bad',1))," +
                "tostring(pcall(C_Commentator.SetCameraPosition,1,2,3))," +
                "tostring(pcall(C_Commentator.SetFollowCameraSpeeds,1))," +
                "tostring(pcall(C_Commentator.SetMouseDisabled))," +
                "tostring(pcall(C_Commentator.SetMoveSpeed,1/0))," +
                "tostring(pcall(C_Commentator.SetSeriesScore,'A','B','A',-1))," +
                "tostring(pcall(C_Commentator.SetSpeedFactor))},':')"));
    }

