                "C_Commentator.GetPlayerAuraInfoByUnit('player',100);" +
                "local cdStart,cdDuration,cdEnabled=" +
                "C_Commentator.GetPlayerCooldownInfoByUnit('player',200);" +
                "local ccSpell,ccExpiration,ccDuration=" +
                "C_Commentator.GetPlayerCrowdControlInfoByUnit('player');" +
