                "local unit=C_Commentator.GetUnitData('player');" +
                "local missingUnit=C_Commentator.GetUnitData('focus');" +
                "local pos=C_Commentator.GetStartLocation(42);" +
                "local color1=C_Commentator.GetTeamColor(1);" +
                "local color2=C_Commentator.GetTeamColorByUnit('target');" +
                "return table.concat({" +
                "C_Commentator.FindTeamNameInCurrentInstance(1)," +
                "tostring(C_Commentator.FindTeamNameInCurrentInstance(2))," +
                "tostring(C_Commentator.GetPlayerFlagInfoByUnit('player'))," +
                "auraStart,auraDuration,tostring(auraEnabled)," +
                "cdStart,cdDuration,tostring(cdEnabled)," +
                "ccSpell,ccExpiration,ccDuration," +
                "charges,maxCharges,chargeStart,chargeDuration," +
                "player.name,player.specialization,player.damageDone," +
                "player.soloShuffleRoundLosses," +
                "unit.healthMax,unit.health,unit.absorbTotal," +
                "tostring(unit.isDeadOrGhost),tostring(unit.isFeignDeath)," +
                "unit.powerTypeToken,unit.power,unit.powerMax," +
                "pos.x,pos.y,pos.z,color1.r,color1.g,color1.b," +
                "color2.r,color2.g,color2.b," +
                "select('#',C_Commentator.GetPlayerAuraInfoByUnit('target',100))," +
                "select('#',C_Commentator.GetPlayerData(1,2))," +
                "missingUnit.healthMax,missingUnit.powerMax,missingUnit.powerTypeToken},':')"));

        Assert.Equal(
            "false:false:false:false:false:false:false:false:false",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(pcall(C_Commentator.FindTeamNameInCurrentInstance))," +
                "tostring(pcall(C_Commentator.GetPlayerAuraInfoByUnit,'player'))," +
                "tostring(pcall(C_Commentator.GetPlayerCooldownInfoByUnit,'bad',1))," +
