                "tostring(pcall(C_Commentator.GetPlayerData,1))," +
                "tostring(pcall(C_Commentator.GetPlayerFlagInfoByUnit,1))," +
                "tostring(pcall(C_Commentator.GetPlayerSpellChargesByUnit,'player'))," +
                "tostring(pcall(C_Commentator.GetStartLocation))," +
                "tostring(pcall(C_Commentator.GetUnitData,'bad'))},':')"));
    }

    [Fact]
    public void CommentatorHistoryRoundTripsAndValidatesBeforeMutation()
    {
        using var session = new EmulatorSession();

        Assert.Equal(
            "A:5:B:7:Player A:Team A:Original:Override:Override",
            session.Lua.Evaluate(
                "C_Commentator.SetCommentatorHistory({" +
                "series={{teams={{name='A',score=5},{name='B',score=7}}}}," +
                "teamDirectory={{playerName='Player A',teamName='Team A'}}," +
                "overrideNameDirectory={{originalName='Original',newName='Override'}}});" +
                "local history=C_Commentator.GetCommentatorHistory();" +
                "local series=C_Commentator.GetOrCreateSeries('B','A');" +
                "return table.concat({" +
                "series.teams[1].name,series.teams[1].score," +
                "series.teams[2].name,series.teams[2].score," +
                "history.teamDirectory[1].playerName," +
                "history.teamDirectory[1].teamName," +
                "history.overrideNameDirectory[1].originalName," +
                "history.overrideNameDirectory[1].newName," +
                "C_Commentator.GetPlayerOverrideName('Original')},':')"));

        Assert.Equal(
            "false:5:Override",
            session.Lua.Evaluate(
                "local ok=pcall(C_Commentator.SetCommentatorHistory,{" +
                "series={{teams={{name='X',score=1},{name='Y',score=2}}}}," +
                "overrideNameDirectory={}});" +
                "local series=C_Commentator.GetOrCreateSeries('A','B');" +
                "return table.concat({tostring(ok),series.teams[1].score," +
                "C_Commentator.GetPlayerOverrideName('Original')},':')"));

        Assert.Equal(
            "123:9:456:789",
            session.Lua.Evaluate(
                "C_Commentator.SetCommentatorHistory({" +
                "series={{teams={{name=123,score=9}}}}," +
                "teamDirectory={{playerName=456,teamName=789}}," +
                "overrideNameDirectory={}});" +
                "local history=C_Commentator.GetCommentatorHistory();" +
                "return table.concat({history.series[1].teams[1].name," +
                "history.series[1].teams[1].score," +
                "history.teamDirectory[1].playerName," +
                "history.teamDirectory[1].teamName},':')"));
    }

