            session.Lua.Evaluate(
                "local canRaid=C_PartyInfo.AllowedToDoPartyConversion(true);" +
                "C_PartyInfo.SetInstanceAbandonVoteResponse(nil);" +
                "C_PartyInfo.SetRestrictPings(3);" +
                "C_PartyInfo.ConvertToRaid();" +
                "local becameRaid=IsInRaid(1);" +
                "local canParty=C_PartyInfo.AllowedToDoPartyConversion(false);" +
                "C_PartyInfo.ConvertToParty();" +
                "return table.concat({" +
                "tostring(canRaid),tostring(becameRaid)," +
                "tostring(C_PartyInfo.GetInstanceAbandonVoteResponse())," +
                "C_PartyInfo.GetRestrictPings(),tostring(canParty)," +
                "tostring(IsInRaid(1))," +
                "tostring(pcall(C_PartyInfo.AllowedToDoPartyConversion))," +
                "tostring(pcall(C_PartyInfo.SetRestrictPings,4))},':')"));

        Assert.Equal(
            "false:true:true:true:true:false",
            session.Lua.Evaluate(
                "return table.concat({" +
                "tostring(pcall(C_PartyInfo.SetInstanceAbandonVoteResponse))," +
                "tostring(pcall(C_PartyInfo.SetInstanceAbandonVoteResponse,nil))," +
                "tostring(pcall(C_PartyInfo.IsPartyFull,0))," +
                "tostring(pcall(C_PartyInfo.IsPartyFull,nil))," +
                "tostring(pcall(C_PartyInfo.IsCrossFactionParty,1.5))," +
                "tostring(pcall(C_PartyInfo.SetRestrictPings,'bad'))},':')"));

        Assert.Equal(
            "nil:true",
            session.Lua.Evaluate(
                "local listener=CreateFrame('Frame');" +
                "listener:RegisterEvent('GUILD_PARTY_STATE_UPDATED');" +
                "listener:SetScript('OnEvent',function(_,event,value) " +
                "GuildPartyEvent=event; GuildPartyValue=value end);" +
                "RequestGuildPartyState();" +
                "local before=GuildPartyEvent;" +
                "return tostring(before)..':'.." +
                "tostring(type(RequestGuildPartyState)=='function')"));
        Assert.Equal(0, session.Lua.PartyInfo.GuildPartyStateRequestCount);

        session.Lua.Guild.IsInGuild = true;
        session.Lua.PartyInfo.IsGuildParty = true;
        Assert.Equal(
            "GUILD_PARTY_STATE_UPDATED:true",
            session.Lua.Evaluate(
                "RequestGuildPartyState();" +
                "return GuildPartyEvent..':'..tostring(GuildPartyValue)"));
        Assert.Equal(1, session.Lua.PartyInfo.GuildPartyStateRequestCount);
    }

