    [Fact]
    public void BankCommandsValidateAndRecordNativeAsynchronousRequests()
    {
        using var session = new EmulatorSession();
        var bank = session.Lua.Bank;
        bank.ViewableBankTypes.UnionWith([0, 2]);
        bank.UsableBankTypes.UnionWith([0, 2]);
        bank.DepositedMoney = 1_000;
        bank.IsBankFrameOpen = true;
        bank.NextPurchasableTabByBankType[0] =
            new WowNextPurchasableBankTabData(100, true, null, null, null);
        session.Lua.Client.Money = 2_000;

        session.Lua.Evaluate(
            "C_Bank.AutoDepositItemsIntoBank(0);" +
            "C_Bank.AutoDepositItemsIntoBank(1);" +
            "C_Bank.PurchaseBankTab(0);" +
            "C_Bank.DepositMoney(2,500);" +
            "C_Bank.WithdrawMoney(2,250);" +
            "C_Bank.UpdateBankTabSettings(0,6,'Materials','icon-path',1023);" +
            "C_Bank.UpdateBankTabSettings(2,12,'Account','icon',5);" +
            "C_Bank.CloseBankFrame()");

        Assert.False(bank.IsBankFrameOpen);
        Assert.Equal(1, bank.AutoDepositRequestCount);
        Assert.Equal((byte)0, bank.LastAutoDepositBankType);
        Assert.Equal(1, bank.PurchaseRequestCount);
        Assert.Equal((byte)0, bank.LastPurchaseBankType);
        Assert.Equal(1, bank.DepositRequestCount);
        Assert.Equal((byte)2, bank.LastDepositBankType);
        Assert.Equal((ulong)500, bank.LastDepositAmount);
        Assert.Equal(1, bank.WithdrawRequestCount);
        Assert.Equal((byte)2, bank.LastWithdrawBankType);
        Assert.Equal((ulong)250, bank.LastWithdrawAmount);
        Assert.Equal(2, bank.TabSettingsRequestCount);
        Assert.Equal(
            new WowBankTabSettingsRequest(2, 12, "Account", "icon", 5),
            bank.LastTabSettingsRequest);
    }

