                "local before=GetMerchantFilter(); " +
                "local ignored=select('#',SetMerchantFilter()); " +
                "local afterIgnored=GetMerchantFilter(); " +
                "local changed=select('#',SetMerchantFilter(7)); " +
                "local afterChanged=GetMerchantFilter(); " +
                "local reset=select('#',ResetSetMerchantFilter()); " +
                "local afterReset=GetMerchantFilter(); " +
                "SetMerchantFilter(7); " +
                "return table.concat({" +
                "select('#',closed),#closed,before,ignored,afterIgnored," +
                "changed,afterChanged,reset,afterReset" +
