        merchant.CanGuildBankRepair = true;
        merchant.RepairAllCost = 50;
        session.Lua.Client.Money = 200;
        merchant.Items.Add(new WowMerchantItemData
        {
            ItemId = 1,
            StackCount = 4,
            CanAfford = true,
            IsPurchasable = true
        });
        merchant.BuybackItems.Add(new WowBuybackItemData
        {
            ItemId = 2,
            Price = 250
        });

        Assert.Equal(
            "0:0:0:0:0:0:false:false",
            session.Lua.Evaluate(
                "return table.concat({" +
                "select('#',C_MerchantFrame.SellAllJunkItems())," +
                "select('#',PickupMerchantItem(1))," +
                "select('#',BuyMerchantItem(1))," +
                "select('#',BuyMerchantItem(1,9000))," +
                "select('#',BuybackItem(1))," +
                "select('#',ShowBuybackSellCursor(1))," +
                "tostring(pcall(BuyMerchantItem))," +
                "tostring(pcall(C_MerchantFrame.GetItemInfo,0))" +
                "},':')"));

        Assert.Equal(1, merchant.SellAllJunkRequestCount);
        Assert.Equal(1, merchant.LastPickedItemIndex);
        Assert.Equal(new WowMerchantPurchaseRequest(1, 5000), merchant.LastPurchaseRequest);
        Assert.Equal(1, merchant.LastBuybackItemIndex);
        Assert.Equal(49, merchant.BuybackSellCursorMode);

        Assert.Equal(
            "0:0:true:true",
            session.Lua.Evaluate(
                "return table.concat({" +
                "select('#',ShowRepairCursor())," +
                "select('#',RepairAllItems(false))," +
                "tostring(InRepairMode()),tostring(CanGuildBankRepair())" +
                "},':')"));
        Assert.True(merchant.IsInRepairMode);
        Assert.Null(merchant.BuybackSellCursorMode);
        Assert.Equal(1, merchant.RepairAllRequestCount);
        Assert.False(merchant.LastRepairAllUsedGuildBank);

        session.Lua.Evaluate(
            "HideRepairCursor(); ResetSetMerchantFilter(); CloseMerchant()");
        Assert.False(merchant.IsOpen);
        Assert.False(merchant.IsInRepairMode);
        Assert.Equal(1, merchant.ResetFilterRequestCount);
        Assert.Equal(1, merchant.CloseRequestCount);
    }

