                "select('#',GetTrainerTradeskillRankValues())},':')"));

        var trainer = session.Lua.Trainer;
        trainer.ServiceCount = 4;
        trainer.IsTradeSkillTrainer = true;
        trainer.ServiceStepIndex = 0;
        trainer.TradeSkillRank = 50;
        trainer.TradeSkillMaxRank = 75;
        trainer.TradeSkillRankModifier = 5;

        Assert.Equal(
            "4:true:1:3:50:75:5:true:true:true:false:true:false:false:" +
            "true:true:false:true:true:true:false:false:false:false",
            session.Lua.Evaluate(
                "local rank,maxRank,modifier=GetTrainerTradeskillRankValues();" +
                "local initialAvailable=GetTrainerServiceTypeFilter('AVAILABLE');" +
                "local initialUnavailable=GetTrainerServiceTypeFilter('unavailable');" +
                "local initialUsed=GetTrainerServiceTypeFilter('used');" +
                "SetTrainerServiceTypeFilter('available',false);" +
                "local disabled=GetTrainerServiceTypeFilter('available');" +
                "SetTrainerServiceTypeFilter('available',true,1);" +
                "local exclusiveAvailable=GetTrainerServiceTypeFilter('available');" +
                "local exclusiveUnavailable=GetTrainerServiceTypeFilter('unavailable');" +
                "local exclusiveUsed=GetTrainerServiceTypeFilter('used');" +
                "SetTrainerServiceTypeFilter('unavailable',true,true);" +
                "local booleanExclusiveAvailable=" +
                "GetTrainerServiceTypeFilter('available');" +
                "local booleanExclusiveUnavailable=" +
                "GetTrainerServiceTypeFilter('unavailable');" +
                "local booleanExclusiveUsed=GetTrainerServiceTypeFilter('used');" +
                "SetTrainerServiceTypeFilter('all');" +
                "local okGetAll=pcall(GetTrainerServiceTypeFilter,'all');" +
                "local okBad=pcall(SetTrainerServiceTypeFilter,'bad',true);" +
                "local okType=pcall(SetTrainerServiceTypeFilter,'used',1);" +
                "local okMissing=pcall(GetTrainerServiceTypeFilter);" +
                "return table.concat({" +
                "GetNumTrainerServices(),tostring(IsTradeskillTrainer())," +
                "GetTrainerServiceStepIndex()," +
                "select('#',GetTrainerTradeskillRankValues())," +
                "rank,maxRank,modifier,tostring(initialAvailable)," +
                "tostring(initialUnavailable),tostring(initialUsed)," +
                "tostring(disabled),tostring(exclusiveAvailable)," +
                "tostring(exclusiveUnavailable),tostring(exclusiveUsed)," +
                "tostring(booleanExclusiveAvailable)," +
                "tostring(booleanExclusiveUnavailable)," +
                "tostring(booleanExclusiveUsed)," +
                "tostring(GetTrainerServiceTypeFilter('available'))," +
                "tostring(GetTrainerServiceTypeFilter('unavailable'))," +
                "tostring(GetTrainerServiceTypeFilter('used'))," +
                "tostring(okGetAll),tostring(okBad),tostring(okType)," +
                "tostring(okMissing)},':')"));

        session.Lua.PlayerInteractions.HasActiveInteraction = true;
        session.Lua.PlayerInteractions.CurrentInteractionType = 7;
        _ = session.Lua.Evaluate("CloseTrainer(); return ''");
        Assert.False(session.Lua.PlayerInteractions.HasActiveInteraction);
        Assert.Equal(
            7,
            session.Lua.PlayerInteractions.LastClearInteractionType);
    }

