    [Fact]
    public void CraftingOrderMutationsRetainParsedNativeRequestFields()
    {
        using var session = new EmulatorSession();

        session.Lua.Evaluate(
            "C_CraftingOrders.CancelOrder(99); " +
            "C_CraftingOrders.ListMyOrders({" +
            "primarySort={sortType=1,reversed=false}," +
            "secondarySort={sortType=7,reversed=true},offset=3," +
            "callback=function() end}); " +
            "C_CraftingOrders.RequestCustomerOrders({" +
            "orderType=2,selectedSkillLineAbility=17,searchFavorites=true," +
            "initialNonPublicSearch=false," +
            "primarySort={sortType=2,reversed=true}," +
            "secondarySort={sortType=0,reversed=false},forCrafter=true," +
            "offset=4,callback=function() end}); " +
            "C_CraftingOrders.PlaceNewOrder({" +
            "skillLineAbilityID=17,orderType=3,orderDuration=2,tipAmount=500," +
            "customerNotes='notes',reagentInfos={},craftingReagentItems={}," +
            "minCraftingQualityID=4,orderTarget='Player',recraftItem='Item-1'})");

        Assert.Equal(99UL, session.Lua.CraftingOrders.LastCancelledOrderId);
        Assert.Equal(3U, session.Lua.CraftingOrders.LastListMyOrdersRequest?.Offset);
        Assert.Equal(
            (byte)7,
            session.Lua.CraftingOrders.LastListMyOrdersRequest?.SecondarySort.SortType);
        Assert.Equal(
            17U,
            session.Lua.CraftingOrders.LastCustomerOrdersRequest
                ?.SelectedSkillLineAbility);
        Assert.True(
            session.Lua.CraftingOrders.LastCustomerOrdersRequest?.ForCrafter);
        Assert.Equal(500UL, session.Lua.CraftingOrders.LastPlacedOrder?.TipAmount);
        Assert.Equal(
            "Item-1",
            session.Lua.CraftingOrders.LastPlacedOrder?.RecraftItem);
    }

