            new WowAzeriteEmpoweredItemTierInfo([101, 102], 15));
        item.Tiers.Add(
            new WowAzeriteEmpoweredItemTierInfo([201, 202], 30));
        item.SelectablePowerIds.Add(101);
        item.SelectedPowerIds.Add(202);
        item.HasAnyUnselectedPowersOverride = true;

        var azerite = session.Lua.AzeriteEmpoweredItem;
        azerite.RespecCost = 50_000;
        azerite.IsHeartOfAzerothEquipped = true;
        azerite.ItemsByLocation[location] = item;
        azerite.EmpoweredItemIds.Add(9000);
        azerite.TierInfoByItem[(9000, 12)] =
        [
            new WowAzeriteEmpoweredItemTierInfo([301], 45)
        ];
        azerite.Powers[101] =
            new WowAzeriteEmpoweredItemPowerInfo(101, 777);
        azerite.PowerText[(location, 101, 1)] =
            new WowAzeriteEmpoweredItemPowerText(
                "Upgraded Power",
                "Upgraded description");
        azerite.SpecsByPowerId[101] =
        [
            new WowAzeriteEmpoweredItemSpecInfo(1, 71),
            new WowAzeriteEmpoweredItemSpecInfo(2, 250)
        ];
        azerite.AvailablePowersBySpec.Add((101, 71));
        azerite.DisplayablePreviewSources.Add((9000, 12));

        session.Lua.Items.Items[9000] = new WowItemData
        {
            ItemId = 9000,
            Name = "Test Azerite Item"
        };
        session.Lua.Items.LocationItemIds[location] = 9000;
        session.Lua.Items.LocationItemIds[otherLocation] = 9001;

        Assert.Equal(
            "18:nil:0:1:2:3:0:2:2:2:101:102:15:2:201:202:30:" +
            "1:1:301:45:101:777:Upgraded Power:Upgraded description:" +
            "2:1:71:2:250:50000:true:true:true:true:true:true:true:" +
            "true:false:true",
            session.Lua.Evaluate(
                "local count=0; for _ in pairs(C_AzeriteEmpoweredItem) " +
                "do count=count+1 end;" +
                "local loc={bagID=0,slotIndex=1};" +
                "local tiers=C_AzeriteEmpoweredItem.GetAllTierInfo(loc);" +
                "local byID=C_AzeriteEmpoweredItem." +
                "GetAllTierInfoByItemID(9000,12);" +
                "local power=C_AzeriteEmpoweredItem.GetPowerInfo(101);" +
                "local text=C_AzeriteEmpoweredItem." +
                "GetPowerText(loc,101,1);" +
                "local specs=C_AzeriteEmpoweredItem.GetSpecsForPower(101);" +
                "local selected=C_AzeriteEmpoweredItem.SelectPower(loc,101);" +
                "C_AzeriteEmpoweredItem.SetHasBeenViewed(loc);" +
                "C_AzeriteEmpoweredItem." +
                "ConfirmAzeriteEmpoweredItemRespec(loc);" +
                "return table.concat({" +
                "count,tostring(C_AzeriteEmpoweredItem." +
                "CloseAzeriteEmpoweredItemRespec)," +
                "Enum.AzeritePowerLevel.Base," +
                "Enum.AzeritePowerLevel.Upgraded," +
                "Enum.AzeritePowerLevel.Downgraded," +
                "Enum.AzeritePowerLevelMeta.NumValues," +
                "Enum.AzeritePowerLevelMeta.MinValue," +
                "Enum.AzeritePowerLevelMeta.MaxValue," +
                "#tiers,#tiers[1].azeritePowerIDs," +
                "tiers[1].azeritePowerIDs[1]," +
                "tiers[1].azeritePowerIDs[2],tiers[1].unlockLevel," +
                "#tiers[2].azeritePowerIDs," +
                "tiers[2].azeritePowerIDs[1]," +
                "tiers[2].azeritePowerIDs[2],tiers[2].unlockLevel," +
                "#byID,#byID[1].azeritePowerIDs," +
                "byID[1].azeritePowerIDs[1],byID[1].unlockLevel," +
                "power.azeritePowerID,power.spellID,text.name," +
                "text.description,#specs,specs[1].classID," +
                "specs[1].specID,specs[2].classID,specs[2].specID," +
                "C_AzeriteEmpoweredItem.GetAzeriteEmpoweredItemRespecCost()," +
                "tostring(C_AzeriteEmpoweredItem." +
                "IsHeartOfAzerothEquipped())," +
                "tostring(C_AzeriteEmpoweredItem." +
                "IsAzeriteEmpoweredItem(loc))," +
                "tostring(C_AzeriteEmpoweredItem." +
                "IsAzeriteEmpoweredItemByID('item:9000'))," +
                "tostring(C_AzeriteEmpoweredItem." +
                "IsAzeritePreviewSourceDisplayable(9000,12))," +
                "tostring(C_AzeriteEmpoweredItem." +
                "IsPowerAvailableForSpec(101,71))," +
                "tostring(C_AzeriteEmpoweredItem." +
                "IsPowerSelected(loc,202))," +
                "tostring(C_AzeriteEmpoweredItem." +
                "HasAnyUnselectedPowers(loc))," +
                "tostring(C_AzeriteEmpoweredItem.HasBeenViewed(loc))," +
                "tostring(C_AzeriteEmpoweredItem.CanSelectPower(loc,999))," +
                "tostring(selected)},':')"));

        Assert.Equal(
            "0:0:0:table:0:false:false:false:false",
            session.Lua.Evaluate(
                "local loc={bagID=0,slotIndex=1};" +
                "local other={bagID=0,slotIndex=2};" +
                "local missingTiers=C_AzeriteEmpoweredItem." +
                "GetAllTierInfoByItemID(9999);" +
                "return table.concat({" +
                "select('#',C_AzeriteEmpoweredItem.GetPowerInfo(999))," +
                "select('#',C_AzeriteEmpoweredItem." +
                "GetPowerText(loc,999,0))," +
                "select('#',C_AzeriteEmpoweredItem.GetSpecsForPower(999))," +
                "type(missingTiers),#missingTiers," +
                "tostring(pcall(C_AzeriteEmpoweredItem." +
                "CanSelectPower,other,101))," +
                "tostring(pcall(C_AzeriteEmpoweredItem.GetPowerText," +
                "loc,101,3))," +
                "tostring(pcall(C_AzeriteEmpoweredItem." +
                "IsPowerAvailableForSpec,101))," +
                "tostring(pcall(C_AzeriteEmpoweredItem." +
                "IsAzeriteEmpoweredItemByID,{}))},':')"));

        Assert.Equal(
            [location],
            azerite.ConfirmedRespecLocations);
        Assert.Equal(
            [new WowAzeriteEmpoweredItemSelectRequest(location, 0, 101)],
            azerite.SelectRequests);
        Assert.Equal(
            [location],
            azerite.SetHasBeenViewedRequests);
        Assert.DoesNotContain(101, item.SelectedPowerIds);
    }

