    [Fact]
    public void ClientApiDocumentationProvidesExactEnumValuesBeforeAddonsLoad()
    {
        var root = Path.Combine(Path.GetTempPath(), $"enum-docs-{Guid.NewGuid():N}");
        var documentation = CreateAddon(
            root,
            "Blizzard_APIDocumentationGenerated",
            ["encountereventsdocumentation.lua"],
            [
                """
                local Constants = {
                    Tables = {
                        {
                            Name = "EncounterEventsIconDirection",
                            Type = "Enumeration",
                            Fields = {
                                { Name = "Left", Type = "EncounterEventsIconDirection", EnumValue = 0 },
                                { Name = "Right", Type = "EncounterEventsIconDirection", EnumValue = 1 },
                                { Name = "Top", Type = "EncounterEventsIconDirection", EnumValue = 0 },
                                { Name = "Bottom", Type = "EncounterEventsIconDirection", EnumValue = 1 },
                            },
                        },
                        {
                            Name = "SignedClientEnum",
                            Type = "Enumeration",
                            Fields = {
                                { Name = "None", Type = "SignedClientEnum", EnumValue = -1 },
                            },
                        },
                        {
                            Name = "ClientMode",
                            Type = "Enumeration",
                            Fields = {
                                { Name = "First", Type = "ClientMode", EnumValue = 4 },
                                { Name = "Last", Type = "ClientMode", EnumValue = 9 },
                            },
                        },
                        {
                            Name = "ChatFrameConstants",
                            Type = "Constants",
                            Values = {
                                { Name = "MaxChatWindows", Type = "number", Value = 10 },
                                { Name = "DefaultOpacity", Type = "number", Value = 0.25 },
                                { Name = "Enabled", Type = "bool", Value = true },
                                { Name = "Label", Type = "string", Value = "client" },
                                { Name = "FirstMode", Type = "ClientMode", Value = "First" },
                                { Name = "LastMode", Type = "ClientMode", Value = "Last" },
                                { Name = "SymbolicValue", Type = "number", Value = FULLNAME_MAX_CHAR },
                            },
                        },
                    },
                }
                """
            ]);
        var consumer = CreateAddon(
            root,
            "EnumConsumer",
            ["main.lua"],
            [
                "enumValuesAtLoad = table.concat({" +
                "Enum.EncounterEventsIconDirection.Left," +
                "Enum.EncounterEventsIconDirection.Right," +
                "Enum.EncounterEventsIconDirection.Top," +
                "Enum.EncounterEventsIconDirection.Bottom," +
                "Enum.SignedClientEnum.None," +
                "Constants.ChatFrameConstants.MaxChatWindows," +
                "Constants.ChatFrameConstants.DefaultOpacity," +
                "tostring(Constants.ChatFrameConstants.Enabled)," +
                "Constants.ChatFrameConstants.Label," +
                "Constants.ChatFrameConstants.FirstMode," +
                "Constants.ChatFrameConstants.LastMode}, ':')"
            ]);

        try
        {
            using var session = new EmulatorSession();
            session.Load(
                [consumer],
                availableAddonPaths: [documentation]);

            Assert.Equal(
                "0:1:0:1:-1:10:0.25:true:client:4:9",
                session.Lua.Evaluate("return enumValuesAtLoad"));
            Assert.Equal(
                "1:2",
                session.Lua.Evaluate(
                    "return Enum.UndocumentedClientEnum.First..':'.." +
                    "Enum.UndocumentedClientEnum.Second"));
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

