    [Fact]
    public void EmulatorSavedVariablesDoNotPersistOrRestoreNilAssignments()
    {
        var root = Path.Combine(Path.GetTempPath(), $"wow-addon-lab-{Guid.NewGuid():N}");
        var addon = CreateAddon(
            root,
            "SavedNil",
            ["main.lua"],
            ["SavedData = { value = 42 }"],
            "## SavedVariables: SavedData UnusedData");
        var savedRoot = Path.Combine(root, "emulator-data");
        var account = Path.Combine(savedRoot, "Account");
        Directory.CreateDirectory(account);
        var savedPath = Path.Combine(account, "SavedNil.lua");
        File.WriteAllText(
            savedPath,
            "-- Saved by WoW Addon Lab at 2026-01-01T00:00:00Z\n" +
            "SavedData = nil\nUnusedData = nil\n");
        try
        {
            using var session = new EmulatorSession(savedVariablesDirectory: savedRoot);
            session.Load(addon, savedRoot);

            Assert.Equal("42", session.Lua.Evaluate("SavedData.value"));
            session.Lua.SaveVariables();
            var persisted = File.ReadAllText(savedPath);
            Assert.Contains("SavedData = {", persisted);
            Assert.DoesNotContain("UnusedData", persisted);
            Assert.DoesNotContain("SavedData = nil", persisted);
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

