    [Fact]
    public void AddOnQueriesPreserveNativeTuplesSecurityEnumsAndOptInLocalTables()
    {
        var root = Path.Combine(Path.GetTempPath(), $"addon-native-contract-{Guid.NewGuid():N}");
        var bootstrap = CreateAddon(
            root,
            "Blizzard_NativeCatalog",
            ["main.lua"],
            [
                "local _, private = ...; private.secureMarker='secure'; " +
                "local f=CreateFrame('Frame'); f:RegisterEvent('ADDON_LOADED'); " +
                "f:SetScript('OnEvent', function(_,_,name,containsBindings) " +
                "if name=='NativeCatalogUser' then nativeCatalogContainsBindings=tostring(containsBindings) end end)"
            ],
            "## Interface: 1\n## AllowAddOnTableAccess: 1");
        var addon = CreateAddon(
            root,
            "NativeCatalogUser",
            ["main.lua", "Bindings.xml"],
            [
                "local name, private = ...; private.marker='kept'; " +
                "local loading,loaded=C_AddOns.IsAddOnLoaded(name); " +
                "nativeCatalogSelfLoad=tostring(loading)..':'..tostring(loaded); " +
                "nativeCatalogSecureReadCount=select('#',C_AddOns.GetAddOnLocalTable('Blizzard_NativeCatalog'))",
                "<Ui></Ui>"
            ],
            "## Interface: 1\n" +
            "## Title: Native catalog user\n" +
            "## Notes: Native notes\n" +
            "## DefaultState: disabled\n" +
            "## AllowAddOnTableAccess: 1");

        try
        {
            using var session = new EmulatorSession();
            session.Load([addon], bootstrapAddonPaths: [bootstrap]);

            Assert.Equal(
                "2:NativeCatalogUser:Native catalog user:Native notes:true:nil:INSECURE:1:0:kept:0:0:true:true:nil",
                session.Lua.Evaluate(
                    "local name,title,notes,loadable,reason,security=C_AddOns.GetAddOnInfo(2); " +
                    "local localTable=C_AddOns.GetAddOnLocalTable(name); " +
                    "local loaded,value=C_AddOns.LoadAddOn(name); " +
                    "return table.concat({C_AddOns.GetNumAddOns(),name,title,notes,tostring(loadable)," +
                    "tostring(reason),security,C_AddOns.GetAddOnSecurity(name)," +
                    "C_AddOns.GetAddOnSecurity('Blizzard_NativeCatalog'),localTable.marker," +
                    "select('#',C_AddOns.GetAddOnLocalTable('Missing'))," +
                    "nativeCatalogSecureReadCount,nativeCatalogContainsBindings," +
                    "tostring(loaded),tostring(value)},':')"));
            Assert.Equal(
                "true:false:false:nil:0:1:2:3",
                session.Lua.Evaluate(
                    "return table.concat({nativeCatalogSelfLoad," +
                    "tostring(C_AddOns.IsAddOnDefaultEnabled('NativeCatalogUser'))," +
                    "tostring(C_AddOns.GetAddOnNotes('Missing'))," +
                    "C_AddOns.GetAddOnInterfaceVersion('Missing')," +
                    "Enum.AddOnSecurityStatus.Insecure,Enum.AddOnEnableState.All," +
                    "Enum.AddOnSecurityStatusMeta.MaxValue},':')"));
            Assert.Equal(
                "NativeCatalogUser:NativeCatalogUser:1:6",
                session.Lua.Evaluate(
                    "local name=C_AddOns.GetAddOnName('NativeCatalogUser'); " +
                    "return table.concat({name,tostring(C_AddOns.GetAddOnMetadata(name,'Group'))," +
                    "select('#',C_AddOns.GetAddOnNotes('Missing'))," +
                    "select('#',C_AddOns.GetAddOnInfo('Missing'))},':')"));
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

    [Fact]
    public void AddOnLoadabilityAndEnablementFollowNativeStatefulContracts()
    {
        var root = Path.Combine(Path.GetTempPath(), $"addon-loadability-{Guid.NewGuid():N}");
        var selected = CreateAddon(
            root,
            "SelectedAddOn",
            ["main.lua"],
            ["selectedAddOnLoaded=true"],
            "## Interface: 1");
        var dependency = CreateAddon(
            root,
            "DemandDependency",
            ["main.lua"],
            ["demandDependencyLoaded=true"],
            "## Interface: 1\n## LoadOnDemand: 1");
        var demand = CreateAddon(
            root,
            "DemandMain",
            ["main.lua"],
            ["demandMainLoaded=true"],
            "## Interface: 1\n## LoadOnDemand: 1\n## Dependencies: DemandDependency");
        var incompatible = CreateAddon(
            root,
            "IncompatibleDemand",
            ["main.lua"],
            ["incompatibleLoaded=true"],
            "## Interface: 999999\n## LoadOnDemand: 1");

        try
        {
            using var session = new EmulatorSession();
            session.Load(
                [selected],
                availableAddonPaths: [dependency, demand, incompatible]);

            Assert.Equal(
                "false:DEMAND_LOADED:true:nil:2:true:nil:true:true",
                session.Lua.Evaluate(
                    "local a,b=C_AddOns.IsAddOnLoadable('DemandMain'); " +
                    "local c,d=C_AddOns.IsAddOnLoadable('DemandMain',nil,true); " +
                    "local loaded,value=C_AddOns.LoadAddOn('DemandMain'); " +
                    "local depLoaded=C_AddOns.IsAddOnLoaded('DemandDependency'); " +
                    "local mainLoaded=C_AddOns.IsAddOnLoaded('DemandMain'); " +
                    "return table.concat({tostring(a),b,tostring(c),tostring(d)," +
                    "select('#',C_AddOns.LoadAddOn('DemandMain')),tostring(loaded),tostring(value)," +
                    "tostring(depLoaded),tostring(mainLoaded)},':')"));

            Assert.Equal(
                "false:true:false:INTERFACE_VERSION:true:false",
                session.Lua.Evaluate(
                    "local before=C_AddOns.IsAddonVersionCheckEnabled(); " +
                    "local loadableBefore=C_AddOns.IsAddOnLoadable('IncompatibleDemand',nil,true); " +
                    "C_AddOns.SetAddonVersionCheck(true); " +
                    "local loadableAfter,reason=C_AddOns.IsAddOnLoadable('IncompatibleDemand',nil,true); " +
                    "local enabled=C_AddOns.IsAddonVersionCheckEnabled(); " +
                    "C_AddOns.SetAddonVersionCheck(false); " +
                    "return table.concat({tostring(before),tostring(loadableBefore)," +
                    "tostring(loadableAfter),reason,tostring(enabled)," +
                    "tostring(C_AddOns.IsAddonVersionCheckEnabled())},':')"));

            Assert.Equal(
                "0:0:2:2:false:false:false:true",
                session.Lua.Evaluate(
                    "C_AddOns.DisableAddOn('SelectedAddOn'); C_AddOns.SaveAddOns(); " +
                    "local disabled=C_AddOns.GetAddOnEnableState('SelectedAddOn'); " +
                    "C_AddOns.EnableAddOn('SelectedAddOn'); C_AddOns.ResetDisabledAddOns(); " +
                    "local restored=C_AddOns.GetAddOnEnableState('SelectedAddOn'); " +
                    "C_AddOns.EnableAddOn('SelectedAddOn'); C_AddOns.ResetAddOns(); " +
                    "local reparsed=C_AddOns.GetAddOnEnableState('SelectedAddOn'); " +
                    "C_AddOns.DisableAllAddOns(); local allDisabled=C_AddOns.GetAddOnEnableState('SelectedAddOn'); " +
                    "C_AddOns.EnableAllAddOns(); local allEnabled=C_AddOns.GetAddOnEnableState('SelectedAddOn'); " +
                    "return table.concat({disabled,restored,reparsed,allEnabled," +
                    "tostring(pcall(C_AddOns.GetAddOnInfo))," +
                    "tostring(pcall(C_AddOns.GetAddOnInfo,{}))," +
                    "tostring(pcall(C_AddOns.SetAddonVersionCheck,1))," +
                    "tostring(pcall(C_AddOns.GetNumAddOns,{}))},':')"));

            Assert.Equal(
                "nil:MISSING:2:nil",
                session.Lua.Evaluate(
                    "local loaded,reason=C_AddOns.LoadAddOn('Missing'); " +
                    "return table.concat({tostring(loaded),reason," +
                    "select('#',C_AddOns.LoadAddOn('Missing'))," +
                    "tostring(select(2,C_AddOns.IsAddOnLoadable('DemandMain',nil,true)))},':')"));
        }
        finally
        {
            Directory.Delete(root, true);
        }
    }

