    private static string CreateAddon(
        string root,
        string name,
        IReadOnlyList<string> files,
        IReadOnlyList<string> contents,
        string metadata = "")
    {
        var addon = Path.Combine(root, name);
        Directory.CreateDirectory(addon);
        File.WriteAllText(
            Path.Combine(addon, $"{name}.toc"),
            $"## Interface: 120000\n{metadata}\n{string.Join('\n', files)}");
        for (var index = 0; index < files.Count; index++)
            File.WriteAllText(Path.Combine(addon, files[index]), contents[index]);
        return addon;
    }

